INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等号", "is_correct": true, "explanation": "等号：式子中缺少的符号，补上后式子才通顺。"}, {"text": "句子", "is_correct": false, "explanation": "语义：数学式子里不会少了“句子”这种语言单位，句意不通。"}, {"text": "星星", "is_correct": false, "explanation": "语义：数学式子里不会少“星星”，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“少”与“脚步”不搭配，不能说“少了脚步”。"}], "explanations": {"等号": "等号：式子中缺少的符号，补上后式子才通顺。", "句子": "语义：数学式子里不会少了“句子”这种语言单位，句意不通。", "星星": "语义：数学式子里不会少“星星”，句意不通。", "脚步": "搭配：“少”与“脚步”不搭配，不能说“少了脚步”。"}, "sentence_index": 6, "correct_answer": "等号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请在两个数中间放上一只等号。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对物品中的一个，等号是符号，不能用“只”。"}, {"text": "请在两个数中间放上一把等号。", "explanation": "这里应该用〈个〉。“把”多用于有柄或能握住的东西，等号不能用“把”。"}, {"text": "请在两个数中间放上一块等号。", "explanation": "这里应该用〈个〉。“块”多用于块状的东西，等号是符号，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在本子上画了一条等号。", "corrected_sentence": "他在本子上画了一个等号。", "error_description": "错误：量词“条”用错。等号是符号，应该用量词“个”，“条”多用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在两个数中间写了一只等号。", "corrected_sentence": "他在两个数中间写了一个等号。", "error_description": "错误：量词“只”用错。等号是符号，应该用量词“个”，“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
