INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89117, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "少数是不多的几个。", "primary_collocate": null, "pronunciation": "shǎo shù", "ipa": "ʂɑʊ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "班里几乎人人都会游泳，只有少数人不会。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数几个学生没有来上课。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜很贵，只有少数人常来。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这次比赛中，少数选手跑完了全程。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友很多，但真正了解他的只有少数。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数人喜欢甜的，少数人喜欢辣的。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数同学带了伞，其他人都淋湿了。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书只有少数地方我没看懂。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数几家银行周六也开门。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识的人里，会说法语的只有少数。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "少數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "少数：不多的几个人或几件事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89117, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少数", "is_correct": true, "explanation": "少数 shǎo shù：不多的几个人或几件事物，即本词所指。"}, {"text": "手术", "is_correct": false, "explanation": "shǒu（第三声）与 shǎo（第三声）韵母不同（ou 与 ao），意思是外科治疗。"}, {"text": "小数", "is_correct": false, "explanation": "xiǎo（第三声）与 shǎo 声母不同（x 与 sh），意思是小数点后的数字。"}, {"text": "表述", "is_correct": false, "explanation": "biǎo（第三声）与 shǎo 声母不同（b 与 sh），意思是用语言说明。"}, {"text": "导数", "is_correct": false, "explanation": "dǎo（第三声）与 shǎo 声母不同（d 与 sh），意思是数学中函数的变化率。"}], "explanations": {"少数": "少数 shǎo shù：不多的几个人或几件事物，即本词所指。", "手术": "shǒu（第三声）与 shǎo（第三声）韵母不同（ou 与 ao），意思是外科治疗。", "小数": "xiǎo（第三声）与 shǎo 声母不同（x 与 sh），意思是小数点后的数字。", "表述": "biǎo（第三声）与 shǎo 声母不同（b 与 sh），意思是用语言说明。", "导数": "dǎo（第三声）与 shǎo 声母不同（d 与 sh），意思是数学中函数的变化率。"}, "sentence_index": null, "correct_answer": "少数"}, "level_3": {"options": [{"text": "少数", "is_correct": true, "explanation": "少数指不多的几个人，与“只有”的限定相合。"}, {"text": "多数", "is_correct": false, "explanation": "语义：“几乎人人都会”与“只有多数人不会”矛盾，“多数”表示大部分。"}, {"text": "大多数", "is_correct": false, "explanation": "语义：“几乎人人都会”与“只有大多数人不会”矛盾，“大多数”指超过半数的人。"}, {"text": "全班", "is_correct": false, "explanation": "语义：“几乎人人都会”与“只有全班人不会”矛盾。"}], "explanations": {"少数": "少数指不多的几个人，与“只有”的限定相合。", "多数": "语义：“几乎人人都会”与“只有多数人不会”矛盾，“多数”表示大部分。", "大多数": "语义：“几乎人人都会”与“只有大多数人不会”矛盾，“大多数”指超过半数的人。", "全班": "语义：“几乎人人都会”与“只有全班人不会”矛盾。"}, "sentence_index": 0, "correct_answer": "少数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们只需要少数的水。", "explanation": "这里应该用〈少量〉。少数指不多的几个人或事物，只用于可数的对象；水不可数，要说“少量的水”。"}, {"text": "他只睡了少数的时间，就起来工作了。", "explanation": "这里应该用〈很短〉。少数指不多的几个人或事物，只用于可数的对象；时间是不可数的，表示时间少要说“很短的时间”。"}, {"text": "厨房里还剩少数面粉。", "explanation": "这里应该用〈少许〉。少数指不多的几个人或事物，只用于可数的对象；面粉不可数，表示少量要说“少许面粉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89117, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "少数", "is_correct": true, "explanation": "少数 shǎo shù：不多的几个人或几件事物，即本词所指。"}, {"text": "枣树", "is_correct": false, "explanation": "zǎo（第三声）与 shǎo 声母不同（z 与 sh），意思是枣树。"}, {"text": "秒数", "is_correct": false, "explanation": "miǎo（第三声）与 shǎo 声母不同（m 与 sh），意思是以秒计的数目。"}, {"text": "小树", "is_correct": false, "explanation": "xiǎo（第三声）与 shǎo 声母不同（x 与 sh），意思是小的树木。"}], "explanations": {"少数": "少数 shǎo shù：不多的几个人或几件事物，即本词所指。", "枣树": "zǎo（第三声）与 shǎo 声母不同（z 与 sh），意思是枣树。", "秒数": "miǎo（第三声）与 shǎo 声母不同（m 与 sh），意思是以秒计的数目。", "小树": "xiǎo（第三声）与 shǎo 声母不同（x 与 sh），意思是小的树木。"}, "sentence_index": null, "correct_answer": "少数"}, "level_3": {"options": [{"text": "少数", "is_correct": true, "explanation": "少数指不多的几个人，与“其他人都淋湿了”的语境相合（只有少数人带了伞）。"}, {"text": "全部", "is_correct": false, "explanation": "语义：若“全部同学”都带了伞，就不会有“其他人”淋湿。"}, {"text": "全体", "is_correct": false, "explanation": "搭配：“全体”已包括所有人，与“其他人”对立的说法不成立。"}, {"text": "全员", "is_correct": false, "explanation": "语义：“全员”指所有成员，与“其他人都淋湿了”矛盾。"}], "explanations": {"少数": "少数指不多的几个人，与“其他人都淋湿了”的语境相合（只有少数人带了伞）。", "全部": "语义：若“全部同学”都带了伞，就不会有“其他人”淋湿。", "全体": "搭配：“全体”已包括所有人，与“其他人”对立的说法不成立。", "全员": "语义：“全员”指所有成员，与“其他人都淋湿了”矛盾。"}, "sentence_index": 6, "correct_answer": "少数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她只喝少数牛奶。", "explanation": "这里应该用〈少许〉。少数用于可数的人或物，牛奶不可数，表示少量要说“少许牛奶”。"}, {"text": "他做菜时只加了少数糖。", "explanation": "这里应该用〈少量〉。少数指不多的几个人或事物，只用于可数的对象；糖不可数，表示少量要说“少量的糖”。"}, {"text": "这道菜我只放了少数盐。", "explanation": "这里应该用〈少许〉。少数指不多的几个人或事物，只用于可数的对象；盐不可数，表示少量要说“少许盐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛只有一个少数人跑完全程。", "corrected_sentence": "这次比赛只有少数人跑完全程。", "error_description": "错误：“少数”前不能加数量短语“一个”。正确：“只有少数人”。“少数”本身表示不多的一部分，应直接用“只有”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在少数学生带了伞，大多数人却没有。", "corrected_sentence": "少数学生带了伞，大多数人却没有。", "error_description": "错误：“少数学生”作主语前不能加介词“在”。正确：“少数学生带了伞”，直接作主语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89118, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多数", "is_correct": true, "explanation": "多数与“少数”相对，指超过半数的大部分，是本义“不到半数”的反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是建筑构件，与“少数”的数量意义没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是地理事物，与“少数”的数量意义没有反义关系。"}, {"text": "老师", "is_correct": false, "explanation": "老师指教书的人，与“少数”的数量意义没有反义关系。"}], "correct_answer": "多数", "explanations": {"多数": "多数与“少数”相对，指超过半数的大部分，是本义“不到半数”的反义词。", "窗户": "窗户是建筑构件，与“少数”的数量意义没有反义关系。", "河流": "河流是地理事物，与“少数”的数量意义没有反义关系。", "老师": "老师指教书的人，与“少数”的数量意义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89118, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多数", "is_correct": true, "explanation": "多数与“少数”相对，指超过半数的大部分，是本义“不到半数”的反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是家具，与“少数”的数量意义没有反义关系。"}, {"text": "星星", "is_correct": false, "explanation": "星星是天体，与“少数”的数量意义没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是地理事物，与“少数”的数量意义没有反义关系。"}], "correct_answer": "多数", "explanations": {"多数": "多数与“少数”相对，指超过半数的大部分，是本义“不到半数”的反义词。", "桌子": "桌子是家具，与“少数”的数量意义没有反义关系。", "星星": "星星是天体，与“少数”的数量意义没有反义关系。", "海洋": "海洋是地理事物，与“少数”的数量意义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "较少的数量;不到半数。", "primary_collocate": null, "pronunciation": "shǎo shù", "ipa": "ʂɑʊ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "少数服从多数，这是我们的规矩。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票结果出来了，他的意见属于少数。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同意的人只是少数，大多数人反对。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，我的看法属于少数，但我不会改变。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个班里，男生是少数。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票时我们是少数，只好听大家的。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百个人里，同意的只占少数。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这一边是少数，对方是多数。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数不一定错，多数也不一定对。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次选举，支持他的人占少数。", "target_word": "少数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "少數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "少数：不到半数的较少数量，与多数相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89118, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少数", "is_correct": true, "explanation": "少数 shǎo shù：较少的数量，不到半数，即本词所指。"}, {"text": "手术", "is_correct": false, "explanation": "shǒu（第三声）与 shǎo（第三声）韵母不同（ou 与 ao），意思是外科治疗。"}, {"text": "小数", "is_correct": false, "explanation": "xiǎo（第三声）与 shǎo 声母不同（x 与 sh），意思是小数点后的数字。"}, {"text": "导数", "is_correct": false, "explanation": "dǎo（第三声）与 shǎo 声母不同（d 与 sh），意思是数学中函数的变化率。"}, {"text": "枣树", "is_correct": false, "explanation": "zǎo（第三声）与 shǎo 声母不同（z 与 sh），意思是枣树。"}], "explanations": {"少数": "少数 shǎo shù：较少的数量，不到半数，即本词所指。", "手术": "shǒu（第三声）与 shǎo（第三声）韵母不同（ou 与 ao），意思是外科治疗。", "小数": "xiǎo（第三声）与 shǎo 声母不同（x 与 sh），意思是小数点后的数字。", "导数": "dǎo（第三声）与 shǎo 声母不同（d 与 sh），意思是数学中函数的变化率。", "枣树": "zǎo（第三声）与 shǎo 声母不同（z 与 sh），意思是枣树。"}, "sentence_index": null, "correct_answer": "少数"}, "level_3": {"options": [{"text": "少数", "is_correct": true, "explanation": "少数指不到半数的较少人数，“少数服从多数”是固定说法。"}, {"text": "多数", "is_correct": false, "explanation": "语义：“多数服从多数”是自己服从自己，说不通。"}, {"text": "大多数", "is_correct": false, "explanation": "语义：“大多数服从多数”同样不成立，服从的主体与对象重合。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“服从”的主语应为人或组织，不能用“数字”。"}], "explanations": {"少数": "少数指不到半数的较少人数，“少数服从多数”是固定说法。", "多数": "语义：“多数服从多数”是自己服从自己，说不通。", "大多数": "语义：“大多数服从多数”同样不成立，服从的主体与对象重合。", "数字": "搭配：“服从”的主语应为人或组织，不能用“数字”。"}, "sentence_index": 0, "correct_answer": "少数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班男生二十人，女生也二十人，男生占少数。", "explanation": "这里应该用〈半数〉。少数指不到半数，男女各占一半时，男生不能说占少数。"}, {"text": "大家都同意这个方案，我的看法也属于少数。", "explanation": "这里应该用〈多数〉。大家都同意时，我的看法应属于多数，用“少数”与前文矛盾。"}, {"text": "在这个国家，七成人口说英语，说英语的人是少数。", "explanation": "这里应该用〈多数〉。七成已超过半数，应说“多数”，不能说“少数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89118, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "少数", "is_correct": true, "explanation": "少数 shǎo shù：较少的数量，不到半数，即本词所指。"}, {"text": "寿数", "is_correct": false, "explanation": "shòu（第四声）与 shǎo（第三声）韵母、声调都不同（ou 与 ao），意思是寿命的长短。"}, {"text": "少时", "is_correct": false, "explanation": "第二个字 shí 与 shù 韵母、声调不同，少时意思是年轻的时候。"}, {"text": "小叔", "is_correct": false, "explanation": "xiǎo 与 shǎo 声母不同（x 与 sh），shū 与 shù 声调不同，意思是丈夫的弟弟。"}], "explanations": {"少数": "少数 shǎo shù：较少的数量，不到半数，即本词所指。", "寿数": "shòu（第四声）与 shǎo（第三声）韵母、声调都不同（ou 与 ao），意思是寿命的长短。", "少时": "第二个字 shí 与 shù 韵母、声调不同，少时意思是年轻的时候。", "小叔": "xiǎo 与 shǎo 声母不同（x 与 sh），shū 与 shù 声调不同，意思是丈夫的弟弟。"}, "sentence_index": null, "correct_answer": "少数"}, "level_3": {"options": [{"text": "少数", "is_correct": true, "explanation": "少数指不到半数的较少数量，与“只占”的限定相合。"}, {"text": "大部分", "is_correct": false, "explanation": "搭配：“只占”后接的应是较少的数量，“大部分”表示多数，不能与“只占”搭配。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“只占全部”说明没有其他人，与“同意的只占”的限定矛盾。"}, {"text": "绝大多数", "is_correct": false, "explanation": "语义：“绝大多数”远超半数，与“只占”表示数量少的意思矛盾。"}], "explanations": {"少数": "少数指不到半数的较少数量，与“只占”的限定相合。", "大部分": "搭配：“只占”后接的应是较少的数量，“大部分”表示多数，不能与“只占”搭配。", "全部": "语义：“只占全部”说明没有其他人，与“同意的只占”的限定矛盾。", "绝大多数": "语义：“绝大多数”远超半数，与“只占”表示数量少的意思矛盾。"}, "sentence_index": 6, "correct_answer": "少数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次投票，我们这边赞成的人占了百分之六十，我们是少数。", "explanation": "这里应该用〈多数〉。百分之六十已超过半数，不能说“少数”。"}, {"text": "全班都同意，我也属于少数。", "explanation": "这里应该用〈大多数〉。全班都同意时，我应属于大多数，用“少数”与前文矛盾。"}, {"text": "全校一千名学生，住校的有七百人，住校的学生是少数。", "explanation": "这里应该用〈多数〉。七百人已超过半数，应说“多数”，不能说“少数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used 