INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表决的时候，少数人们要服从多数。", "corrected_sentence": "表决的时候，少数人要服从多数。", "error_description": "错误：“少数人”后不能再加复数词尾“们”，两者重复。正确：“少数人要服从多数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同意的人只占的少数。", "corrected_sentence": "同意的人只占少数。", "error_description": "错误：“只占”与“少数”之间不能加“的”。正确：“只占少数”，“只占”直接带宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
