INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "号子是大家一起干活时一边唱一边喊的调子。", "primary_collocate": null, "pronunciation": "hào zi", "ipa": "xɑʊ˥˩ tsɪ", "syllable_count": 2, "sentences": [{"text": "大家一起抬木头，一边走一边喊号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听过一段很有力的号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喊号子的声音又大又好听。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个号子很简单，我一学就会。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人盖房子时爱唱号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "号子一响，大家一起用力。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人教孩子们唱船上的号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着号子，我想起了小时候的码头。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们靠号子来统一步调。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拉网的时候，渔民们喊着号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一首号子", "label": "量词"}, {"form": "劳动号子", "label": "复合"}, {"form": "號子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "大家一起干活时边唱边喊的调子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89119, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "号子", "is_correct": true, "explanation": "正确答案：号子，指大家干活时边唱边喊的调子。"}, {"text": "帽子", "is_correct": false, "explanation": "mào（第四声）与 hào 声母不同，意思是帽子。"}, {"text": "稻子", "is_correct": false, "explanation": "dào（第四声）与 hào 声母不同，意思是稻子。"}, {"text": "套子", "is_correct": false, "explanation": "tào（第四声）与 hào 声母不同，意思是套子。"}, {"text": "罩子", "is_correct": false, "explanation": "zhào（第四声）与 hào 声母不同，意思是罩子。"}], "explanations": {"号子": "正确答案：号子，指大家干活时边唱边喊的调子。", "帽子": "mào（第四声）与 hào 声母不同，意思是帽子。", "稻子": "dào（第四声）与 hào 声母不同，意思是稻子。", "套子": "tào（第四声）与 hào 声母不同，意思是套子。", "罩子": "zhào（第四声）与 hào 声母不同，意思是罩子。"}, "sentence_index": null, "correct_answer": "号子"}, "level_3": {"options": [{"text": "号子", "is_correct": true, "explanation": "正确：“喊号子”指干活时边唱边喊的调子，与“抬木头、走”相配。"}, {"text": "钟声", "is_correct": false, "explanation": "搭配：“喊”不用于钟声，钟声是敲出来的，不说喊钟声。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音符的纸，不能边走边喊。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是用来演奏的，不能边走边喊。"}], "explanations": {"号子": "正确：“喊号子”指干活时边唱边喊的调子，与“抬木头、走”相配。", "钟声": "搭配：“喊”不用于钟声，钟声是敲出来的，不说喊钟声。", "乐谱": "语义：乐谱是记录音符的纸，不能边走边喊。", "乐器": "语义：乐器是用来演奏的，不能边走边喊。"}, "sentence_index": 0, "correct_answer": "号子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈哄孩子睡觉时，常唱号子。", "explanation": "这里应该用〈儿歌〉。号子是大家干活时一唱众和的调子，哄孩子睡觉不用号子。"}, {"text": "裁判吹着号子，示意比赛开始。", "explanation": "这里应该用〈哨子〉。号子是人唱出的调子，不能吹，吹用于哨子。"}, {"text": "这朵号子很响亮，大家都听见了。", "explanation": "这里应该用〈首〉。号子是歌曲，量词用“首”，“朵”多用于花、云等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89119, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "号子", "is_correct": true, "explanation": "正确答案：号子，指大家干活时边唱边喊的调子。"}, {"text": "豹子", "is_correct": false, "explanation": "bào（第四声）与 hào 声母不同，意思是豹子。"}, {"text": "毫子", "is_correct": false, "explanation": "háo（第二声）与 hào 声调不同，意思是旧时的小硬币。"}, {"text": "套子", "is_correct": false, "explanation": "tào（第四声）与 hào 声母不同，意思是套子。"}], "explanations": {"号子": "正确答案：号子，指大家干活时边唱边喊的调子。", "豹子": "bào（第四声）与 hào 声母不同，意思是豹子。", "毫子": "háo（第二声）与 hào 声调不同，意思是旧时的小硬币。", "套子": "tào（第四声）与 hào 声母不同，意思是套子。"}, "sentence_index": null, "correct_answer": "号子"}, "level_3": {"options": [{"text": "号子", "is_correct": true, "explanation": "正确：“唱船上的号子”指船工劳动时唱的调子。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“唱”用于歌曲、词句，不说唱钥匙。"}, {"text": "棉被", "is_correct": false, "explanation": "语义：棉被是盖的东西，不能唱。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是材料，不能唱。"}], "explanations": {"号子": "正确：“唱船上的号子”指船工劳动时唱的调子。", "钥匙": "搭配：“唱”用于歌曲、词句，不说唱钥匙。", "棉被": "语义：棉被是盖的东西，不能唱。", "玻璃": "语义：玻璃是材料，不能唱。"}, "sentence_index": 6, "correct_answer": "号子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂老板在会上喊起了号子，要大家努力赚钱。", "explanation": "这里应该用〈口号〉。号子是干活时一唱众和的调子，激励、宣传的话要说口号。"}, {"text": "他按了一下号子，门铃就响了。", "explanation": "这里应该用〈按钮〉。号子是人唱出的歌，不能用手按；按的是按钮。"}, {"text": "这只号子很长，工人们都在唱。", "explanation": "这里应该用〈首〉。号子是歌曲，量词用“首”，“只”多用于动物或单件小物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "领头的人先吹起号子，大家才跟着用力。", "corrected_sentence": "领头的人先唱起号子，大家才跟着用力。", "error_description": "搭配错误：“号子”是边唱边喊的调子，应说“唱起号子”，不能说“吹起号子”（“吹”用于号角、哨子等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他唱了一根号子，嗓子都哑了。", "corrected_sentence": "他唱了一首号子，嗓子都哑了。", "error_description": "量词错误：“号子”是歌曲，量词应用“首”，不应用“根”（“根”用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
