INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "集体劳动时，为协调动作而一唱众和的歌声。", "primary_collocate": null, "pronunciation": "hào zi", "ipa": "xɑʊ˥˩ tsɪ", "syllable_count": 2, "sentences": [{"text": "工人们一边喊号子，一边拉船。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边传来整齐的号子声。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬大石头时，大家喊起了号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老渔民会唱很多劳动号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领头的人先喊，大家跟着唱号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了号子，大家的动作就整齐了。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷年轻时在码头喊过号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的田里响起了高亢的号子。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首号子是工人们在修路时唱的。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "号子让大家一起用力。", "target_word": "号子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一首号子", "label": "量词"}, {"form": "劳动号子", "label": "复合"}, {"form": "號子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "集体劳动时协调动作的一唱众和的歌声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89120, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "号子", "is_correct": true, "explanation": "正确答案：号子，指集体劳动时一唱众和的歌声。"}, {"text": "帽子", "is_correct": false, "explanation": "mào（第四声）与 hào 声母不同，意思是帽子。"}, {"text": "稻子", "is_correct": false, "explanation": "dào（第四声）与 hào 声母不同，意思是稻子。"}, {"text": "套子", "is_correct": false, "explanation": "tào（第四声）与 hào 声母不同，意思是套子。"}, {"text": "罩子", "is_correct": false, "explanation": "zhào（第四声）与 hào 声母不同，意思是罩子。"}], "explanations": {"号子": "正确答案：号子，指集体劳动时一唱众和的歌声。", "帽子": "mào（第四声）与 hào 声母不同，意思是帽子。", "稻子": "dào（第四声）与 hào 声母不同，意思是稻子。", "套子": "tào（第四声）与 hào 声母不同，意思是套子。", "罩子": "zhào（第四声）与 hào 声母不同，意思是罩子。"}, "sentence_index": null, "correct_answer": "号子"}, "level_3": {"options": [{"text": "号子", "is_correct": true, "explanation": "正确：“喊号子”指干活时一唱众和的歌声，与“拉船”相配。"}, {"text": "口哨", "is_correct": false, "explanation": "搭配：“喊”不用于口哨，口哨要吹，不说“喊口哨”。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“喊”不说喊歌曲，歌曲要唱。"}, {"text": "账本", "is_correct": false, "explanation": "语义：账本是记账用的本子，不能“喊”，与“一边拉船”也不相配。"}], "explanations": {"号子": "正确：“喊号子”指干活时一唱众和的歌声，与“拉船”相配。", "口哨": "搭配：“喊”不用于口哨，口哨要吹，不说“喊口哨”。", "歌曲": "搭配：“喊”不说喊歌曲，歌曲要唱。", "账本": "语义：账本是记账用的本子，不能“喊”，与“一边拉船”也不相配。"}, "sentence_index": 0, "correct_answer": "号子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "游行的队伍边走边高喊号子，要求涨工资。", "explanation": "这里应该用〈口号〉。号子是集体劳动时一唱众和的歌，口号是喊出的宣传或要求的话，游行时不说喊号子。"}, {"text": "他用号子在纸上写字。", "explanation": "这里应该用〈笔〉。号子是集体劳动时一唱众和的歌声，不是能拿来写字的东西。"}, {"text": "他今天唱了一只号子。", "explanation": "这里应该用〈首〉。号子是歌曲，量词用“首”；“只”多用于动物或单件小物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89120, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "号子", "is_correct": true, "explanation": "正确答案：号子，指集体劳动时一唱众和的歌声。"}, {"text": "豹子", "is_correct": false, "explanation": "bào（第四声）与 hào 声母不同，意思是豹子。"}, {"text": "报子", "is_correct": false, "explanation": "bào（第四声）与 hào 声母不同，意思是报信的人。"}, {"text": "毫子", "is_correct": false, "explanation": "háo（第二声）与 hào 声调不同，意思是旧时的小硬币。"}], "explanations": {"号子": "正确答案：号子，指集体劳动时一唱众和的歌声。", "豹子": "bào（第四声）与 hào 声母不同，意思是豹子。", "报子": "bào（第四声）与 hào 声母不同，意思是报信的人。", "毫子": "háo（第二声）与 hào 声调不同，意思是旧时的小硬币。"}, "sentence_index": null, "correct_answer": "号子"}, "level_3": {"options": [{"text": "号子", "is_correct": true, "explanation": "正确：“喊过号子”指年轻时在码头干活时喊的歌声。"}, {"text": "绳子", "is_correct": false, "explanation": "搭配：“喊”不说喊绳子，绳子不是用来喊的。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能喊。"}, {"text": "木桶", "is_correct": false, "explanation": "语义：木桶是盛水的器具，不能喊。"}], "explanations": {"号子": "正确：“喊过号子”指年轻时在码头干活时喊的歌声。", "绳子": "搭配：“喊”不说喊绳子，绳子不是用来喊的。", "窗户": "语义：窗户是建筑部件，不能喊。", "木桶": "语义：木桶是盛水的器具，不能喊。"}, "sentence_index": 6, "correct_answer": "号子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吹着号子，催大家快走。", "explanation": "这里应该用〈号角〉。号子是人唱出的歌，不能吹；吹用于号角、口哨等。"}, {"text": "他站在台上，用号子动员大家参军。", "explanation": "这里应该用〈号召〉。号子是劳动时一唱众和的歌，不用来动员他人；动员他人要说号召。"}, {"text": "工人们唱了一把号子，把船拉上了岸。", "explanation": "这里应该用〈首〉。号子是歌曲，量词用“首”；“把”用于有柄的东西，如刀、伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老船工唱起一只号子，大家就一起使劲。", "corrected_sentence": "老船工唱起一首号子，大家就一起使劲。", "error_description": "量词错误：“号子”是歌曲，量词应用“首”，不应用“只”（“只”多用于动物或单件小物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们一起用力拉船，齐声喊起了一条号子。", "corrected_sentence": "工人们一起用力拉船，齐声喊起了一首号子。", "error_description": "量词错误：“号子”是歌曲，量词应用“首”，不应用“条”（“条”用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
