INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几天是天数尚不确定、需要询问或说不准的时长。", "primary_collocate": null, "pronunciation": "jǐ tiān", "ipa": "tɕi˨˩˦ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "我不知道还要等几天。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说不准要出差几天。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你打算在这里住几天?", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生没说要住院几天。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上可能要走几天。", "target_word": "几天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没人知道这场雨会下几天。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你请了几天假?", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要在上海玩几天,还没想好。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不好,飞机可能要晚几天。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事要做几天,我现在还不清楚。", "target_word": "几天", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾天", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天数不确定或需要询问,如“住几天”“等几天”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a2d37c5-ce5a-420d-8d73-ab1cf9e08d40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：不确定的天数，是本次听辨的目标词。"}, {"text": "几年", "is_correct": false, "explanation": "nián（第二声）与 tiān（第一声）声母不同（n 与 t），意思是几年。"}, {"text": "几千", "is_correct": false, "explanation": "qiān 与 tiān 声母不同（q 与 t），意思是几千。"}, {"text": "几点", "is_correct": false, "explanation": "diǎn（第三声）与 tiān（第一声）声母不同（d 与 t）且声调不同，意思是几点钟。"}], "explanations": {"几天": "几天：不确定的天数，是本次听辨的目标词。", "几年": "nián（第二声）与 tiān（第一声）声母不同（n 与 t），意思是几年。", "几千": "qiān 与 tiān 声母不同（q 与 t），意思是几千。", "几点": "diǎn（第三声）与 tiān（第一声）声母不同（d 与 t）且声调不同，意思是几点钟。"}, "sentence_index": null, "correct_answer": "几天"}, "level_3": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：不确定的天数，与“不知道”的语气相符。"}, {"text": "几本", "is_correct": false, "explanation": "搭配：“几本”是书本的数量，不能表示等待的时长。"}, {"text": "今天", "is_correct": false, "explanation": "搭配：“还要等今天”不成立，“今天”指当天，不能作“等”的时段。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“还要等时间”不成立，“时间”不能直接作“等”的时段。"}], "explanations": {"几天": "几天：不确定的天数，与“不知道”的语气相符。", "几本": "搭配：“几本”是书本的数量，不能表示等待的时长。", "今天": "搭配：“还要等今天”不成立，“今天”指当天，不能作“等”的时段。", "时间": "搭配：“还要等时间”不成立，“时间”不能直接作“等”的时段。"}, "sentence_index": 0, "correct_answer": "几天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电梯还要等几天才到？", "explanation": "这里应该用〈几分钟〉。等电梯的时间以分钟计，“几天”太长。"}, {"text": "这首歌你要唱几天？", "explanation": "这里应该用〈几分钟〉。唱一首歌只需几分钟，不能用“几天”问时长。"}, {"text": "你吃一顿饭要吃几天？", "explanation": "这里应该用〈多长时间〉。一顿饭的时长很短，用“几天”询问不合理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几天", "is_correct": true, "explanation": "几天：询问不确定的天数，这里问请假的天数。"}, {"text": "几秒", "is_correct": false, "explanation": "语义：请假不以秒计，“几秒”与此冲突。"}, {"text": "几世纪", "is_correct": false, "explanation": "语义：“几世纪”太过漫长，不能作请假的时长。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“请了时间假”不成立，“时间”不能直接作请假的数量。"}], "explanations": {"几天": "几天：询问不确定的天数，这里问请假的天数。", "几秒": "语义：请假不以秒计，“几秒”与此冲突。", "几世纪": "语义：“几世纪”太过漫长，不能作请假的时长。", "时间": "搭配：“请了时间假”不成立，“时间”不能直接作请假的数量。"}, "sentence_index": 6, "correct_answer": "几天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小孩几天就睡着了。", "explanation": "这里应该用〈一刻钟〉。入睡只需一刻钟，“几天”表示若干日子，与“就”的快速语气冲突。"}, {"text": "这道汤要煮几天，我先去买菜。", "explanation": "这里应该用〈三十分钟〉。煮一道汤的时长以分钟计，“几天”不能用于这样的烹饪时长。"}, {"text": "他跑完一百米只用了几天。", "explanation": "这里应该用〈几秒〉。跑完一百米只需几秒，“几天”指若干日子，用在这样的短时段里不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还不确定要在那里住几天个。", "corrected_sentence": "我还不确定要在那里住几天。", "error_description": "“几天”后多加了量词“个”。“几天”作时量补语时是固定说法，后面不能直接加“个”，正确是“住几天”；写成“住几天个”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们要在上海玩了几天？", "corrected_sentence": "你们要在上海玩几天？", "error_description": "错误在于“了”。“了”表示动作已经完成，与表示将来的“要”相矛盾；应说“你们要在上海玩几天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
