INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89125, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "战线是两边打仗时，双方的人排开的那一条线。", "primary_collocate": null, "pronunciation": "zhàn xiàn", "ipa": "ʈʂan˥˩ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "两军的战线拉得很长。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们守在战线上，一步也不退。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战线那边的枪声越来越大。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方的战线在河边停了下来。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上有一条红色的战线。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军来到战线，看了看士兵。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战线离我们的村子很近。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到晚上，战线上就安静了。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队一直守着南边的战线。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生冒着雨走到战线，送药给士兵。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "战線", "label": "繁体"}], "register": "通用", "sense_fingerprint": "打仗时双方人员排开形成的那条线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战线", "is_correct": true, "explanation": "战线：交战双方排开的那条线（zhàn xiàn，第四声）。"}, {"text": "展现", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展示、显现。"}, {"text": "占先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是抢先、居先。"}, {"text": "战舰", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j/x），听感相近；意思是作战用的军舰。"}], "explanations": {"战线": "战线：交战双方排开的那条线（zhàn xiàn，第四声）。", "展现": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展示、显现。", "占先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是抢先、居先。", "战舰": "jiàn 与 xiàn 声母不同（j/x），听感相近；意思是作战用的军舰。"}, "sentence_index": null, "correct_answer": "战线"}, "level_3": {"options": [{"text": "战线", "is_correct": true, "explanation": "战线：双方军队排开形成的那条线，与“拉得很长”搭配。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然水道，不是军队排开的线。"}, {"text": "桥梁", "is_correct": false, "explanation": "语义：桥梁是跨越水面的建筑，不是两军对峙的线。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“账单”不能说“两军的……拉得很长”，与军事对峙的语境不合。"}], "explanations": {"战线": "战线：双方军队排开形成的那条线，与“拉得很长”搭配。", "河流": "语义：河流是自然水道，不是军队排开的线。", "桥梁": "语义：桥梁是跨越水面的建筑，不是两军对峙的线。", "账单": "搭配：“账单”不能说“两军的……拉得很长”，与军事对峙的语境不合。"}, "sentence_index": 0, "correct_answer": "战线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用一根红色的战线缝好了衣服。", "explanation": "这里应该用〈缝线〉。缝衣服用的线要说缝线，战线指两边打仗时双方排开的那一条线，不指缝纫用线。"}, {"text": "电工把两根战线接在了一起。", "explanation": "这里应该用〈电线〉。接在一起用来导电的线要说电线，战线指两边打仗时双方排开的那一条线。"}, {"text": "他把一条战线拴在了树上。", "explanation": "这里应该用〈绳子〉。拴东西常用绳子；战线指两边打仗时双方排开的那一条线，与拴东西无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战线", "is_correct": true, "explanation": "战线：双方对峙的前线，与“离我们的村子很近”搭配，指具体的作战地带。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“歌曲”不是可以与村子远近比较的地点，不能作主语。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是一种活动，不是有远近距离的地方。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的思想，无法说“离村子很近”。"}], "explanations": {"战线": "战线：双方对峙的前线，与“离我们的村子很近”搭配，指具体的作战地带。", "歌曲": "搭配：“歌曲”不是可以与村子远近比较的地点，不能作主语。", "考试": "语义：考试是一种活动，不是有远近距离的地方。", "道理": "语义：道理是抽象的思想，无法说“离村子很近”。"}, "sentence_index": 6, "correct_answer": "战线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双方各摆了一张战线。", "explanation": "这里应该用〈条〉。战线的量词是条，不能用“张”。"}, {"text": "他们在河边搭起了一座战线。", "explanation": "这里应该用〈条〉。战线的量词是条，不能用“座”。"}, {"text": "哨兵守着那一台战线。", "explanation": "这里应该用〈条〉。战线的量词是条，不能用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们战线上坚守了三天。", "corrected_sentence": "士兵们在战线上坚守了三天。", "error_description": "错误：“战线上”前缺少“在”。正确：“在战线上坚守”。表示动作发生的处所，要用“在”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根战线在河边拉得很长。", "corrected_sentence": "这条战线在河边拉得很长。", "error_description": "错误：“这根战线”。正确：“这条战线”。“战线”的量词是“条”，不能用“根”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
