INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "战线比喻某一方面的工作领域，如教育战线、卫生战线、科研战线等。", "primary_collocate": null, "pronunciation": "zhàn xiàn", "ipa": "ʈʂan˥˩ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他在教育战线工作了三十年。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们在抗疫战线上忙了很久。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在宣传战线上做了很多年的工作。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是农业战线上的老专家。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的扶贫战线太长，人手根本不够。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家们在科研战线上努力了很多年。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化战线很长，我们人太少。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在卫生战线上工作了一辈子。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条战线上的工作很辛苦。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同志讲了他们在水利战线上的事。", "target_word": "战线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "战線", "label": "繁体"}], "register": "通用", "sense_fingerprint": "比喻某一方面的工作领域（如教育、卫生、科研）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战线", "is_correct": true, "explanation": "战线：交战双方对峙的前线，或比喻某一方面的工作领域（zhàn xiàn，第四声）。"}, {"text": "展现", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展示、显现。"}, {"text": "占先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是抢先、居先。"}, {"text": "战舰", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j/x），听感相近；意思是作战用的军舰。"}], "explanations": {"战线": "战线：交战双方对峙的前线，或比喻某一方面的工作领域（zhàn xiàn，第四声）。", "展现": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展示、显现。", "占先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是抢先、居先。", "战舰": "jiàn 与 xiàn 声母不同（j/x），听感相近；意思是作战用的军舰。"}, "sentence_index": null, "correct_answer": "战线"}, "level_3": {"options": [{"text": "战线", "is_correct": true, "explanation": "战线：比喻某一方面的工作领域，这里指教育工作的领域。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是自然地理事物，不是工作领域，与“工作了三十年”不合。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是场所，不能与“教育”并列构成工作领域。"}, {"text": "河岸", "is_correct": false, "explanation": "语义：河岸是地理位置，不指可以工作的领域。"}], "explanations": {"战线": "战线：比喻某一方面的工作领域，这里指教育工作的领域。", "海洋": "语义：海洋是自然地理事物，不是工作领域，与“工作了三十年”不合。", "厨房": "搭配：“厨房”是场所，不能与“教育”并列构成工作领域。", "河岸": "语义：河岸是地理位置，不指可以工作的领域。"}, "sentence_index": 0, "correct_answer": "战线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在教育这座战线上工作了十年。", "explanation": "这里应该用〈条〉。战线的量词是条，不能用“座”。"}, {"text": "卫生这把战线上的人都很忙。", "explanation": "这里应该用〈条〉。战线的量词是条，不能用“把”。"}, {"text": "他一直在科研这颗战线上努力。", "explanation": "这里应该用〈条〉。战线的量词是条，不能用“颗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX