INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战线", "is_correct": true, "explanation": "战线：比喻某一方面的工作领域，这里指文化工作的领域，与“很长”“人太少”搭配。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是水域，不能比喻某一方面的工作领域。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用书，不能比喻某一方面的工作领域。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“车站”是场所，不能说“文化车站很长”。"}], "explanations": {"战线": "战线：比喻某一方面的工作领域，这里指文化工作的领域，与“很长”“人太少”搭配。", "河流": "语义：河流是水域，不能比喻某一方面的工作领域。", "课本": "语义：课本是学习用书，不能比喻某一方面的工作领域。", "车站": "搭配：“车站”是场所，不能说“文化车站很长”。"}, "sentence_index": 6, "correct_answer": "战线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场战线打了整整三天。", "explanation": "这里应该用〈战役〉。一场有明确目标的作战行动要说战役，战线指某一方面的工作领域，不指作战行动。"}, {"text": "我们沿着南边的这条战线出发去北京。", "explanation": "这里应该用〈路线〉。去某地的行进路线要说路线，战线不能指这种路线。"}, {"text": "这架飞机沿着这条战线飞行。", "explanation": "这里应该用〈航线〉。飞机的飞行路线要说航线，战线不能指空中的路线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这根战线上的人都很辛苦。", "corrected_sentence": "我们这条战线上的人都很辛苦。", "error_description": "错误：“这根战线”。正确：“这条战线”。“战线”的量词是“条”，不能用“根”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她医疗战线工作了二十年。", "corrected_sentence": "她在医疗战线工作了二十年。", "error_description": "错误：“医疗战线工作”缺少介词“在”。正确：“在医疗战线工作”。表示工作的处所，要用“在”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89127, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89127, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89127, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "血统是从爸爸妈妈那里一代一代传下来的血的关系。", "primary_collocate": null, "pronunciation": "xuè tǒng", "ipa": "ɕɥe˥˩ tʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个孩子有中国血统。", "target_word": "血统", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他爸爸是德国人，他有德国血统。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家的血统很特别。", "target_word": "血统", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她妈妈是日本人，所以她有日本血统。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我外公是英国人，所以我身上有英国血统。", "target_word": "血统", "complexity_tier": "T3", "furigana": "wǒ wàigōng shì Yīngguó rén, suǒyǐ wǒ shēnshang yǒu Yīngguó xuètǒng.", "sentence_source": "generated"}, {"text": "我想知道我的血统是哪里来的。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两个人有同样的血统。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "血统不同，长得也不一样。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有一半中国血统，一半法国血统。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个家族的血统传了几百年。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "血統", "label": "繁体"}, {"form": "纯血统", "label": "复合"}, {"form": "血统论", "label": "复合"}], "register": "通用", "sense_fingerprint": "父母一代代传下来的血缘关系，常指某国或某族的血", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄没有国别，“有中国年龄”说不通。"}, {"text": "血统", "is_correct": true, "explanation": "血统指父母一代代传下来的血缘关系，“有中国血统”说的是血缘来源，与句意相合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高描述身材高度，不能与“中国”搭配成“有中国身高”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有中国”后面接的是血统、国籍一类名词，体重不能这样搭配。"}], "explanations": {"年龄": "语义：年龄没有国别，“有中国年龄”说不通。", "血统": "血统指父母一代代传下来的血缘关系，“有中国血统”说的是血缘来源，与句意相合。", "身高": "体貌：身高描述身材高度，不能与“中国”搭配成“有中国身高”。", "体重": "搭配：“有中国”后面接的是血统、国籍一类名词，体重不能这样搭配。"}, "sentence_index": 0, "correct_answer": "血统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出国旅游要带血统。", "explanation": "这里应该用〈护照〉。护照是随身携带的证件，血统是血缘关系，不能带在身上。"}, {"text": "他说话有很重的血统。", "explanation": "这里应该用〈口音〉。口音指说话的发音特点，血统不指语音。"}, {"text": "他的血统一米八。", "explanation": "这里应该用〈身高〉。身高可以用米量出，血统是血缘关系，无法用米来量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闪电", "is_correct": false, "explanation": "语义：闪电是天象，不能说“有同样的闪电”。"}, {"text": "血统", "is_correct": true, "explanation": "血统指父母传下来的血缘关系，“同样的血统”说的是两人血缘相同，与句意相合。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不能说“有同样的地震”。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电学量，人没有“同样的电压”，说不通。"}], "explanations": {"闪电": "语义：闪电是天象，不能说“有同样的闪电”。", "血统": "血统指父母传下来的血缘关系，“同样的血统”说的是两人血缘相同，与句意相合。", "地震": "语义：地震是自然灾害，不能说“有同样的地震”。", "电压": "语义：电压是电学量，人没有“同样的电压”，说不通。"}, "sentence_index": 6, "correct_answer": "血统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的血统有三十公斤。", "explanation": "这里应该用〈体重〉。体重可以用公斤称量，血统是血缘关系，不能用公斤计算。"}, {"text": "今天的血统很好。", "explanation": "这里应该用〈天气〉。天气指气候状况，血统不指天气，这句话说不通。"}, {"text": "他的血统是大学本科。", "explanation": "这里应该用〈学历〉。学历指受教育的程度，血统不指教育经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一只特别的血统。", "corrected_sentence": "我家有一种特别的血统。", "error_description": "量词错误：血统应用量词“种”，不能用“只”。“只”多用于动物或成对物品中的单个，不能修饰抽象的血缘关系。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家的血统可以追溯唐朝。", "corrected_sentence": "我们家的血统可以追溯到唐朝。", "error_description": "补语错误：“追溯”后要用介词“到”引出时间终点，应说“追溯到唐朝”，不能省略“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
