INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89128, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由祖先传下来的、有血缘关系的系统。", "primary_collocate": null, "pronunciation": "xuè tǒng", "ipa": "ɕɥe˥˩ tʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这只狗的血统很纯。", "target_word": "血统", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有一半外国血统。", "target_word": "血统", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这匹马血统高贵，价格很高。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的家人都有蒙古族血统。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很骄傲，因为他有皇室血统。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这只猫是纯血统的。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候的人很看重血统。", "target_word": "血统", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人想知道自己的血统来自哪里。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家人的血统可以追溯到一千年前。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的血统不能决定他是什么样的人。", "target_word": "血统", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "血統", "label": "繁体"}, {"form": "纯血统", "label": "复合"}, {"form": "血统论", "label": "复合"}], "register": "通用", "sense_fingerprint": "祖先传下来的血缘系统，指家族或种族的来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "搭配：“纯”用于血统、品种等，不能用来形容体重。"}, {"text": "血统", "is_correct": true, "explanation": "血统指祖先传下来的血缘系统，“很纯”可以形容血统的纯正程度，与句意相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是年数，没有纯与不纯之分，“年龄很纯”说不通。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：体型指身体或外形的轮廓，不能用“很纯”来形容，句子说的是血缘。"}], "explanations": {"体重": "搭配：“纯”用于血统、品种等，不能用来形容体重。", "血统": "血统指祖先传下来的血缘系统，“很纯”可以形容血统的纯正程度，与句意相合。", "年龄": "语义：年龄是年数，没有纯与不纯之分，“年龄很纯”说不通。", "体型": "体貌：体型指身体或外形的轮廓，不能用“很纯”来形容，句子说的是血缘。"}, "sentence_index": 0, "correct_answer": "血统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的血统是A型。", "explanation": "这里应该用〈血型〉。血型指血液的类别，血统指祖先传下来的血缘系统，二者不能互换。"}, {"text": "血统把氧气送到全身。", "explanation": "这里应该用〈血液〉。血液负责运输氧气，血统是血缘关系，不承担运输功能。"}, {"text": "他的血统是一百二。", "explanation": "这里应该用〈血压〉。血压是测量出的数值，血统是血缘关系，不能用数字来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：古时候没有电脑，不能说古人看重它。"}, {"text": "血统", "is_correct": true, "explanation": "血统是祖先传下来的血缘系统，古人很看重它，与句意相合。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电学量，古人不会“看重电压”，说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古时候没有手机，不能说古人看重它。"}], "explanations": {"电脑": "语义：古时候没有电脑，不能说古人看重它。", "血统": "血统是祖先传下来的血缘系统，古人很看重它，与句意相合。", "电压": "语义：电压是电学量，古人不会“看重电压”，说不通。", "手机": "语义：古时候没有手机，不能说古人看重它。"}, "sentence_index": 6, "correct_answer": "血统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的血统比我大三岁。", "explanation": "这里应该用〈年龄〉。年龄表示岁数，血统是血缘关系，不能用来比较岁数大小。"}, {"text": "这个孩子的血统长得很快。", "explanation": "这里应该用〈身高〉。身高会随成长而增长，血统不会长高，也不能说长得快。"}, {"text": "这只狗的血统有十公斤。", "explanation": "这里应该用〈体重〉。体重可以用公斤称量，血统是血缘关系，不能用公斤计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他身上有一只特殊的血统。", "corrected_sentence": "他身上有一种特殊的血统。", "error_description": "量词错误：血统是抽象名词，应该用量词“种”，不能用“只”。“只”多用于动物或成对物品中的单个。正确说法是“一种特殊的血统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个家族的血统可以追溯明朝。", "corrected_sentence": "这个家族的血统可以追溯到明朝。", "error_description": "补语错误：“追溯”后要用介词“到”引出时间终点，应说“追溯到明朝”，不能省略“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关上", "is_correct": true, "explanation": "关上：与打开互为反义，指使盒子、门等敞开的东西闭合。"}, {"text": "拿起", "is_correct": false, "explanation": "拿起：表示用手取，与打开没有反义关系。"}, {"text": "挂上", "is_correct": false, "explanation": "挂上：表示挂在某处，与打开没有反义关系。"}, {"text": "穿上", "is_correct": false, "explanation": "穿上：表示把衣物套在身上，与打开没有反义关系。"}], "correct_answer": "关上", "explanations": {"关上": "关上：与打开互为反义，指使盒子、门等敞开的东西闭合。", "拿起": "拿起：表示用手取，与打开没有反义关系。", "挂上": "挂上：表示挂在某处，与打开没有反义关系。", "穿上": "穿上：表示把衣物套在身上，与打开没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合上", "is_correct": true, "explanation": "合上：与打开互为反义，指使本子等书页闭合。"}, {"text": "放下", "is_correct": false, "explanation": "放下：表示把东西放到某处，与打开没有反义关系。"}, {"text": "举起", "is_correct": false, "explanation": "举起：表示向上抬，与打开没有反义关系。"}, {"text": "脱下", "is_correct": false, "explanation": "脱下：表示把衣物从身上取下，与打开没有反义关系。"}], "correct_answer": "合上", "explanations": {"合上": "合上：与打开互为反义，指使本子等书页闭合。", "放下": "放下：表示把东西放到某处，与打开没有反义关系。", "举起": "举起：表示向上抬，与打开没有反义关系。", "脱下": "脱下：表示把衣物从身上取下，与打开没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使关闭的东西展开或敞开。", "primary_collocate": null, "pronunciation": "dǎ kāi", "ipa": "ta˨˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "请把窗户打开，屋里太热了。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开书，开始看第三页。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子的盖子很紧，你能帮我打开吗？", "target_word": "打开", "complexity_tier": "T3", "furigana": "zhè ge xiāng zi de gài zi hěn jǐn, nǐ néng bāng wǒ dǎ kāi ma?", "sentence_source": "generated"}, {"text": "妈妈打开盒子，里面有一个蛋糕。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开门，看见一只小猫。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开了伞，走进雨里。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们打开书，翻到第十页。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开地图，找到了去公园的路。", "target_word": "打开", "complexity_tier": "T3", "furigana": "tā dǎ kāi dì tú, zhǎo dào le qù gōng yuán de lù.", "sentence_source": "generated"}, {"text": "太冷了，别打开窗户。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开本子，写下了今天的日期。", "target_word": "打开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打开了", "label": "体标"}, {"form": "打开过", "label": "体标"}, {"form": "打開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打开：使关闭的东西（门窗、书、盒子等）展开或敞开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '464d8e31-3b58-4903-948d-c22c693dcaf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打开", "is_correct": true, "explanation": "打开：使窗户展开或敞开，屋里太热，所以要开窗。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去灰尘，与“屋里太热”这个要求不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理，与“屋里太热”没有关系，句意不通。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：挂多用于窗帘、画等，不说“挂窗户”。"}], "explanations": {"打开": "打开：使窗户展开或敞开，屋里太热，所以要开窗。", "擦": "语义：擦是抹去灰尘，与“屋里太热”这个要求不符。", "修": "语义：修是修理，与“屋里太热”没有关系，句意不通。", "挂": "搭配：挂多用于窗帘、画等，不说“挂窗户”。"}, "sentence_index": 0, "correct_answer": "打开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打开了谜底。", "explanation": "这里应该用〈揭开〉。谜底、真相要用“揭开”，打开只用于门、盒子等具体的东西。"}, {"text": "他打开了一个人。", "explanation": "这里应该用〈找〉。“打开”只用于能展开或敞开的东西，不能用于人，找人要说“找”。"}, {"text": "他打开了那场比赛。", "explanation": "这里应该用〈开始〉。比赛要用“开始”，打开表示使东西展开或敞开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打开", "is_correct": true, "explanation": "打开：使书展开，翻到第十页才能看到内容。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕书会弄坏书页，与“翻到第十页”的要求不符。"}, {"text": "掀", "is_correct": false, "explanation": "搭配：掀多用于盖子、被子，不说“掀书”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔掉书就无法翻到第十页，与句意矛盾。"}], "explanations": {"打开": "打开：使书展开，翻到第十页才能看到内容。", "撕": "语义：撕书会弄坏书页，与“翻到第十页”的要求不符。", "掀": "搭配：掀多用于盖子、被子，不说“掀书”。", "扔": "语义：扔掉书就无法翻到第十页，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "打开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打开了一家公司。", "explanation": "这里应该用〈开办〉。公司、学校要用“开办”，打开只用于门、盒子等能敞开的东西。"}, {"text": "他打开了一场病。", "explanation": "这里应该用〈治好〉。病要用“治好”，打开不能用于疾病。"}, {"text": "他打开了一场会议。", "explanation": "这里应该用〈召开〉。会议要用“召开”，打开不用于会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把窗户打开了，好吗？", "corrected_sentence": "请把窗户打开，好吗？", "error_description": "体标错误：祈使句“请……”表示请求对方做某事，句末不用“了”。“了”应删去，应说“请把窗户打开，好吗？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王把包打开了了，拿出了一本书。", "corrected_sentence": "小王把包打开了，拿出了一本书。", "error_description": "体标重复：“打开”后只用一个“了”表示完成，多出的“了”要删去。应说“小王把包打开了，拿出了一本书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
