INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89132, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用桶等容器从井、河或水源处取水。", "primary_collocate": null, "pronunciation": "dǎ shuǐ", "ipa": "ta˨˩˦ ʂueɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "早上奶奶去井边打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明拿着桶去河边打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里没有自来水，大家都去井里打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天早上都要打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我帮妈妈去打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在山下的小河边打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提着两个桶去打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以前，我要去打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用旧桶在井边打水。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打水的时候，要小心滑倒。", "target_word": "打水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了水", "label": "完成体（了）"}, {"form": "打过水", "label": "经历体（过）"}], "register": "口语", "sense_fingerprint": "用桶从井、河等水源处取水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '790811c9-6e97-424f-b6aa-eb7a3bd287ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打水", "is_correct": true, "explanation": "打水指用桶从井边取水，与“井边”的语境相符，符合句意。"}, {"text": "买菜", "is_correct": false, "explanation": "搭配：井边是取水的地方，不能在那里买菜，“去井边买菜”与句意不搭。"}, {"text": "看病", "is_correct": false, "explanation": "语义：去井边看病与句中的取水场景冲突，句子说的是奶奶取水。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：井边不适合下棋，“去井边下棋”与早上取水的语境不符。"}], "explanations": {"打水": "打水指用桶从井边取水，与“井边”的语境相符，符合句意。", "买菜": "搭配：井边是取水的地方，不能在那里买菜，“去井边买菜”与句意不搭。", "看病": "语义：去井边看病与句中的取水场景冲突，句子说的是奶奶取水。", "下棋": "语义：井边不适合下棋，“去井边下棋”与早上取水的语境不符。"}, "sentence_index": 0, "correct_answer": "打水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用机器打水，把地下室的积水排了出去。", "explanation": "这里应该用〈抽水〉。打水指用桶等容器从水源取水，用机器把水抽出来要说抽水。"}, {"text": "花园里的花干了，她用水壶给花打水。", "explanation": "这里应该用〈浇水〉。打水指用桶等容器从水源取水，给花喝水要说浇水。"}, {"text": "他用打气筒给篮球打水，球很快就鼓起来了。", "explanation": "这里应该用〈打气〉。打水指从水源取水，给篮球充气要说打气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打水", "is_correct": true, "explanation": "打水指提着桶去水源取水，符合句中“提着两个桶”的情境。"}, {"text": "上学", "is_correct": false, "explanation": "语义：提着两个桶去上学，“去上学”与“提着两个桶”的情境不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：提着桶去睡觉，动作与句中的“提着两个桶”不搭配。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：拿着桶去游泳，桶与游泳的动作互不相关。"}], "explanations": {"打水": "打水指提着桶去水源取水，符合句中“提着两个桶”的情境。", "上学": "语义：提着两个桶去上学，“去上学”与“提着两个桶”的情境不符。", "睡觉": "搭配：提着桶去睡觉，动作与句中的“提着两个桶”不搭配。", "游泳": "语义：拿着桶去游泳，桶与游泳的动作互不相关。"}, "sentence_index": 6, "correct_answer": "打水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "楼上的厕所坏了，一直不打水。", "explanation": "这里应该用〈冲水〉。打水指取水，冲厕所要说冲水。"}, {"text": "他用水管给汽车打水，把车冲得干干净净。", "explanation": "这里应该用〈冲洗〉。打水指用容器从水源取水，用水管冲车要说冲洗。"}, {"text": "他给自行车胎打水，胎越打越硬。", "explanation": "这里应该用〈打气〉。打水指从水源取水，给车胎充气要说打气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打水得很快。", "corrected_sentence": "他打水打得很快。", "error_description": "补语错误：“打水”是动宾结构，程度补语不能直接接在“打水”之后用“得”，应重复动词说“打水打得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天早上去河边打水，一共打了两个水。", "corrected_sentence": "他昨天早上去河边打水，一共打了两桶水。", "error_description": "量词错误：“水”按容器计量应用“桶”，不能用“个”，应说“打了两桶水”，不能说“打了两个水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
