INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89133, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "行人是在路上走路的人。", "primary_collocate": null, "pronunciation": "xíng rén", "ipa": "ɕiŋ˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "马路上有很多行人。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮了，行人要停下来。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机看见行人，马上停车。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行人应该走人行道。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥上的行人不多。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，行人都走得很快。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街没有红绿灯，行人过马路很危险。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上路灯很暗，行人很少。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车要让行人先走。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有个行人在过马路。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "行人天桥", "label": "复合"}], "register": "中性", "sense_fingerprint": "在路上走路的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89133, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行人", "is_correct": true, "explanation": "正确答案：行人，指在路上走路的人。"}, {"text": "情人", "is_correct": false, "explanation": "声母 q 与 x 不同（qíng 与 xíng），意思是恋爱中的一方。"}, {"text": "新人", "is_correct": false, "explanation": "xīn 与 xíng 韵尾和声调不同，意思是刚来的人或新婚的人。"}, {"text": "杏仁", "is_correct": false, "explanation": "声调不同：xìng（第四声）与 xíng（第二声）不同，意思是杏子的果仁。"}], "explanations": {"行人": "正确答案：行人，指在路上走路的人。", "情人": "声母 q 与 x 不同（qíng 与 xíng），意思是恋爱中的一方。", "新人": "xīn 与 xíng 韵尾和声调不同，意思是刚来的人或新婚的人。", "杏仁": "声调不同：xìng（第四声）与 xíng（第二声）不同，意思是杏子的果仁。"}, "sentence_index": null, "correct_answer": "行人"}, "level_3": {"options": [{"text": "行人", "is_correct": true, "explanation": "正确：“行人”指在路上走路的人，马路上当然有很多行人。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，不会出现在马路上。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵在天空中飘，与“马路上”的位置不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：说“马路上有很多……”指可以看见的人或车，空气不是这样描述的对象。"}], "explanations": {"行人": "正确：“行人”指在路上走路的人，马路上当然有很多行人。", "星星": "语义：星星在天上，不会出现在马路上。", "云朵": "语义：云朵在天空中飘，与“马路上”的位置不符。", "空气": "语义：说“马路上有很多……”指可以看见的人或车，空气不是这样描述的对象。"}, "sentence_index": 0, "correct_answer": "行人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是修车的行人，什么毛病都能看出来。", "explanation": "这里应该用〈行家〉。行人指在路上走路的人，对某方面很内行的人要说“行家”。"}, {"text": "开车的行人很有经验。", "explanation": "这里应该用〈司机〉。开车的人是司机，行人是在路上走路的人，不能开车。"}, {"text": "路口的行人正在指挥交通。", "explanation": "这里应该用〈交警〉。指挥交通的是交警，行人不能指挥交通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89133, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行人", "is_correct": true, "explanation": "正确答案：行人，指在路上走路的人。"}, {"text": "亲人", "is_correct": false, "explanation": "读音不同：qīn rén 与 xíng rén 声母、韵母和声调都不同，意思是家里的人。"}, {"text": "仙人", "is_correct": false, "explanation": "读音不同：xiān（第一声，-ian）与 xíng（第二声，-ing）不同，意思是神话里的神仙。"}, {"text": "行文", "is_correct": false, "explanation": "第二个字读音不同：wén 与 rén 声母不同，意思是写文章的方式。"}], "explanations": {"行人": "正确答案：行人，指在路上走路的人。", "亲人": "读音不同：qīn rén 与 xíng rén 声母、韵母和声调都不同，意思是家里的人。", "仙人": "读音不同：xiān（第一声，-ian）与 xíng（第二声，-ing）不同，意思是神话里的神仙。", "行文": "第二个字读音不同：wén 与 rén 声母不同，意思是写文章的方式。"}, "sentence_index": null, "correct_answer": "行人"}, "level_3": {"options": [{"text": "行人", "is_correct": true, "explanation": "正确：“行人”指步行的人，句中说的是过马路时的人。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不会自己过马路，与句意不符。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水里，不能过马路。"}, {"text": "树", "is_correct": false, "explanation": "语义：树固定在地上，不会过马路。"}], "explanations": {"行人": "正确：“行人”指步行的人，句中说的是过马路时的人。", "雨伞": "语义：雨伞不会自己过马路，与句意不符。", "鱼": "语义：鱼生活在水里，不能过马路。", "树": "语义：树固定在地上，不会过马路。"}, "sentence_index": 6, "correct_answer": "行人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫是行人。", "explanation": "“行人”只指走路的人，小猫是动物，要说“动物”或“宠物”。"}, {"text": "那棵大树是行人。", "explanation": "“行人”只指人，大树是植物，不能用“行人”指它。"}, {"text": "这辆红色汽车是行人。", "explanation": "“行人”指步行的人，汽车是车辆，不能用“行人”指它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上有很多行人们。", "corrected_sentence": "街上有很多行人。", "error_description": "“们”用错：“很多”已经表示数量多，“行人”后面不能再加“们”，应说“很多行人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看见两个的行人在等车。", "corrected_sentence": "我看见两个行人在等车。", "error_description": "多余的“的”：数量短语和名词之间不用“的”，应说“两个行人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
