INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89134, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在道路上行走的人。", "primary_collocate": null, "pronunciation": "xíng rén", "ipa": "ɕiŋ˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "行人在人行道上慢慢走。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时，行人要看红绿灯。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个路口每天有几千个行人经过。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有两个行人停在路边看地图。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时要注意行人。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太大，街上几乎没有行人。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行人过街请走斑马线。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位行人向我问路。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行人和车辆都要守规则。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是行人专用路，汽车不能进。", "target_word": "行人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "行人天桥", "label": "复合"}], "register": "中性", "sense_fingerprint": "在道路上行走的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行人", "is_correct": true, "explanation": "正确答案：行人，指在道路上行走的人。"}, {"text": "情人", "is_correct": false, "explanation": "声母 q 与 x 不同（qíng 与 xíng），意思是恋爱中的一方。"}, {"text": "新人", "is_correct": false, "explanation": "韵母不同（xīn 为 -in，xíng 为 -ing），且声调不同，意思是刚来的人或新婚的人。"}, {"text": "杏仁", "is_correct": false, "explanation": "声调不同：xìng（第四声）与 xíng（第二声），意思是杏子的果仁。"}], "explanations": {"行人": "正确答案：行人，指在道路上行走的人。", "情人": "声母 q 与 x 不同（qíng 与 xíng），意思是恋爱中的一方。", "新人": "韵母不同（xīn 为 -in，xíng 为 -ing），且声调不同，意思是刚来的人或新婚的人。", "杏仁": "声调不同：xìng（第四声）与 xíng（第二声），意思是杏子的果仁。"}, "sentence_index": null, "correct_answer": "行人"}, "level_3": {"options": [{"text": "行人", "is_correct": true, "explanation": "正确：“行人”指在道路上行走的人，正是会在人行道上慢慢走的人。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车一般在车道上行驶，不会在人行道上慢慢走。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己走路，与“慢慢走”不符。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵在天空中飘，不会在人行道上走。"}], "explanations": {"行人": "正确：“行人”指在道路上行走的人，正是会在人行道上慢慢走的人。", "汽车": "语义：汽车一般在车道上行驶，不会在人行道上慢慢走。", "石头": "语义：石头不会自己走路，与“慢慢走”不符。", "云朵": "语义：云朵在天空中飘，不会在人行道上走。"}, "sentence_index": 0, "correct_answer": "行人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "坐公交车的行人很多。", "explanation": "这里应该用〈乘客〉。坐车的人是乘客，行人是在路上走路的人。"}, {"text": "飞机上的行人都系好了安全带。", "explanation": "这里应该用〈乘客〉。坐飞机的人是乘客，行人是在路上走路的人。"}, {"text": "开公交车的行人很认真。", "explanation": "这里应该用〈司机〉。开公交车的是司机，行人不能开车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89134, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行人", "is_correct": true, "explanation": "正确答案：行人，指在道路上行走的人。"}, {"text": "亲人", "is_correct": false, "explanation": "读音不同：qīn rén 与 xíng rén 声母、韵母和声调都不同，意思是家里的人。"}, {"text": "仙人", "is_correct": false, "explanation": "读音不同：xiān（第一声，-ian）与 xíng（第二声，-ing）不同，意思是神话里的神仙。"}, {"text": "行文", "is_correct": false, "explanation": "第二个字读音不同：wén 与 rén 声母不同，意思是写文章的方式。"}], "explanations": {"行人": "正确答案：行人，指在道路上行走的人。", "亲人": "读音不同：qīn rén 与 xíng rén 声母、韵母和声调都不同，意思是家里的人。", "仙人": "读音不同：xiān（第一声，-ian）与 xíng（第二声，-ing）不同，意思是神话里的神仙。", "行文": "第二个字读音不同：wén 与 rén 声母不同，意思是写文章的方式。"}, "sentence_index": null, "correct_answer": "行人"}, "level_3": {"options": [{"text": "行人", "is_correct": true, "explanation": "正确：“行人”指步行的人，过街时请走斑马线的是行人。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用来挡雨的物品，不会过街，也不会走斑马线。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会去看斑马线，与“过街请走斑马线”的对象不符。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“过街”的主语应是人，不能说“花瓶过街”。"}], "explanations": {"行人": "正确：“行人”指步行的人，过街时请走斑马线的是行人。", "雨伞": "语义：雨伞是用来挡雨的物品，不会过街，也不会走斑马线。", "小猫": "语义：小猫不会去看斑马线，与“过街请走斑马线”的对象不符。", "花瓶": "搭配：“过街”的主语应是人，不能说“花瓶过街”。"}, "sentence_index": 6, "correct_answer": "行人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是摄影的行人，拍的照片很好看。", "explanation": "这里应该用〈行家〉。行人指走路的人，对某方面很内行的人要说“行家”。"}, {"text": "那块石头是行人。", "explanation": "“行人”只指人，石头是无生命的物体，不能用“行人”指它。"}, {"text": "这台电脑是行人。", "explanation": "“行人”只指人，电脑是电子设备，不能用“行人”指它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路上有三只行人。", "corrected_sentence": "路上有三个行人。", "error_description": "量词用错：“行人”指人，量词应用“个”，不能用“只”（“只”多用于动物等）。应说“路上有三个行人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些行人们都在等红灯。", "corrected_sentence": "这些行人都在等红灯。", "error_description": "“们”用错：“这些”已经表示复数，后面不能再加“们”，应说“这些行人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
