INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "日日是每一天,天天。", "primary_collocate": null, "pronunciation": "rì rì", "ipa": "ɻ̩˥˩ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他日日喝茶，已经成了习惯。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟日日玩游戏，作业都忘了写。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店日日有人排队买面包。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶日日念叨着孙子。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我日日坐地铁上班，很方便。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫日日睡在窗台上晒太阳。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她日日给花浇水，这个习惯坚持了好几年，花开得很好。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他日日加班，身体越来越累。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，爷爷日日烧水泡脚。", "target_word": "日日", "complexity_tier": "T3", "furigana": "dōng tiān dào le, yé ye rì rì shāo shuǐ pào jiǎo.", "sentence_source": "generated"}, {"text": "孩子们日日盼着过年。", "target_word": "日日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日日夜夜", "label": "复合"}], "register": "书面", "sense_fingerprint": "日日:每一天,天天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 小猫 (Zipf 3.7), 窗 (Zipf 3.98), 晒太阳 (Zipf 3.4)']::text[], '1a2d37c5-ce5a-420d-8d73-ab1cf9e08d40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日日", "is_correct": true, "explanation": "日日（rì rì）：每一天、天天，正确答案。"}, {"text": "日历", "is_correct": false, "explanation": "日历（rì lì）：第二个音节 lì 与 rì 声母不同（l 与 r），意思是日历，不是“每一天”。"}, {"text": "日式", "is_correct": false, "explanation": "日式（rì shì）：第二个音节 shì 与 rì 声母不同（sh 与 r），意思是日本式的。"}, {"text": "日志", "is_correct": false, "explanation": "日志（rì zhì）：第二个音节 zhì 与 rì 声母不同（zh 与 r），意思是日志、记录。"}, {"text": "日记", "is_correct": false, "explanation": "日记（rì jì）：第二个音节 jì 与 rì 声母不同（j 与 r），意思是日记本。"}], "explanations": {"日日": "日日（rì rì）：每一天、天天，正确答案。", "日历": "日历（rì lì）：第二个音节 lì 与 rì 声母不同（l 与 r），意思是日历，不是“每一天”。", "日式": "日式（rì shì）：第二个音节 shì 与 rì 声母不同（sh 与 r），意思是日本式的。", "日志": "日志（rì zhì）：第二个音节 zhì 与 rì 声母不同（zh 与 r），意思是日志、记录。", "日记": "日记（rì jì）：第二个音节 jì 与 rì 声母不同（j 与 r），意思是日记本。"}, "sentence_index": null, "correct_answer": "日日"}, "level_3": {"options": [{"text": "日日", "is_correct": true, "explanation": "日日：每一天都喝茶，与“已经成了习惯”的说法相合。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示刚发生的事，与“已经成了习惯”的长期状态相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“已经成了习惯”的说法相矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指出乎意料的一次性事件，与“已经成了习惯”的长期状态相矛盾。"}], "explanations": {"日日": "日日：每一天都喝茶，与“已经成了习惯”的说法相合。", "刚刚": "语义：“刚刚”表示刚发生的事，与“已经成了习惯”的长期状态相矛盾。", "偶尔": "语义：“偶尔”表示不常发生，与“已经成了习惯”的说法相矛盾。", "突然": "语义：“突然”指出乎意料的一次性事件，与“已经成了习惯”的长期状态相矛盾。"}, "sentence_index": 0, "correct_answer": "日日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他日日过生日。", "explanation": "这里不能用〈日日〉：生日每年只有一次，“日日”指每天重复，应改用〈每年〉。"}, {"text": "公司日日召开年会。", "explanation": "这里不能用〈日日〉：年会每年只开一次，应改用〈每年〉。"}, {"text": "他日日当选班长。", "explanation": "这里不能用〈日日〉：当选班长是一次性的事件，应改用〈终于〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日日", "is_correct": true, "explanation": "日日：每天都给花浇水，表示每天的照料习惯，与“花开得很好”相合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能修饰“给花浇水”这样的动作。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指即将发生的近期动作，与“坚持了好几年”的长期习惯不合。"}, {"text": "从来", "is_correct": false, "explanation": "用法：“从来”通常与否定词连用（如“从来不”），且与“坚持了好几年”的持续习惯相矛盾。"}], "explanations": {"日日": "日日：每天都给花浇水，表示每天的照料习惯，与“花开得很好”相合。", "非常": "搭配：“非常”修饰形容词或心理动词，不能修饰“给花浇水”这样的动作。", "马上": "语义：“马上”指即将发生的近期动作，与“坚持了好几年”的长期习惯不合。", "从来": "用法：“从来”通常与否定词连用（如“从来不”），且与“坚持了好几年”的持续习惯相矛盾。"}, "sentence_index": 6, "correct_answer": "日日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她日日出国留学。", "explanation": "这里不能用〈日日〉：出国留学是一次性的事，“日日”指每天重复，应改用〈终于〉。"}, {"text": "我们日日过春节。", "explanation": "这里不能用〈日日〉：春节每年只有一次，应改用〈每年〉。"}, {"text": "他日日考上大学。", "explanation": "这里不能用〈日日〉：考上大学只发生一次，“日日”指每天重复，应改用〈终于〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很日日打扫房间，家里干净多了。", "corrected_sentence": "妈妈日日打扫房间，家里干净多了。", "error_description": "错误在于“很”。“日日”本身已表示每天，是频率副词，不能再被程度副词“很”修饰，应说“日日打扫房间”，不能说“很日日打扫房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他日日了练琴，手艺越来越好。", "corrected_sentence": "他日日练琴，手艺越来越好。", "error_description": "“了”不能放在“日日”和动词“练”之间。这里说的是每天的习惯，应直接说“日日练琴”，不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89137, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "“短暂”与“持久”相对，指时间不长、不能保持。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地不硬，与“持久”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”说明白、不模糊，与“持久”不构成反义。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”说速度快，与“持久”的时间长短不构成反义。"}], "correct_answer": "短暂", "explanations": {"短暂": "“短暂”与“持久”相对，指时间不长、不能保持。", "柔软": "“柔软”形容质地不硬，与“持久”没有反义关系。", "清楚": "“清楚”说明白、不模糊，与“持久”不构成反义。", "迅速": "“迅速”说速度快，与“持久”的时间长短不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89137, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "“短暂”与“持久”相对，指时间不长、不能保持。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”形容温度低，与“持久”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”说光线充足，与“持久”不构成反义。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”说心情或状态不紧张，与“持久”不构成反义。"}], "correct_answer": "短暂", "explanations": {"短暂": "“短暂”与“持久”相对，指时间不长、不能保持。", "寒冷": "“寒冷”形容温度低，与“持久”没有反义关系。", "明亮": "“明亮”说光线充足，与“持久”不构成反义。", "轻松": "“轻松”说心情或状态不紧张，与“持久”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89137, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "持久是说能一直保持，很长时间不会变。", "primary_collocate": null, "pronunciation": "chí jiǔ", "ipa": "ʈʂʰɻ̩˧˥ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们的友谊非常持久。", "target_word": "持久", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种香味很持久。", "target_word": "持久", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "只有坚持努力，好成绩才能持久。", "target_word": "持久", "complexity_tier": "T3", "furigana": "zhǐ yǒu jiān chí nǔ lì, hǎo chéng jì cái néng chí jiǔ.", "sentence_source": "generated"}, {"text": "这种爱情很难持久。", "target_word": "持久", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新鲜感通常不持久。", "target_word": "持久", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的好心情很持久，一整天都很开心。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这款口红的颜色持久，一天不会掉。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个药的效果不持久，需要每天吃。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对音乐的兴趣很持久。", "target_word": "持久", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好的关系需要持久的信任。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不持久", "label": "否定"}, {"form": "持久性", "label": "派生"}, {"form": "持久战", "label": "复合"}], "register": "书面", "sense_fingerprint": "状态、效果、感情长时间保持不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持久", "is_correct": true, "explanation": "“持久”指能长时间保持，与“友谊非常……”的句意相符。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”说的是味道，不能用来形容友谊。"}, {"text": "湿润", "is_correct": false, "explanation": "语义：“湿润”形容含水分的状态，不能修饰友谊。"}, {"text": "清秀", "is_correct": false, "explanation": "体貌：“清秀”形容人或物的外貌，与友谊不搭配。"}], "explanations": {"持久": "“持久”指能长时间保持，与“友谊非常……”的句意相符。", "辣": "语义：“辣”说的是味道，不能用来形容友谊。", "湿润": "语义：“湿润”形容含水分的状态，不能修饰友谊。", "清秀": "体貌：“清秀”形容人或物的外貌，与友谊不搭配。"}, "sentence_index": 0, "correct_answer": "持久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个假期很持久，我们玩了一个月。", "explanation": "这里应该用〈长〉。持久强调状态或效果长时间保持，说时间的长短要用〈长〉。"}, {"text": "这条路很持久，走了一下午还没到。", "explanation": "这里应该用〈远〉。持久说状态或效果长时间保持，说路程的远近要用〈远〉。"}, {"text": "这个班的人数很持久，足足有六十个人。", "explanation": "这里应该用〈多〉。持久说状态或效果长时间保持，说人数的多少要用〈多〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持久", "is_correct": true, "explanation": "“持久”指颜色能一直保持，与“一天不会掉”相符。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”说温度高，不能用来描述颜色。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来说颜色。"}, {"text": "俊俏", "is_correct": false, "explanation": "体貌：“俊俏”形容人的相貌，不能用来说颜色。"}], "explanations": {"持久": "“持久”指颜色能一直保持，与“一天不会掉”相符。", "烫": "语义：“烫”说温度高，不能用来描述颜色。", "清脆": "语义：“清脆”形容声音，不能用来说颜色。", "俊俏": "体貌：“俊俏”形容人的相貌，不能用来说颜色。"}, "sentence_index": 6, "correct_answer": "持久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子很持久，比爸爸还高一头。", "explanation": "这里应该用〈高〉。持久说状态或效果长时间保持，不用来比较身高。"}, {"text": "这条裤子很持久，我穿着太长了。", "explanation": "这里应该用〈长〉。持久说状态或效果长时间保持，不用来形容裤子的长短。"}, {"text": "这座老房子的面积很持久，有五百平方米。", "explanation": "这里应该用〈大〉。持久说状态或效果长时间保持，说面积的大小要用〈大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段持久地关系让人羡慕。", "corrected_sentence": "这段持久的关系让人羡慕。", "error_description": "“持久”修饰名词“关系”时要用“的”，不用“地”；“地”用来修饰动词，后面不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种香皂的香味留很持久。", "corrected_sentence": "这种香皂的香味留得很持久。", "error_description": "补语要用“得”连接：“留得很持久”。这里漏掉了“得”，应为“留得”，不能直接说“留很持久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
