INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89138, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能长时间保持不变或不间断。", "primary_collocate": null, "pronunciation": "chí jiǔ", "ipa": "ʈʂʰɻ̩˧˥ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这场持久的谈判终于结束了。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑马拉松需要很持久的耐力。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一场持久的战斗，大家都累了。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学外语要靠持久的努力。", "target_word": "持久", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的体力很持久，能一直跑下去。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "观众给了他们持久的掌声。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种运动不太激烈，但是很持久。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民们和洪水作了持久的斗争。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想拿第一，必须有持久的耐心。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场争论既激烈又持久，谁也不让谁。", "target_word": "持久", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不持久", "label": "否定"}, {"form": "持久性", "label": "派生"}, {"form": "持久战", "label": "复合"}], "register": "书面", "sense_fingerprint": "活动、体力、努力长时间不间断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持久", "is_correct": true, "explanation": "“持久”指长时间不间断，与“谈判终于结束了”相符。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线，不能用来修饰谈判。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容味道，不能用来修饰谈判。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材或体形，不能用来修饰谈判。"}], "explanations": {"持久": "“持久”指长时间不间断，与“谈判终于结束了”相符。", "明亮": "语义：“明亮”形容光线，不能用来修饰谈判。", "香甜": "语义：“香甜”形容味道，不能用来修饰谈判。", "矮小": "体貌：“矮小”形容身材或体形，不能用来修饰谈判。"}, "sentence_index": 0, "correct_answer": "持久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的讨论很持久，几分钟就结束了。", "explanation": "这里应该用〈短暂〉。持久指能长时间不间断，讨论几分钟就结束，应该用〈短暂〉。"}, {"text": "这场大雨很持久，一会儿就停了。", "explanation": "这里应该用〈短暂〉。持久指能长时间不间断，雨一会儿就停，应该用〈短暂〉。"}, {"text": "这次停电很持久，只停了两分钟。", "explanation": "这里应该用〈短暂〉。持久指能长时间不间断，停电只有两分钟，应该用〈短暂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持久", "is_correct": true, "explanation": "“持久”指不间断、能长时间坚持，与“不太激烈，但是很……”相符。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”形容温度高，不能用来形容运动的持续性。"}, {"text": "甜美", "is_correct": false, "explanation": "体貌：“甜美”形容容貌或声音的美好，不能用来形容运动。"}, {"text": "尖锐", "is_correct": false, "explanation": "语义：“尖锐”形容物体末端细或言辞锋利，不能用来形容运动的持续性。"}], "explanations": {"持久": "“持久”指不间断、能长时间坚持，与“不太激烈，但是很……”相符。", "滚烫": "语义：“滚烫”形容温度高，不能用来形容运动的持续性。", "甜美": "体貌：“甜美”形容容貌或声音的美好，不能用来形容运动。", "尖锐": "语义：“尖锐”形容物体末端细或言辞锋利，不能用来形容运动的持续性。"}, "sentence_index": 6, "correct_answer": "持久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛很持久，一个球就决出了胜负。", "explanation": "这里应该用〈短暂〉。持久指能长时间不间断，一个球就决出胜负要用〈短暂〉。"}, {"text": "他的反应很持久，一下子就做出来了。", "explanation": "这里应该用〈迅速〉。持久说时间长，不用来形容反应的速度。"}, {"text": "校长的讲话很持久，一分钟就讲完了。", "explanation": "这里应该用〈简短〉。持久指能长时间不间断，讲话一分钟就结束要用〈简短〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有持久地耐心。", "corrected_sentence": "他有持久的耐心。", "error_description": "“持久”修饰名词“耐心”时要用“的”，不用“地”；“地”用来修饰动词，后面不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场雨下很持久，一直没停。", "corrected_sentence": "这场雨下得很持久，一直没停。", "error_description": "补语要用“得”连接：“下得很持久”。这里漏掉了“得”，不能直接说“下很持久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
