INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一学科或行业中使用的专门用语。", "primary_collocate": null, "pronunciation": "shù yǔ", "ipa": "ʂu˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书里有很多科学术语。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律术语对学生来说很难。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上解释了这个医学术语。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你查一下这个术语是什么意思。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个术语只用在数学课里。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "论文里的术语要写得准确。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习物理时，要先记住很多术语。", "target_word": "术语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把英文术语翻译成了中文。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词是计算机领域的术语。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先学会这些基本术语。", "target_word": "术语", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个术语", "label": "量词"}, {"form": "術語", "label": "繁体"}, {"form": "专业术语", "label": "复合"}], "register": "中性", "sense_fingerprint": "学科或行业中使用的专门用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "术语", "is_correct": true, "explanation": "正确：“科学术语”指某一学科的专门用语，与“这本书里”的语境相合。"}, {"text": "海鲜", "is_correct": false, "explanation": "搭配：“科学”修饰知识、方法等抽象事物，不修饰“海鲜”，句意不通。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“科学饺子”不是常见搭配，“科学”一般不用来修饰食物。"}, {"text": "大象", "is_correct": false, "explanation": "语义：“大象”是动物，不能作为“科学”一类的内容在书中大量出现。"}], "explanations": {"术语": "正确：“科学术语”指某一学科的专门用语，与“这本书里”的语境相合。", "海鲜": "搭配：“科学”修饰知识、方法等抽象事物，不修饰“海鲜”，句意不通。", "饺子": "搭配：“科学饺子”不是常见搭配，“科学”一般不用来修饰食物。", "大象": "语义：“大象”是动物，不能作为“科学”一类的内容在书中大量出现。"}, "sentence_index": 0, "correct_answer": "术语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你查一下这头术语是什么意思。", "explanation": "这里应该用〈个〉或〈种〉。量词“头”用于牛、猪等动物，不用于术语。"}, {"text": "请你查一下这把术语是什么意思。", "explanation": "这里应该用〈个〉或〈种〉。量词“把”用于有把手的器具，不用于术语。"}, {"text": "请你查一下这张术语是什么意思。", "explanation": "这里应该用〈个〉或〈种〉。量词“张”用于平面的东西，不用于术语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "术语", "is_correct": true, "explanation": "正确：“术语”是学科的专门用语，与“学习物理时要先记住”相合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是需要记住的学科内容，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是物体，不是可以“记住”的学科知识。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“记住”可接知识、名称，“椅子”是具体物件，不构成这一搭配。"}], "explanations": {"术语": "正确：“术语”是学科的专门用语，与“学习物理时要先记住”相合。", "空气": "语义：“空气”不是需要记住的学科内容，句意不通。", "石头": "语义：“石头”是物体，不是可以“记住”的学科知识。", "椅子": "搭配：“记住”可接知识、名称，“椅子”是具体物件，不构成这一搭配。"}, "sentence_index": 6, "correct_answer": "术语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶常说一些术语，教我们做人的道理。", "explanation": "这里应该用〈俗语〉。术语是行业的专门用语，讲做人道理的民间说法是俗语。"}, {"text": "运动员们高喊着加油的术语。", "explanation": "这里应该用〈口号〉。术语是专门用语，不是高声喊出来的话，应说“加油的口号”。"}, {"text": "我给小狗起的术语是“旺财”。", "explanation": "这里应该用〈名字〉。术语指专门用语，给小狗起的名字应说“名字”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门课里有几本重要的术语。", "corrected_sentence": "这门课里有几个重要的术语。", "error_description": "量词错误：“术语”应与“个”或“种”搭配，“本”用于书籍。正确形式是「几个重要的术语」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前学过这个术语们。", "corrected_sentence": "我以前学过这个术语。", "error_description": "复数标记错误：“们”只用于指人的名词，“术语”是事物，不能加“们”，应说“这个术语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在几样事物中突出这一个，比别的都更加突出。", "primary_collocate": null, "pronunciation": "zuì shì", "ipa": "tsweɪ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "春天的花园里，最是桃花开得好看。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多礼物，最是妈妈送的那本书让我难忘。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都很热情，最是小王对我好。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的小城很安静，最是下雨的时候让人想家。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人坐在一起吃饭，最是这个时候让人开心。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了很多画，最是那张山水画让我喜欢。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的话不多，最是那句“慢慢来”我记得清楚。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的天空很蓝，最是傍晚的云好看。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱过很多歌，最是那首老歌让人感动。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江边风景很多，最是夜里的灯光美。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，放在形容词或小句前，表示在几样东西里这一个比别的都更加突出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 夜里 (Zipf 3.96), 小城 (Zipf 3.69), 想家 (Zipf 3.1)']::text[], '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最是", "is_correct": true, "explanation": "正确。句中在春天的花园里突出桃花开得最好看。"}, {"text": "偏", "is_correct": false, "explanation": "语义：“偏”表示与预期相反，句中没有这种对比。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前文没有需要转折的内容。"}, {"text": "越", "is_correct": false, "explanation": "搭配：“越”要成对使用（越……越……），不能单独修饰“桃花开得好看”。"}], "explanations": {"最是": "正确。句中在春天的花园里突出桃花开得最好看。", "偏": "语义：“偏”表示与预期相反，句中没有这种对比。", "却": "语义：“却”表示转折，前文没有需要转折的内容。", "越": "搭配：“越”要成对使用（越……越……），不能单独修饰“桃花开得好看”。"}, "sentence_index": 0, "correct_answer": "最是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最是随便看看，没有买东西。", "explanation": "这里应该用〈只是〉。最是要在几样事物中突出一个，这里只是轻描淡写地叙述，没有比较的对象。"}, {"text": "我昨天在家看书，最是看了一个下午。", "explanation": "这里应该用〈只〉。最是要在几样事物中突出程度最高的一个，单纯说明看了多久时要用只。"}, {"text": "我们周末最是一起去公园散步。", "explanation": "这里应该用〈经常〉。最是要在几样事物中突出程度最高的一个，表示惯常做某事时要用经常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最是", "is_correct": true, "explanation": "正确。句中突出老人的话不多，而那句“慢慢来”让人印象最深。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或动词，不能直接修饰“那句‘慢慢来’”这样的名词短语。"}, {"text": "居然", "is_correct": false, "explanation": "语义：“居然”表示出乎意料，句中没有意外的情况。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“记得清楚”的强调不符。"}], "explanations": {"最是": "正确。句中突出老人的话不多，而那句“慢慢来”让人印象最深。", "十分": "搭配：“十分”修饰形容词或动词，不能直接修饰“那句‘慢慢来’”这样的名词短语。", "居然": "语义：“居然”表示出乎意料，句中没有意外的情况。", "偶尔": "语义：“偶尔”表示不常发生，与“记得清楚”的强调不符。"}, "sentence_index": 6, "correct_answer": "最是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这最是我要找的人。", "explanation": "这里应该用〈就是〉。最是要在几样事物中突出一个，这里只是肯定，没有比较的对象。"}, {"text": "我最是很爱吃鱼。", "explanation": "这里应该用〈非常〉。最是表示在几样事物中突出一个，与“很”并用语义重复；单纯表示程度高时用非常。"}, {"text": "他跑得很快，最是跑了一圈就累了。", "explanation": "这里应该用〈只〉。最是表示在几样事物中突出一个，描述数量少时要用只。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上海的夜景很美，很最是外滩的灯光让人难忘。", "corrected_sentence": "上海的夜景很美，最是外滩的灯光让人难忘。", "error_description": "错误：“最是”前面不能再加程度副词“很”，两者重复。正确：“最是外滩的灯光让人难忘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个山村的景色很美，最是的清晨的雾让人难忘。", "corrected_sentence": "这个山村的景色很美，最是清晨的雾让人难忘。", "error_description": "错误：“最是”后多加了“的”，“是”与“的”连用，“最是的清晨的雾”不成句。正确：“最是清晨的雾”，“最是”后直接接名词性短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
