INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89142, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词,表示在同类中程度最高;尤其是。", "primary_collocate": null, "pronunciation": "zuì shì", "ipa": "tsweɪ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "北京的秋天很美，最是十月的香山动人。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的小吃很多，最是夜市里的面让人想吃。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年四季中，最是春天让人觉得舒服。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都爱玩，最是小明喜欢在雨里跑。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江南的水乡很有名，最是下雨天的小桥好看。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢听音乐，最是夜晚的钢琴让我放松。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国菜种类很多，最是四川菜的辣让我难忘。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人里面，最是奶奶关心我的身体。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，最是除夕夜热闹。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夏天很凉快，最是早上的空气让人舒服。", "target_word": "最是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，在同类事物中挑出程度最高、最突出的一个，相当于“尤其是”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最是", "is_correct": true, "explanation": "正确。句中在同类景致中突出十月的香山最动人。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与前文相反的结果，但“很美”的描述并没有相反的内容。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”后接动词或形容词，不能直接接名词短语“十月的香山”。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“很美”“动人”的描述不符。"}], "explanations": {"最是": "正确。句中在同类景致中突出十月的香山最动人。", "反而": "语义：“反而”表示与前文相反的结果，但“很美”的描述并没有相反的内容。", "已经": "搭配：“已经”后接动词或形容词，不能直接接名词短语“十月的香山”。", "偶尔": "语义：“偶尔”表示不常发生，与“很美”“动人”的描述不符。"}, "sentence_index": 0, "correct_answer": "最是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了很多东西，最是没有带钱包。", "explanation": "这里应该用〈可是〉。最是表示程度最高，不能表示转折；前后转折要用可是。"}, {"text": "我今天在超市，最是买了鸡蛋。", "explanation": "这里应该用〈刚〉。最是表示程度最高，描述刚发生的动作时要用刚。"}, {"text": "这件事我最是告诉了他。", "explanation": "这里应该用〈只〉。最是表示程度最高，单纯叙述只告诉了一个人时要用只。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最是", "is_correct": true, "explanation": "正确。句中在众多中国菜里，突出四川菜的辣最让人难忘。"}, {"text": "越", "is_correct": false, "explanation": "搭配：“越”要成对使用（越……越……），不能单独修饰“四川菜的辣”。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前文“种类很多”没有需要转折的内容。"}, {"text": "一定", "is_correct": false, "explanation": "搭配：“一定”修饰动词或形容词，不能直接带“四川菜的辣让我难忘”这样的主谓结构。"}], "explanations": {"最是": "正确。句中在众多中国菜里，突出四川菜的辣最让人难忘。", "越": "搭配：“越”要成对使用（越……越……），不能单独修饰“四川菜的辣”。", "却": "语义：“却”表示转折，前文“种类很多”没有需要转折的内容。", "一定": "搭配：“一定”修饰动词或形容词，不能直接带“四川菜的辣让我难忘”这样的主谓结构。"}, "sentence_index": 6, "correct_answer": "最是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这最是我要找的人。", "explanation": "这里应该用〈才是〉。最是要在几样事物中突出一个，这里只是肯定，没有比较的对象。"}, {"text": "这间屋子最是有点乱。", "explanation": "这里应该用〈稍微〉。最是表示程度最高，不能与“有点”搭配；表示程度轻时要用稍微。"}, {"text": "我今天最是很累。", "explanation": "这里应该用〈非常〉。最是表示在同类中程度最高，与“很”并用语义重复；表示程度高时用非常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢很多季节，最是的初夏傍晚让人舒服。", "corrected_sentence": "我喜欢很多季节，最是初夏傍晚让人舒服。", "error_description": "“最是”后面不能直接加“的”，应说“最是初夏傍晚”。错误：最是的初夏；正确：最是初夏。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的菜很多，很最是烤鸭让人想再来。", "corrected_sentence": "这家店的菜很多，最是烤鸭让人想再来。", "error_description": "“最是”前面不能再加“很”等程度副词，两者重复。错误：很最是烤鸭；正确：最是烤鸭。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
