INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89143, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示式是用数字或字母写出来的一个式子。", "primary_collocate": null, "pronunciation": "biǎo shì shì", "ipa": "pjɑʊ̯²¹⁴ ʂɻ̩⁵¹ ʂɻ̩⁵¹", "syllable_count": 3, "sentences": [{"text": "他用字母写了一个表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表示式里只有数字。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把表示式抄在本子上。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表示式中的a是什么？", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们算这个表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表示式有三个字母。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写错了一个表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会写简单的表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表示式的结果是十。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看黑板上的表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个表示式", "label": "量词：个"}], "register": "书面", "sense_fingerprint": "用数字或字母写出来的式子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不能用字母写出来。"}, {"text": "表示式", "is_correct": true, "explanation": "符合语境：用字母或数字写出来的式子。"}, {"text": "图画", "is_correct": false, "explanation": "搭配：“写”用于文字或式子，“图画”要用“画”，不能说“写图画”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能用字母写出来。"}], "explanations": {"手机": "语义：手机是通讯工具，不能用字母写出来。", "表示式": "符合语境：用字母或数字写出来的式子。", "图画": "搭配：“写”用于文字或式子，“图画”要用“画”，不能说“写图画”。", "窗户": "语义：窗户是建筑部件，不能用字母写出来。"}, "sentence_index": 0, "correct_answer": "表示式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在饭店点了一个表示式。", "explanation": "〈表示式〉是数学中的式子，不能用来“点”；这里应该说〈菜〉。"}, {"text": "我们班的表示式今天很热闹。", "explanation": "〈表示式〉指数学中的式子，不能指热闹的场面；这里应该说〈活动〉或〈班会〉。"}, {"text": "他爱吃表示式，每天都要买一个。", "explanation": "〈表示式〉是数学中的式子，不能用来吃；这里应该说〈点心〉之类的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水杯", "is_correct": false, "explanation": "语义：水杯是盛水的器具，不能用笔写出来。"}, {"text": "表示式", "is_correct": true, "explanation": "符合语境：用数字或字母写出来的式子。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是建筑空间，不是文字或式子，不能被写错。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“写”的对象是文字或式子，不能说“写一个石头”。"}], "explanations": {"水杯": "语义：水杯是盛水的器具，不能用笔写出来。", "表示式": "符合语境：用数字或字母写出来的式子。", "房间": "语义：房间是建筑空间，不是文字或式子，不能被写错。", "石头": "搭配：“写”的对象是文字或式子，不能说“写一个石头”。"}, "sentence_index": 6, "correct_answer": "表示式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请看黑板上的表示式，它是一首很好听的歌。", "explanation": "〈表示式〉是数学中的式子，不是歌曲；这里应该说〈歌词〉之类的词。"}, {"text": "他在台上跳了一个表示式。", "explanation": "〈表示式〉是数学中的式子，不能用来“跳”；这里应该说〈舞〉。"}, {"text": "妈妈在院子里种了一个表示式。", "explanation": "〈表示式〉不能种在院子里；这里应该说〈树〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让我们把这个表示式们算出来。", "corrected_sentence": "老师让我们把这个表示式算出来。", "error_description": "“这个”限定单数，“表示式”不是指人的名词，不能加“们”；应说“这个表示式”，“表示式们”错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想把这个表示式抄。", "corrected_sentence": "我想把这个表示式抄下来。", "error_description": "“把”字句的动词后通常要带补语，“把这个表示式抄”不完整；应说“把这个表示式抄下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
