INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用符号表示数学或逻辑关系的式子。", "primary_collocate": null, "pronunciation": "biǎo shì shì", "ipa": "pjɑʊ̯²¹⁴ ʂɻ̩⁵¹ ʂɻ̩⁵¹", "syllable_count": 3, "sentences": [{"text": "请写出这个关系的表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表示式里有两个符号。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表示式很短，我一眼就看懂了。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不懂这个表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用符号写出了表示式。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表示式说明两个数的关系。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个表示式写在本子上。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表示式一点也不难，我很快就算出来了。", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说说这个表示式的意思吗？", "target_word": "表示式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个表示式", "label": "量词：个"}], "register": "书面", "sense_fingerprint": "用符号写出数学或逻辑关系的式子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "照片", "is_correct": false, "explanation": "搭配：“写出”用于文字或式子，不能说“写出照片”。"}, {"text": "表示式", "is_correct": true, "explanation": "符合语境：指用符号写出的、表示数学或逻辑关系的式子。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，不是可以写出来的关系。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能用来表示“关系”。"}], "explanations": {"照片": "搭配：“写出”用于文字或式子，不能说“写出照片”。", "表示式": "符合语境：指用符号写出的、表示数学或逻辑关系的式子。", "天气": "语义：天气指气候状况，不是可以写出来的关系。", "窗户": "语义：窗户是建筑部件，不能用来表示“关系”。"}, "sentence_index": 0, "correct_answer": "表示式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在墙上挂了一个表示式。", "explanation": "〈表示式〉是数学或逻辑中的式子，是抽象的，不能挂在墙上；这里应该说〈挂图〉之类的具体事物。"}, {"text": "他用剪刀剪了一个表示式。", "explanation": "〈表示式〉是用符号写出的抽象式子，不能用剪刀剪；这里应该说〈纸〉之类的具体东西。"}, {"text": "他的表示式看起来很高兴。", "explanation": "〈表示式〉只指数学或逻辑中的式子，不能指脸上的神情；这里应该说〈表情〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不能用来说明数的关系。"}, {"text": "表示式", "is_correct": true, "explanation": "符合语境：用符号表示数学关系的式子，可以说明两个数的关系。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景象，不能用来说明数的关系。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然现象，与数的关系无关。"}], "explanations": {"手机": "语义：手机是通讯工具，不能用来说明数的关系。", "表示式": "符合语境：用符号表示数学关系的式子，可以说明两个数的关系。", "天空": "语义：天空是自然景象，不能用来说明数的关系。", "雨水": "语义：雨水是自然现象，与数的关系无关。"}, "sentence_index": 6, "correct_answer": "表示式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个表示式今天感冒了，没来上课。", "explanation": "〈表示式〉是数学或逻辑中的式子，不会生病，也不会上课；这里应该说〈同学〉。"}, {"text": "他是我们班的表示式，数学最好。", "explanation": "〈表示式〉指数学或逻辑中的式子，只能指事物，不能指人；这里应该说〈同学〉。"}, {"text": "这个表示式的价钱是十块钱。", "explanation": "〈表示式〉是抽象的式子，不能有价钱；这里应该说〈商品〉之类有价格的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这个表示式写在了本子。", "corrected_sentence": "我把这个表示式写在了本子上。", "error_description": "“写在”后面要接处所，“本子”是普通名词，要加“上”变成处所，应说“写在了本子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看了懂这个表示式的意思。", "corrected_sentence": "我看懂了这个表示式的意思。", "error_description": "“看懂”是动补结构，“了”应放在补语之后，应说“看懂了”；“看了懂”语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "法院是人们打官司、由法官判断是非对错的地方。", "primary_collocate": null, "pronunciation": "fǎ yuàn", "ipa": "fa˨˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "法院就在警察局旁边，走路很近。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天要去法院参加审判，所以请了假。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院门口站着很多等消息的人。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所法院很大，有十几间审判室。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和朋友坐地铁到法院去旁听。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次审判在法院的第三审判庭进行。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官每天在法院里听两边说话。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子问：“法官在法院里做什么？”", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，法院是判断对错的地方。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵了很久，最后一起去法院。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一所法院", "label": "量词"}, {"form": "基层法院", "label": "复合"}, {"form": "中级法院", "label": "复合"}], "register": "中性", "sense_fingerprint": "法院：判断对错的地方，指人们去的那个场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b344bf-0d85-4cad-8e3c-b481bef5b4ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：审理案件、判断是非的场所。"}, {"text": "发源", "is_correct": false, "explanation": "发源 fā yuán 与 fǎ yuàn 两个音节的声调都不同，意思是水流或事物从某处开始产生。"}, {"text": "法源", "is_correct": false, "explanation": "法源 fǎ yuán 只有第二个音节声调不同（yuán 第二声，yuàn 第四声），意思是法律的来源。"}, {"text": "发愿", "is_correct": false, "explanation": "发愿 fā yuàn 只有第一个音节声调不同（fā 第一声，fǎ 第三声），意思是许下誓愿。"}], "explanations": {"法院": "法院：审理案件、判断是非的场所。", "发源": "发源 fā yuán 与 fǎ yuàn 两个音节的声调都不同，意思是水流或事物从某处开始产生。", "法源": "法源 fǎ yuán 只有第二个音节声调不同（yuán 第二声，yuàn 第四声），意思是法律的来源。", "发愿": "发愿 fā yuàn 只有第一个音节声调不同（fā 第一声，fǎ 第三声），意思是许下誓愿。"}, "sentence_index": null, "correct_answer": "法院"}, "level_3": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：审理案件的场所，符合“就在警察局旁边，走路很近”。"}, {"text": "法律", "is_correct": false, "explanation": "语义：法律是抽象的规则，不是可以“就在…旁边、走路很近”的地方。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：手机是物品，“走路很近”说的是可以走过去的场所，不能说“手机走路很近”。"}, {"text": "警察局", "is_correct": false, "explanation": "语义：句中已用警察局作参照，“警察局就在警察局旁边”指代不通。"}], "explanations": {"法院": "法院：审理案件的场所，符合“就在警察局旁边，走路很近”。", "法律": "语义：法律是抽象的规则，不是可以“就在…旁边、走路很近”的地方。", "手机": "搭配：手机是物品，“走路很近”说的是可以走过去的场所，不能说“手机走路很近”。", "警察局": "语义：句中已用警察局作参照，“警察局就在警察局旁边”指代不通。"}, "sentence_index": 0, "correct_answer": "法院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在法院上陈述了事实。", "explanation": "这里应该用〈法庭〉。“在法庭上”指案件审理的场所，“法院”是机构或建筑，不说“在法院上”。"}, {"text": "他生病了，就去法院看病。", "explanation": "这里应该用〈医院〉。看病是医院的职能；法院是审判案件的地方，不能用来看病，所以这句话不成立。"}, {"text": "我每次路过这台法院都会看一眼。", "explanation": "这里应该用〈所〉。“台”用于机器、演出等，法院是建筑和机构，量词说“一所法院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：审理案件、判断是非的场所。"}, {"text": "法眼", "is_correct": false, "explanation": "法眼 fǎ yǎn 的第一个音节和 fǎ yuàn 完全相同，第二个音节 yǎn 与 yuàn 韵母和声调都不同。意思是敏锐的眼光。"}, {"text": "发言", "is_correct": false, "explanation": "发言 fā yán 的声调不同（fā 第一声，yán 第二声），第二个音节的韵母也不同（yan 与 yuan）。意思是说出自己的意见。"}, {"text": "府院", "is_correct": false, "explanation": "府院 fǔ yuàn 只有第一个音节韵母不同（u 与 a），声调相同，意思是旧时官府的院落。"}, {"text": "化缘", "is_correct": false, "explanation": "化缘 huà yuán 的第一个音节声母和声调不同（huà 与 fǎ），第二个音节声调不同（yuán 第二声）。意思是僧人向人求布施。"}], "explanations": {"法院": "法院：审理案件、判断是非的场所。", "法眼": "法眼 fǎ yǎn 的第一个音节和 fǎ yuàn 完全相同，第二个音节 yǎn 与 yuàn 韵母和声调都不同。意思是敏锐的眼光。", "发言": "发言 fā yán 的声调不同（fā 第一声，yán 第二声），第二个音节的韵母也不同（yan 与 yuan）。意思是说出自己的意见。", "府院": "府院 fǔ yuàn 只有第一个音节韵母不同（u 与 a），声调相同，意思是旧时官府的院落。", "化缘": "化缘 huà yuán 的第一个音节声母和声调不同（huà 与 fǎ），第二个音节声调不同（yuán 第二声）。意思是僧人向人求布施。"}, "sentence_index": null, "correct_answer": "法院"}, "level_3": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：审理案件、听取双方陈述的场所，符合句意。"}, {"text": "医院", "is_correct": false, "explanation": "语义：法官不在医院工作，“在医院里听两边说话”与句中的法官身份不合。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“听两边说话”需要争议双方在场的场所，厨房不搭配。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是审理纠纷的场所，“法官在学校里听两边说话”不合常理。"}], "explanations": {"法院": "法院：审理案件、听取双方陈述的场所，符合句意。", "医院": "语义：法官不在医院工作，“在医院里听两边说话”与句中的法官身份不合。", "厨房": "搭配：“听两边说话”需要争议双方在场的场所，厨房不搭配。", "学校": "语义：学校不是审理纠纷的场所，“法官在学校里听两边说话”不合常理。"}, "sentence_index": 6, "correct_answer": "法院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们吵了很久，最后一起去法院报了案。", "explanation": "这里应该用〈警察局〉。报案是向警察局报告违法事件，法院负责审判，不说“去法院报案”。"}, {"text": "他们吵了很久，最后一起去法院举报对方。", "explanation": "这里应该用〈检察院〉。举报是向检察院或公安机关检举违法行为，法院负责审判，不说“去法院举报”。"}, {"text": "他们吵了很久，最后一起去了一辆法院。", "explanation": "这里应该用〈所〉。“辆”只用于车辆，法院是机构和建筑，量词说“一所法院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天下班都路过一本法院的门口。", "corrected_sentence": "我每天下班都路过一所法院的门口。", "error_description": "错误：“本”用于书本，“法院”是建筑和机构，不能说“一本法院”。正确：应说“一所法院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去着法院两次，都是为了旁听。", "corrected_sentence": "我去过法院两次，都是为了旁听。", "error_description": "错误：表示曾经有过经历，应用“过”，“着”表示持续状态，不能用在“去”后面。正确：应说“去过法院两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家的审判机关,依法审理案件。", "primary_collocate": null, "pronunciation": "fǎ yuàn", "ipa": "fa˨˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "法院依法审理了这个案件。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院作出了公正的判决。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这起案子由当地法院负责审理。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不同意判决，向上一级法院提出了申诉。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院是国家的审判机关。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把公司告上了法院。", "target_word": "法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院要求他在三天内交出证据。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院的法官必须按照法律来判案。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件案子，法院下个月才会判决。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院认为证据不够，宣布他无罪。", "target_word": "法院", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一所法院", "label": "量词"}, {"form": "基层法院", "label": "复合"}, {"form": "中级法院", "label": "复合"}], "register": "中性", "sense_fingerprint": "法院：国家的审判机关，依法审理案件、作出判决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b344bf-0d85-4cad-8e3c-b481bef5b4ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：国家的审判机关，依法审理案件。"}, {"text": "发源", "is_correct": false, "explanation": "发源 fā yuán 与 fǎ yuàn 两个音节的声调都不同，意思是水流或事物从某处开始产生。"}, {"text": "法源", "is_correct": false, "explanation": "法源 fǎ yuán 只有第二个音节声调不同（yuán 第二声），意思是法律的来源。"}, {"text": "发愿", "is_correct": false, "explanation": "发愿 fā yuàn 只有第一个音节声调不同（fā 第一声，fǎ 第三声），意思是许下誓愿。"}], "explanations": {"法院": "法院：国家的审判机关，依法审理案件。", "发源": "发源 fā yuán 与 fǎ yuàn 两个音节的声调都不同，意思是水流或事物从某处开始产生。", "法源": "法源 fǎ yuán 只有第二个音节声调不同（yuán 第二声），意思是法律的来源。", "发愿": "发愿 fā yuàn 只有第一个音节声调不同（fā 第一声，fǎ 第三声），意思是许下誓愿。"}, "sentence_index": null, "correct_answer": "法院"}, "level_3": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：国家的审判机关，符合“依法审理了这个案件”。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是企业，不是审判机关，不能“依法审理案件”。"}, {"text": "律师", "is_correct": false, "explanation": "搭配：“审理案件”的主语应是审判机关；律师只代理案件，不能说“律师依法审理”。"}, {"text": "检察院", "is_correct": false, "explanation": "语义：检察院负责提起公诉，不负责审理案件，与“依法审理”不合。"}], "explanations": {"法院": "法院：国家的审判机关，符合“依法审理了这个案件”。", "公司": "语义：公司是企业，不是审判机关，不能“依法审理案件”。", "律师": "搭配：“审理案件”的主语应是审判机关；律师只代理案件，不能说“律师依法审理”。", "检察院": "语义：检察院负责提起公诉，不负责审理案件，与“依法审理”不合。"}, "sentence_index": 0, "correct_answer": "法院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这起案子由法院提起公诉，指控他抢劫。", "explanation": "这里应该用〈检察院〉。提起公诉是检察院的职责，法院负责审判，不能说“由法院提起公诉”。"}, {"text": "法院上周就开始侦查这起抢劫案。", "explanation": "这里应该用〈警察局〉。侦查是公安机关的工作，法院负责审理，不能说“法院侦查”。"}, {"text": "他在一位法院工作了十年。", "explanation": "这里应该用〈所〉。“位”用于人，法院是机构，量词说“一所法院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：国家的审判机关，依法审理案件。"}, {"text": "法眼", "is_correct": false, "explanation": "法眼 fǎ yǎn 的第一个音节和 fǎ yuàn 完全相同，第二个音节 yǎn 与 yuàn 韵母和声调都不同。意思是敏锐的眼光。"}, {"text": "发言", "is_correct": false, "explanation": "发言 fā yán 的声调不同（fā 第一声，yán 第二声），第二个音节的韵母也不同（yan 与 yuan）。意思是说出自己的意见。"}, {"text": "府院", "is_correct": false, "explanation": "府院 fǔ yuàn 只有第一个音节韵母不同（u 与 a），声调相同，意思是旧时官府的院落。"}, {"text": "化缘", "is_correct": false, "explanation": "化缘 huà yuán 的第一个音节声母和声调不同（huà 与 fǎ），第二个音节声调不同（yuán 第二声）。意思是僧人向人求布施。"}], "explanations": {"法院": "法院：国家的审判机关，依法审理案件。", "法眼": "法眼 fǎ yǎn 的第一个音节和 fǎ yuàn 完全相同，第二个音节 yǎn 与 yuàn 韵母和声调都不同。意思是敏锐的眼光。", "发言": "发言 fā yán 的声调不同（fā 第一声，yán 第二声），第二个音节的韵母也不同（yan 与 yuan）。意思是说出自己的意见。", "府院": "府院 fǔ yuàn 只有第一个音节韵母不同（u 与 a），声调相同，意思是旧时官府的院落。", "化缘": "化缘 huà yuán 的第一个音节声母和声调不同（huà 与 fǎ），第二个音节声调不同（yuán 第二声）。意思是僧人向人求布施。"}, "sentence_index": null, "correct_answer": "法院"}, "level_3": {"options": [{"text": "法院", "is_correct": true, "explanation": "法院：国家的审判机关，可以“要求他在三天内交出证据”。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是违法的人，没有权力要求别人交出证据。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“要求…交出证据”需要调查或审判的权限，厨师没有这种搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地点，不能作“要求”的主语。"}], "explanations": {"法院": "法院：国家的审判机关，可以“要求他在三天内交出证据”。", "小偷": "语义：小偷是违法的人，没有权力要求别人交出证据。", "厨师": "搭配：“要求…交出证据”需要调查或审判的权限，厨师没有这种搭配。", "花园": "语义：花园是地点，不能作“要求”的主语。"}, "sentence_index": 6, "correct_answer": "法院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场纠纷在法院上进行了辩论。", "explanation": "这里应该用〈法庭〉。“在法庭上”指开庭的场所，“法院”指机构，不说“在法院上”。"}, {"text": "这辆法院昨天宣布，他被判了三年。", "explanation": "这里应该用〈所〉。“辆”只用于车辆，法院是机构，量词说“一所法院”。"}, {"text": "法院接受了他的委托，准备打官司。", "explanation": "这里应该用〈律师事务所〉。接受委托、代理诉讼是律师事务所的业务，法院不接受委托。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这起案件，法院已经受理着了。", "corrected_sentence": "这起案件，法院已经受理了。", "error_description": "错误：“受理”在这里表示已经完成的动作，不能用表示持续的“着”。正确：应说“法院已经受理了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这起案子已法院审结。", "corrected_sentence": "这起案子已由法院审结。", "error_description": "介词漏用：“法院”作审结的施事，前面需要介词“由”，应说“已由法院审结”；去掉“由”成“已法院审结”，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723ce58d-f234-47cd-bfc4-2683846ec4d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
