INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89147, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "损坏是东西被弄坏了，不能好好用了。", "primary_collocate": null, "pronunciation": "sǔn huài", "ipa": "suən˨˩˦ xwaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "手机掉在地上，屏幕损坏了，不能用了。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑掉在水里，主板损坏了。", "target_word": "损坏", "complexity_tier": "T3", "furigana": "sǔn huài", "sentence_source": "generated"}, {"text": "搬家的时候，我的新桌子损坏了。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书太旧了，有几页已经损坏，看不清楚。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用了两年，这个吸尘器的电机终于损坏了。", "target_word": "损坏", "complexity_tier": "T3", "furigana": "sǔn huài", "sentence_source": "generated"}, {"text": "这个玩具很容易损坏，要轻一点儿拿。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天风很大，门口的路灯损坏了两个。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心摔了一下，眼镜损坏了。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请检查一下，包裹里的东西有没有损坏。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣柜里的衣服没有损坏，只是有点脏。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "损坏了", "label": "体标"}, {"form": "损坏过", "label": "体标"}, {"form": "損壞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西坏了、受了伤害，不能再正常使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89147, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "损坏", "is_correct": true, "explanation": "屏幕掉在地上后失去功能，符合“损坏”指东西坏了、不能用的意思。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于衣物等物品，不能说屏幕洗了。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量，不能说屏幕增加了。"}, {"text": "发送", "is_correct": false, "explanation": "语义：“发送”指传递信息，与屏幕坏了、不能用的语境不相合，句意不通。"}], "explanations": {"损坏": "屏幕掉在地上后失去功能，符合“损坏”指东西坏了、不能用的意思。", "洗": "搭配：“洗”用于衣物等物品，不能说屏幕洗了。", "增加": "搭配：“增加”说的是数量，不能说屏幕增加了。", "发送": "语义：“发送”指传递信息，与屏幕坏了、不能用的语境不相合，句意不通。"}, "sentence_index": 0, "correct_answer": "损坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这次生意中损坏了十万元。", "explanation": "这里应该用〈损失〉。损坏指物品受损，不能用于钱财方面的损失。"}, {"text": "他在比赛中损坏了一个对手。", "explanation": "这里应该用〈伤害〉。损坏针对物品，不能指人；伤害别人要用〈伤害〉。"}, {"text": "这家公司的财务状况已经损坏，需要调整。", "explanation": "这里应该用〈恶化〉。损坏指物品受损，状况变差要用〈恶化〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89147, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "损坏", "is_correct": true, "explanation": "路灯被风吹坏，失去功能，符合“损坏”的意思。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”用于人完成学业，不能说路灯毕业了。"}, {"text": "收起", "is_correct": false, "explanation": "搭配：“收起”不用于路灯，不能说收起了两个路灯。"}, {"text": "合上", "is_correct": false, "explanation": "搭配：“合上”多用于盖子、书本等，不用于路灯。"}], "explanations": {"损坏": "路灯被风吹坏，失去功能，符合“损坏”的意思。", "毕业": "搭配：“毕业”用于人完成学业，不能说路灯毕业了。", "收起": "搭配：“收起”不用于路灯，不能说收起了两个路灯。", "合上": "搭配：“合上”多用于盖子、书本等，不用于路灯。"}, "sentence_index": 6, "correct_answer": "损坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司去年损坏了三百万元。", "explanation": "这里应该用〈亏损〉。损坏用于具体物品，公司钱财减少要用〈亏损〉。"}, {"text": "他们损坏了政府。", "explanation": "这里应该用〈推翻〉。损坏针对具体物品，不能用于政权。"}, {"text": "他浪费了整整一个下午，把时间也损坏了。", "explanation": "这里应该用〈耽误〉。损坏指使物品受损，时间白白消耗要用〈耽误〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨太大了，路边的广告牌没损坏了。", "corrected_sentence": "雨太大了，路边的广告牌没损坏。", "error_description": "错误：“没”否定的是未发生的动作，“了”表示动作已经完成，两者不能同时用。“没损坏了”应去掉“了”，写成“没损坏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的雨伞昨天被风吹得损坏着。", "corrected_sentence": "我的雨伞昨天被风吹得损坏了。", "error_description": "错误：“损坏”表示变化的结果，不能加表示持续的“着”，应改用表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
