INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89148, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使物品受到破坏而失去原有的功能或完整。", "primary_collocate": null, "pronunciation": "sǔn huài", "ipa": "suən˨˩˦ xwaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "请不要损坏公园里的椅子和路灯。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不小心损坏了学校的玻璃。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意损坏别人的东西，大家都很生气。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬运工人损坏了客人的一台冰箱，要赔钱。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器用太久，会损坏里面的零件。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温会损坏手机的电池，夏天别放在车里。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车撞到墙，损坏了自行车的前轮。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共设施是大家的，不能随便损坏。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫抓破了沙发，损坏了不少家具。", "target_word": "损坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "损坏图书馆的书，要照价赔偿。", "target_word": "损坏", "complexity_tier": "T3", "furigana": "sǔn huài", "sentence_source": "generated"}], "morphological_forms": [{"form": "损坏了", "label": "体标"}, {"form": "损坏过", "label": "体标"}, {"form": "被损坏", "label": "被动"}, {"form": "損壞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "及物用法：使物品受到破坏，失去原有功能或完整", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "损坏", "is_correct": true, "explanation": "“请不要损坏”是劝人不要使公园设施受到破坏，符合“损坏”的及物用法。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”与“请不要”的劝阻语境相反，劝人不要保护设施，句意不通。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”用于花草、土地等，不能说浇椅子和路灯。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”指种植，椅子和路灯不能被种植。"}], "explanations": {"损坏": "“请不要损坏”是劝人不要使公园设施受到破坏，符合“损坏”的及物用法。", "保护": "语义：“保护”与“请不要”的劝阻语境相反，劝人不要保护设施，句意不通。", "浇": "搭配：“浇”用于花草、土地等，不能说浇椅子和路灯。", "种": "搭配：“种”指种植，椅子和路灯不能被种植。"}, "sentence_index": 0, "correct_answer": "损坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次意外让公司损坏了几百万元。", "explanation": "这里应该用〈损失〉。损坏用于物品，钱财受损要用〈损失〉。"}, {"text": "他的谎言损坏了很多朋友。", "explanation": "这里应该用〈伤害〉。损坏只用于物品，伤害别人要用〈伤害〉。"}, {"text": "这场大雨损坏了我们的行程。", "explanation": "这里应该用〈耽误〉。损坏指使物品受损，行程被拖延要用〈耽误〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "损坏", "is_correct": true, "explanation": "撞到墙后自行车前轮受损，符合“损坏”的意思。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量或程度，不能说增加了自行车的前轮。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”后面接乐趣、待遇等，不接车轮。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示赞美，与撞到墙后的受损语境冲突。"}], "explanations": {"损坏": "撞到墙后自行车前轮受损，符合“损坏”的意思。", "增加": "搭配：“增加”说的是数量或程度，不能说增加了自行车的前轮。", "享受": "搭配：“享受”后面接乐趣、待遇等，不接车轮。", "欣赏": "语义：“欣赏”表示赞美，与撞到墙后的受损语境冲突。"}, "sentence_index": 6, "correct_answer": "损坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按时损坏了图书馆的书。", "explanation": "这里应该用〈归还〉。损坏是使物品受损，把书还回去要用〈归还〉。"}, {"text": "他损坏了整整一个下午。", "explanation": "这里应该用〈浪费〉。损坏针对物品，时间白白过去要用〈浪费〉。"}, {"text": "他损坏了约定。", "explanation": "这里应该用〈打破〉。损坏只用于具体物品，约定被违反要用〈打破〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天没损坏了邻居的花盆。", "corrected_sentence": "他昨天没损坏邻居的花盆。", "error_description": "错误：“没”否定已发生的动作，不能再加表示完成的“了”，应去掉“了”，写成“没损坏邻居的花盆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把故意损坏了公园的长椅。", "corrected_sentence": "他故意损坏了公园的长椅。", "error_description": "错误：多加了“把”，写成“把故意损坏”。“把”后面要先接处置对象（如“公园的长椅”），“故意”是状语，不能直接放在“把”后面。应去掉“把”，写成“他故意损坏了公园的长椅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
