INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89149, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "西元是用来算年份的一种叫法。", "primary_collocate": null, "pronunciation": "xī yuán", "ipa": "ɕi˥ yɛn˧˥", "syllable_count": 2, "sentences": [{"text": "西元二〇〇〇年，我出生在北京。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是西元一九九〇年出版的。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书主要讲的是西元一九〇〇年以前的事。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在表格里写上西元几年几月几日。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子建于西元一九二〇年。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西元和农历是两种不同的算年份方法。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的护照上写着出生于西元一九八五年。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西元二〇二四年是龙年。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写下西元一年。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大水发生在西元一九九八年夏天。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "西元前", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来计算年份的纪年叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62e3c067-3c4e-4854-b164-7c1afd2d112c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西元", "is_correct": true, "explanation": "“西元”是纪年方式，可以用来表示“二〇〇〇年”，与句意相符。"}, {"text": "上午", "is_correct": false, "explanation": "语义：上午指一天中的时段，不能用来表示年份。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期指一周中的某一天，不能用来表示年份。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：夏天是季节，不能与具体的年份“二〇〇〇年”搭配。"}], "explanations": {"西元": "“西元”是纪年方式，可以用来表示“二〇〇〇年”，与句意相符。", "上午": "语义：上午指一天中的时段，不能用来表示年份。", "星期": "语义：星期指一周中的某一天，不能用来表示年份。", "夏天": "搭配：夏天是季节，不能与具体的年份“二〇〇〇年”搭配。"}, "sentence_index": 0, "correct_answer": "西元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年西元二十岁，正在上大学。", "explanation": "这里应该用〈年龄〉。西元是纪年名称，只能表示年份，不能用来表示年龄。"}, {"text": "我们明天在西元见面吧。", "explanation": "西元是纪年名称，不是地点，不能用在“在……见面”里。"}, {"text": "我买了一件西元的衣服。", "explanation": "这里应该用〈西式〉。西元指纪年方式，西式才表示西洋式样的衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西元", "is_correct": true, "explanation": "“西元”是纪年方式，可以用来表示“一九八五年”，与句意相符。"}, {"text": "假期", "is_correct": false, "explanation": "语义：假期是放假的时间，不能用来表示年份。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：“周末”不能与“一九八五年”这样的年份搭配。"}, {"text": "清明", "is_correct": false, "explanation": "语义：清明是节气或节日，不能用来表示年份。"}], "explanations": {"西元": "“西元”是纪年方式，可以用来表示“一九八五年”，与句意相符。", "假期": "语义：假期是放假的时间，不能用来表示年份。", "周末": "搭配：“周末”不能与“一九八五年”这样的年份搭配。", "清明": "语义：清明是节气或节日，不能用来表示年份。"}, "sentence_index": 6, "correct_answer": "西元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的西元是三十分钟。", "explanation": "西元是纪年名称，不能用来表示比赛的时长，这里误把纪年当成了时间长短。"}, {"text": "他的西元很高，大家都叫他大个子。", "explanation": "西元不是身体的特征，不能用来描述个子高矮。"}, {"text": "老师的西元很严格，同学们都怕他。", "explanation": "西元是纪年名称，不是人的性格，不能用来形容老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座寺庙建西元八〇〇年。", "corrected_sentence": "这座寺庙建于西元八〇〇年。", "error_description": "错误形式：“建西元八〇〇年”；正确形式：“建于西元八〇〇年”。“建”表示时间时，后面要用“于”引出时间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人出生于西元的一九五〇年。", "corrected_sentence": "那个人出生于西元一九五〇年。", "error_description": "错误形式：“西元的一九五〇年”；正确形式：“西元一九五〇年”。“西元”后面直接接年份，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
