INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89150, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公元，国际通行的纪年方式（多用于台湾地区）。", "primary_collocate": null, "pronunciation": "xī yuán", "ipa": "ɕi˥ yɛn˧˥", "syllable_count": 2, "sentences": [{"text": "台湾的文件常用西元和民国两种年份。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在台湾，西元二〇二四年是民国一百一十三年。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台湾朋友填表时，习惯写西元年。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台湾的新闻多用西元纪年。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张台北的发票上印着西元日期。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台湾的课本里，西元和民国对照着写。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台湾的身份证上，生日用民国年，不用西元。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台湾的历史书常说西元一六二四年荷兰人来了。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台北的博物馆里，展品旁写着西元年份。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在台湾，很多人说西元，不说公元。", "target_word": "西元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "西元前", "label": "复合"}], "register": "中性", "sense_fingerprint": "台湾地区对公元纪年的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62e3c067-3c4e-4854-b164-7c1afd2d112c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西元", "is_correct": true, "explanation": "“西元”是台湾文件常用的年份之一，与“民国”并列，句意相符。"}, {"text": "春节", "is_correct": false, "explanation": "语义：春节是节日，不是纪年方式，“常用春节和民国两种年份”不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期指一周中的日子，不能作为年份的计算方式。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：夏天是季节，不能与“民国”并列作为年份。"}], "explanations": {"西元": "“西元”是台湾文件常用的年份之一，与“民国”并列，句意相符。", "春节": "语义：春节是节日，不是纪年方式，“常用春节和民国两种年份”不通。", "星期": "语义：星期指一周中的日子，不能作为年份的计算方式。", "夏天": "搭配：夏天是季节，不能与“民国”并列作为年份。"}, "sentence_index": 0, "correct_answer": "西元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爸爸西元六十岁，身体很好。", "explanation": "这里应该用〈年龄〉。西元是纪年方式，只能表示年份，不能用来表示年龄。"}, {"text": "我渴了，想喝一杯西元。", "explanation": "西元是纪年方式，不是饮料，不能喝。"}, {"text": "这位台湾朋友是西元人。", "explanation": "西元是纪年名称，不能用来指人的国籍或身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西元", "is_correct": true, "explanation": "“西元”是台湾用来与“民国年”相对的纪年方式，与“不用西元”的句意相符。"}, {"text": "假期", "is_correct": false, "explanation": "语义：假期不是纪年方式，“生日不用假期”不成立。"}, {"text": "清明", "is_correct": false, "explanation": "语义：清明是节日，与纪年方式无关，句子不通。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：“周末”不能与“民国年”这样的纪年方式对比。"}], "explanations": {"西元": "“西元”是台湾用来与“民国年”相对的纪年方式，与“不用西元”的句意相符。", "假期": "语义：假期不是纪年方式，“生日不用假期”不成立。", "清明": "语义：清明是节日，与纪年方式无关，句子不通。", "周末": "搭配：“周末”不能与“民国年”这样的纪年方式对比。"}, "sentence_index": 6, "correct_answer": "西元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天西元七点吃早饭，很规律。", "explanation": "西元是纪年方式，不能用来表示钟点，这里误把纪年当成了时刻。"}, {"text": "这本书的西元很有意思，大家都在看。", "explanation": "西元不能表示书的内容，它只用来表示年份。"}, {"text": "考试的时间是西元两小时。", "explanation": "西元是纪年方式，不能用来表示时长，这里误把纪年当成了时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台湾的课本常西元纪年。", "corrected_sentence": "台湾的课本常用西元纪年。", "error_description": "错误形式：“常西元纪年”；正确形式：“常用西元纪年”。“常”后面要接动词，“西元”是名词，需要动词“用”带出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台湾的朋友很少用了西元纪年。", "corrected_sentence": "台湾的朋友很少用西元纪年。", "error_description": "错误形式：“很少用了西元纪年”；正确形式：“很少用西元纪年”。“很少”表示习惯性的情况，与表示完成的“了”相矛盾，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
