INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89151, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "犯罪是做了法律不让做的坏事。", "primary_collocate": null, "pronunciation": "fàn zuì", "ipa": "fan˥˩ tsweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "警察把犯罪的人带走了。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不懂法律，也不知道什么是犯罪。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偷东西是不对的，严重的话就是犯罪。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很守法，从不犯罪。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，犯罪的人要受到惩罚。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人以前犯罪，现在想重新做人。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很穷，但是他不想犯罪。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察每天都在努力减少犯罪。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷在晚上犯罪，所以警察晚上更忙。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候家里很穷，长大后走上了犯罪的路。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯了罪", "label": "体标（了）"}, {"form": "犯过罪", "label": "体标（过）"}, {"form": "犯罪分子", "label": "复合"}, {"form": "犯罪率", "label": "复合"}], "register": "中性", "sense_fingerprint": "做了法律不许做的坏事（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "守法", "is_correct": false, "explanation": "语义：“守法”指遵守法律，与“警察把…带走”的执法情境意思相反。"}, {"text": "犯罪", "is_correct": true, "explanation": "“犯罪”指做了法律禁止的行为，正是警察把人带走的原因。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，警察不会因此把人带走，句子不通。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”不能与“把…带走”这类执法动作搭配，句子不自然。"}], "explanations": {"守法": "语义：“守法”指遵守法律，与“警察把…带走”的执法情境意思相反。", "犯罪": "“犯罪”指做了法律禁止的行为，正是警察把人带走的原因。", "表扬": "语义：“表扬”是称赞，警察不会因此把人带走，句子不通。", "结婚": "搭配：“结婚”不能与“把…带走”这类执法动作搭配，句子不自然。"}, "sentence_index": 0, "correct_answer": "犯罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他开车超速，这是犯罪。", "explanation": "这里应该用〈违法〉。犯罪指触犯刑法、应受刑罚处罚的行为；超速只违反交通法规，不能说成犯罪。"}, {"text": "他上课总是睡觉，这是一次犯罪。", "explanation": "这里应该用〈犯错〉。犯罪只用于触犯法律的行为；上课睡觉只是犯错误，不构成犯罪。"}, {"text": "他在公司迟到了三次，这是犯罪的行为。", "explanation": "这里应该用〈违纪〉。犯罪指触犯法律；迟到违反的是公司纪律，应说违纪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "守法", "is_correct": false, "explanation": "语义：“他很穷，但是他不想守法”没有对比关系，与“很穷”的处境不构成转折，句子意思不通。"}, {"text": "犯罪", "is_correct": true, "explanation": "“犯罪”与“很穷”的处境形成转折，“但是他不想…”正指向不愿走的歧路。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与“很穷，但是他不想…”的语境没有关联，句子不通。"}, {"text": "雪糕", "is_correct": false, "explanation": "语法：“不想”之后须接动词，“雪糕”是名词，句子不成立。"}], "explanations": {"守法": "语义：“他很穷，但是他不想守法”没有对比关系，与“很穷”的处境不构成转折，句子意思不通。", "犯罪": "“犯罪”与“很穷”的处境形成转折，“但是他不想…”正指向不愿走的歧路。", "散步": "语义：“散步”与“很穷，但是他不想…”的语境没有关联，句子不通。", "雪糕": "语法：“不想”之后须接动词，“雪糕”是名词，句子不成立。"}, "sentence_index": 6, "correct_answer": "犯罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在篮球比赛中多次犯罪，被裁判吹了哨。", "explanation": "这里应该用〈犯规〉。犯罪指触犯法律；比赛中违反规则应说犯规。"}, {"text": "他在长辈面前大声说话，这是犯罪。", "explanation": "这里应该用〈失礼〉。犯罪指触犯刑法；在长辈面前大声说话只是失礼，应说失礼。"}, {"text": "他在期末考试中犯罪，成绩被取消了。", "explanation": "这里应该用〈作弊〉。考试中舞弊应说作弊；犯罪特指触犯刑法的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时犯罪过，后来改过自新了。", "corrected_sentence": "他年轻时犯过罪，后来改过自新了。", "error_description": "错误形式：“犯罪过”；正确形式：“犯过罪”。“过”是体标，应紧跟动词“犯”，放在“犯”与“罪”之间，不能放在整个动宾结构之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人没犯了罪，警察放了他。", "corrected_sentence": "这个人没犯罪，警察放了他。", "error_description": "错误形式：“没犯了罪”；正确形式：“没犯罪”或“没有犯罪”。否定已发生或未发生的行为时，“没”不能与动词后的“了”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
