INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出触犯法律、应受刑罚处罚的行为。", "primary_collocate": null, "pronunciation": "fàn zuì", "ipa": "fan˥˩ tsweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他因为抢银行而犯罪，法院判了他十年。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说他犯罪的证据很清楚。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在调查他是不是犯罪了。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯罪的人要为自己的行为负责。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是第一次犯罪，法院决定从轻处理。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师说他没有犯罪，应该马上放了他。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了钱，开始和朋友一起犯罪。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在法律面前，有钱人犯罪也要受罚。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院说，他犯罪时已经十八岁了。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓到了在网上犯罪的人。", "target_word": "犯罪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯了罪", "label": "体标（了）"}, {"form": "犯过罪", "label": "体标（过）"}, {"form": "犯罪分子", "label": "复合"}, {"form": "犯罪率", "label": "复合"}], "register": "中性", "sense_fingerprint": "做出触犯法律、应受刑罚的行为（法律语境）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参加", "is_correct": false, "explanation": "语义：“参加”是加入某项活动，与“抢银行”之后被判刑的因果关系不符，句子不通。"}, {"text": "犯罪", "is_correct": true, "explanation": "“犯罪”指触犯法律的行为，正是“抢银行”之后被判刑的原因。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“因为抢银行而结婚”不能说，“结婚”与“抢银行”的因果关系搭配不当。"}, {"text": "守法", "is_correct": false, "explanation": "语义：“守法”与“抢银行”完全相反，因此被判刑的句子不成立。"}], "explanations": {"参加": "语义：“参加”是加入某项活动，与“抢银行”之后被判刑的因果关系不符，句子不通。", "犯罪": "“犯罪”指触犯法律的行为，正是“抢银行”之后被判刑的原因。", "结婚": "搭配：“因为抢银行而结婚”不能说，“结婚”与“抢银行”的因果关系搭配不当。", "守法": "语义：“守法”与“抢银行”完全相反，因此被判刑的句子不成立。"}, "sentence_index": 0, "correct_answer": "犯罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骑车闯红灯，这是犯罪的行为。", "explanation": "这里应该用〈违章〉。犯罪指触犯法律并应受刑罚处罚；闯红灯属于违章，应说违章。"}, {"text": "他在长辈面前不讲礼貌，这是犯罪的表现。", "explanation": "这里应该用〈失礼〉。犯罪指触犯法律；不讲礼貌只是失礼，不构成犯罪。"}, {"text": "他没按合同交货，这是犯罪。", "explanation": "这里应该用〈违约〉。犯罪指触犯刑法；没有按合同履行只是违约，应说违约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：“为了钱，开始和朋友一起散步”与动机不相合，句子不通。"}, {"text": "犯罪", "is_correct": true, "explanation": "“犯罪”指触犯法律的行为，与“为了钱”的动机相吻合。"}, {"text": "守法", "is_correct": false, "explanation": "语义：“守法”不是为了钱而和朋友一起去做的行为，与动机不相合，句子不通。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：“为了钱，开始和朋友一起道歉”没有合理的因果关系，句子不通。"}], "explanations": {"散步": "语义：“为了钱，开始和朋友一起散步”与动机不相合，句子不通。", "犯罪": "“犯罪”指触犯法律的行为，与“为了钱”的动机相吻合。", "守法": "语义：“守法”不是为了钱而和朋友一起去做的行为，与动机不相合，句子不通。", "道歉": "语义：“为了钱，开始和朋友一起道歉”没有合理的因果关系，句子不通。"}, "sentence_index": 6, "correct_answer": "犯罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在网上乱发广告，这是犯罪。", "explanation": "这里应该用〈违规〉。犯罪指触犯法律；在网站上违反平台规则应说违规。"}, {"text": "他答应了的事情没做到，这是犯罪。", "explanation": "这里应该用〈失信〉。犯罪指触犯刑法；不守承诺只是失信，应说失信。"}, {"text": "他上班时间偷偷睡觉，这是犯罪的行为。", "explanation": "这里应该用〈违纪〉。犯罪指触犯刑法；上班睡觉只是违反公司纪律，应说违纪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前犯罪过，这次被判得更重了。", "corrected_sentence": "他以前犯过罪，这次被判得更重了。", "error_description": "错误形式：“犯罪过”；正确形式：“犯过罪”。体标“过”应放在动词“犯”之后、宾语“罪”之前，不能放在动宾结构的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次他没有犯了罪，法院才放了他。", "corrected_sentence": "这次他没有犯罪，法院才放了他。", "error_description": "错误形式：“没有犯了罪”；正确形式：“没有犯罪”。“没有”否定时，动词后不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89153, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "雇用", "is_correct": true, "explanation": "正确：雇用与解雇意思相对，雇用是雇人，解雇是辞退员工。"}, {"text": "辞职", "is_correct": false, "explanation": "非反义：辞职指员工自己离开，与解雇同属离职，但不是反义词。"}, {"text": "提拔", "is_correct": false, "explanation": "非反义：提拔指升职，与解雇没有反义关系。"}, {"text": "批准", "is_correct": false, "explanation": "非反义：批准指同意，与解雇没有反义关系。"}], "correct_answer": "雇用", "explanations": {"雇用": "正确：雇用与解雇意思相对，雇用是雇人，解雇是辞退员工。", "辞职": "非反义：辞职指员工自己离开，与解雇同属离职，但不是反义词。", "提拔": "非反义：提拔指升职，与解雇没有反义关系。", "批准": "非反义：批准指同意，与解雇没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89153, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "雇用", "is_correct": true, "explanation": "正确：雇用与解雇意思相对，雇用是雇人，解雇是辞退员工。"}, {"text": "鼓励", "is_correct": false, "explanation": "非反义：鼓励指给人信心或支持，与解雇没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "非反义：修理指把坏的东西修好，与解雇没有反义关系。"}, {"text": "劝说", "is_correct": false, "explanation": "非反义：劝说指用话语说服别人，与解雇没有反义关系。"}], "correct_answer": "雇用", "explanations": {"雇用": "正确：雇用与解雇意思相对，雇用是雇人，解雇是辞退员工。", "鼓励": "非反义：鼓励指给人信心或支持，与解雇没有反义关系。", "修理": "非反义：修理指把坏的东西修好，与解雇没有反义关系。", "劝说": "非反义：劝说指用话语说服别人，与解雇没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89153, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解雇是老板让工人以后不用来上班了。", "primary_collocate": null, "pronunciation": "jiě gù", "ipa": "tɕje˨˩ ku˥˩", "syllable_count": 2, "sentences": [{"text": "老板因为他总是迟到，把他解雇了。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司解雇了三个工作不认真的工人。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班常常睡觉，老板就解雇了他。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂不挣钱，老板只好解雇一些工人。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很怕老板解雇她，所以每天都来得很早。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板昨天解雇了那个偷东西的人。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，再迟到就要解雇你。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板为什么解雇你？你做错了什么？", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆解雇了两个不干净的厨师。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板没有解雇他，只给了他一次机会。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解雇了", "label": "完成体"}, {"form": "解雇过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "老板让工人不再上班，日常口语中的辞退", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89153, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解雇", "is_correct": true, "explanation": "正确：“解雇”指老板辞退员工，与“总是迟到”的处理相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：因为总是迟到，老板不会表扬他，与句中的原因冲突。"}, {"text": "提拔", "is_correct": false, "explanation": "语义：因为总是迟到，老板不会提拔他，句意矛盾。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”说水平、质量，不能用于对人的处理。"}], "explanations": {"解雇": "正确：“解雇”指老板辞退员工，与“总是迟到”的处理相符。", "表扬": "语义：因为总是迟到，老板不会表扬他，与句中的原因冲突。", "提拔": "语义：因为总是迟到，老板不会提拔他，句意矛盾。", "提高": "搭配：“提高”说水平、质量，不能用于对人的处理。"}, "sentence_index": 0, "correct_answer": "解雇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为要照顾父母，解雇了自己。", "explanation": "这里应该用〈辞职〉。解雇是雇主辞退员工，不能解雇自己；员工自己离开要说辞职。"}, {"text": "那名学生因为作弊，被学校解雇了。", "explanation": "这里应该用〈开除〉。解雇只用于劳动关系中的员工，学生被学校除名应说开除。"}, {"text": "公司因为亏损，解雇了这支球队。", "explanation": "这里应该用〈解散〉。解雇只用于辞退人员，球队、组织要说解散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89153, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解雇", "is_correct": true, "explanation": "正确：“再迟到就要解雇你”是老板的警告，与句意相符。"}, {"text": "录用", "is_correct": false, "explanation": "语义：“再迟到就要……”是威胁，录用与之矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“再迟到”的后果不会是感谢，句意矛盾。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量，不能用于人。"}], "explanations": {"解雇": "正确：“再迟到就要解雇你”是老板的警告，与句意相符。", "录用": "语义：“再迟到就要……”是威胁，录用与之矛盾。", "感谢": "语义：“再迟到”的后果不会是感谢，句意矛盾。", "增加": "搭配：“增加”说数量，不能用于人。"}, "sentence_index": 6, "correct_answer": "解雇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双方同意解雇合同。", "explanation": "这里应该用〈解除〉。解雇只用于辞退员工，合同要说解除。"}, {"text": "学校解雇了明天的春游。", "explanation": "这里应该用〈取消〉。解雇只用于辞退员工，活动要说取消。"}, {"text": "他解雇了家里那台旧电脑。", "explanation": "这里应该用〈扔掉〉。解雇只用于辞退员工，不能用于东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板昨天被解雇了那名迟到的员工。", "corrected_sentence": "老板昨天解雇了那名迟到的员工。", "error_description": "“被”位置错误：“解雇”带宾语“那名员工”时是主动用法，“被”不能加在它前面，应说“老板昨天解雇了那名迟到的员工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板昨天解雇着那位迟到的员工。", "corrected_sentence": "老板昨天解雇了那位迟到的员工。", "error_description": "体标误用：“解雇”是一次完成的动作，表示已经发生要用“了”，不能用“着”，应说“老板昨天解雇了那位迟到的员工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89154, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "雇用", "is_correct": true, "explanation": "正确：雇用与解雇意思相对，雇用是雇人，解雇是辞退员工。"}, {"text": "批准", "is_correct": false, "explanation": "非反义：批准指同意，与解雇没有反义关系。"}, {"text": "鼓励", "is_correct": false, "explanation": "非反义：鼓励指给人信心或支持，与解雇没有反义关系。"}, {"text": "提拔", "is_correct": false, "explanation": "非反义：提拔指升职，与解雇没有反义关系。"}], "correct_answer": "雇用", "explanations": {"雇用": "正确：雇用与解雇意思相对，雇用是雇人，解雇是辞退员工。", "批准": "非反义：批准指同意，与解雇没有反义关系。", "鼓励": "非反义：鼓励指给人信心或支持，与解雇没有反义关系。", "提拔": "非反义：提拔指升职，与解雇没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
