INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89154, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "雇主解除雇佣关系，辞退雇员。", "primary_collocate": null, "pronunciation": "jiě gù", "ipa": "tɕje˨˩ ku˥˩", "syllable_count": 2, "sentences": [{"text": "公司没有理由，不能随便解雇员工。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司解雇了他，还给了他三个月的工资。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定解雇那位经常犯错的员工。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司去年解雇了一百多名员工。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律说，雇主不能随便解雇怀孕的员工。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司解雇他以前，先和他谈了一次话。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直担心公司会解雇他。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司因为经济不好，解雇了不少员工。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没做错什么，公司为什么解雇她？", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把那名员工解雇后，又请了新人。", "target_word": "解雇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解雇了", "label": "完成体"}, {"form": "解雇过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "雇主解除雇佣关系，辞退员工，偏正式场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解雇", "is_correct": true, "explanation": "正确：“解雇员工”指雇主解除雇佣关系，与“没有理由，不能随便”相符。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”说活动、会议，不能用于员工。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、地面，不能用于员工。"}, {"text": "抚养", "is_correct": false, "explanation": "语义：抚养指养育子女或亲属，与员工不合。"}], "explanations": {"解雇": "正确：“解雇员工”指雇主解除雇佣关系，与“没有理由，不能随便”相符。", "举办": "搭配：“举办”说活动、会议，不能用于员工。", "打扫": "搭配：“打扫”用于房间、地面，不能用于员工。", "抚养": "语义：抚养指养育子女或亲属，与员工不合。"}, "sentence_index": 0, "correct_answer": "解雇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司因为亏损，解雇了这个部门。", "explanation": "这里应该用〈解散〉。解雇只用于辞退人员，部门、机构要说解散。"}, {"text": "她因为想去外地发展，决定解雇自己。", "explanation": "这里应该用〈辞职〉。解雇是雇主辞退员工，不能解雇自己；员工主动离开要说辞职。"}, {"text": "选民投票解雇了那位议员。", "explanation": "这里应该用〈罢免〉。解雇用于雇佣关系中的员工，议员被罢免应说罢免。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解雇", "is_correct": true, "explanation": "正确：“担心公司会解雇他”指怕被辞退，与句意相符。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：担心的事不会是被感谢，句意矛盾。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“担心”的内容应是不好的事，奖励与之矛盾。"}, {"text": "注销", "is_correct": false, "explanation": "搭配：“注销”用于账号、证件，不说注销人。"}], "explanations": {"解雇": "正确：“担心公司会解雇他”指怕被辞退，与句意相符。", "感谢": "语义：担心的事不会是被感谢，句意矛盾。", "奖励": "语义：“担心”的内容应是不好的事，奖励与之矛盾。", "注销": "搭配：“注销”用于账号、证件，不说注销人。"}, "sentence_index": 6, "correct_answer": "解雇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个学生因为打架，被学校解雇了。", "explanation": "这里应该用〈开除〉。解雇只用于劳动关系中的员工，学生被学校除名应说开除。"}, {"text": "两家公司决定解雇这份合作协议。", "explanation": "这里应该用〈解除〉。解雇只用于辞退员工，协议、合同要说解除。"}, {"text": "剧院解雇了今晚的演出。", "explanation": "这里应该用〈取消〉。解雇只用于辞退员工，演出要说取消。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理把那名迟到的员工解雇。", "corrected_sentence": "经理把那名迟到的员工解雇了。", "error_description": "把字句错误：“把”字句中的动词“解雇”后面不能光秃秃结束，应加“了”，说“把那名迟到的员工解雇了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司解雇着一个努力工作的员工。", "corrected_sentence": "公司解雇了一个努力工作的员工。", "error_description": "体标误用：“解雇”是一次完成的动作，表示已经发生要用“了”，不能用“着”，应说“公司解雇了一个努力工作的员工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
