INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情为什么这样或那样做的根据。", "primary_collocate": null, "pronunciation": "lǐ yóu", "ipa": "li˨˩˦ jou˧˥", "syllable_count": 2, "sentences": [{"text": "你有什么理由不去上课？", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的理由很清楚。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要我们说出自己的理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个理由不够好，我不同意。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有理由，他不会这样做。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了一个很好的理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给了我们三个理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的理由是天气太冷。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉我拒绝的理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到相信他的理由。", "target_word": "理由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "做事或下判断所依据的根据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223a2931-5429-4f73-9c3e-06403fa309c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室不是不去上课的原因，“有什么教室不去上课”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“有什么”后接的是可以说明原因的词，“天气”不能这样接，“有什么天气不去上课”不通。"}, {"text": "理由", "is_correct": true, "explanation": "正确：“有什么理由”是询问原因的固定说法，“不去上课”需要一个根据，符合句意。"}, {"text": "力气", "is_correct": false, "explanation": "语义：力气不能作为不去上课的根据，句意不通。"}], "explanations": {"教室": "语义：教室不是不去上课的原因，“有什么教室不去上课”说不通。", "天气": "搭配：“有什么”后接的是可以说明原因的词，“天气”不能这样接，“有什么天气不去上课”不通。", "理由": "正确：“有什么理由”是询问原因的固定说法，“不去上课”需要一个根据，符合句意。", "力气": "语义：力气不能作为不去上课的根据，句意不通。"}, "sentence_index": 0, "correct_answer": "理由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的理由很先进，大家都很佩服。", "explanation": "这里应该用〈理念〉。“先进”形容理念、技术等，“理由”指做事的根据，不能说“很先进”。"}, {"text": "他提出了一块理由。", "explanation": "量词不当：理由是抽象的，应说“一个理由”或“一条理由”；“块”用于块状的东西，不用于理由。"}, {"text": "这次火灾的理由是电线老化。", "explanation": "这里应该用〈原因〉。“理由”指人做事或说明做法的根据，火灾等事情的起因应说“原因”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "配价：“给”要求能被给予的事物作宾语，月亮不能被公司给人，句意不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是可以一个一个数着送给人的东西，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“三个”后接“天空”不符合常规的计量说法，“三个天空”不通。"}, {"text": "理由", "is_correct": true, "explanation": "正确：“理由”是可数名词，“公司给了我们三个理由”符合句意，表示公司提出的三点根据。"}], "explanations": {"月亮": "配价：“给”要求能被给予的事物作宾语，月亮不能被公司给人，句意不通。", "大海": "语义：大海不是可以一个一个数着送给人的东西，句意不通。", "天空": "搭配：“三个”后接“天空”不符合常规的计量说法，“三个天空”不通。", "理由": "正确：“理由”是可数名词，“公司给了我们三个理由”符合句意，表示公司提出的三点根据。"}, "sentence_index": 6, "correct_answer": "理由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的理由跑得很快。", "explanation": "用法错误：“理由”是抽象的根据，不会跑，不能说“跑得很快”。"}, {"text": "我们的理由很远大，值得尊敬。", "explanation": "这里应该用〈理想〉。“远大”形容理想、抱负，“理由”指做事的根据，不能说“很远大”。"}, {"text": "这个理由重了五公斤。", "explanation": "用法错误：“理由”是抽象的根据，没有重量，不能说“重了五公斤”；说重量的应是“行李”等实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出了三张理由。", "corrected_sentence": "他提出了三条理由。", "error_description": "量词错误：“理由”应说“三条理由”或“三个理由”；“张”用于纸张、桌子等平面的东西，不能用来数理由。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有出说理由。", "corrected_sentence": "他没有说出理由。", "error_description": "补语位置错误：结果补语“出”应紧跟动词“说”，说“说出理由”；“出说理由”的语序不对，母语者会立刻察觉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
