INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "设或是“要是”的意思，说一件还没发生的事。", "primary_collocate": null, "pronunciation": "shè huò", "ipa": "ʂɤ˥˩ xwo˥˩", "syllable_count": 2, "sentences": [{"text": "设或你明年去北京，可以住在我家。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或明天考试，你今晚就早点睡吧。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或我忘了带钥匙，你能给我开门吗？", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或下个月涨工资，我就买一台新电脑。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或他明天不来，会议就改到后天。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或你将来回到这里，一定要来找我。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或这次比赛赢了，我请大家吃饭。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或你迷路了，就给我打电话。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或明早起不来，请你叫我一声。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设或买不到票，我们就明天再走。", "target_word": "设或", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "設或", "label": "繁体"}], "register": "书面", "sense_fingerprint": "连词，相当于“要是”，假设一件还没发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfff504e-4568-4828-bef5-09ba6f7af341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，句中没有相反的前文，不能引出假设。"}, {"text": "设或", "is_correct": true, "explanation": "正确：相当于“要是”，假设你明年去北京。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”要接在原因或结果之后，不能引出还没发生的假设。"}, {"text": "何况", "is_correct": false, "explanation": "语义：“何况”表示递进，要以前文为基础，不能用来引出假设的条件。"}], "explanations": {"然而": "语义：“然而”表示转折，句中没有相反的前文，不能引出假设。", "设或": "正确：相当于“要是”，假设你明年去北京。", "因此": "搭配：“因此”要接在原因或结果之后，不能引出还没发生的假设。", "何况": "语义：“何况”表示递进，要以前文为基础，不能用来引出假设的条件。"}, "sentence_index": 0, "correct_answer": "设或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很喜欢他，设或他是我最好的朋友。", "explanation": "这里应该用〈因为〉。“设或”只引出尚未发生的假设，不能说明已经存在的原因。"}, {"text": "设或天气很冷，他昨天还是跑步去了。", "explanation": "这里应该用〈虽然〉。「设或」表示假设，不能与「昨天」这样已经发生的时间搭配，应说「虽然……还是」。"}, {"text": "这道题设或老师昨天都没做出来。", "explanation": "这里应该用〈连〉。「设或」表示假设，不能表示强调，且这里说的是昨天已经发生的情况，应说「连……都」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否则", "is_correct": false, "explanation": "语义：「否则」表示不然会怎样，要接在前句的做法之后，不能引出「比赛赢了」这一假设条件。"}, {"text": "设或", "is_correct": true, "explanation": "正确：相当于“要是”，假设这次比赛赢了。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，不能引出假设的条件。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示进一步补充理由，不能用来引出假设。"}], "explanations": {"否则": "语义：「否则」表示不然会怎样，要接在前句的做法之后，不能引出「比赛赢了」这一假设条件。", "设或": "正确：相当于“要是”，假设这次比赛赢了。", "反而": "语义：“反而”表示与预期相反，不能引出假设的条件。", "况且": "语义：“况且”表示进一步补充理由，不能用来引出假设。"}, "sentence_index": 6, "correct_answer": "设或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你坐火车设或飞机都可以。", "explanation": "这里应该用〈或者〉。“设或”表示假如，不表示选择。"}, {"text": "他一直在努力，设或昨天终于成功了。", "explanation": "这里应该用〈终于〉。「设或」只说尚未发生的假设，这里说的是昨天已经发生的结果。"}, {"text": "他没有准备，考试设或昨天已经失败了。", "explanation": "这里应该用〈因此〉。「设或」只表示假设，这里说的是已经发生的结果，应说「因此」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "设或了天气好，我们就去爬山。", "corrected_sentence": "设或天气好，我们就去爬山。", "error_description": "错误：“设或了天气好”，应为“设或天气好”。假设连词“设或”后不能加“了”，“了”表示已经完成，与尚未发生的假设相矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "设或的你不喜欢这家，我们就换一家。", "corrected_sentence": "设或你不喜欢这家，我们就换一家。", "error_description": "错误：“设或的你”，应为“设或你”。连词“设或”后面直接接分句的主语，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89162, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离婚", "is_correct": true, "explanation": "“离婚”与“结婚”构成反义，指解除夫妻关系。"}, {"text": "毕业", "is_correct": false, "explanation": "“毕业”指完成学业，与“结婚”没有反义关系。"}, {"text": "生病", "is_correct": false, "explanation": "“生病”指身体不适，与“结婚”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指外出游览，与“结婚”没有反义关系。"}], "correct_answer": "离婚", "explanations": {"离婚": "“离婚”与“结婚”构成反义，指解除夫妻关系。", "毕业": "“毕业”指完成学业，与“结婚”没有反义关系。", "生病": "“生病”指身体不适，与“结婚”没有反义关系。", "旅行": "“旅行”指外出游览，与“结婚”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89162, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离婚", "is_correct": true, "explanation": "“离婚”与“结婚”构成反义，指解除夫妻关系。"}, {"text": "工作", "is_correct": false, "explanation": "“工作”指从事职业活动，与“结婚”没有反义关系。"}, {"text": "出差", "is_correct": false, "explanation": "“出差”指因公外出，与“结婚”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”指休息入睡，与“结婚”没有反义关系。"}], "correct_answer": "离婚", "explanations": {"离婚": "“离婚”与“结婚”构成反义，指解除夫妻关系。", "工作": "“工作”指从事职业活动，与“结婚”没有反义关系。", "出差": "“出差”指因公外出，与“结婚”没有反义关系。", "睡觉": "“睡觉”指休息入睡，与“结婚”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "男女双方依法结为夫妻。", "primary_collocate": null, "pronunciation": "jié hūn", "ipa": "tɕjɛ³⁵ xwən⁵⁵", "syllable_count": 2, "sentences": [{"text": "他们打算明年春天结婚。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，男的二十二岁才能结婚。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚要带身份证去登记。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐上个月结婚了。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经结婚三年了。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人结婚前要先去登记。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候和他结婚？", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚那天下了大雪。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "依法结婚的两个人是夫妻。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她二十五岁就结婚了。", "target_word": "结婚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结了婚", "label": "体标（了）"}, {"form": "结过婚", "label": "体标（过）"}, {"form": "结婚证", "label": "复合"}], "register": "中性", "sense_fingerprint": "男女依法登记，成为夫妻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结婚", "is_correct": true, "explanation": "“结婚”指男女结为夫妻，与“打算明年春天”搭配，句意通顺。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“打算”的内容应是可以计划去做的事，“生病”不能作为计划。"}, {"text": "去世", "is_correct": false, "explanation": "语义：“去世”指人死亡，不能作为“打算”的内容。"}, {"text": "出嫁", "is_correct": false, "explanation": "搭配：“出嫁”只用于女子嫁入夫家，主语“他们”指双方，不能说“出嫁”。"}], "explanations": {"结婚": "“结婚”指男女结为夫妻，与“打算明年春天”搭配，句意通顺。", "生病": "语义：“打算”的内容应是可以计划去做的事，“生病”不能作为计划。", "去世": "语义：“去世”指人死亡，不能作为“打算”的内容。", "出嫁": "搭配：“出嫁”只用于女子嫁入夫家，主语“他们”指双方，不能说“出嫁”。"}, "sentence_index": 0, "correct_answer": "结婚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事情终于结婚了。", "explanation": "这里应该用〈结束〉。“结婚”指男女结为夫妻，事情完结要用“结束”。"}, {"text": "我昨天在商店结婚了一件衣服。", "explanation": "这里应该用〈买〉。“结婚”指男女结为夫妻，不能带“衣服”这样的宾语；在商店得到衣服应该说“买”。"}, {"text": "这道数学题我终于结婚了。", "explanation": "这里应该用〈做完〉。“结婚”指男女结为夫妻，不能用于题目；完成一道题应该说“做完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结婚", "is_correct": true, "explanation": "“和他结婚”表示与对方成为夫妻，句意通顺。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是一个人的身体动作，不能表示与“他”共同进行的事。"}, {"text": "打喷嚏", "is_correct": false, "explanation": "语义：“打喷嚏”是一个人的生理反应，不能与“和他”构成共同行为。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”只涉及一个人，不能带“和他”这样的伴随对象。"}], "explanations": {"结婚": "“和他结婚”表示与对方成为夫妻，句意通顺。", "咳嗽": "语义：“咳嗽”是一个人的身体动作，不能表示与“他”共同进行的事。", "打喷嚏": "语义：“打喷嚏”是一个人的生理反应，不能与“和他”构成共同行为。", "出生": "配价：“出生”只涉及一个人，不能带“和他”这样的伴随对象。"}, "sentence_index": 6, "correct_answer": "结婚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们六年前从小学结婚了。", "explanation": "这里应该用〈毕业〉。“从小学毕业”才自然，“结婚”指男女结为夫妻，不能表示完成学业。"}, {"text": "我每天早上七点结婚，然后去上学。", "explanation": "这里应该用〈起床〉。“结婚”指男女结为夫妻，不是每天早上做的事；早上醒来下床应该说“起床”。"}, {"text": "吃完饭，服务员说请到前台结婚。", "explanation": "这里应该用〈结账〉。“结账”指付清饭钱，“结婚”不能表示付账；前台要做的是结账，不是结婚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把他结婚。", "corrected_sentence": "我想跟他结婚。", "error_description": "错误：“结婚”是离合词，不能直接带宾语，不能用“把”引出对象，写成“把他结婚”错误。正确：应用介词“跟”引出对象，说“跟他结婚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们结婚结的很早。", "corrected_sentence": "他们结婚结得很早。", "error_description": "错误：动词后引出补语要用助词“得”，写成“结的很早”不对。正确：“结婚”是离合词，带“得”补语时要重复动词，说“结婚结得很早”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
