INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89163, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把作品、文章等收进一本书或一个集子里。", "primary_collocate": null, "pronunciation": "shōu lù", "ipa": "ʂoʊ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这本书收录了十首诗。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本词典收录了很多新词。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把我的作文收录在这本小书里。", "target_word": "收录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个集子收录了他早年的作品。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本故事书收录着二十个小故事。", "target_word": "收录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌没有收录在新专辑里。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书的最后收录了一张地图。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本小说集一共收录五篇小说。", "target_word": "收录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的校刊收录过我的一首诗。", "target_word": "收录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你喜欢的诗收录到这个本子里。", "target_word": "收录", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收录了", "label": "体标"}, {"form": "收录过", "label": "体标"}, {"form": "收錄", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "把内容收进某本书或某个集子里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89163, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收录", "is_correct": true, "explanation": "正确：收录（shōu lù），把作品、词语等收进书籍或汇集。"}, {"text": "收据", "is_correct": false, "explanation": "jù 与 lù 声母不同（j 与 l），意思是收据。"}, {"text": "收住", "is_correct": false, "explanation": "zhù 与 lù 声母不同（zh 与 l），意思是收住、停住。"}, {"text": "收付", "is_correct": false, "explanation": "fù 与 lù 声母不同（f 与 l），意思是收款与付款。"}], "explanations": {"收录": "正确：收录（shōu lù），把作品、词语等收进书籍或汇集。", "收据": "jù 与 lù 声母不同（j 与 l），意思是收据。", "收住": "zhù 与 lù 声母不同（zh 与 l），意思是收住、停住。", "收付": "fù 与 lù 声母不同（f 与 l），意思是收款与付款。"}, "sentence_index": null, "correct_answer": "收录"}, "level_3": {"options": [{"text": "收录", "is_correct": true, "explanation": "正确：收录，把十首诗收进这本书里，符合句意。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于音视频，书不能播放诗。"}, {"text": "朗诵", "is_correct": false, "explanation": "搭配：“朗诵”要求有人朗读，书不能朗诵十首诗。"}, {"text": "背诵", "is_correct": false, "explanation": "配价：“背诵”的施事必须是人，书不能背诵。"}], "explanations": {"收录": "正确：收录，把十首诗收进这本书里，符合句意。", "播放": "搭配：“播放”用于音视频，书不能播放诗。", "朗诵": "搭配：“朗诵”要求有人朗读，书不能朗诵十首诗。", "背诵": "配价：“背诵”的施事必须是人，书不能背诵。"}, "sentence_index": 0, "correct_answer": "收录"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察收录了这个迷路的小孩，让他在派出所过夜。", "explanation": "这里应该用〈收留〉。收录用于作品、词语等被收入书籍或汇集，暂时照顾迷路的人要用收留。"}, {"text": "我收录了很多古董，都放在家里。", "explanation": "这里应该用〈收藏〉。收录指把作品收入书籍或集子，珍贵的古董要用收藏。"}, {"text": "记者收录了很多证据，准备写报道。", "explanation": "这里应该用〈搜集〉。收录的对象是作品、词语，搜集证据和材料要用搜集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收录", "is_correct": true, "explanation": "正确：收录，地图被收进书的最后，符合句意。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：书不会吞东西，句子的主语无法执行“吞下”的动作。"}, {"text": "说明", "is_correct": false, "explanation": "搭配：“说明”的宾语是情况、道理，不能说“说明一张地图”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：书不会咬东西，这个动作不符合句意。"}], "explanations": {"收录": "正确：收录，地图被收进书的最后，符合句意。", "吞下": "语义：书不会吞东西，句子的主语无法执行“吞下”的动作。", "说明": "搭配：“说明”的宾语是情况、道理，不能说“说明一张地图”。", "咬": "语义：书不会咬东西，这个动作不符合句意。"}, "sentence_index": 6, "correct_answer": "收录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位好心的阿姨收录了一只流浪猫，养在家里。", "explanation": "这里应该用〈收留〉。收录用于作品、词语等，接纳流浪动物要用收留。"}, {"text": "他把借给朋友的钱收录回来了。", "explanation": "这里应该用〈收回〉。收录指收进书籍或汇集，把借出去的钱拿回来要用收回。"}, {"text": "衣柜里收录着我的冬天衣服。", "explanation": "这里应该用〈收纳〉。收录用于作品、词语，把衣物放进柜子要用收纳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的三首诗都收录了这本书里。", "corrected_sentence": "我的三首诗都收录进了这本书里。", "error_description": "错误：“收录”后漏掉趋向补语“进”。正确说法是“收录进了这本书里”，表示收入书中。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本散文集收录在三十篇文章。", "corrected_sentence": "这本散文集收录了三十篇文章。", "error_description": "错误：“收录”后应用“了”表示完成，这里误用“在”。“收录在”后面不能直接接收录的内容。正确说法是“收录了三十篇文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
