INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收录", "is_correct": true, "explanation": "正确：收录，把小说放进年度选集，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“放进选集”的意思相反。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：“冲洗”用于照片、衣物等，不能用于小说。"}, {"text": "删", "is_correct": false, "explanation": "语义：“删”是去掉，与“放进选集”的意思相反。"}], "explanations": {"收录": "正确：收录，把小说放进年度选集，符合句意。", "扔": "语义：“扔”是丢弃，与“放进选集”的意思相反。", "冲洗": "搭配：“冲洗”用于照片、衣物等，不能用于小说。", "删": "语义：“删”是去掉，与“放进选集”的意思相反。"}, "sentence_index": 6, "correct_answer": "收录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老奶奶收录了一只被丢下的小狗。", "explanation": "这里应该用〈收留〉。收录用于文章、词语等，接纳被丢下的小动物要用收留。"}, {"text": "他收录了借给同学的钱，一分也没少。", "explanation": "这里应该用〈收回〉。收录指收进书籍或汇集，借出去的钱收回来要用收回。"}, {"text": "农民收录了田里的小麦。", "explanation": "这里应该用〈收割〉。收录只用于文章、词语等进入书籍或汇集，割下庄稼要用收割。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些文章都收录了这本选集。", "corrected_sentence": "这些文章都收录进了这本选集。", "error_description": "错误：“收录”后漏掉趋向补语“进”，“收录了这本选集”意思不通。正确说法是“收录进了这本选集”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份年刊收录在三位校友的文章。", "corrected_sentence": "这份年刊收录了三位校友的文章。", "error_description": "错误：“收录”后应用“了”表示完成，这里误用“在”。“收录在”后面不能直接接收录的内容。正确说法是“收录了三位校友的文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
