INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89167, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "数据网络是能让很多电脑互相传送信息的网。", "primary_collocate": null, "pronunciation": "shù jù wǎng luò", "ipa": "ʂu˥˩ tɕy˥˩ wɑŋ˨˩˦ lwo˥˩", "syllable_count": 4, "sentences": [{"text": "数据网络让很多电脑可以互相传送信息。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有一个很大的数据网络。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的电脑都连在同一个数据网络上。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了数据网络，大家可以很快看到文件。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据网络坏了，电脑就不能互相联系了。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是数据网络。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数据网络把全城的银行连在一起。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的电脑和打印机也在一个数据网络里。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要先接上数据网络，电脑才能互相传文件。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的数据网络很安全，信息不会丢。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个数据网络", "label": "量词"}, {"form": "移动数据网络", "label": "复合"}, {"form": "數據網絡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让很多电脑互相传送信息的网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfff504e-4568-4828-bef5-09ba6f7af341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园不能让电脑之间传送信息，句子说的是传输信息的网。"}, {"text": "数据网络", "is_correct": true, "explanation": "正确：让很多电脑互相传送信息的网，与句意相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，无法让电脑互相传送信息。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“让……可以互相传送信息”的主语应是通信网络，书架不能与“传送信息”搭配。"}], "explanations": {"花园": "语义：花园不能让电脑之间传送信息，句子说的是传输信息的网。", "数据网络": "正确：让很多电脑互相传送信息的网，与句意相符。", "厨房": "语义：厨房是做饭的地方，无法让电脑互相传送信息。", "书架": "搭配：“让……可以互相传送信息”的主语应是通信网络，书架不能与“传送信息”搭配。"}, "sentence_index": 0, "correct_answer": "数据网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有了数据网络，大家可以很快吃饱饭。", "explanation": "这里应该用〈食堂〉。食堂能让大家很快吃饱饭；数据网络只负责传输信息，不能提供食物。"}, {"text": "运动员把数据网络拉好了。", "explanation": "这里应该用〈球网〉。球网是挂在球场中间的网，数据网络是传输数据的系统，不能拉起来挂好。"}, {"text": "工地的楼下挂着数据网络。", "explanation": "这里应该用〈安全网〉。安全网是挂在工地上防止坠落的网，数据网络是传输数据的系统，不能用来防止坠落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是摆放花卉的器皿，不能把全城的银行连在一起。"}, {"text": "数据网络", "is_correct": true, "explanation": "正确：能把全城的银行连在一起的通信系统，与“把……连在一起”相符。"}, {"text": "日历", "is_correct": false, "explanation": "语义：日历只用来记录日期，不能连接银行。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛用于照明，不能把全城的银行连在一起。"}], "explanations": {"花瓶": "语义：花瓶是摆放花卉的器皿，不能把全城的银行连在一起。", "数据网络": "正确：能把全城的银行连在一起的通信系统，与“把……连在一起”相符。", "日历": "语义：日历只用来记录日期，不能连接银行。", "蜡烛": "语义：蜡烛用于照明，不能把全城的银行连在一起。"}, "sentence_index": 6, "correct_answer": "数据网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的数据网络很大，可以放很多书。", "explanation": "这里应该用〈书架〉。数据网络是传输信息的系统，不是存放东西的容器，“放”要用于容器。"}, {"text": "小王每天早上给数据网络浇水。", "explanation": "这里误把数据网络当成了植物。“浇水”的对象应是植物，数据网络是传输信息的设备，不是植物，不能浇。"}, {"text": "他每天用数据网络洗脸。", "explanation": "这里的错误是“洗脸”需要毛巾之类的用具，数据网络用于传输信息，不能用来洗脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司有一本很大的数据网络。", "corrected_sentence": "我们公司有一个很大的数据网络。", "error_description": "错误：“一本数据网络”，应为“一个数据网络”。“本”用于书籍，数据网络不用“本”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经数据网络接好了。", "corrected_sentence": "我已经把数据网络接好了。", "error_description": "错误：“我已经数据网络接好了”，应为“我已经把数据网络接好了”。处置式要用“把”把处置对象“数据网络”提到动词前，漏掉“把”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
