INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89168, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门用来在计算机或设备之间传输数据的通信网络。", "primary_collocate": null, "pronunciation": "shù jù wǎng luò", "ipa": "ʂu˥˩ tɕy˥˩ wɑŋ˨˩˦ lwo˥˩", "syllable_count": 4, "sentences": [{"text": "工厂里的机器通过数据网络互相传送数据。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据网络出了问题，设备都连不上了。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数据网络专门传输医院的检查数据。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里新建的数据网络速度非常快。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把所有电脑都接入了数据网络。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据网络的安全，需要专门的人来管理。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和电脑可以在数据网络里交换信息。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的数据网络昨天坏了，网课上不了。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种数据网络只传数据，不能打电话。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司负责维护数据网络。", "target_word": "数据网络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个数据网络", "label": "量词"}, {"form": "移动数据网络", "label": "复合"}, {"form": "數據網絡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "专用于计算机或设备之间传输数据的通信网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfff504e-4568-4828-bef5-09ba6f7af341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道路", "is_correct": false, "explanation": "语义：道路不能用来传送数据，“互相传送数据”需要的是通信网络。"}, {"text": "数据网络", "is_correct": true, "explanation": "正确：专门传输数据的通信网络，与“通过”“互相传送数据”相符。"}, {"text": "流水线", "is_correct": false, "explanation": "搭配：“通过”后接的应是传输媒介，流水线是生产线，不能与“传送数据”搭配。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是用餐的地方，不能作为机器之间传送数据的途径。"}], "explanations": {"道路": "语义：道路不能用来传送数据，“互相传送数据”需要的是通信网络。", "数据网络": "正确：专门传输数据的通信网络，与“通过”“互相传送数据”相符。", "流水线": "搭配：“通过”后接的应是传输媒介，流水线是生产线，不能与“传送数据”搭配。", "食堂": "语义：食堂是用餐的地方，不能作为机器之间传送数据的途径。"}, "sentence_index": 0, "correct_answer": "数据网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们周末去数据网络玩游戏。", "explanation": "这里应该用〈网吧〉。数据网络是传输数据的通信系统，不是可以前往、进去玩耍的场所。"}, {"text": "我们公司建了一个数据网络来煮饭。", "explanation": "这里应该用〈厨房〉。厨房用于做饭，数据网络只负责在设备之间传输数据，不能用来煮饭。"}, {"text": "渔民把数据网络撒进了河里。", "explanation": "这里应该用〈渔网〉。渔网是捕鱼用的网，数据网络是传输数据的通信系统，不能撒进河里捕鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是交换信息的场所，“在……里”后接的应是能进行信息交换的系统。"}, {"text": "数据网络", "is_correct": true, "explanation": "正确：手机和电脑通过它交换信息，与“交换信息”相符。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是买卖菜的地方，手机和电脑不能在那里交换信息。"}, {"text": "农田", "is_correct": false, "explanation": "语义：农田是种植作物的地方，与手机、电脑交换信息无关。"}], "explanations": {"冰箱": "语义：冰箱不是交换信息的场所，“在……里”后接的应是能进行信息交换的系统。", "数据网络": "正确：手机和电脑通过它交换信息，与“交换信息”相符。", "菜市场": "语义：菜市场是买卖菜的地方，手机和电脑不能在那里交换信息。", "农田": "语义：农田是种植作物的地方，与手机、电脑交换信息无关。"}, "sentence_index": 6, "correct_answer": "数据网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把数据网络插到路由器上。", "explanation": "这里应该用〈网线〉。网线是插在路由器上的线，数据网络是传输数据的系统，不能插到路由器上。"}, {"text": "他为人热情，朋友很多，在商界的数据网络很广。", "explanation": "这里应该用〈人脉〉。人脉指人与人之间的关系，数据网络是设备之间传输数据的系统，不能指人际关系。"}, {"text": "他在公司负责背诵数据网络。", "explanation": "这里误把数据网络当成了文字或课文。“背诵”的对象是课文，数据网络是设备，不能背诵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司上个月才建好一本新数据网络。", "corrected_sentence": "我们公司上个月才建好一套新数据网络。", "error_description": "错误：“一本数据网络”，应为“一套数据网络”。“本”用于书籍，数据网络是一整套系统，应用量词“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们为新办公室建了一台数据网络。", "corrected_sentence": "我们为新办公室建了一套数据网络。", "error_description": "错误：“一台数据网络”，应为“一套数据网络”。“台”用于机器设备，数据网络是一整套系统，应该用量词“套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
