INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写作;撰写。", "primary_collocate": null, "pronunciation": "zhù", "ipa": "ʈʂu˥˩", "syllable_count": 1, "sentences": [{"text": "这本小说是一位老教授著的。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生著有三本关于历史的书。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她花了五年时间，著成了这本书。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲁迅著的小说，我读过好几本。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生著过一本讲养生的书。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他白天上班，晚上在家著书。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师正在著一本新的历史教材。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书是三位专家一起著的。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后，著了一本关于家乡的书。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是谁著的？封面上没写名字。", "target_word": "著", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "著了", "label": "完成体"}, {"form": "著过", "label": "经历体"}, {"form": "著作", "label": "复合"}, {"form": "著者", "label": "复合"}], "register": "书面", "sense_fingerprint": "著书；撰写作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89170, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "猪", "is_correct": false, "explanation": "zhū（第一声）与 zhù（第四声）声调不同，意思是猪。"}, {"text": "著", "is_correct": true, "explanation": "著（zhù，第四声）：写作、撰写，是本题的正确答案。"}, {"text": "处", "is_correct": false, "explanation": "chù 与 zhù 声母不同（ch 与 zh），声调相同，意思是处所、地方。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。"}, {"text": "煮", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是烧煮。"}, {"text": "树", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），声调相同，意思是树木。"}], "explanations": {"猪": "zhū（第一声）与 zhù（第四声）声调不同，意思是猪。", "著": "著（zhù，第四声）：写作、撰写，是本题的正确答案。", "处": "chù 与 zhù 声母不同（ch 与 zh），声调相同，意思是处所、地方。", "竹": "zhú（第二声）与 zhù（第四声）声调不同，意思是竹子。", "煮": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是烧煮。", "树": "shù 与 zhù 声母不同（sh 与 zh），声调相同，意思是树木。"}, "sentence_index": null, "correct_answer": "著"}, "level_3": {"options": [{"text": "画", "is_correct": false, "explanation": "搭配：“画”用于图画，小说是文字作品，不能说“画的小说”。"}, {"text": "著", "is_correct": true, "explanation": "著：写作、撰写。这里指老教授写成了这本小说，与“小说”和“教授”相符。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”指拍摄影片或照片，与“小说”不相容，句意不通。"}, {"text": "演", "is_correct": false, "explanation": "语义：“演”指表演角色，教授不能靠“演”写出一本小说。"}], "explanations": {"画": "搭配：“画”用于图画，小说是文字作品，不能说“画的小说”。", "著": "著：写作、撰写。这里指老教授写成了这本小说，与“小说”和“教授”相符。", "拍": "语义：“拍”指拍摄影片或照片，与“小说”不相容，句意不通。", "演": "语义：“演”指表演角色，教授不能靠“演”写出一本小说。"}, "sentence_index": 0, "correct_answer": "著"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都给老家的父母著信。", "explanation": "这里应该用〈写〉。“著”多指撰写书籍、著作，写信要用〈写〉，不能说“著信”。"}, {"text": "这位作曲家著了一首交响曲。", "explanation": "这里应该用〈创作〉。“著”指撰写文字作品，谱写交响曲等乐曲要用〈创作〉。"}, {"text": "这位工人著了一扇新门。", "explanation": "这里应该用〈装〉。“著”指撰写书籍、论著，安装门扇要用〈装〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89170, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "珠", "is_correct": false, "explanation": "zhū（第一声）与 zhù（第四声）声调不同，意思是珠子。"}, {"text": "著", "is_correct": true, "explanation": "著（zhù，第四声）：写作、撰写，是本题的正确答案。"}, {"text": "逐", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是追赶、依次。"}, {"text": "主", "is_correct": false, "explanation": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是主人。"}, {"text": "数", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），声调相同，意思是数字。"}], "explanations": {"珠": "zhū（第一声）与 zhù（第四声）声调不同，意思是珠子。", "著": "著（zhù，第四声）：写作、撰写，是本题的正确答案。", "逐": "zhú（第二声）与 zhù（第四声）声调不同，意思是追赶、依次。", "主": "zhǔ（第三声）与 zhù（第四声）声调不同，意思是主人。", "数": "shù 与 zhù 声母不同（sh 与 zh），声调相同，意思是数字。"}, "sentence_index": null, "correct_answer": "著"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，教材不能吃，句子不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不能说穿一本教材。"}, {"text": "著", "is_correct": true, "explanation": "著：写作、撰写。这里指老师在编写新教材，符合“正在…一本新教材”的语境。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧，老师不会去烧一本新教材，句意不合常理。"}], "explanations": {"吃": "语义：“吃”指进食，教材不能吃，句子不通。", "穿": "搭配：“穿”用于衣服、鞋袜，不能说穿一本教材。", "著": "著：写作、撰写。这里指老师在编写新教材，符合“正在…一本新教材”的语境。", "烧": "语义：“烧”指燃烧，老师不会去烧一本新教材，句意不合常理。"}, "sentence_index": 6, "correct_answer": "著"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他花了一周时间，著了一首新歌。", "explanation": "这里应该用〈编〉。“著”指撰写书籍、文章等著作，编写歌曲、谱曲要用〈编〉。"}, {"text": "她从小就喜欢著诗。", "explanation": "这里应该用〈作〉。“著”多用于书籍、论著，写诗要用〈作〉。"}, {"text": "他在墙上著了一幅壁画。", "explanation": "这里应该用〈画〉。“著”指写成书籍，在墙上绘制壁画要用〈画〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老作家一生著着八部长篇小说。", "corrected_sentence": "这位老作家一生著有八部长篇小说。", "error_description": "错误：“著着八部”。正确：“著有八部”。“著有”是固定说法，表示写过若干作品；“着”表示动作的持续状态，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她花了三年，著了成一本小说。", "corrected_sentence": "她花了三年，著成了一本小说。", "error_description": "错误：“著了成”。正确：“著成了”。“成”是“著”的结果补语，要紧跟在“著”后面，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
