INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89171, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "误指因迟到或耽搁而错过时间、车船或事情。", "primary_collocate": null, "pronunciation": "wù", "ipa": "u˥˩", "syllable_count": 1, "sentences": [{"text": "路上堵车，我误了火车。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡过头，误了上课时间。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别为了玩，误了正事。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机晚点，我误了会议。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪，我误了回家的车。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我误了你的事。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他病了，误了一个星期的课。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快走吧，别误了时间。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只差五分钟，我们就误了船。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别误了这件事，今天必须做完。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "误了", "label": "体标"}, {"form": "误过", "label": "体标"}], "register": "中性", "sense_fingerprint": "因迟到或耽搁而错过时间、车船、事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4db7646-0948-40ca-93a1-22bf840509fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89171, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "午", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是中午。"}, {"text": "误", "is_correct": true, "explanation": "正确：“误”（第四声）表示耽误、错过，即本句的意思。"}, {"text": "无", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）声调不同，意思是没有。"}, {"text": "步", "is_correct": false, "explanation": "bù 与 wù 声母不同（b 与 w），意思是步子。"}, {"text": "户", "is_correct": false, "explanation": "hù 与 wù 声母不同（h 与 w），意思是门户、家庭。"}], "explanations": {"午": "wǔ（第三声）与 wù（第四声）声调不同，意思是中午。", "误": "正确：“误”（第四声）表示耽误、错过，即本句的意思。", "无": "wú（第二声）与 wù（第四声）声调不同，意思是没有。", "步": "bù 与 wù 声母不同（b 与 w），意思是步子。", "户": "hù 与 wù 声母不同（h 与 w），意思是门户、家庭。"}, "sentence_index": null, "correct_answer": "误"}, "level_3": {"options": [{"text": "买", "is_correct": false, "explanation": "语义：堵车导致的是错过火车，“买”与句意不符，句子说不通。"}, {"text": "误", "is_correct": true, "explanation": "正确：堵车导致没赶上火车，用“误”表示因耽搁而错过，符合句意。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指把东西交给别人，火车不能被“送”，与句意不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，与堵车后错过车的语境不符。"}], "explanations": {"买": "语义：堵车导致的是错过火车，“买”与句意不符，句子说不通。", "误": "正确：堵车导致没赶上火车，用“误”表示因耽搁而错过，符合句意。", "送": "语义：“送”指把东西交给别人，火车不能被“送”，与句意不符。", "修": "语义：“修”指修理，与堵车后错过车的语境不符。"}, "sentence_index": 0, "correct_answer": "误"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书店里误了一本书。", "explanation": "这里的“误”不能带“书”这类实物。耽误义只用于时间、车船、事情，不能说“误了一本书”。"}, {"text": "我在厨房里误了一把菜刀。", "explanation": "同上，“误”的耽误义不能带“菜刀”这类实物。"}, {"text": "我在公园里误了一棵树。", "explanation": "同上，“误”的耽误义不能带“树”这类实物，句子说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89171, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "舞", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞。"}, {"text": "误", "is_correct": true, "explanation": "正确：“误”（第四声）表示耽误，即本句的意思。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 wù 声母不同（n 与 w），意思是愤怒。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 wù 声母不同（g 与 w），意思是故意、缘故。"}, {"text": "入", "is_correct": false, "explanation": "rù 与 wù 声母不同（r 与 w），意思是进入。"}], "explanations": {"舞": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞。", "误": "正确：“误”（第四声）表示耽误，即本句的意思。", "怒": "nù 与 wù 声母不同（n 与 w），意思是愤怒。", "故": "gù 与 wù 声母不同（g 与 w），意思是故意、缘故。", "入": "rù 与 wù 声母不同（r 与 w），意思是进入。"}, "sentence_index": null, "correct_answer": "误"}, "level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能搭配“课”，不能说“喝了一个星期的课”。"}, {"text": "误", "is_correct": true, "explanation": "正确：因病缺课，用“误”表示耽误、错过课程，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是字、文章，不能说“写课”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，与“课”无关，句子不通。"}], "explanations": {"喝": "搭配：“喝”不能搭配“课”，不能说“喝了一个星期的课”。", "误": "正确：因病缺课，用“误”表示耽误、错过课程，符合句意。", "写": "搭配：“写”的对象是字、文章，不能说“写课”。", "洗": "语义：“洗”指清洗，与“课”无关，句子不通。"}, "sentence_index": 6, "correct_answer": "误"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在教室里误了一支笔。", "explanation": "这里的“误”不能带“笔”这类实物。耽误义只用于时间、车船、事情。"}, {"text": "他在街上误了一只鸽子。", "explanation": "同上，“误”的耽误义不能带“鸽子”这类动物。"}, {"text": "我们在院子里误了一把伞。", "explanation": "同上，“误”的耽误义不能带“伞”这类实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前误了过一次火车。", "corrected_sentence": "我以前误过一次火车。", "error_description": "体标错误：“误”后已带“过”表示经历，不能再加“了”，应说“误过一次火车”，不说“误了过一次火车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别误着明天的会议，早点准备。", "corrected_sentence": "别误了明天的会议，早点准备。", "error_description": "体标错误：“误”后表示完成或结果应用“了”，不用“着”。正确说法是“误了明天的会议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
