INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89172, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "耽搁或连累，使别人的事情、前途等受到损失。", "primary_collocate": null, "pronunciation": "wù", "ipa": "u˥˩", "syllable_count": 1, "sentences": [{"text": "医生来晚了，误了病人的治疗。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做会误了孩子。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直玩游戏，误了自己的前途。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天天贪玩，误了自己的学业。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李来迟了，误了大家的时间。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别因为小事，误了大事。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话没人接，误了我的事。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的一句话，误了整个计划。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母太宠孩子，反而误了孩子。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让坏习惯误了你的将来。", "target_word": "误", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "误了", "label": "体标"}, {"form": "误过", "label": "体标"}], "register": "中性", "sense_fingerprint": "耽搁或连累，使别人的事情、前途受损失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4db7646-0948-40ca-93a1-22bf840509fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "午", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是中午。"}, {"text": "误", "is_correct": true, "explanation": "正确：“误”（第四声）表示耽搁、使受害，即本句的意思。"}, {"text": "目", "is_correct": false, "explanation": "mù 与 wù 声母不同（m 与 w），意思是眼睛、目标。"}, {"text": "户", "is_correct": false, "explanation": "hù 与 wù 声母不同（h 与 w），意思是门户、家庭。"}, {"text": "付", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），意思是付钱。"}], "explanations": {"午": "wǔ（第三声）与 wù（第四声）声调不同，意思是中午。", "误": "正确：“误”（第四声）表示耽搁、使受害，即本句的意思。", "目": "mù 与 wù 声母不同（m 与 w），意思是眼睛、目标。", "户": "hù 与 wù 声母不同（h 与 w），意思是门户、家庭。", "付": "fù 与 wù 声母不同（f 与 w），意思是付钱。"}, "sentence_index": null, "correct_answer": "误"}, "level_3": {"options": [{"text": "救", "is_correct": false, "explanation": "搭配：“救”搭配的是人，不能说“救了治疗”。"}, {"text": "误", "is_correct": true, "explanation": "正确：来晚耽误了治疗，用“误”表示耽误、影响，符合句意。"}, {"text": "测", "is_correct": false, "explanation": "语义：“测”指测量，与治疗无关，句子不通。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”不能搭配“治疗”，不能说“送了病人的治疗”。"}], "explanations": {"救": "搭配：“救”搭配的是人，不能说“救了治疗”。", "误": "正确：来晚耽误了治疗，用“误”表示耽误、影响，符合句意。", "测": "语义：“测”指测量，与治疗无关，句子不通。", "送": "搭配：“送”不能搭配“治疗”，不能说“送了病人的治疗”。"}, "sentence_index": 0, "correct_answer": "误"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正在误这个新方案。", "explanation": "这里应该用〈研究〉。“误”没有研究、探讨的意思，不能用在“方案”上。"}, {"text": "大家正在误预算的问题。", "explanation": "这里应该用〈讨论〉。“误”没有讨论、商议的意思，不能用在“预算的问题”上。"}, {"text": "他在博物馆里误油画。", "explanation": "这里应该用〈欣赏〉。“误”没有欣赏的意思，不能用在“油画”上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89172, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）声调不同，意思是没有。"}, {"text": "误", "is_correct": true, "explanation": "正确：“误”（第四声）表示耽搁、连累，即本句的意思。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 wù 声母不同（n 与 w），意思是愤怒。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 wù 声母不同（g 与 w），意思是故意、缘故。"}, {"text": "入", "is_correct": false, "explanation": "rù 与 wù 声母不同（r 与 w），意思是进入。"}], "explanations": {"无": "wú（第二声）与 wù（第四声）声调不同，意思是没有。", "误": "正确：“误”（第四声）表示耽搁、连累，即本句的意思。", "怒": "nù 与 wù 声母不同（n 与 w），意思是愤怒。", "故": "gù 与 wù 声母不同（g 与 w），意思是故意、缘故。", "入": "rù 与 wù 声母不同（r 与 w），意思是进入。"}, "sentence_index": null, "correct_answer": "误"}, "level_3": {"options": [{"text": "帮", "is_correct": false, "explanation": "语义：电话没人接是耽误了事，“帮”表示助益，与句意相反，句子不通。"}, {"text": "误", "is_correct": true, "explanation": "正确：电话没人接耽误了事情，用“误”表示耽误、连累，符合句意。"}, {"text": "押", "is_correct": false, "explanation": "语义：“押”指抵押，与电话没人接的语境不符，句子不通。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指切割，与“我的事”无关，句子不通。"}], "explanations": {"帮": "语义：电话没人接是耽误了事，“帮”表示助益，与句意相反，句子不通。", "误": "正确：电话没人接耽误了事情，用“误”表示耽误、连累，符合句意。", "押": "语义：“押”指抵押，与电话没人接的语境不符，句子不通。", "切": "语义：“切”指切割，与“我的事”无关，句子不通。"}, "sentence_index": 6, "correct_answer": "误"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都在误他的生日。", "explanation": "这里应该用〈庆祝〉。“误”没有庆祝的意思，不能用在“生日”上。"}, {"text": "我们必须误交通规则。", "explanation": "这里应该用〈遵守〉。“误”没有遵守的意思，不能用在“交通规则”上。"}, {"text": "他在舞台上误魔术。", "explanation": "这里应该用〈表演〉。“误”没有表演的意思，不能用在“魔术”上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他迟到了一次，误着了自己的前途。", "corrected_sentence": "他迟到了一次，误了自己的前途。", "error_description": "体标错误：“误”后表示结果应用“了”，不用“着”。正确说法是“误了自己的前途”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直没醒，把一件大事误。", "corrected_sentence": "他一直没醒，把一件大事误了。", "error_description": "体标缺失：“把”字句中动词“误”后要带“了”等补充成分，不能只说“误”，应说“把一件大事误了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
