INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89173, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "货币是买东西时用的钱。", "primary_collocate": null, "pronunciation": "huò bì", "ipa": "xuɔ˥˩ pi˥˩", "syllable_count": 2, "sentences": [{"text": "买东西要用货币。", "target_word": "货币", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去国外旅行要换当地货币。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店只收本国货币。", "target_word": "货币", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你带的是哪国的货币？", "target_word": "货币", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "美元是美国的货币。", "target_word": "货币", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在机场换了一些外国货币。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子认识了几种不同的货币。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机器可以收各种货币。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日本用的货币叫日元。", "target_word": "货币", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出国前我先准备好了当地货币。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "貨幣", "label": "繁体"}, {"form": "外国货币", "label": "复合"}, {"form": "当地货币", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常买东西、换钱时用的钱，常指某国的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89173, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "货币", "is_correct": true, "explanation": "货币就是买东西时用的钱，填入后语义吻合。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不是付款的东西，与“买东西要用”的语境不符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能用来付款，与“买东西要用”的语境不符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不是买东西时的付款工具。"}], "explanations": {"货币": "货币就是买东西时用的钱，填入后语义吻合。", "书本": "语义：书本不是付款的东西，与“买东西要用”的语境不符。", "雨伞": "语义：雨伞不能用来付款，与“买东西要用”的语境不符。", "地图": "语义：地图不是买东西时的付款工具。"}, "sentence_index": 0, "correct_answer": "货币"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的货币是十块钱。", "explanation": "这里应该用〈价格〉。衣服的价钱用“价格”表示，货币指付款用的钱本身，不能指商品的价钱。"}, {"text": "银行把贷款货币调低了。", "explanation": "这里应该用〈利率〉。可以调低的是利率，货币本身不能被调低。"}, {"text": "他手里拿着一只货币。", "explanation": "这里应该用〈种〉。货币的量词用“种”，“只”用于动物等，不用于货币。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "货币", "is_correct": true, "explanation": "货币是可以被认识、分辨的一类钱，填入后语义吻合。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳不是可以分类认识的种类。"}, {"text": "汗水", "is_correct": false, "explanation": "语义：汗水是身体排出的液体，不是可以分种类认识的东西，句子不通。"}, {"text": "纸屑", "is_correct": false, "explanation": "语义：纸屑是碎纸，不能说“认识了几种不同的纸屑”。"}], "explanations": {"货币": "货币是可以被认识、分辨的一类钱，填入后语义吻合。", "心跳": "语义：心跳不是可以分类认识的种类。", "汗水": "语义：汗水是身体排出的液体，不是可以分种类认识的东西，句子不通。", "纸屑": "语义：纸屑是碎纸，不能说“认识了几种不同的纸屑”。"}, "sentence_index": 6, "correct_answer": "货币"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个市场的货币很便宜。", "explanation": "这里应该用〈东西〉。“便宜”形容的是商品，货币是付款用的钱本身，不能说便宜。"}, {"text": "他每月的货币是五千元。", "explanation": "这里应该用〈工资〉。货币不能用来表示月收入的数额。"}, {"text": "他把当地货币唱了一遍。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌曲，货币不能被唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去国外前他先换好了很当地货币。", "corrected_sentence": "去国外前他先换好了当地货币。", "error_description": "错误：多出“很”。“当地”修饰名词“货币”时是定语，不能受程度副词“很”修饰，应为“当地货币”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他认识了几只不同的货币。", "corrected_sentence": "他认识了几种不同的货币。", "error_description": "错误：量词“只”，应为“种”。“只”用于动物等，货币的量词是“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
