INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89174, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "充当商品交换媒介的东西，如纸币、硬币。", "primary_collocate": null, "pronunciation": "huò bì", "ipa": "xuɔ˥˩ pi˥˩", "syllable_count": 2, "sentences": [{"text": "货币是商品交换的媒介。", "target_word": "货币", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "纸币和硬币都是货币。", "target_word": "货币", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "历史上的货币有很多种。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货币的价值会随经济变化。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个国家都有自己的货币。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代人用贝壳当货币。", "target_word": "货币", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "银行负责发行和管理货币。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货币贬值通常会引起物价上涨。", "target_word": "货币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货币的出现让交易变得方便。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汇率是两种货币之间的比价。", "target_word": "货币", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "貨幣", "label": "繁体"}, {"form": "数字货币", "label": "复合"}, {"form": "虚拟货币", "label": "复合"}], "register": "书面语", "sense_fingerprint": "经济学意义上充当商品交换媒介的东西，如纸币、硬币", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "货币", "is_correct": true, "explanation": "货币正是充当商品交换媒介的东西，填入后语义吻合。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不是充当交换媒介的东西。"}, {"text": "货物", "is_correct": false, "explanation": "语义：货物是被交换的对象，不是交换的媒介。"}, {"text": "发票", "is_correct": false, "explanation": "搭配：“媒介”前一般是能承担交换功能的事物，“发票”是交易凭证，不能说成交换的媒介。"}], "explanations": {"货币": "货币正是充当商品交换媒介的东西，填入后语义吻合。", "工厂": "语义：工厂是生产场所，不是充当交换媒介的东西。", "货物": "语义：货物是被交换的对象，不是交换的媒介。", "发票": "搭配：“媒介”前一般是能承担交换功能的事物，“发票”是交易凭证，不能说成交换的媒介。"}, "sentence_index": 0, "correct_answer": "货币"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的货币很好吃。", "explanation": "这里应该用〈食物〉。货币指充当交换媒介的钱，不能被吃，“好吃”形容的应是食物。"}, {"text": "这家公司去年的货币很高。", "explanation": "这里应该用〈利润〉。货币指交换媒介本身，不能用来形容收益的高低。"}, {"text": "妈妈把货币放进冰箱里冷藏。", "explanation": "这里应该用〈食物〉。货币是交换媒介，不需要冷藏；放进冰箱冷藏的应是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "货币", "is_correct": true, "explanation": "货币是银行发行和管理的对象，填入后语义吻合。"}, {"text": "树木", "is_correct": false, "explanation": "语义：银行不发行、也不管理树木，与句中“发行”“管理”的对象不符。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：银行不会管理病毒，句子语义不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“发行”一般用于纸币、票证、书刊等，不说“发行作业”。"}], "explanations": {"货币": "货币是银行发行和管理的对象，填入后语义吻合。", "树木": "语义：银行不发行、也不管理树木，与句中“发行”“管理”的对象不符。", "病毒": "语义：银行不会管理病毒，句子语义不通。", "作业": "搭配：“发行”一般用于纸币、票证、书刊等，不说“发行作业”。"}, "sentence_index": 6, "correct_answer": "货币"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每月的货币是五千元。", "explanation": "这里应该用〈工资〉。货币指充当交换媒介的钱，不能用来表示月收入的数额。"}, {"text": "这件衣服的货币很便宜。", "explanation": "这里应该用〈价格〉。商品的价钱要说“价格”，货币不能用来形容便宜与否。"}, {"text": "我昨天给货币打了个电话。", "explanation": "这里应该用〈朋友〉。货币是交换媒介，不能接电话；打电话的对象应是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他投资了一条虚拟货币。", "corrected_sentence": "他投资了一种虚拟货币。", "error_description": "错误：量词“条”，应为“种”。“条”用于细长的东西，货币的量词是“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两只货币之间的比价叫汇率。", "corrected_sentence": "这两种货币之间的比价叫汇率。", "error_description": "错误：量词“只”，应为“种”。“只”用于动物等，货币的量词是“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
