INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "警察中具有一定级别的官员。", "primary_collocate": null, "pronunciation": "jǐng guān", "ipa": "tɕiŋ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "他从警察升为警官了。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有通过考试，才能成为警官。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位警官的级别很高。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是警察局里级别最高的警官。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肩上有星的警官，级别比一般警察高。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王警官今年升了职。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作很努力，三十岁就当上了警官。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校专门培养未来的警官。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警官的制服和普通警察的不一样。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是市里最年轻的警官。", "target_word": "警官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位警官", "label": "量词"}, {"form": "警官证", "label": "复合"}], "register": "中性", "sense_fingerprint": "警察中有级别的官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警官", "is_correct": true, "explanation": "正确：“升为”后接职务、级别，“警官”指有级别的警察官员，符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”不是职务或级别，“从警察升为学生”不合常理。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“从警察升为农民”的身份变化不合句意。"}, {"text": "战士", "is_correct": false, "explanation": "搭配：“升为”需接职务或级别，“战士”是职业称呼，不能用于这一搭配。"}], "explanations": {"警官": "正确：“升为”后接职务、级别，“警官”指有级别的警察官员，符合句意。", "学生": "语义：“学生”不是职务或级别，“从警察升为学生”不合常理。", "农民": "语义：“从警察升为农民”的身份变化不合句意。", "战士": "搭配：“升为”需接职务或级别，“战士”是职业称呼，不能用于这一搭配。"}, "sentence_index": 0, "correct_answer": "警官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位警官每天在医院里为病人做手术。", "explanation": "这里应该用〈医生〉。警官是警察中的官员，为病人做手术的是医生。"}, {"text": "这位警官在法庭上主持审判。", "explanation": "这里应该用〈法官〉。警官是警察中的官员，主持审判的是法官。"}, {"text": "那位警官每天在地里种庄稼。", "explanation": "这里应该用〈农民〉。警官是警察中的官员，在地里种庄稼的是农民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警官", "is_correct": true, "explanation": "正确：“当上了”接职务，“警官”是有级别的警察官员，与“工作努力”的结果相合。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”不是靠努力可以“当上”的身份，句意荒谬。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“老人”不是职务，不能“当上”；且与“三十岁”矛盾。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：“孩子”不是职务，不能说“当上了孩子”。"}], "explanations": {"警官": "正确：“当上了”接职务，“警官”是有级别的警察官员，与“工作努力”的结果相合。", "婴儿": "语义：“婴儿”不是靠努力可以“当上”的身份，句意荒谬。", "老人": "语义：“老人”不是职务，不能“当上”；且与“三十岁”矛盾。", "孩子": "语义：“孩子”不是职务，不能说“当上了孩子”。"}, "sentence_index": 6, "correct_answer": "警官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口停着一辆警官。", "explanation": "这里应该用〈位〉。量词“辆”用于车辆，指人的警官应用“位”。"}, {"text": "我们小区来了一台新警官。", "explanation": "这里应该用〈位〉。量词“台”用于机器设备，不用于人。"}, {"text": "这所学校里有一座很高的警官。", "explanation": "这里应该用〈位〉。量词“座”用于建筑、山等大型固定物，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于从普通警察升为一辆警官了。", "corrected_sentence": "他终于从普通警察升为一位警官了。", "error_description": "量词错误：指人的“警官”应用“位”，“辆”用于车。正确形式是「升为一位警官」，错误形式是「升为一辆警官」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他二十多岁就当了上警官。", "corrected_sentence": "他二十多岁就当上了警官。", "error_description": "补语位置错误：“当上”是动补结构，“了”应放在“上”之后。正确形式是「当上了警官」，错误形式是「当了上警官」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
