INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89177, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89177, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旅程是出门远行时，从出发到到达走的路。", "primary_collocate": null, "pronunciation": "lǚ chéng", "ipa": "ly˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "从上海到拉萨，旅程有三千多公里。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上的旅程很辛苦。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时走过漫长的旅程。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐船的旅程要两天一夜。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅程漫长，孩子在车上睡着了。", "target_word": "旅程", "complexity_tier": "T3", "furigana": "lǚ chéng", "sentence_source": "generated"}, {"text": "他走完了最后一段旅程。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回家的旅程总是特别快。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这趟旅程不远，一天就到。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑马的旅程比开车慢得多。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一路的旅程，我们都带着地图。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段旅程", "label": "量词"}], "register": "中性", "sense_fingerprint": "出发到到达所走的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅程", "is_correct": true, "explanation": "“旅程”指从出发到到达所走的路，可以用公里来计算，符合“有三千多公里”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不用公里计量，不能说体重有三千多公里。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是路途，说它有三千多公里，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是路途，“有三千多公里”与考试的内容不相合。"}], "explanations": {"旅程": "“旅程”指从出发到到达所走的路，可以用公里来计算，符合“有三千多公里”。", "体重": "搭配：“体重”不用公里计量，不能说体重有三千多公里。", "作业": "语义：作业不是路途，说它有三千多公里，句意不通。", "考试": "语义：考试不是路途，“有三千多公里”与考试的内容不相合。"}, "sentence_index": 0, "correct_answer": "旅程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我已经把事故的旅程告诉了老师。", "explanation": "这里应该用〈经过〉。旅程指出门远行时从出发到到达走的路，事故的发生过程要用〈经过〉。"}, {"text": "这位旅程很有礼貌。", "explanation": "这里应该用〈旅客〉。旅程指路途，不能指人。"}, {"text": "这家工厂的生产旅程很严格。", "explanation": "这里应该用〈过程〉。旅程指出门远行时走的路，工厂的生产步骤要用〈过程〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅程", "is_correct": true, "explanation": "“回家的旅程”指回家路上的行程，可以用“快”来形容。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“快”不能用来形容工资，不能说回家的工资快。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是路途，“回家的感冒总是特别快”句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是路程，不能说回家的钥匙快。"}], "explanations": {"旅程": "“回家的旅程”指回家路上的行程，可以用“快”来形容。", "工资": "搭配：“快”不能用来形容工资，不能说回家的工资快。", "感冒": "语义：感冒是疾病，不是路途，“回家的感冒总是特别快”句意不通。", "钥匙": "语义：钥匙不是路程，不能说回家的钥匙快。"}, "sentence_index": 6, "correct_answer": "旅程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我国旅程发展很快。", "explanation": "这里应该用〈经济〉。旅程指路途，不能指经济状况发展，应说经济发展。"}, {"text": "他的旅程提高了不少。", "explanation": "这里应该用〈成绩〉。旅程不能提高，成绩才能提高。"}, {"text": "这个旅程很好用。", "explanation": "这里应该用〈网站〉。旅程是路途，不能说好用，好用的应是网站或工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "从北京到广州，这座旅程有两千多公里。", "corrected_sentence": "从北京到广州，这段旅程有两千多公里。", "error_description": "错误：“座”不能用于旅程，应改为“段”。“座”用于山、楼等大型固定物，不用于路程。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一段漫长地旅程，我们走得很慢。", "corrected_sentence": "这是一段漫长的旅程，我们走得很慢。", "error_description": "错误：修饰名词“旅程”的形容词要用“的”，不能用“地”。“地”用于修饰动词，应改为“漫长的旅程”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
