INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89178, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旅行的路程，也指旅行的过程。", "primary_collocate": null, "pronunciation": "lǚ chéng", "ipa": "ly˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这段旅程很长，我们走了三天。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你这段旅程愉快！", "target_word": "旅程", "complexity_tier": "T3", "furigana": "lǚ chéng", "sentence_source": "generated"}, {"text": "他把旅程安排得很清楚。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅程让我认识了很多朋友。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的旅程从北京开始。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机晚点了，我们的旅程只好推迟一天。", "target_word": "旅程", "complexity_tier": "T3", "furigana": "lǚ chéng", "sentence_source": "generated"}, {"text": "旅程中，他一直看着窗外。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一段难忘的旅程。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一段旅程，我们坐火车去。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅程结束后，大家都累了。", "target_word": "旅程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段旅程", "label": "量词"}], "register": "中性", "sense_fingerprint": "旅行的路程与过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅程", "is_correct": true, "explanation": "“这段旅程”指一段路途或过程，“走了三天”与之相合。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：午餐是一顿饭，与“我们走了三天”的旅行语境不相合，句意不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“很长”不用于形容工资，不能说工资很长。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程可以很长，但“我们走了三天”与课程的语境冲突，句意不通。"}], "explanations": {"旅程": "“这段旅程”指一段路途或过程，“走了三天”与之相合。", "午餐": "语义：午餐是一顿饭，与“我们走了三天”的旅行语境不相合，句意不通。", "工资": "搭配：“很长”不用于形容工资，不能说工资很长。", "课程": "语义：课程可以很长，但“我们走了三天”与课程的语境冲突，句意不通。"}, "sentence_index": 0, "correct_answer": "旅程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做饭的旅程很简单，半个小时就做好了。", "explanation": "这里应该用〈过程〉。旅程只指旅行中的路程或过程，做饭的步骤要用〈过程〉。"}, {"text": "这位旅程很有礼貌。", "explanation": "这里应该用〈旅客〉。旅程指路途或过程，不能指人。"}, {"text": "这次会议的旅程安排得很满。", "explanation": "这里应该用〈日程〉。旅程指旅行的路途，会议的安排要用〈日程〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅程", "is_correct": true, "explanation": "“旅程中”指旅途之中，“一直看着窗外”符合旅行途中的情境。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术中的病人或医生不会“一直看着窗外”，与医疗场景冲突，句意很不合常理。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是医疗记录，不能作为“看着窗外”的场合。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：“食谱中”指在菜谱里，与“他一直看着窗外”的旅途情境不相合，句意不通。"}], "explanations": {"旅程": "“旅程中”指旅途之中，“一直看着窗外”符合旅行途中的情境。", "手术": "语义：手术中的病人或医生不会“一直看着窗外”，与医疗场景冲突，句意很不合常理。", "病历": "语义：病历是医疗记录，不能作为“看着窗外”的场合。", "食谱": "语义：“食谱中”指在菜谱里，与“他一直看着窗外”的旅途情境不相合，句意不通。"}, "sentence_index": 6, "correct_answer": "旅程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写完了旅程，大家都累了。", "explanation": "这里应该用〈作业〉。旅程是路途或过程，不能被写完，写完要用〈作业〉。"}, {"text": "这场旅程，他踢进了两个球。", "explanation": "这里应该用〈比赛〉。旅程是旅行的路途或过程，不能在里面踢进球，踢球进球要用〈比赛〉。"}, {"text": "他没通过旅程。", "explanation": "这里应该用〈考试〉。旅程不是可以通过的测试，通过的对象要用〈考试〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座旅程很愉快，大家都很开心。", "corrected_sentence": "这段旅程很愉快，大家都很开心。", "error_description": "错误：“座”不能用于旅程，应改为“段”。“座”多用于山、楼等大型固定物，旅程的计量词是“段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段漫长地旅程让我们学到了很多。", "corrected_sentence": "这段漫长的旅程让我们学到了很多。", "error_description": "错误：修饰名词“旅程”的形容词要用“的”，不能用“地”。“地”用于修饰动词，应改为“漫长的旅程”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "里人是住在同一个地方的人。", "primary_collocate": null, "pronunciation": "lǐ rén", "ipa": "li˨˩˦ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他和我是里人，从小一起长大。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的里人都很热情。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "里人都来帮他盖房子。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地人来了，里人热情地招待他们。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇上的里人互相照应，关系很亲近。", "target_word": "里人", "complexity_tier": "T3", "furigana": "zhè gè xiǎo zhèn shàng de lǐ rén hù xiāng zhào yìng, guān xì hěn qīn jìn.", "sentence_source": "generated"}, {"text": "过年时，里人聚在一起吃饭。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我搬来以后，里人都说这里的水特别甜。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在村口遇到了一位里人。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王是我们村里最老的里人。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难，里人总会互相帮忙。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "里人:住在同一个地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a2d37c5-ce5a-420d-8d73-ab1cf9e08d40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "里人", "is_correct": true, "explanation": "里人：住在同一个地方的人，与“从小一起长大”的关系相合。"}, {"text": "外人", "is_correct": false, "explanation": "语义：“外人”指不属于自己圈子的人，与“从小一起长大”的亲近关系相矛盾。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”指互不认识的人，与“从小一起长大”明显不合。"}, {"text": "宾客", "is_correct": false, "explanation": "语域：“宾客”是正式用词，与“从小一起长大”这种口语化叙述的语域不合。"}], "explanations": {"里人": "里人：住在同一个地方的人，与“从小一起长大”的关系相合。", "外人": "语义：“外人”指不属于自己圈子的人，与“从小一起长大”的亲近关系相矛盾。", "陌生人": "语义：“陌生人”指互不认识的人，与“从小一起长大”明显不合。", "宾客": "语域：“宾客”是正式用词，与“从小一起长大”这种口语化叙述的语域不合。"}, "sentence_index": 0, "correct_answer": "里人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指人，不能指学校，应改用〈母校〉。"}, {"text": "景区的里人都来自各地。", "explanation": "这里不能用〈里人〉：“里人”指住在同一个地方的人，来自各地的游客不住在同一个地方，应改用〈游客〉。"}, {"text": "两个国家的人在联合国开会，他们都是里人。", "explanation": "这里不能用〈里人〉：两国的人分属不同的国家，与“住在同一个地方”不符，应改用〈代表〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里人", "is_correct": true, "explanation": "里人：住在同一个地方的人，说话人也是这里的人，与“这里的水”的语境相合。"}, {"text": "祖先", "is_correct": false, "explanation": "语义：“祖先”已故，不能说话评价眼前的水，与“说”不合。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”还不会表达这种评价，与“说这里的水特别甜”不合。"}, {"text": "陛下", "is_correct": false, "explanation": "语域：“陛下”是对君主的敬称，与这句日常叙述的语域不合。"}], "explanations": {"里人": "里人：住在同一个地方的人，说话人也是这里的人，与“这里的水”的语境相合。", "祖先": "语义：“祖先”已故，不能说话评价眼前的水，与“说”不合。", "婴儿": "语义：“婴儿”还不会表达这种评价，与“说这里的水特别甜”不合。", "陛下": "语域：“陛下”是对君主的敬称，与这句日常叙述的语域不合。"}, "sentence_index": 6, "correct_answer": "里人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在网上认识的外国朋友是我的里人。", "explanation": "这里不能用〈里人〉：网上认识的外国朋友与我不住在同一个地方，应改用〈网友〉。"}, {"text": "我在国外遇到的中国人都是我的里人。", "explanation": "这里不能用〈里人〉：国外的中国人与我不在同一个地方，应改用〈同胞〉。"}, {"text": "这只狗是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指人，不能指动物，应改用〈宠物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春节时，一只里人回来团聚。", "corrected_sentence": "春节时，一位里人回来团聚。", "error_description": "量词错误：“里人”指人，应用〈位〉，不能用〈只〉（〈只〉多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很里人都来帮我修房子。", "corrected_sentence": "我的里人都来帮我修房子。", "error_description": "“很”是程度副词，不能修饰名词“里人”。“我”与“里人”之间应加“的”，应说“我的里人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同乡的人;同里的人(旧时用语)。", "primary_collocate": null, "pronunciation": "lǐ rén", "ipa": "li˨˩˦ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他乡遇到里人，格外高兴。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，那位客人是他的里人。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧时里人常常互相照应。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门在外，里人最亲。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在京城认识了几位里人。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位里人在异地相见，聊了很久。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位先生是我的里人，也姓李。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "里人听说他回来了，都来看望。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在京城相遇，原来竟是里人。", "target_word": "里人", "complexity_tier": "T3", "furigana": "tā men zài jīng chéng xiāng yù, yuán lái jìng shì lǐ rén.", "sentence_source": "generated"}, {"text": "里人来信说，家乡今年丰收了。", "target_word": "里人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "旧时用语", "sense_fingerprint": "里人:同乡的人,旧时用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a2d37c5-ce5a-420d-8d73-ab1cf9e08d40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "里人", "is_correct": true, "explanation": "里人：同乡的人，在他乡遇到同乡，格外亲切。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”是有仇怨的对头，他乡相遇不会“格外高兴”，与同乡之义相反。"}, {"text": "债主", "is_correct": false, "explanation": "语义：“债主”指向别人讨债的人，与他乡相遇的“格外高兴”不合，也不是同乡。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”指偷东西的人，与“格外高兴”的情感相矛盾，也不是同乡。"}], "explanations": {"里人": "里人：同乡的人，在他乡遇到同乡，格外亲切。", "仇人": "语义：“仇人”是有仇怨的对头，他乡相遇不会“格外高兴”，与同乡之义相反。", "债主": "语义：“债主”指向别人讨债的人，与他乡相遇的“格外高兴”不合，也不是同乡。", "小偷": "语义：“小偷”指偷东西的人，与“格外高兴”的情感相矛盾，也不是同乡。"}, "sentence_index": 0, "correct_answer": "里人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指同乡的人，指的是人，北京是地方，应改用〈故乡〉。"}, {"text": "他在京城认识了几位里人，他们来自五大洲。", "explanation": "这里不能用〈里人〉：“里人”指同乡，来自五大洲的人不可能是同乡，应改用〈朋友〉。"}, {"text": "这家公司的里人都是外国人。", "explanation": "这里不能用〈里人〉：“里人”指同乡，外国员工与我们不是同乡，应改用〈同事〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "里人", "is_correct": true, "explanation": "里人：同乡的人，说明这位先生与我是同乡，与“也姓李”的叙述相合。"}, {"text": "陌生人", "is_correct": false, "explanation": "搭配：“我的陌生人”前后矛盾，不能用“我的”修饰“陌生人”。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”指过路的人，与“是我的”这种关系不合，也与“也姓李”的说法不符。"}, {"text": "外国人", "is_correct": false, "explanation": "语义：“外国人”指他国国籍的人，与同姓“李”的语境不合。"}], "explanations": {"里人": "里人：同乡的人，说明这位先生与我是同乡，与“也姓李”的叙述相合。", "陌生人": "搭配：“我的陌生人”前后矛盾，不能用“我的”修饰“陌生人”。", "路人": "语义：“路人”指过路的人，与“是我的”这种关系不合，也与“也姓李”的说法不符。", "外国人": "语义：“外国人”指他国国籍的人，与同姓“李”的语境不合。"}, "sentence_index": 6, "correct_answer": "里人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位刚来中国的外国游客是我的里人。", "explanation": "这里不能用〈里人〉：外国游客不可能与我同乡，应改用〈朋友〉。"}, {"text": "这只猫是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指人，不能指动物，应改用〈宠物〉。"}, {"text": "这辆车是我的里人。", "explanation": "这里不能用〈里人〉：“里人”指人，不能指车辆，应改用〈爱车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在北京遇到一只里人，倍感亲切。", "corrected_sentence": "他在北京遇到一位里人，倍感亲切。", "error_description": "量词错误：“里人”指人，应用〈位〉，不能用〈只〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "里人了托人带口信，问我近况。", "corrected_sentence": "里人托人带口信，问我近况。", "error_description": "“了”不能放在“里人”后面。这里不是完成的动作，应直接说“里人托人带口信”，不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
