INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89181, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "警察局是警察工作的地方。遇到坏人可以去那里找他们。", "primary_collocate": null, "pronunciation": "jǐng chá jú", "ipa": "tɕiŋ˨˩˦ ʈʂʰa˧˥ tɕy˧˥", "syllable_count": 3, "sentences": [{"text": "遇到坏人，你可以去警察局找警察。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局离我家很近，走路五分钟就到。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明迷路了，爸爸带他去警察局。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在路上捡到手机，把它交给了警察局。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很害怕，跑进警察局请警察帮忙。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局门口有两个警察站着。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人被带到警察局了。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边有一个警察局。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天去警察局报案，钱包不见了。", "target_word": "警察局", "complexity_tier": "T3", "furigana": "wǒ zuó tiān qù jǐng chá jú bào àn, qián bāo bú jiàn le。", "sentence_source": "generated"}, {"text": "晚上警察局里的灯还亮着。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个警察局", "label": "量词"}, {"form": "一座警察局", "label": "量词"}], "register": "中性", "sense_fingerprint": "警察工作的地方，遇到坏人可以去求助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警察局", "is_correct": true, "explanation": "正确。遇到坏人可以去警察局找警察，句意通顺。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不是求助找警察的地方，去那里找不到警察。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园与遇到坏人求助无关，句子不成立。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：超市不是报警求助的场所，“去超市找警察”不搭配。"}], "explanations": {"警察局": "正确。遇到坏人可以去警察局找警察，句意通顺。", "图书馆": "语义：图书馆不是求助找警察的地方，去那里找不到警察。", "动物园": "语义：动物园与遇到坏人求助无关，句子不成立。", "超市": "搭配：超市不是报警求助的场所，“去超市找警察”不搭配。"}, "sentence_index": 0, "correct_answer": "警察局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爸爸是警察局，每天上班很辛苦。", "explanation": "这里应该用〈警员〉。警察局是机构，不能用来指人，说人要用警员。"}, {"text": "警察局响了，大家赶紧跑出去。", "explanation": "这里应该用〈警报〉。警察局不会响，只有警报才会鸣响。"}, {"text": "他戴着警察局，走路很神气。", "explanation": "这里应该用〈警帽〉。警察局是建筑，不能戴在头上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警察局", "is_correct": true, "explanation": "正确。坏人被带到警察局，符合执法的语境。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场不是执法场所，坏人不会被带到那里。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店与拘捕无关，句意不成立。"}, {"text": "咖啡馆", "is_correct": false, "explanation": "搭配：“被带到”后接的场所应是执法或拘留机关，咖啡馆不搭配。"}], "explanations": {"警察局": "正确。坏人被带到警察局，符合执法的语境。", "游乐场": "语义：游乐场不是执法场所，坏人不会被带到那里。", "理发店": "语义：理发店与拘捕无关，句意不成立。", "咖啡馆": "搭配：“被带到”后接的场所应是执法或拘留机关，咖啡馆不搭配。"}, "sentence_index": 6, "correct_answer": "警察局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察局很好喝，我们每人喝了一杯。", "explanation": "这里应该用〈果汁〉。警察局是机构，不是饮料，不能喝，也不能说好喝。"}, {"text": "我家的警察局很可爱，每天陪我散步。", "explanation": "这里应该用〈小狗〉。警察局是机构，不是动物，不能陪人散步。"}, {"text": "警察拿着警察局巡逻。", "explanation": "这里应该用〈警棍〉。警察局是建筑，不能拿在手里巡逻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遇到坏人，你可以去一只警察局报警。", "corrected_sentence": "遇到坏人，你可以去警察局报警。", "error_description": "量词错误：错误形式为“去一只警察局”，正确形式为“去警察局”。“只”用于动物或小件物品，不能修饰建筑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个坏人被送进了在警察局。", "corrected_sentence": "那个坏人被送进了警察局。", "error_description": "介词误用：“进”后直接接处所，错误形式为“进了在警察局”，正确形式为“进了警察局”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
