INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "警察办公和处理案件的机构。", "primary_collocate": null, "pronunciation": "jǐng chá jú", "ipa": "tɕiŋ˨˩˦ ʈʂʰa˧˥ tɕy˧˥", "syllable_count": 3, "sentences": [{"text": "他去警察局办了一份证明。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局正在处理这个案件。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有很多个警察局。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的哥哥在警察局工作了十年。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局的负责人开了一个会。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民可以到警察局报案。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的钱包丢了，所以去了警察局。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局发布了新的通知。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局和法院都在这条街上。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在警察局门口等着消息。", "target_word": "警察局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个警察局", "label": "量词"}, {"form": "一座警察局", "label": "量词"}], "register": "中性", "sense_fingerprint": "警察办公、处理案件的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警察局", "is_correct": true, "explanation": "正确。警察局是办理证明等事务的机构，句意通顺。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园不办理证明，“去动物园办了一份证明”不成立。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能在那里办证明。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“办证明”需要办理机关，食堂不是办证的地方，不能搭配。"}], "explanations": {"警察局": "正确。警察局是办理证明等事务的机构，句意通顺。", "动物园": "语义：动物园不办理证明，“去动物园办了一份证明”不成立。", "厨房": "语义：厨房是做饭的地方，不能在那里办证明。", "食堂": "搭配：“办证明”需要办理机关，食堂不是办证的地方，不能搭配。"}, "sentence_index": 0, "correct_answer": "警察局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的叔叔是警察局，每天很忙。", "explanation": "这里应该用〈警察〉。警察局是机构，不能用来指人。"}, {"text": "他开着警察局去城里。", "explanation": "这里应该用〈警车〉。警察局是建筑，不能被开着去城里。"}, {"text": "我的钱包被警察局偷走了。", "explanation": "这里应该用〈小偷〉。警察局是机构，不会偷东西，不能作“偷”的施事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警察局", "is_correct": true, "explanation": "正确。丢了钱包所以去警察局，句意通顺。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池与丢失钱包后的去处无关，句子不成立。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是处理失物或报案的地方，与“钱包丢了”的语境不符。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：丢了钱包的去处应是可以报案或找回物品的部门，菜市场不搭配。"}], "explanations": {"警察局": "正确。丢了钱包所以去警察局，句意通顺。", "游泳池": "语义：游泳池与丢失钱包后的去处无关，句子不成立。", "花园": "语义：花园不是处理失物或报案的地方，与“钱包丢了”的语境不符。", "菜市场": "搭配：丢了钱包的去处应是可以报案或找回物品的部门，菜市场不搭配。"}, "sentence_index": 6, "correct_answer": "警察局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察局很好吃，我们每人吃了一份。", "explanation": "这里应该用〈饼干〉。警察局是机构，不是食物，不能吃，也不能说好吃。"}, {"text": "他穿着警察局去上班。", "explanation": "这里应该用〈警服〉。警察局是建筑，不能穿在身上。"}, {"text": "我的警察局很可爱，每天陪我玩。", "explanation": "这里应该用〈小狗〉。警察局是机构，不是动物，不会可爱地陪人玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天去一只警察局补办了身份证。", "corrected_sentence": "我昨天去警察局补办了身份证。", "error_description": "量词错误：错误形式为“去一只警察局”，正确形式为“去警察局”。“只”用于动物或小件物品，不能修饰建筑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的钱包丢了，所以我去在警察局报了案。", "corrected_sentence": "我的钱包丢了，所以我去警察局报了案。", "error_description": "介词误用：“去”后直接接处所，错误形式为“去在警察局”，正确形式为“去警察局”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
