INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89183, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "星星是晚上挂在天上，一闪一闪的小亮点。", "primary_collocate": null, "pronunciation": "xīng xing", "ipa": "ɕiŋ˥ ɕiŋ", "syllable_count": 2, "sentences": [{"text": "星星在天上一闪一闪的。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，星星是天上的小灯。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明躺在床上看星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的星星又多又亮。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指着天空说：“看，星星！”", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对着星星许愿。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外有几颗星星，亮亮的。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画了一幅夜空，上面有很多星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在草地上，一起看星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮旁边有一颗很小的星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}], "register": "中性", "sense_fingerprint": "晚上天上一闪一闪的小亮点，日常生活、儿童视角义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89183, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "星星", "is_correct": true, "explanation": "正确：星星一闪一闪的，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是持续发出的光，白天也很亮，不会一闪一闪的。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮的光很平稳，不会一闪一闪的。"}, {"text": "云", "is_correct": false, "explanation": "体貌：云没有发光的小亮点，不会一闪一闪的。"}], "explanations": {"星星": "正确：星星一闪一闪的，符合句意。", "太阳": "语义：太阳是持续发出的光，白天也很亮，不会一闪一闪的。", "月亮": "语义：月亮的光很平稳，不会一闪一闪的。", "云": "体貌：云没有发光的小亮点，不会一闪一闪的。"}, "sentence_index": 0, "correct_answer": "星星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的裙子上缀满了小星星。", "explanation": "这里用的是“星星”的形状义，指星形的装饰物，不指夜空中的小亮点。"}, {"text": "中午的星星又大又亮。", "explanation": "这里应该用〈太阳〉。白天看不见星星，“又大又亮”指的是太阳。"}, {"text": "他是我们班的小星星，每次考试都拿第一。", "explanation": "这里用的是比喻义，指成绩出色的人，不指天体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星星", "is_correct": true, "explanation": "正确：几颗星星、亮亮的，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "量词：「窗户」用「扇」，不用「颗」，「几颗窗户」不通。"}, {"text": "树叶", "is_correct": false, "explanation": "量词：「树叶」用「片」，不用「颗」，「几颗树叶」不通。"}, {"text": "椅子", "is_correct": false, "explanation": "量词：「椅子」用「把」，不用「颗」，「几颗椅子」不通。"}], "explanations": {"星星": "正确：几颗星星、亮亮的，符合句意。", "窗户": "量词：「窗户」用「扇」，不用「颗」，「几颗窗户」不通。", "树叶": "量词：「树叶」用「片」，不用「颗」，「几颗树叶」不通。", "椅子": "量词：「椅子」用「把」，不用「颗」，「几颗椅子」不通。"}, "sentence_index": 6, "correct_answer": "星星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮旁边有一座很小的星星。", "explanation": "这里应该用〈颗〉。“座”用于山、房屋等大型固定的东西，星星用“颗”。"}, {"text": "月亮旁边有一条很小的星星。", "explanation": "这里应该用〈颗〉。“条”用于河流、裤子等长的东西，星星不用“条”。"}, {"text": "月亮旁边有一把很小的星星。", "explanation": "这里应该用〈颗〉。“把”用于有柄的东西，星星不用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用手指着天上那颗亮亮星星。", "corrected_sentence": "我用手指着天上那颗亮亮的星星。", "error_description": "助词错误：“亮亮”修饰“星星”时要用“的”，应说“亮亮的星星”，不能说“亮亮星星”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上十点，星星一颗颗冒来出了。", "corrected_sentence": "晚上十点，星星一颗颗冒出来了。", "error_description": "补语语序错误：「冒出来」的趋向补语语序是「出来」，不能说「冒来出」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
