INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "夜空中肉眼可见的发光或反光的天体，如恒星、行星等。", "primary_collocate": null, "pronunciation": "xīng xing", "ipa": "ɕiŋ˥ ɕiŋ", "syllable_count": 2, "sentences": [{"text": "夜里没有云，我们能看见很多星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的灯太亮，看不到星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用望远镜看天上的星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些星星离地球非常远。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星星有的是恒星，有的是行星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，有的星星自己会发光。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们在山上数星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮以后，星星就慢慢看不见了。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸教我怎么认天上的星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现了一颗新的星星。", "target_word": "星星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}], "register": "中性", "sense_fingerprint": "夜空中可见的天体（恒星、行星），科学观察义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "星星", "is_correct": true, "explanation": "正确：夜里能看见很多星星，符合语境，与“没有云”不矛盾。"}, {"text": "云", "is_correct": false, "explanation": "语义：句中已说“夜里没有云”，不能再说看见很多云，与前句矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：月亮只有一个，不能与“很多”搭配。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：夜里看不到太阳，“太阳”与“夜里”矛盾。"}], "explanations": {"星星": "正确：夜里能看见很多星星，符合语境，与“没有云”不矛盾。", "云": "语义：句中已说“夜里没有云”，不能再说看见很多云，与前句矛盾。", "月亮": "搭配：月亮只有一个，不能与“很多”搭配。", "太阳": "语义：夜里看不到太阳，“太阳”与“夜里”矛盾。"}, "sentence_index": 0, "correct_answer": "星星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是我们班的小星星，每次考试都拿第一。", "explanation": "这里用的是比喻义，指成绩出色的人，不指天体。"}, {"text": "她的裙子上缀着很多小星星。", "explanation": "这里用的是“星星”的形状义，指星形的装饰物，不指夜空中的天体。"}, {"text": "夜空中有一座很亮的星星。", "explanation": "这里应该用〈颗〉。“座”用于山、房屋等大型固定的东西，星星用“颗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星星", "is_correct": true, "explanation": "正确：山上数星星与“晚上”的场景相符。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：大海是一个整体，不能用“数”来计数。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：晚上不会出现彩虹，与“晚上”矛盾。"}, {"text": "日出", "is_correct": false, "explanation": "语义：日出在清晨，与“晚上”矛盾。"}], "explanations": {"星星": "正确：山上数星星与“晚上”的场景相符。", "大海": "搭配：大海是一个整体，不能用“数”来计数。", "彩虹": "语义：晚上不会出现彩虹，与“晚上”矛盾。", "日出": "语义：日出在清晨，与“晚上”矛盾。"}, "sentence_index": 6, "correct_answer": "星星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家发现了一张新的星星。", "explanation": "这里应该用〈颗〉。“星星”用“颗”，“张”用于纸、桌子等平面的东西。"}, {"text": "科学家发现了一只新的星星。", "explanation": "这里应该用〈颗〉。“只”多用于动物，星星不用“只”。"}, {"text": "她是我心里的一颗星星。", "explanation": "这里用的是比喻义，指心中珍爱的人，不指天体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上有一颗很亮星星。", "corrected_sentence": "天上有一颗很亮的星星。", "error_description": "助词错误：“很亮”修饰“星星”时要用“的”，应说“很亮的星星”，不能说“很亮星星”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天黑以后，星星一颗颗亮来起了。", "corrected_sentence": "天黑以后，星星一颗颗亮起来了。", "error_description": "补语语序错误：“亮起来”是趋向补语，应说“亮起来”，不能说“亮来起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
