INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89187, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开别的国家，回到自己的国家。", "primary_collocate": null, "pronunciation": "huí guó", "ipa": "xweɪ˧˥ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "他在国外学了四年，明年夏天就回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想家了，打算下个月回国看看。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去美国工作三年后回国了。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师昨天从日本回国，现在在家休息。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家人准备春节前回国过年。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买好了回国的机票，下周三就走。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出国十年，今年第一次回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "留学生放假后都回国看家人了。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候回国？我想请你吃饭。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说爷爷病了，他马上订票回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回国了", "label": "体标"}, {"form": "回國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "离开外国，回到自己的祖国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfff504e-4568-4828-bef5-09ba6f7af341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89187, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回国", "is_correct": true, "explanation": "回国：离开外国，回到自己的国家。这是本词。"}, {"text": "回锅", "is_correct": false, "explanation": "回锅（huíguō）与 huíguó 第二个音节声调不同（guō 第一声），意思是把食物再加热。"}, {"text": "悔过", "is_correct": false, "explanation": "悔过（huǐguò）与 huíguó 两个音节声调都不同，意思是认识错误并改正。"}, {"text": "回过", "is_correct": false, "explanation": "回过（huíguò）与 huíguó 第二个音节声调不同（guò 第四声），意思是转过或恢复，如“回过神”。"}, {"text": "回顾", "is_correct": false, "explanation": "回顾（huígù）与 huíguó 韵母不同（gù 与 guó），意思是回头看、追述过去。"}], "explanations": {"回国": "回国：离开外国，回到自己的国家。这是本词。", "回锅": "回锅（huíguō）与 huíguó 第二个音节声调不同（guō 第一声），意思是把食物再加热。", "悔过": "悔过（huǐguò）与 huíguó 两个音节声调都不同，意思是认识错误并改正。", "回过": "回过（huíguò）与 huíguó 第二个音节声调不同（guò 第四声），意思是转过或恢复，如“回过神”。", "回顾": "回顾（huígù）与 huíguó 韵母不同（gù 与 guó），意思是回头看、追述过去。"}, "sentence_index": null, "correct_answer": "回国"}, "level_3": {"options": [{"text": "回国", "is_correct": true, "explanation": "正确：前句说他在国外学习，明年夏天回到本国，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“学习四年、明年夏天”的安排无关，句意不通。"}, {"text": "出走", "is_correct": false, "explanation": "语义：“出走”指离家出逃，与按计划学习后回来的语境不符。"}, {"text": "返航", "is_correct": false, "explanation": "搭配：“返航”多用于船只、飞机，不能用来说人返回。"}], "explanations": {"回国": "正确：前句说他在国外学习，明年夏天回到本国，符合句意。", "睡觉": "语义：睡觉与“学习四年、明年夏天”的安排无关，句意不通。", "出走": "语义：“出走”指离家出逃，与按计划学习后回来的语境不符。", "返航": "搭配：“返航”多用于船只、飞机，不能用来说人返回。"}, "sentence_index": 0, "correct_answer": "回国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天下班回国做饭，很累。", "explanation": "这里应该用〈回家〉。回国指从外国回到本国，每天下班回到住处不能用“回国”。"}, {"text": "他去超市买菜，半小时后回国。", "explanation": "这里应该用〈回来〉。回国指从外国回到本国，去超市买菜后回来不能用“回国”。"}, {"text": "我是北京人，这个暑假想回国去日本玩。", "explanation": "这里应该用〈出国〉。回国指从外国回到本国，北京人去日本是离开本国，应说“出国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回国", "is_correct": true, "explanation": "正确：他出国十年，今年第一次返回本国，符合句意。"}, {"text": "出境", "is_correct": false, "explanation": "语义：“出境”指离开国境，他已出国十年，不能说今年第一次出境。"}, {"text": "留学", "is_correct": false, "explanation": "语义：“留学”指去国外求学，句中没有求学的语境，且他已出国十年。"}, {"text": "离国", "is_correct": false, "explanation": "语域：“离国”偏书面，与口语叙述不协调；且与“出国十年”语义重复。"}], "explanations": {"回国": "正确：他出国十年，今年第一次返回本国，符合句意。", "出境": "语义：“出境”指离开国境，他已出国十年，不能说今年第一次出境。", "留学": "语义：“留学”指去国外求学，句中没有求学的语境，且他已出国十年。", "离国": "语域：“离国”偏书面，与口语叙述不协调；且与“出国十年”语义重复。"}, "sentence_index": 6, "correct_answer": "回国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是中国人，住在上海，周末回国看朋友。", "explanation": "这里应该用〈回老家〉。住在上海的中国人回老家，是国内移动，不能用“回国”。"}, {"text": "周末我回国自习。", "explanation": "这里应该用〈回学校〉。回国只指从外国回到本国，回学校自习不能用“回国”。"}, {"text": "累了，他回国睡觉。", "explanation": "这里应该用〈回房间〉。回国指从外国返回本国，回到住处的房间不能用“回国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去年把回国了。", "corrected_sentence": "我去年回国了。", "error_description": "错误：“把回国了”。“回国”不能用于“把”字处置式，句中多出“把”，应删去，改为“我去年回国了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
