INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从外国返回本国。", "primary_collocate": null, "pronunciation": "huí guó", "ipa": "xweɪ˧˥ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "他结束了国外的工作，决定回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在英国读书，今年六月回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回国以后，他开了一家小公司。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回国前，买了很多礼物给家人。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回国后很不习惯这里的天气。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大使完成任务后，坐飞机回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在德国工作，很少回国。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚回国，还没找到合适的工作。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情结束后，很多人终于能回国了。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位歌手在法国住了很久，最近回国了。", "target_word": "回国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回国了", "label": "体标"}, {"form": "回过国", "label": "体标"}], "register": "中性", "sense_fingerprint": "从外国返回本国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfff504e-4568-4828-bef5-09ba6f7af341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回国", "is_correct": true, "explanation": "回国：从外国返回本国。这是本词。"}, {"text": "回锅", "is_correct": false, "explanation": "回锅（huíguō）与 huíguó 第二个音节声调不同（guō 第一声），意思是把食物再加热。"}, {"text": "回过", "is_correct": false, "explanation": "回过（huíguò）与 huíguó 第二个音节声调不同（guò 第四声），意思是转过或恢复，如“回过神”。"}, {"text": "回顾", "is_correct": false, "explanation": "回顾（huígù）与 huíguó 韵母不同（gù 与 guó），意思是回头看、追述过去。"}], "explanations": {"回国": "回国：从外国返回本国。这是本词。", "回锅": "回锅（huíguō）与 huíguó 第二个音节声调不同（guō 第一声），意思是把食物再加热。", "回过": "回过（huíguò）与 huíguó 第二个音节声调不同（guò 第四声），意思是转过或恢复，如“回过神”。", "回顾": "回顾（huígù）与 huíguó 韵母不同（gù 与 guó），意思是回头看、追述过去。"}, "sentence_index": null, "correct_answer": "回国"}, "level_3": {"options": [{"text": "回国", "is_correct": true, "explanation": "正确：前句说他结束了国外的工作，决定返回本国，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“结束国外工作、做决定”的语境无关，句意不通。"}, {"text": "打针", "is_correct": false, "explanation": "语义：打针是就医行为，与句中的决定不符，句意不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与“结束工作后决定……”的语境无关，句意不通。"}], "explanations": {"回国": "正确：前句说他结束了国外的工作，决定返回本国，符合句意。", "睡觉": "语义：睡觉与“结束国外工作、做决定”的语境无关，句意不通。", "打针": "语义：打针是就医行为，与句中的决定不符，句意不通。", "吃饭": "语义：吃饭与“结束工作后决定……”的语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "回国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天下班回国做饭，很累。", "explanation": "这里应该用〈回家〉。回国指从外国回到本国，每天下班回到住处不能用“回国”。"}, {"text": "我是中国人，这个暑假想回国去泰国玩。", "explanation": "这里应该用〈出国〉。回国指从外国回到本国，中国人去泰国玩是离开本国，应说“出国”。"}, {"text": "他刚从办公室出来，又回国去拿文件。", "explanation": "这里应该用〈回办公室〉。回国只指从外国回到本国，在办公楼之间往返不能用“回国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回国", "is_correct": true, "explanation": "正确：前句说哥哥在德国工作，所以很少回到本国，符合句意。"}, {"text": "上学", "is_correct": false, "explanation": "语义：哥哥已在德国工作，不是去上学，“上学”与语境不符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”意为结束工作，与“在德国工作”相矛盾，不能说很少退休。"}, {"text": "入学", "is_correct": false, "explanation": "搭配：“入学”针对学生，不能用于正在工作的人。"}], "explanations": {"回国": "正确：前句说哥哥在德国工作，所以很少回到本国，符合句意。", "上学": "语义：哥哥已在德国工作，不是去上学，“上学”与语境不符。", "退休": "语义：“退休”意为结束工作，与“在德国工作”相矛盾，不能说很少退休。", "入学": "搭配：“入学”针对学生，不能用于正在工作的人。"}, "sentence_index": 6, "correct_answer": "回国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是中国人，住在广州，周末回国看朋友。", "explanation": "这里应该用〈回老家〉。住在广州的中国人回老家，是国内移动，不能用“回国”。"}, {"text": "周末我回国自习。", "explanation": "这里应该用〈回学校〉。回国只指从外国回到本国，回学校自习不能用“回国”。"}, {"text": "累了，他回国睡觉。", "explanation": "这里应该用〈回房间〉。回国指从外国返回本国，回到住处的房间不能用“回国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天被回国了。", "corrected_sentence": "他昨天回国了。", "error_description": "错误：“被回国了”。“回国”不能用于被动句，句中多出“被”，应删去，改为“他昨天回国了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上个月把回国了。", "corrected_sentence": "他上个月回国了。", "error_description": "错误：“把回国”。“回国”是不及物动词，不能用于“把”字处置式，应删去“把”，改为“他上个月回国了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
