INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89189, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "景象是你看到的一幅一幅的样子。", "primary_collocate": null, "pronunciation": "jǐng xiàng", "ipa": "tɕiŋ˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "窗外的景象真美。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的景象让我很感动。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅景象我永远忘不了。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪后的景象像一幅画。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着眼前的景象，说不出话。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边日落的景象非常好看。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，公园里是一片热闹的景象。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜晚城市的景象很漂亮。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拍下了那个美丽的景象。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的景象和城里很不一样。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一幅景象", "label": "量词"}], "register": "中性", "sense_fingerprint": "眼前看到的画面般的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89189, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "景象", "is_correct": true, "explanation": "正确。景象指眼前看到的画面或样子。"}, {"text": "镜像", "is_correct": false, "explanation": "jìng（第四声）与 jǐng（第三声）只有声调不同，镜像的意思是镜子里的影像。"}, {"text": "竞相", "is_correct": false, "explanation": "jìng xiāng 与 jǐng xiàng 两个音节的声调都不同，竞相的意思是争先恐后地。"}, {"text": "井下", "is_correct": false, "explanation": "xià 与 xiàng 只差韵母 ng，声调相同，井下的意思是井的下面（矿井中）。"}], "explanations": {"景象": "正确。景象指眼前看到的画面或样子。", "镜像": "jìng（第四声）与 jǐng（第三声）只有声调不同，镜像的意思是镜子里的影像。", "竞相": "jìng xiāng 与 jǐng xiàng 两个音节的声调都不同，竞相的意思是争先恐后地。", "井下": "xià 与 xiàng 只差韵母 ng，声调相同，井下的意思是井的下面（矿井中）。"}, "sentence_index": null, "correct_answer": "景象"}, "level_3": {"options": [{"text": "景象", "is_correct": true, "explanation": "正确。“窗外的景象”指看到的画面，可以用“真美”来形容。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”没有美丑，与“真美”矛盾。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：形容“味道”一般用“香”“好”，不说“真美”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“窗外的”指看到的景物，名字不是可以看到的东西。"}], "explanations": {"景象": "正确。“窗外的景象”指看到的画面，可以用“真美”来形容。", "价格": "语义：“价格”没有美丑，与“真美”矛盾。", "味道": "搭配：形容“味道”一般用“香”“好”，不说“真美”。", "名字": "语义：“窗外的”指看到的景物，名字不是可以看到的东西。"}, "sentence_index": 0, "correct_answer": "景象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的景象很高，大家都叫他小巨人。", "explanation": "这里应该用〈身高〉。景象指看到的画面，人的高矮要说身高。"}, {"text": "我对他的景象很好。", "explanation": "这里应该用〈印象〉。景象指看到的画面，对人的感受要用印象。"}, {"text": "这个人是我理想的景象。", "explanation": "这里应该用〈对象〉。景象指看到的画面，不能指想交往的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "景象", "is_correct": true, "explanation": "正确。“热闹”形容的是公园里的场面，用“景象”最合适。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“一片”后面接有面积的事物，不说“一片人数”。"}, {"text": "方案", "is_correct": false, "explanation": "语义：“热闹”形容场面或气氛，“方案”不能热闹。"}, {"text": "天气", "is_correct": false, "explanation": "语义：公园里的“热闹”指场面，天气不能用“热闹”来形容。"}], "explanations": {"景象": "正确。“热闹”形容的是公园里的场面，用“景象”最合适。", "人数": "搭配：“一片”后面接有面积的事物，不说“一片人数”。", "方案": "语义：“热闹”形容场面或气氛，“方案”不能热闹。", "天气": "语义：公园里的“热闹”指场面，天气不能用“热闹”来形容。"}, "sentence_index": 6, "correct_answer": "景象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都在景象里学习。", "explanation": "这里应该用〈教室〉。景象是看到的画面，不是场所，不能说“在景象里”。"}, {"text": "他每天都喜欢吃景象。", "explanation": "这里应该用〈食物〉。景象是看到的画面，不能吃，能吃的要说食物。"}, {"text": "我把景象搬进了卧室。", "explanation": "这里应该用〈东西〉。景象是看到的画面，不是有形的物体，不能搬动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条海边的景象让我想起了家乡。", "corrected_sentence": "那幅海边的景象让我想起了家乡。", "error_description": "“景象”是看到的画面，量词应用“幅”，不能用“条”（“条”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，我一直把忘不了那片景象。", "corrected_sentence": "这些年，我一直忘不了那片景象。", "error_description": "错误：“忘不了”前面多加了“把”，写成“把忘不了”。“把”字句要先有处置对象再接动词，这里“忘不了”直接带宾语，不用“把”。应去掉“把”，写成“我一直忘不了那片景象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
