INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "所看到的情景或状况。", "primary_collocate": null, "pronunciation": "jǐng xiàng", "ipa": "tɕiŋ˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "到处是一片繁忙的景象。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后的景象让人难过。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，街上是一片混乱的景象。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站里人很多，一派热闹景象。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子里出现了新的景象。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛现场的景象很紧张。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争留下了可怕的景象。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的广场上，一片欢乐的景象。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水过后的景象让大家很难过。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的景象这几年变化很大。", "target_word": "景象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一幅景象", "label": "量词"}], "register": "中性", "sense_fingerprint": "所见的情景或状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89190, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "景象", "is_correct": true, "explanation": "正确。景象指看到的情景或状况。"}, {"text": "镜像", "is_correct": false, "explanation": "jìng（第四声）与 jǐng（第三声）只有声调不同，镜像的意思是镜子里的影像。"}, {"text": "竞相", "is_correct": false, "explanation": "jìng xiāng 与 jǐng xiàng 两个音节的声调都不同，竞相的意思是争先恐后地。"}, {"text": "井下", "is_correct": false, "explanation": "xià 与 xiàng 只差韵母 ng，声调相同，井下的意思是井的下面（矿井中）。"}], "explanations": {"景象": "正确。景象指看到的情景或状况。", "镜像": "jìng（第四声）与 jǐng（第三声）只有声调不同，镜像的意思是镜子里的影像。", "竞相": "jìng xiāng 与 jǐng xiàng 两个音节的声调都不同，竞相的意思是争先恐后地。", "井下": "xià 与 xiàng 只差韵母 ng，声调相同，井下的意思是井的下面（矿井中）。"}, "sentence_index": null, "correct_answer": "景象"}, "level_3": {"options": [{"text": "景象", "is_correct": true, "explanation": "正确。“到处是一片繁忙的”描写的是眼前的场面，用“景象”最合适。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“繁忙”形容场面或人事，“价格”不能繁忙。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“繁忙”形容人来人往的场面，颜色不能繁忙。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“繁忙”一般不用来形容“味道”。"}], "explanations": {"景象": "正确。“到处是一片繁忙的”描写的是眼前的场面，用“景象”最合适。", "价格": "语义：“繁忙”形容场面或人事，“价格”不能繁忙。", "颜色": "语义：“繁忙”形容人来人往的场面，颜色不能繁忙。", "味道": "搭配：“繁忙”一般不用来形容“味道”。"}, "sentence_index": 0, "correct_answer": "景象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在同学心中的景象很好。", "explanation": "这里应该用〈形象〉。景象指眼前看到的情景，人在别人心中的样子要用形象。"}, {"text": "我对这位老师的景象很好。", "explanation": "这里应该用〈印象〉。景象指看到的情景，对人的感受要用印象。"}, {"text": "他是我理想的景象。", "explanation": "这里应该用〈对象〉。景象指看到的情景，不能指想交往的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "景象", "is_correct": true, "explanation": "正确。“战争留下了可怕的”指战争留下的可见情形，用“景象”最合适。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“可怕的”一般不用来修饰“歌曲”。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：战争不会留下菜谱，菜谱与“可怕”不相容。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是战争留下的可见情形，与“可怕”不相配。"}], "explanations": {"景象": "正确。“战争留下了可怕的”指战争留下的可见情形，用“景象”最合适。", "歌曲": "搭配：“可怕的”一般不用来修饰“歌曲”。", "菜谱": "语义：战争不会留下菜谱，菜谱与“可怕”不相容。", "课本": "语义：课本不是战争留下的可见情形，与“可怕”不相配。"}, "sentence_index": 6, "correct_answer": "景象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都在景象里复习。", "explanation": "这里应该用〈图书馆〉。景象是看到的情景，不是场所，不能说“在景象里”。"}, {"text": "妈妈做饭时，把景象放进了锅里。", "explanation": "这里应该用〈食材〉。景象是看到的情景，不能下锅，下锅的要说食材。"}, {"text": "他把景象借给了同学。", "explanation": "这里应该用〈东西〉。景象是看到的情景，不是可以借出去的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条山间的景象让我难忘。", "corrected_sentence": "那幅山间的景象让我难忘。", "error_description": "“景象”是看到的画面，量词应用“幅”，不能用“条”（“条”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我至今还记得那天得景象。", "corrected_sentence": "我至今还记得那天的景象。", "error_description": "错误：修饰语“那天”和名词“景象”之间应用结构助词“的”，写成“那天的景象”。这里用了“得”，“得”不能连接名词修饰语，应改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
