INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89191, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "卖钱是把东西卖给别人，换来钱。", "primary_collocate": null, "pronunciation": "mài qián", "ipa": "mai˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他把旧手机拿去卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书可以拿去卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧衣服别扔，拿去卖钱吧。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了交学费，他拿家里的粮食去卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把院子里的菜拿到市场卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把玩具拿去卖钱，想买新书包。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们收集旧报纸，拿去卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月没钱了，我只好把旧电脑拿去卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把画拿到网上卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了小东西，再拿去卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "卖了钱", "label": "体标"}, {"form": "賣錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把东西卖给别人换钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89191, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卖钱", "is_correct": true, "explanation": "卖钱 mài qián：把东西卖给别人，换来钱。"}, {"text": "带钱", "is_correct": false, "explanation": "声母不同（d 与 m）。dài qián 意思是随身带着钱，与 mài qián 只差一个声母。"}, {"text": "赖钱", "is_correct": false, "explanation": "声母不同（l 与 m）。lài qián 意思是赖账、不肯还钱。"}, {"text": "埋钱", "is_correct": false, "explanation": "声调不同：mái qián（阳平）与 mài qián（去声）。埋钱是把钱埋起来。"}], "explanations": {"卖钱": "卖钱 mài qián：把东西卖给别人，换来钱。", "带钱": "声母不同（d 与 m）。dài qián 意思是随身带着钱，与 mài qián 只差一个声母。", "赖钱": "声母不同（l 与 m）。lài qián 意思是赖账、不肯还钱。", "埋钱": "声调不同：mái qián（阳平）与 mài qián（去声）。埋钱是把钱埋起来。"}, "sentence_index": null, "correct_answer": "卖钱"}, "level_3": {"options": [{"text": "卖钱", "is_correct": true, "explanation": "卖钱：把旧手机卖掉换钱，符合「拿去」的语境。"}, {"text": "养", "is_correct": false, "explanation": "搭配：「养」的对象是动物或植物，不能用于手机。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：「回忆」针对经历或往事，不能用于被拿走的实物。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，不能带「把」字宾语。"}], "explanations": {"卖钱": "卖钱：把旧手机卖掉换钱，符合「拿去」的语境。", "养": "搭配：「养」的对象是动物或植物，不能用于手机。", "回忆": "语义：「回忆」针对经历或往事，不能用于被拿走的实物。", "散步": "配价：「散步」是不及物动词，不能带「把」字宾语。"}, "sentence_index": 0, "correct_answer": "卖钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在超市打工卖钱。", "explanation": "这里应该用〈赚钱〉。卖钱是把东西卖给别人换钱，打工是出卖劳动，要说赚钱。"}, {"text": "他去银行卖钱。", "explanation": "这里应该用〈取钱〉。卖钱是把物品卖给别人，从银行拿出存款要说取钱。"}, {"text": "他终于把钱卖给了朋友。", "explanation": "这里应该用〈还钱〉。卖钱是把物品卖出去换钱，这里的钱是现金，归还欠朋友的款项要说还钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89191, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "卖钱", "is_correct": true, "explanation": "卖钱 mài qián：把东西卖给别人，换来钱。"}, {"text": "菜钱", "is_correct": false, "explanation": "声母不同（c 与 m）。cài qián 意思是买菜的钱，与 mài qián 只差一个声母。"}, {"text": "派钱", "is_correct": false, "explanation": "声母不同（p 与 m）。pài qián 意思是把钱分发给别人，比如过年派红包。"}, {"text": "晒钱", "is_correct": false, "explanation": "声母不同（sh 与 m）。shài qián 是口语，意思是炫耀自己有钱。"}], "explanations": {"卖钱": "卖钱 mài qián：把东西卖给别人，换来钱。", "菜钱": "声母不同（c 与 m）。cài qián 意思是买菜的钱，与 mài qián 只差一个声母。", "派钱": "声母不同（p 与 m）。pài qián 意思是把钱分发给别人，比如过年派红包。", "晒钱": "声母不同（sh 与 m）。shài qián 是口语，意思是炫耀自己有钱。"}, "sentence_index": null, "correct_answer": "卖钱"}, "level_3": {"options": [{"text": "卖钱", "is_correct": true, "explanation": "卖钱：把收集来的旧报纸卖掉换钱，符合句意。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：「演奏」要求乐器或乐曲作宾语，不能用于报纸。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：「结婚」是离合词，不能带被「拿去」支配的实物宾语。"}, {"text": "思念", "is_correct": false, "explanation": "语义：「思念」针对人或情感，不能是被拿去的物品。"}], "explanations": {"卖钱": "卖钱：把收集来的旧报纸卖掉换钱，符合句意。", "演奏": "搭配：「演奏」要求乐器或乐曲作宾语，不能用于报纸。", "结婚": "配价：「结婚」是离合词，不能带被「拿去」支配的实物宾语。", "思念": "语义：「思念」针对人或情感，不能是被拿去的物品。"}, "sentence_index": 6, "correct_answer": "卖钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃完饭以后，他先卖钱再离开。", "explanation": "这里应该用〈付钱〉。卖钱指把物品卖给别人换钱，结账时把钱交给店家要说付钱。"}, {"text": "他每周去财务室卖钱。", "explanation": "这里应该用〈领钱〉。卖钱指把东西卖给别人换钱，去财务室领工资不是卖东西。"}, {"text": "他每月去物业卖钱。", "explanation": "这里应该用〈交钱〉。卖钱指把物品卖出去，向物业付费要说交钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧书拿掉卖钱。", "corrected_sentence": "他把旧书拿去卖钱。", "error_description": "搭配错误：「去」误作「掉」。错误形式是「拿掉卖钱」，「拿掉」表示除去，与「卖钱」连用不通；正确形式是「拿去卖钱」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把小东西拿卖钱。", "corrected_sentence": "他把小东西拿去卖钱。", "error_description": "漏字：「拿」后需要趋向补语（「去」或「来」），表示把东西带走或拿来卖，不能省。错误形式是「拿卖钱」，正确形式是「拿去卖钱」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
