INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "东西好卖，能卖出钱。", "primary_collocate": null, "pronunciation": "mài qián", "ipa": "mai˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这种花很卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧杂志不卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在种水果比种粮食更卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的包很卖钱，一周就卖完了。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画不太卖钱，所以生活很紧。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "什么东西最卖钱，你知道吗？", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工做的小玩具在这里很卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的热饮最卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写得好，所以特别卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些破瓶子一点也不卖钱。", "target_word": "卖钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "賣錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "东西好卖，能卖出钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89192, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卖钱", "is_correct": true, "explanation": "卖钱 mài qián：东西好卖，能卖出钱。"}, {"text": "带钱", "is_correct": false, "explanation": "声母不同（d 与 m）。dài qián 意思是随身带着钱，与 mài qián 只差一个声母。"}, {"text": "赖钱", "is_correct": false, "explanation": "声母不同（l 与 m）。lài qián 意思是赖账、不肯还钱。"}, {"text": "埋钱", "is_correct": false, "explanation": "声调不同：mái qián（阳平）与 mài qián（去声）。埋钱是把钱埋起来。"}], "explanations": {"卖钱": "卖钱 mài qián：东西好卖，能卖出钱。", "带钱": "声母不同（d 与 m）。dài qián 意思是随身带着钱，与 mài qián 只差一个声母。", "赖钱": "声母不同（l 与 m）。lài qián 意思是赖账、不肯还钱。", "埋钱": "声调不同：mái qián（阳平）与 mài qián（去声）。埋钱是把钱埋起来。"}, "sentence_index": null, "correct_answer": "卖钱"}, "level_3": {"options": [{"text": "卖钱", "is_correct": true, "explanation": "卖钱：这种花很好卖，能卖出钱，符合句意。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：「害羞」描写人的心理，花不会害羞。"}, {"text": "能干", "is_correct": false, "explanation": "搭配：「能干」只用于人，不能形容花。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：「喜欢」表示人的喜爱之情，不能用来说花的好销程度。"}], "explanations": {"卖钱": "卖钱：这种花很好卖，能卖出钱，符合句意。", "害羞": "语义：「害羞」描写人的心理，花不会害羞。", "能干": "搭配：「能干」只用于人，不能形容花。", "喜欢": "语义：「喜欢」表示人的喜爱之情，不能用来说花的好销程度。"}, "sentence_index": 0, "correct_answer": "卖钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个道理很卖钱。", "explanation": "这里应该用〈深刻〉。卖钱形容货物好卖，形容道理的程度要说深刻，「道理」不是货物。"}, {"text": "这个孩子很卖钱。", "explanation": "这里应该用〈讨人喜欢〉。卖钱形容货物好卖，形容孩子招人喜欢要说讨人喜欢。"}, {"text": "这次考试很卖钱。", "explanation": "这里应该用〈难〉。卖钱形容货物好卖，形容考试的难度要说难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
