INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高兴是心里很快乐,想笑。", "primary_collocate": null, "pronunciation": "gāo xìng", "ipa": "kɑʊ̯˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "看到小狗，孩子很高兴。", "target_word": "高兴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我今天心里特别高兴。", "target_word": "高兴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她高兴得一直笑个不停。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟收到新玩具，高兴极了。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷看着我们，高兴地笑了。", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见朋友来了，她高兴地拍起手来。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你高兴的时候，喜欢做什么？", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天天气好，大家都很高兴。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她过生日，我们也跟着高兴。", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听见孩子的笑声，妈妈心里很高兴。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高兴了", "label": "体标"}, {"form": "高高兴兴", "label": "重叠"}, {"form": "高興", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里快乐想笑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db53ca1e-ed36-4d8f-b5e7-254742013a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”形容价格低，不能用来描述孩子的心情。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容神情郑重，与看到小狗时的愉快情绪不符。"}, {"text": "高兴", "is_correct": true, "explanation": "“高兴”表示心里快乐，与“看到小狗”的情境相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描述孩子的心情。"}], "explanations": {"便宜": "语义：“便宜”形容价格低，不能用来描述孩子的心情。", "严肃": "语义：“严肃”形容神情郑重，与看到小狗时的愉快情绪不符。", "高兴": "“高兴”表示心里快乐，与“看到小狗”的情境相符。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描述孩子的心情。"}, "sentence_index": 0, "correct_answer": "高兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很高兴那只狗。", "explanation": "这里应该用〈怕〉。高兴表示心里快乐，不能用来表示对某物的害怕。"}, {"text": "这次晚会的气氛很高兴。", "explanation": "这里应该用〈热烈〉。高兴只用来描述人的心情，不能用来形容场合的气氛。"}, {"text": "我很高兴小时候的老朋友。", "explanation": "这里应该用〈怀念〉。高兴表示当下的愉快，不能表示对过去之人的思念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干净", "is_correct": false, "explanation": "语义：“干净”形容没有污垢，不能用来描述人的心情。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能用来描述心情或状态。"}, {"text": "高兴", "is_correct": true, "explanation": "“高兴”表示心里快乐，与“喜欢做什么”的语境相符。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”形容价格低，不能用来形容人或心情状态。"}], "explanations": {"干净": "语义：“干净”形容没有污垢，不能用来描述人的心情。", "矮": "体貌：“矮”形容身高，不能用来描述心情或状态。", "高兴": "“高兴”表示心里快乐，与“喜欢做什么”的语境相符。", "便宜": "语义：“便宜”形容价格低，不能用来形容人或心情状态。"}, "sentence_index": 6, "correct_answer": "高兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很高兴这本书。", "explanation": "这里应该用〈喜欢〉。高兴表示心里愉快，不能直接带事物作宾语表示喜爱。"}, {"text": "这次展览很高兴。", "explanation": "这里应该用〈精彩〉。高兴只描述人的心情，不能用来评价展览、演出等事物。"}, {"text": "我很高兴远方的亲人。", "explanation": "这里应该用〈思念〉。高兴不能表示对远方亲人的思念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
