INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "愉快而兴奋。", "primary_collocate": null, "pronunciation": "gāo xìng", "ipa": "kɑʊ̯˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "听到好消息，我很高兴。", "target_word": "高兴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她拿到礼物，高兴得跳了起来。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "见到你，我非常高兴。", "target_word": "高兴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试得了第一名，他高兴极了。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们高兴地唱着歌回家。", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天你为什么这么高兴？", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说：“我今天特别高兴！”", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛赢了，大家都很高兴。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我高兴地告诉妈妈，我找到工作了。", "target_word": "高兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没这么高兴过。", "target_word": "高兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高兴了", "label": "体标"}, {"form": "高高兴兴", "label": "重叠"}, {"form": "高興", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到好事而愉快兴奋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db53ca1e-ed36-4d8f-b5e7-254742013a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤心", "is_correct": false, "explanation": "语义：“伤心”表示难过，与“听到好消息”带来的情绪相反。"}, {"text": "高兴", "is_correct": true, "explanation": "“高兴”表示愉快，与“好消息”的内容相符，正好填入空位。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”表示孤单、无人作伴的感觉，与听到好消息后的情绪不符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描述心情。"}], "explanations": {"伤心": "语义：“伤心”表示难过，与“听到好消息”带来的情绪相反。", "高兴": "“高兴”表示愉快，与“好消息”的内容相符，正好填入空位。", "寂寞": "语义：“寂寞”表示孤单、无人作伴的感觉，与听到好消息后的情绪不符。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描述心情。"}, "sentence_index": 0, "correct_answer": "高兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很高兴这个礼物。", "explanation": "这里应该用〈喜欢〉。高兴表示心里愉快，不能直接带事物作宾语表示喜爱。"}, {"text": "我很高兴他的勇气。", "explanation": "这里应该用〈佩服〉。高兴只表示心情愉快，不表示对他人品质的敬重。"}, {"text": "童年的时光非常高兴。", "explanation": "这里应该用〈快乐〉。高兴只用来形容人当下的心情，不能用来形容时光或时期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生气", "is_correct": false, "explanation": "语义：“生气”表示愤怒，与“笑着说”的状态相矛盾。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：“害怕”表示恐惧，与“笑着说”的状态相矛盾。"}, {"text": "高兴", "is_correct": true, "explanation": "“高兴”与“笑着说”的状态一致，符合“特别”和感叹语气。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身材，不能用来描述心情。"}], "explanations": {"生气": "语义：“生气”表示愤怒，与“笑着说”的状态相矛盾。", "害怕": "语义：“害怕”表示恐惧，与“笑着说”的状态相矛盾。", "高兴": "“高兴”与“笑着说”的状态一致，符合“特别”和感叹语气。", "瘦": "体貌：“瘦”形容身材，不能用来描述心情。"}, "sentence_index": 6, "correct_answer": "高兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很高兴这只狗。", "explanation": "这里应该用〈怕〉。高兴表示心里愉快，不能用来表示对某物的害怕。"}, {"text": "这次会议很高兴。", "explanation": "这里应该用〈愉快〉。高兴的主语应是人，表示人的心情；形容会议、活动等事情要用〈愉快〉。"}, {"text": "我很高兴远方的家人。", "explanation": "这里应该用〈想念〉。高兴不能表示对远方亲人的思念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我很高兴地。", "corrected_sentence": "今天我很高兴。", "error_description": "错误：“很高兴地”。正确：“很高兴”。形容词单独作谓语时后面不加“地”，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个高兴人走过来。", "corrected_sentence": "一个高兴的人走过来。", "error_description": "错误：“高兴人”。正确：“高兴的人”。形容词修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私人", "is_correct": true, "explanation": "反义：“私人的”指归个人所有，与“国有”（归国家所有）相对。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容声音或环境，与所有权的意义无关。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：“美丽”形容外貌或景色，与所有权无关。"}, {"text": "整齐", "is_correct": false, "explanation": "无关：“整齐”形容排列或外观，与所有权无关。"}], "correct_answer": "私人", "explanations": {"私人": "反义：“私人的”指归个人所有，与“国有”（归国家所有）相对。", "安静": "无关：“安静”形容声音或环境，与所有权的意义无关。", "美丽": "无关：“美丽”形容外貌或景色，与所有权无关。", "整齐": "无关：“整齐”形容排列或外观，与所有权无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私有", "is_correct": true, "explanation": "反义：“私有”指归个人所有，与“国有”相对。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”形容心情，与所有权无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容明白或清晰，与所有权无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外貌，与所有权无关。"}], "correct_answer": "私有", "explanations": {"私有": "反义：“私有”指归个人所有，与“国有”相对。", "高兴": "无关：“高兴”形容心情，与所有权无关。", "清楚": "无关：“清楚”形容明白或清晰，与所有权无关。", "漂亮": "无关：“漂亮”形容外貌，与所有权无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "属于国家所有的。", "primary_collocate": null, "pronunciation": "guó yǒu", "ipa": "kwo˧˥ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家银行是国有银行，不是私人的。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块土地是国有的，不能随便卖。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家国有企业工作。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国有资产要好好保护。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大桥是国有的，不是私人的。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸在一家国有工厂当工人。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家国有公司有一万多名工人。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国有土地上不能自己盖房子。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂以前是国有的，现在卖给了私人公司。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去国有银行贷款买房子。", "target_word": "国有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國有", "label": "繁体"}, {"form": "国有企业", "label": "复合"}, {"form": "国有化", "label": "复合"}], "register": "中性", "sense_fingerprint": "属于国家所有的，与私人的相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e7e323-496a-4e04-9d9e-25a70cdf1aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国有", "is_correct": true, "explanation": "正确。“国有”修饰银行，表示归国家所有，与后半句“不是私人的”相呼应。"}, {"text": "私人", "is_correct": false, "explanation": "语义：“私人银行”与后半句“不是私人的”正面矛盾，句子自相抵触。"}, {"text": "私营", "is_correct": false, "explanation": "语义：“私营”指民间经营，与后半句“不是私人的”矛盾。"}, {"text": "国产", "is_correct": false, "explanation": "搭配：“国产”多用于商品，一般不说“国产银行”。"}], "explanations": {"国有": "正确。“国有”修饰银行，表示归国家所有，与后半句“不是私人的”相呼应。", "私人": "语义：“私人银行”与后半句“不是私人的”正面矛盾，句子自相抵触。", "私营": "语义：“私营”指民间经营，与后半句“不是私人的”矛盾。", "国产": "搭配：“国产”多用于商品，一般不说“国产银行”。"}, "sentence_index": 0, "correct_answer": "国有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国有很大，人口也很多。", "explanation": "“国有”是形容词，指财产归国家所有，不能用来指“国家”本身，这里应该用〈国家〉。"}, {"text": "我对你的感情是国有的，别人不要管。", "explanation": "“国有”指财产归国家所有，只能修饰事物，不能用来描述感情；这里应该用〈私人〉表示个人的、不让别人管。"}, {"text": "我的爸爸是国有的，每天都去公司上班。", "explanation": "“国有”只能说财产或企业归国家所有，不能用来指人；可以说“我爸爸在国有企业工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国有", "is_correct": true, "explanation": "正确。“国有”修饰公司，表示归国家所有，与“一万多名工人”的规模相合。"}, {"text": "小型", "is_correct": false, "explanation": "语义：“小型”指规模小，与“有一万多名工人”的规模矛盾。"}, {"text": "微型", "is_correct": false, "explanation": "语义：“微型”指极小，与“一万多名工人”明显矛盾。"}, {"text": "国产", "is_correct": false, "explanation": "搭配：“国产”多用于商品，不用来修饰“公司”。"}], "explanations": {"国有": "正确。“国有”修饰公司，表示归国家所有，与“一万多名工人”的规模相合。", "小型": "语义：“小型”指规模小，与“有一万多名工人”的规模矛盾。", "微型": "语义：“微型”指极小，与“一万多名工人”明显矛盾。", "国产": "搭配：“国产”多用于商品，不用来修饰“公司”。"}, "sentence_index": 6, "correct_answer": "国有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国之间的交流是国有的。", "explanation": "“国有”指财产归国家所有，不能表示“国与国之间”，这里应该用〈国际〉。"}, {"text": "我对妈妈的爱非常国有。", "explanation": "“国有”只修饰财产或企业，不能用来形容感情；形容爱的程度应该用〈深厚〉。"}, {"text": "这次演习是国有的任务，很重要。", "explanation": "“国有”指财产归国家所有，不能表示“用于国家防卫”，这里应该用〈国防〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块土地是很国有的，不能随便卖。", "corrected_sentence": "这块土地是国有的，不能随便卖。", "error_description": "错误：“国有”是属性词，不能受程度副词“很”修饰。应去掉“很”，说“是国有的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹在一家很国有银行工作。", "corrected_sentence": "我妹妹在一家国有银行工作。", "error_description": "错误：“国有”是属性词，不能受程度副词“很”修饰。应去掉“很”，说“一家国有银行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
