INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89197, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不得是不可以做的意思。", "primary_collocate": null, "pronunciation": "bù dé", "ipa": "pu˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "图书馆里不得大声说话。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时不得看手机。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经允许，不得进入这个房间。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共场所不得吸烟。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生上课时不得迟到。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八岁以下的人不得进入网吧。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有票的人不得上车。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里不得大声吵闹。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本店的东西，卖出后不得退换。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时不得打电话。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "不可以做某事（规则、告示中的禁止）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89197, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示一定要，与图书馆要求安静的规定相反，句子意思不合。"}, {"text": "不得", "is_correct": true, "explanation": "“不得”表示禁止，与图书馆里不许大声说话的规定相符。"}, {"text": "可以", "is_correct": false, "explanation": "语义：“可以”表示允许，在图书馆大声说话与要求安静的场所规定矛盾。"}, {"text": "能", "is_correct": false, "explanation": "语义：“能”作许可解时，“图书馆里能大声说话”与图书馆要求安静的规定相矛盾；作能力解则语境不通。"}], "explanations": {"必须": "语义：“必须”表示一定要，与图书馆要求安静的规定相反，句子意思不合。", "不得": "“不得”表示禁止，与图书馆里不许大声说话的规定相符。", "可以": "语义：“可以”表示允许，在图书馆大声说话与要求安静的场所规定矛盾。", "能": "语义：“能”作许可解时，“图书馆里能大声说话”与图书馆要求安静的规定相矛盾；作能力解则语境不通。"}, "sentence_index": 0, "correct_answer": "不得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天感冒了，不得去上班。", "explanation": "这里应该用〈不能〉。不得表示禁止，多用于规定；因生病而做不到应说不能。"}, {"text": "天气冷，你不得穿短裤。", "explanation": "这里应该用〈不要〉。不得是书面的禁令用语，用于规章制度，不用于个人劝告。"}, {"text": "明天放假，你不得早起。", "explanation": "这里应该用〈不必〉。不得表示禁止；表示没有必要时应说不必。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应该", "is_correct": false, "explanation": "语义：“应该”表示按道理应当，与“没有票”的人不能上车的规定相反。"}, {"text": "不得", "is_correct": true, "explanation": "“不得”表示禁止，与没有票的人不许上车的规定相符。"}, {"text": "要", "is_correct": false, "explanation": "语义：“要”表示需要、必须，与没有票的人不许上车的规定相反，句子意思不合。"}, {"text": "不用", "is_correct": false, "explanation": "语义：“不用”表示没有必要，与“不得”表示的禁止义不符，“没有票的人不用上车”意思不通。"}], "explanations": {"应该": "语义：“应该”表示按道理应当，与“没有票”的人不能上车的规定相反。", "不得": "“不得”表示禁止，与没有票的人不许上车的规定相符。", "要": "语义：“要”表示需要、必须，与没有票的人不许上车的规定相反，句子意思不合。", "不用": "语义：“不用”表示没有必要，与“不得”表示的禁止义不符，“没有票的人不用上车”意思不通。"}, "sentence_index": 6, "correct_answer": "不得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天没睡好，不得开车。", "explanation": "这里应该用〈不宜〉。不得是禁令用语，自己状态不好而不该做的事应说不宜。"}, {"text": "这道题很简单，我不得做错。", "explanation": "这里应该用〈不会〉。不得表示禁止，推测自己做不出错应说不会。"}, {"text": "外面太吵了，我晚上不得睡觉。", "explanation": "这里应该用〈不能〉。不得表示规定上的禁止；因外界原因做不到应说不能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个区域不得着停车，请大家遵守。", "corrected_sentence": "这个区域不得停车，请大家遵守。", "error_description": "错误在“不得”和动词“停车”之间加了“着”。“不得”是情态动词，后面直接接动词，不能插入“着”；正确说法是“不得停车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个区域不得了拍照，请遵守规定。", "corrected_sentence": "这个区域不得拍照，请遵守规定。", "error_description": "错误形式：“不得了拍照”；正确形式：“不得拍照”。“了”不能加在情态动词“不得”之后；“不得了”是另一个词，表示程度很高，此处不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
