INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89198, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不可以;不许。", "primary_collocate": null, "pronunciation": "bù dé", "ipa": "pu˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "游客不得在博物馆里拍照。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司规定，上班时间不得玩游戏。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼里不得放自行车。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员不得收客人的礼物。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上不得乱扔垃圾。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有证件，任何人不得进入工厂。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请注意，本车厢内不得吃东西。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机不得喝酒后开车。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校规定，学生不得带手机进教室。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是私人的地方，外人不得进来。", "target_word": "不得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "不许、禁止（规定、制度中的用语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示一定要，与博物馆禁止拍照的规定相悖。"}, {"text": "应该", "is_correct": false, "explanation": "语义：“应该”表示应当，与规定中不许拍照的要求相悖。"}, {"text": "不得", "is_correct": true, "explanation": "“不得”表示禁止，与规定游客不许在博物馆拍照的语境相符。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接用在“在博物馆里拍照”这样的介宾结构前，句子不通。"}], "explanations": {"必须": "语义：“必须”表示一定要，与博物馆禁止拍照的规定相悖。", "应该": "语义：“应该”表示应当，与规定中不许拍照的要求相悖。", "不得": "“不得”表示禁止，与规定游客不许在博物馆拍照的语境相符。", "很": "语法：“很”是程度副词，不能直接用在“在博物馆里拍照”这样的介宾结构前，句子不通。"}, "sentence_index": 0, "correct_answer": "不得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事不急，你不得马上回复。", "explanation": "这里应该用〈不必〉。不得表示禁止；表示没有必要时应说不必。"}, {"text": "他不得会游泳，所以从不下水。", "explanation": "这里应该用〈不会〉。不得表示禁止，不能用来表示能力。"}, {"text": "我的腿受伤了，这几天不得走路。", "explanation": "这里应该用〈不能〉。不得是规定中的禁止用语；因身体原因做不到应说不能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可以", "is_correct": false, "explanation": "语义：“可以”表示允许，与“请注意”后的车厢禁食提醒相反。"}, {"text": "不得", "is_correct": true, "explanation": "“不得”表示禁止，与车厢内禁止进食的提醒相符。"}, {"text": "要", "is_correct": false, "explanation": "语义：“要”表示需要或打算，与车厢内禁止进食的提醒不合。"}, {"text": "能", "is_correct": false, "explanation": "语义：“能”表示允许或可能，“本车厢内能吃东西”与“请注意”引出的禁止提醒相反。"}], "explanations": {"可以": "语义：“可以”表示允许，与“请注意”后的车厢禁食提醒相反。", "不得": "“不得”表示禁止，与车厢内禁止进食的提醒相符。", "要": "语义：“要”表示需要或打算，与车厢内禁止进食的提醒不合。", "能": "语义：“能”表示允许或可能，“本车厢内能吃东西”与“请注意”引出的禁止提醒相反。"}, "sentence_index": 6, "correct_answer": "不得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨晚喝醉了，不得回家。", "explanation": "这里应该用〈不能〉。不得是禁令用语，自己喝醉后做不到回家应说不能。"}, {"text": "你不得这么着急。", "explanation": "这里应该用〈不要〉。不得用于规章制度，不用于劝对方别着急。"}, {"text": "他这次不得考得好。", "explanation": "这里应该用〈未必〉。不得表示禁止，不能表示“不一定”的推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室里不得着抽烟，请大家注意。", "corrected_sentence": "会议室里不得抽烟，请大家注意。", "error_description": "错误在“不得”和动词“抽烟”之间加了“着”。“不得”是情态动词，后面直接接动词，不能插入“着”；正确说法是“不得抽烟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "未经批准，任何人不得了复印这份文件。", "corrected_sentence": "未经批准，任何人不得复印这份文件。", "error_description": "错误形式：“不得了复印”；正确形式：“不得复印”。“了”不能加在情态动词“不得”之后；“不得了”是另一个词，此处不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
