INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89199, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89199, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军事家是特别会指挥打仗的人。", "primary_collocate": null, "pronunciation": "jūn shì jiā", "ipa": "tɕyn˥ ʂɨ˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "他是一位很有名的军事家。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷说，军事家要会指挥打仗。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位军事家带着士兵打赢了那场仗。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我最想当军事家。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军事家每天都要看地图，想怎么打仗。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位军事家从来没有输过。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一位中国军事家的故事。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军事家不但勇敢，而且很聪明。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了很多书，想成为军事家。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王请来一位军事家帮他保护国家。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "特别会指挥打仗的人，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89199, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是机器，不能指一位有名的人。"}, {"text": "军事家", "is_correct": true, "explanation": "“军事家”指特别会指挥打仗的人，符合“他是一位很有名的……”所指的人。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，“房子”应用“座”或“所”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是无生命的东西，不能说“他是一位很有名的石头”。"}], "explanations": {"电脑": "语义：“电脑”是机器，不能指一位有名的人。", "军事家": "“军事家”指特别会指挥打仗的人，符合“他是一位很有名的……”所指的人。", "房子": "搭配：量词“位”只用于人，“房子”应用“座”或“所”。", "石头": "语义：“石头”是无生命的东西，不能说“他是一位很有名的石头”。"}, "sentence_index": 0, "correct_answer": "军事家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥在部队当军事家，每天训练很辛苦。", "explanation": "这里应该用〈军人〉。军事家指特别会指挥打仗的人，每天在部队训练的普通人应说〈军人〉。"}, {"text": "我在营部当军事家，负责写文件和整理材料。", "explanation": "这里应该用〈参谋〉。军事家指特别会指挥打仗的人，负责写文件、整理材料的职务应说〈参谋〉。"}, {"text": "他是乐团的军事家，每次演出都很精彩。", "explanation": "这里应该用〈指挥家〉。军事家指特别会指挥打仗的人，指挥乐团的人应说〈指挥家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89199, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大熊猫", "is_correct": false, "explanation": "语义：“位”指人，“大熊猫”不是人，不能作为这个故事的主角。"}, {"text": "军事家", "is_correct": true, "explanation": "“军事家”指特别会指挥打仗的人，可以作为“一位中国……的故事”的主角。"}, {"text": "电视剧", "is_correct": false, "explanation": "语义：“电视剧”是作品，不是人，不能作为“一位……的故事”的主角。"}, {"text": "茶叶", "is_correct": false, "explanation": "语义：“茶叶”不是人，不能作为“一位……的故事”的主角。"}], "explanations": {"大熊猫": "语义：“位”指人，“大熊猫”不是人，不能作为这个故事的主角。", "军事家": "“军事家”指特别会指挥打仗的人，可以作为“一位中国……的故事”的主角。", "电视剧": "语义：“电视剧”是作品，不是人，不能作为“一位……的故事”的主角。", "茶叶": "语义：“茶叶”不是人，不能作为“一位……的故事”的主角。"}, "sentence_index": 6, "correct_answer": "军事家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国王请来一位军事家帮他管理国家的钱。", "explanation": "这里应该用〈财务主管〉。军事家指特别会指挥打仗的人，负责管理钱财的人应说〈财务主管〉。"}, {"text": "军事家们在雨中修理汽车，很辛苦。", "explanation": "这里应该用〈汽车修理工〉。军事家指特别会指挥打仗的人，修理汽车的人应说〈汽车修理工〉。"}, {"text": "国王请来一位军事家，专门为他做饭。", "explanation": "这里应该用〈厨师〉。军事家指特别会指挥打仗的人，为人做饭的应说〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只出色的军事家，也很会写文章。", "corrected_sentence": "他是一位出色的军事家，也很会写文章。", "error_description": "错误：“一只出色的军事家”；正确：“一位出色的军事家”。“军事家”指人，量词应用“位”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校请来了一位很有名军事家讲课。", "corrected_sentence": "学校请来了一位很有名的军事家讲课。", "error_description": "错误：“很有名军事家”；正确：“很有名的军事家”。“很有名”修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
