INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "精通军事理论、善于指挥作战的人。", "primary_collocate": null, "pronunciation": "jūn shì jiā", "ipa": "tɕyn˥ ʂɨ˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "这位军事家写过很多关于战争的书。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但是军事家，也是一位大学老师。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军事家研究了很多年，终于想出好办法。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙武是中国古代有名的军事家。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位军事家非常熟悉军事理论。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学请了一位军事家来讲战争的历史。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是军事家，所以很会安排作战计划。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上的军事家常常很会用兵。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位军事家的作战方法，很多人还在学。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要成为好的军事家，必须先学好军事理论。", "target_word": "军事家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "精通军事理论、善于指挥作战的专家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：“花园”是地方，不会写书，不能作为“这位……写过书”的主语。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然事物，不会写书。"}, {"text": "军事家", "is_correct": true, "explanation": "“军事家”指精通军事理论、善于指挥作战的人，能写关于战争的书。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不会写书，不能作为“这位……写过很多关于战争的书”的主语。"}], "explanations": {"花园": "语义：“花园”是地方，不会写书，不能作为“这位……写过书”的主语。", "河流": "语义：“河流”是自然事物，不会写书。", "军事家": "“军事家”指精通军事理论、善于指挥作战的人，能写关于战争的书。", "钢琴": "语义：“钢琴”是乐器，不会写书，不能作为“这位……写过很多关于战争的书”的主语。"}, "sentence_index": 0, "correct_answer": "军事家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军事家每天在操场上教我们队列动作。", "explanation": "这里应该用〈教官〉。军事家指精通军事理论、善于指挥作战的人，教队列动作的人应说〈教官〉。"}, {"text": "军事家们在雨中修理汽车，很辛苦。", "explanation": "这里应该用〈汽车修理工〉。军事家指精通军事理论、善于指挥作战的人，修理汽车的人应说〈汽车修理工〉。"}, {"text": "那位军事家每天给病人检查身体。", "explanation": "这里应该用〈医生〉。军事家指精通军事理论、善于指挥作战的人，给病人检查身体的应说〈医生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，与“很会安排作战计划”不搭。"}, {"text": "花匠", "is_correct": false, "explanation": "语义：花匠负责种花，与“很会安排作战计划”不搭。"}, {"text": "武夫", "is_correct": false, "explanation": "语域：“武夫”是书面语，带贬义，指只会蛮干的人，与“很会安排作战计划”不符。"}, {"text": "军事家", "is_correct": true, "explanation": "“军事家”指精通军事理论、善于指挥作战的人，正好与“很会安排作战计划”相符。"}], "explanations": {"厨师": "语义：厨师负责做饭，与“很会安排作战计划”不搭。", "花匠": "语义：花匠负责种花，与“很会安排作战计划”不搭。", "武夫": "语域：“武夫”是书面语，带贬义，指只会蛮干的人，与“很会安排作战计划”不符。", "军事家": "“军事家”指精通军事理论、善于指挥作战的人，正好与“很会安排作战计划”相符。"}, "sentence_index": 6, "correct_answer": "军事家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位军事家在音乐会上唱了三首歌。", "explanation": "这里应该用〈歌手〉。军事家指精通军事理论、善于指挥作战的人，在音乐会上唱歌的应说〈歌手〉。"}, {"text": "这位军事家在舞台上表演得很好。", "explanation": "这里应该用〈演员〉。军事家指精通军事理论、善于指挥作战的人，在舞台上表演的应说〈演员〉。"}, {"text": "这位军事家做的菜非常好吃，很多人都来买。", "explanation": "这里应该用〈厨师〉。军事家指精通军事理论、善于指挥作战的人，做菜的应说〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他读了很多军事理论，后来成了一本出色的军事家。", "corrected_sentence": "他读了很多军事理论，后来成了一位出色的军事家。", "error_description": "错误：“一本出色的军事家”；正确：“一位出色的军事家”。“本”用于书籍，指人应用“位”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直想当一把好的军事家，所以努力学习。", "corrected_sentence": "他一直想当一位好的军事家，所以努力学习。", "error_description": "错误：“一把好的军事家”；正确：“一位好的军事家”。“把”用于有柄的器具，指人应用“位”或“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89201, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
