INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "值得不值得：指付出与得到相比是否划算。", "primary_collocate": null, "pronunciation": "zhí", "ipa": "ʈʂɻ̩˧˥", "syllable_count": 1, "sentences": [{"text": "花三个小时去看他，我觉得很值。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么贵的菜，吃一次也不值。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说，为这件小事生气值吗？", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书只要十块，买了很值。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了一点钱丢了工作，真不值。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打车要一百块，坐地铁才五块，坐地铁更值。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑花了八千块，你觉得值吗？", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然路很远，但是看到这么美的风景，一切都值了。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮朋友这个忙，我觉得很值。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服便宜又好看，买它真值。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "值得", "label": "复合"}, {"form": "值钱", "label": "复合"}, {"form": "价值", "label": "复合"}], "register": "中性", "sense_fingerprint": "值不值：付出与得到相比是否划算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89201, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "值", "is_correct": true, "explanation": "值（zhí，第二声）指付出与得到相比是否划算，即值得。"}, {"text": "指", "is_correct": false, "explanation": "指（zhǐ，第三声）与 zhí 声调不同，意思是手指。"}, {"text": "制", "is_correct": false, "explanation": "制（zhì，第四声）与 zhí 声调不同，意思是制造。"}, {"text": "至", "is_correct": false, "explanation": "至（zhì，第四声）与 zhí 声调不同，意思是到达。"}, {"text": "只", "is_correct": false, "explanation": "只（zhǐ，第三声）与 zhí 声调不同，意思是仅、只。"}, {"text": "织", "is_correct": false, "explanation": "织（zhī，第一声）与 zhí 声调不同，意思是编织。"}], "explanations": {"值": "值（zhí，第二声）指付出与得到相比是否划算，即值得。", "指": "指（zhǐ，第三声）与 zhí 声调不同，意思是手指。", "制": "制（zhì，第四声）与 zhí 声调不同，意思是制造。", "至": "至（zhì，第四声）与 zhí 声调不同，意思是到达。", "只": "只（zhǐ，第三声）与 zhí 声调不同，意思是仅、只。", "织": "织（zhī，第一声）与 zhí 声调不同，意思是编织。"}, "sentence_index": null, "correct_answer": "值"}, "level_3": {"options": [{"text": "值", "is_correct": true, "explanation": "值表示付出与收获相称，“很值”说这次去看他是划算的。"}, {"text": "方", "is_correct": false, "explanation": "语义：“方”形容形状，不能用来评价付出是否划算。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：“圆”形容形状，不能用来形容对付出的感受。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”指质地，与“值不值”的判断不相干。"}], "explanations": {"值": "值表示付出与收获相称，“很值”说这次去看他是划算的。", "方": "语义：“方”形容形状，不能用来评价付出是否划算。", "圆": "搭配：“圆”形容形状，不能用来形容对付出的感受。", "硬": "语义：“硬”指质地，与“值不值”的判断不相干。"}, "sentence_index": 0, "correct_answer": "值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了这点小事生气，真没值。", "explanation": "这里应该用〈没必要〉。“值”表示值不值得，不能用“没值”来表示“没有必要”。"}, {"text": "这台电脑很贵，但是值买。", "explanation": "这里应该用〈值得〉。“值”不能直接带动词作宾语，表示值得做某事要说“值得买”。"}, {"text": "为了一点钱丢了工作，真值不来。", "explanation": "这里应该用〈划不来〉。“值”不能与“不来”组合表示不划算，要说“划不来”或“不值”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89201, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "值", "is_correct": true, "explanation": "值（zhí，第二声）指付出与得到相比是否划算，即值得。"}, {"text": "纸", "is_correct": false, "explanation": "纸（zhǐ，第三声）与 zhí 声调不同，意思是纸张。"}, {"text": "质", "is_correct": false, "explanation": "质（zhì，第四声）与 zhí 声调不同，意思是质量。"}, {"text": "之", "is_correct": false, "explanation": "之（zhī，第一声）与 zhí 声调不同，意思是“的”或代词。"}, {"text": "止", "is_correct": false, "explanation": "止（zhǐ，第三声）与 zhí 声调不同，意思是停止。"}, {"text": "知", "is_correct": false, "explanation": "知（zhī，第一声）与 zhí 声调不同，意思是知道。"}], "explanations": {"值": "值（zhí，第二声）指付出与得到相比是否划算，即值得。", "纸": "纸（zhǐ，第三声）与 zhí 声调不同，意思是纸张。", "质": "质（zhì，第四声）与 zhí 声调不同，意思是质量。", "之": "之（zhī，第一声）与 zhí 声调不同，意思是“的”或代词。", "止": "止（zhǐ，第三声）与 zhí 声调不同，意思是停止。", "知": "知（zhī，第一声）与 zhí 声调不同，意思是知道。"}, "sentence_index": null, "correct_answer": "值"}, "level_3": {"options": [{"text": "值", "is_correct": true, "explanation": "值表示付出与收获相称，“值吗”问花八千块买电脑是否划算。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”用于衣物，电脑不能穿，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，电脑不能吃，与句意不合。"}, {"text": "戴", "is_correct": false, "explanation": "配价：“戴”要求戴在身上的物品作宾语，电脑不能戴，句子不通。"}], "explanations": {"值": "值表示付出与收获相称，“值吗”问花八千块买电脑是否划算。", "穿": "语义：“穿”用于衣物，电脑不能穿，句子不通。", "吃": "语义：“吃”指进食，电脑不能吃，与句意不合。", "戴": "配价：“戴”要求戴在身上的物品作宾语，电脑不能戴，句子不通。"}, "sentence_index": 6, "correct_answer": "值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我值一百块买了这件衣服。", "explanation": "这里应该用〈花〉。“值”的主语只能是东西，表示东西价钱相当，不能说人用一百块去值东西；花钱买东西要说“花”。"}, {"text": "这件衣服很便宜，我很值它。", "explanation": "这里应该用〈喜欢〉。“值”表示划算，主语是事情或东西，不能说人“值”某物来表达喜爱。"}, {"text": "这次活动很有意义，大家都值参加。", "explanation": "这里应该用〈值得〉。“值”不能直接带动词，表示值得去做某事要说“值得参加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么便宜的书，买一本值很。", "corrected_sentence": "这么便宜的书，买一本很值。", "error_description": "错误在“很”放在了“值”后面。“很”要修饰“值”，应放在它前面；正确说法是“很值”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋这么贵，我觉得一点也值不。", "corrected_sentence": "这双鞋这么贵，我觉得一点也不值。", "error_description": "错误在“不”放在了“值”后面。否定词要放在“值”前面，应说“不值”；“值不”是语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
