INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89202, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "价格相当;有价值。", "primary_collocate": null, "pronunciation": "zhí", "ipa": "ʈʂɻ̩˧˥", "syllable_count": 1, "sentences": [{"text": "这件衣服值三百块。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块手表值多少钱？", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆旧车只值五千元。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画值一百万元。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一斤苹果值多少钱，你知道吗？", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包太贵了，不值八百块。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚老邮票值很多钱，因为发行量很少。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书一共值二十块钱。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那套房子现在值两百万。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只花瓶很旧，但是值一千块。", "target_word": "值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "值得", "label": "复合"}, {"form": "值钱", "label": "复合"}, {"form": "价值", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西的价格相当于多少钱，或有价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89202, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "值", "is_correct": true, "explanation": "值（zhí，第二声）指价格相当，或有价值。"}, {"text": "指", "is_correct": false, "explanation": "指（zhǐ，第三声）与 zhí 声调不同，意思是手指或指向。"}, {"text": "知", "is_correct": false, "explanation": "知（zhī，第一声）与 zhí 声母、韵母相同，只是声调不同，意思是知道。"}, {"text": "制", "is_correct": false, "explanation": "制（zhì，第四声）与 zhí 声调不同，意思是制造。"}, {"text": "至", "is_correct": false, "explanation": "至（zhì，第四声）与 zhí 声调不同，意思是到达。"}, {"text": "止", "is_correct": false, "explanation": "止（zhǐ，第三声）与 zhí 声调不同，意思是停止。"}], "explanations": {"值": "值（zhí，第二声）指价格相当，或有价值。", "指": "指（zhǐ，第三声）与 zhí 声调不同，意思是手指或指向。", "知": "知（zhī，第一声）与 zhí 声母、韵母相同，只是声调不同，意思是知道。", "制": "制（zhì，第四声）与 zhí 声调不同，意思是制造。", "至": "至（zhì，第四声）与 zhí 声调不同，意思是到达。", "止": "止（zhǐ，第三声）与 zhí 声调不同，意思是停止。"}, "sentence_index": null, "correct_answer": "值"}, "level_3": {"options": [{"text": "值", "is_correct": true, "explanation": "值表示价格相当，“值三百块”说的是这件衣服的价钱是三百块。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，衣服不能喝，与句意不合。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指睡觉，衣服不能睡，与价钱无关。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指把衣服穿在身上，与价钱无关，句子无意义。"}], "explanations": {"值": "值表示价格相当，“值三百块”说的是这件衣服的价钱是三百块。", "喝": "语义：“喝”指饮用，衣服不能喝，与句意不合。", "睡": "语义：“睡”指睡觉，衣服不能睡，与价钱无关。", "穿": "语义：“穿”指把衣服穿在身上，与价钱无关，句子无意义。"}, "sentence_index": 0, "correct_answer": "值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件衣服的价钱值。", "explanation": "这里应该用〈相当〉。“值”是动词，要带价格宾语，不能单独作“价钱”的谓语；表示价钱相同应说“相当”。"}, {"text": "专家值这幅画一百万元。", "explanation": "这里应该用〈估价〉。“值”的主语只能是东西，表示东西价格相当；人评定价格要说估价。"}, {"text": "我值一百万元买了这幅画。", "explanation": "这里应该用〈花〉。“值”的主语只能是东西，表示东西价钱相当，不能说人用一百万元去值东西；花钱买东西要说“花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89202, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "值", "is_correct": true, "explanation": "值（zhí，第二声）指价格相当，或有价值。"}, {"text": "纸", "is_correct": false, "explanation": "纸（zhǐ，第三声）与 zhí 声调不同，意思是纸张。"}, {"text": "织", "is_correct": false, "explanation": "织（zhī，第一声）与 zhí 声调不同，意思是编织。"}, {"text": "只", "is_correct": false, "explanation": "只（zhǐ，第三声）与 zhí 声调不同，意思是仅、只。"}, {"text": "志", "is_correct": false, "explanation": "志（zhì，第四声）与 zhí 声调不同，意思是志向。"}, {"text": "质", "is_correct": false, "explanation": "质（zhì，第四声）与 zhí 声调不同，意思是质量。"}], "explanations": {"值": "值（zhí，第二声）指价格相当，或有价值。", "纸": "纸（zhǐ，第三声）与 zhí 声调不同，意思是纸张。", "织": "织（zhī，第一声）与 zhí 声调不同，意思是编织。", "只": "只（zhǐ，第三声）与 zhí 声调不同，意思是仅、只。", "志": "志（zhì，第四声）与 zhí 声调不同，意思是志向。", "质": "质（zhì，第四声）与 zhí 声调不同，意思是质量。"}, "sentence_index": null, "correct_answer": "值"}, "level_3": {"options": [{"text": "值", "is_correct": true, "explanation": "值表示价格相当，“值很多钱”说这枚老邮票的价钱高。"}, {"text": "借", "is_correct": false, "explanation": "配价：“借”要求借入的人作主语，“老邮票”不能借钱。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与邮票的价钱无关，句子不通。"}, {"text": "带", "is_correct": false, "explanation": "语义：“带”指随身携带，邮票不能带钱，与句意不合。"}], "explanations": {"值": "值表示价格相当，“值很多钱”说这枚老邮票的价钱高。", "借": "配价：“借”要求借入的人作主语，“老邮票”不能借钱。", "吃": "语义：“吃”指进食，与邮票的价钱无关，句子不通。", "带": "语义：“带”指随身携带，邮票不能带钱，与句意不合。"}, "sentence_index": 6, "correct_answer": "值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店主值这只花瓶一千块。", "explanation": "这里应该用〈卖〉。“值”的主语只能是东西，人不能作主语去“值”某物的价钱；店主卖花瓶要说卖。"}, {"text": "这家店值一千块的押金。", "explanation": "这里应该用〈收〉。“值”只表示东西的价钱相当，不能表示店家收取费用；收押金要说“收”。"}, {"text": "学校值他一千块。", "explanation": "这里应该用〈罚〉。“值”不能表示对人的处罚；学校罚人钱要说“罚他一千块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块旧表值了两千块。", "corrected_sentence": "这块旧表值两千块。", "error_description": "错误在“值”后面加了“了”。“值”表示价格相当，是状态动词，不能带“了”；正确说法是“值两千块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆自行车值得三百块。", "corrected_sentence": "那辆自行车值三百块。", "error_description": "错误在“值”后面加了“得”，变成了另一个词“值得”。“值得”后接动词或形容词，表示有价值、值得去做；表示价钱相当应说“值三百块”，不能说“值得三百块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
