INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89203, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "很快就要到了，只差一点点时间。", "primary_collocate": null, "pronunciation": "zài jí", "ipa": "tsaɪ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "新年在即，公司里的人都很忙。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试在即，我一点儿也不敢玩。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议在即，经理还在改报告。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行在即，我高兴得睡不着觉。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日在即，朋友们都在给他买礼物。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开业在即，小店门口挂满了红花。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "决赛在即，教练让大家早点休息。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "期末在即，图书馆里坐满了学生。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演讲在即，他的手心全是汗。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离别在即，母亲给我煮了一碗面。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "很快就要到来，只差一点时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：“新年”不会退休，“退休”不能用于时间，句意不通。"}, {"text": "在即", "is_correct": true, "explanation": "正确：在即指很快就要到来，与“新年”搭配，表示新年快到了。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：新年不会放弃，“放弃”的主语须是人或团体，句意不通。"}, {"text": "出版", "is_correct": false, "explanation": "语义：新年不能出版，“出版”与新年无关。"}], "explanations": {"退休": "语义：“新年”不会退休，“退休”不能用于时间，句意不通。", "在即": "正确：在即指很快就要到来，与“新年”搭配，表示新年快到了。", "放弃": "语义：新年不会放弃，“放弃”的主语须是人或团体，句意不通。", "出版": "语义：新年不能出版，“出版”与新年无关。"}, "sentence_index": 0, "correct_answer": "在即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟在即长高。", "explanation": "这里应该用〈快要〉。“在即”只指事件即将发生，不能用来描述人的成长。"}, {"text": "妈妈在即回来。", "explanation": "这里应该用〈马上〉。“在即”指事件即将到来，不能用人作主语表示回来。"}, {"text": "这列火车慢慢在即。", "explanation": "这里应该用〈靠近〉。“在即”指事件即将发生，不用来描写列车的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：决赛不会出生，“出生”与比赛无关，句意不通。"}, {"text": "在即", "is_correct": true, "explanation": "正确：在即指决赛很快就要到来，与“决赛”搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：决赛不会忘记，“忘记”的主语须是有记忆的人，句意不通。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：决赛不能毕业，“毕业”与比赛无关。"}], "explanations": {"出生": "语义：决赛不会出生，“出生”与比赛无关，句意不通。", "在即": "正确：在即指决赛很快就要到来，与“决赛”搭配。", "忘记": "语义：决赛不会忘记，“忘记”的主语须是有记忆的人，句意不通。", "毕业": "语义：决赛不能毕业，“毕业”与比赛无关。"}, "sentence_index": 6, "correct_answer": "在即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫在即。", "explanation": "语义：“在即”只指事件即将发生，不能以动物作主语，句意不通。"}, {"text": "他在即回国。", "explanation": "这里应该用〈即将〉。“在即”描述事件即将发生，不用人作主语。"}, {"text": "这件衣服在即。", "explanation": "这里用的是“物件”作主语，“在即”只能指事件即将发生，不能用来描写衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春节在即着，大家都在准备年货。", "corrected_sentence": "春节在即，大家都在准备年货。", "error_description": "体标错误：“在即”表示事件即将到来，不能带持续体标记“着”，应去掉“着”，说“春节在即”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春游很在即，老师提醒大家带好水。", "corrected_sentence": "春游在即，老师提醒大家带好水。", "error_description": "程度副词错误：“在即”是动词性结构，前面不能加程度副词“很”，应说“春游在即”，不能说“春游很在即”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
