INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89204, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指某件事情即将发生，时间已经非常临近。", "primary_collocate": null, "pronunciation": "zài jí", "ipa": "tsaɪ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "考试在即，他每天都复习到很晚。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节在即，街上的商店都很热闹。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛在即，队员们都在认真练习。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼在即，新娘心里有点紧张。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业在即，同学们都舍不得离开学校。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开学在即，妈妈帮我准备好了书包。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发在即，大家再检查一次行李。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出在即，演员们已经化好了妆。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期结束在即，他还有很多作业没写。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家在即，我们的东西还没有收拾好。", "target_word": "在即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某事即将发生，时间非常临近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "语义：考试不会放弃，“放弃”的主语须是人，句意不通。"}, {"text": "在即", "is_correct": true, "explanation": "正确：在即指事情很快就要发生，与“考试”搭配，表示考试临近。"}, {"text": "出国", "is_correct": false, "explanation": "语义：考试不能出国，“出国”与考试无关，句意不通。"}, {"text": "开学", "is_correct": false, "explanation": "语义：考试与开学不是同一件事，考试不会开学。"}], "explanations": {"放弃": "语义：考试不会放弃，“放弃”的主语须是人，句意不通。", "在即": "正确：在即指事情很快就要发生，与“考试”搭配，表示考试临近。", "出国": "语义：考试不能出国，“出国”与考试无关，句意不通。", "开学": "语义：考试与开学不是同一件事，考试不会开学。"}, "sentence_index": 0, "correct_answer": "在即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这艘船慢慢在即。", "explanation": "这里应该用〈靠近〉。“在即”指某件事情即将发生，不用来描写船只的位置。"}, {"text": "我在即回国。", "explanation": "这里应该用〈即将〉。“在即”只用于某件事情即将发生，不能以人作主语，应说“我即将回国”。"}, {"text": "这个孩子在即长大。", "explanation": "这里应该用〈快要〉。“在即”只指事件即将发生，不能用来描述人的成长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：出发与结婚不相干，“出发结婚”句意不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：出发不会忘记，“忘记”的主语须是人，句意不通。"}, {"text": "在即", "is_correct": true, "explanation": "正确：在即指出发即将到来，与“出发”搭配。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：出发不能毕业，“出发毕业”不成立。"}], "explanations": {"结婚": "语义：出发与结婚不相干，“出发结婚”句意不通。", "忘记": "语义：出发不会忘记，“忘记”的主语须是人，句意不通。", "在即": "正确：在即指出发即将到来，与“出发”搭配。", "毕业": "语义：出发不能毕业，“出发毕业”不成立。"}, "sentence_index": 6, "correct_answer": "在即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫在即。", "explanation": "语义：“在即”只指事件即将发生，不能以动物作主语，句意不通。"}, {"text": "他在即回国。", "explanation": "这里应该用〈将要〉。“在即”描述事件即将发生，不用人作主语。"}, {"text": "这张桌子在即。", "explanation": "这里用的是“物件”作主语，“在即”只能指事件即将发生，不能用来描写桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛在即着，他每天都在训练。", "corrected_sentence": "比赛在即，他每天都在训练。", "error_description": "体标错误：“在即”表示事件临近，不能带持续体标记“着”，应去掉“着”，说“比赛在即”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新学期很在即，学生们都在准备开学。", "corrected_sentence": "新学期在即，学生们都在准备开学。", "error_description": "程度副词错误：“在即”表示事件临近，不能受“很”修饰，应去掉“很”，说“新学期在即”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
