INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89206, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指女子每月一次的子宫出血现象，即月经。", "primary_collocate": null, "pronunciation": "yuè xìn", "ipa": "ɥe˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "月信就是月经，每月来一次。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的月信已经三个月没来了。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月信量太多，要及时就医。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书里把月经叫作月信。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说月信周期大约二十八天。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月信前，她常常觉得很累。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怀孕以后，月信会停止。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她记下每次月信的日期。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月信不规律，可能和压力有关。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月信结束后，她的身体慢慢恢复了。", "target_word": "月信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "女子每月一次的子宫出血现象，即月经", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '790811c9-6e97-424f-b6aa-eb7a3bd287ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月信", "is_correct": true, "explanation": "月信指女子每月一次的子宫出血，即月经，作定义句的主语，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资就是月经”不成立，工资与子宫出血无关。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票与“月经”的含义完全不符。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：“婚礼”不能指每月来一次的生理现象，与“每月来一次”搭配不当。"}], "explanations": {"月信": "月信指女子每月一次的子宫出血，即月经，作定义句的主语，符合句意。", "工资": "语义：“工资就是月经”不成立，工资与子宫出血无关。", "车票": "语义：车票与“月经”的含义完全不符。", "婚礼": "搭配：“婚礼”不能指每月来一次的生理现象，与“每月来一次”搭配不当。"}, "sentence_index": 0, "correct_answer": "月信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每到月信都要结账。", "explanation": "这里应该用〈月底〉。月信指女子每月一次的子宫出血，表示时间的月底要说月底。"}, {"text": "她每月都买一张公交月信。", "explanation": "这里应该用〈月票〉。月信指生理现象，买乘车的凭证要说月票。"}, {"text": "山里的月信格外明亮。", "explanation": "这里应该用〈月光〉。月信指女子的生理现象，月亮的光要说月光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月信", "is_correct": true, "explanation": "月信指月经，怀孕以后会停止，符合句意。"}, {"text": "学费", "is_correct": false, "explanation": "语义：怀孕以后学费不会因此停止，与句中的情境不符。"}, {"text": "电费", "is_correct": false, "explanation": "语义：电费与怀孕引起的变化无关。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：驾照不会因怀孕而“停止”，二者搭配不当。"}], "explanations": {"月信": "月信指月经，怀孕以后会停止，符合句意。", "学费": "语义：怀孕以后学费不会因此停止，与句中的情境不符。", "电费": "语义：电费与怀孕引起的变化无关。", "驾照": "搭配：驾照不会因怀孕而“停止”，二者搭配不当。"}, "sentence_index": 6, "correct_answer": "月信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中秋节一家人围坐在一起吃月信。", "explanation": "这里应该用〈月饼〉。月信指女子的生理现象，中秋吃的点心要说月饼。"}, {"text": "这份杂志是一本月信，每个月出版一次。", "explanation": "这里应该用〈月刊〉。月信指生理现象，每月出版的刊物要说月刊。"}, {"text": "列车进站了，乘客走上月信。", "explanation": "这里应该用〈月台〉。月信指生理现象，乘客等车时站立的地方要说月台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上个月的月信来了一个。", "corrected_sentence": "她上个月的月信来了一次。", "error_description": "量词错误：月经发生的次数应用“次”计量，不能用“个”，应说“来了一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的月信总是来的很晚。", "corrected_sentence": "她的月信总是来得很晚。", "error_description": "补语结构错误：程度补语应用“得”连接，“来得很晚”中的“得”不能换成“的”，不能说“来的很晚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
