INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89207, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军医院是给当兵的人看病的医院。", "primary_collocate": null, "pronunciation": "jūn yī yuàn", "ipa": "tɕyn˥ i˥ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "当兵的哥哥生病了，去了军医院。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军医院里有很多穿军装的医生。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个士兵受伤了，马上送到军医院。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸以前当过兵，常去军医院。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军医院离部队很近。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军医院一般只给当兵的人看病。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在军医院做了一个小手术。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们感冒了，都去军医院拿药。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在军医院当护士。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所军医院的医生都很年轻。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "给当兵的人看病的医院，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89207, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电影院", "is_correct": false, "explanation": "语义：生病要去看病，“电影院”不是医疗场所。"}, {"text": "军医院", "is_correct": true, "explanation": "“军医院”是给当兵的人看病的医院，符合哥哥生病去看病的语境。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：生病要去看病，“图书馆”不是医疗场所。"}, {"text": "健身房", "is_correct": false, "explanation": "语义：生病的人不会去健身房，句子说的是看病。"}], "explanations": {"电影院": "语义：生病要去看病，“电影院”不是医疗场所。", "军医院": "“军医院”是给当兵的人看病的医院，符合哥哥生病去看病的语境。", "图书馆": "语义：生病要去看病，“图书馆”不是医疗场所。", "健身房": "语义：生病的人不会去健身房，句子说的是看病。"}, "sentence_index": 0, "correct_answer": "军医院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想去军医院买一本书。", "explanation": "这里应该用〈书店〉。军医院是给当兵的人看病的医院，买书应去〈书店〉。"}, {"text": "学生们在军医院里踢足球。", "explanation": "这里应该用〈操场〉。军医院是看病的地方，踢足球应去〈操场〉。"}, {"text": "我家附近有一座军医院，周末很多人去看书。", "explanation": "这里应该用〈图书馆〉。军医院是看病的地方，周末去看书应去〈图书馆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图书馆", "is_correct": false, "explanation": "语义：做手术要在医疗机构，“图书馆”不是医院。"}, {"text": "银行", "is_correct": false, "explanation": "语义：“银行”是金融机构，不能做手术。"}, {"text": "护士", "is_correct": false, "explanation": "语义：“在”后面要接地点，“护士”是人，不是做手术的地方。"}, {"text": "军医院", "is_correct": true, "explanation": "“军医院”是医院，能做手术，符合“他在……做了一个小手术”。"}], "explanations": {"图书馆": "语义：做手术要在医疗机构，“图书馆”不是医院。", "银行": "语义：“银行”是金融机构，不能做手术。", "护士": "语义：“在”后面要接地点，“护士”是人，不是做手术的地方。", "军医院": "“军医院”是医院，能做手术，符合“他在……做了一个小手术”。"}, "sentence_index": 6, "correct_answer": "军医院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所军医院每天生产大量汽车。", "explanation": "这里应该用〈汽车厂〉。军医院是看病的地方，大量生产汽车的应是〈汽车厂〉。"}, {"text": "这所军医院每天都有很多人来存钱。", "explanation": "这里应该用〈银行〉。军医院是给当兵的人看病的医院，存钱应去〈银行〉。"}, {"text": "这所军医院的球员都很年轻。", "explanation": "这里应该用〈球队〉。军医院是看病的地方，球员应属于〈球队〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅把军医院工作了十年。", "corrected_sentence": "我舅舅在军医院工作了十年。", "error_description": "错误：“把军医院工作了十年”；正确：“在军医院工作了十年”。“把”字句的宾语必须是受处置的对象，地点不能作“把”的宾语，应改用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经在军医院工作着。", "corrected_sentence": "他曾经在军医院工作过。", "error_description": "错误：“曾经……工作着”；正确：“曾经……工作过”。“着”表示持续，与“曾经”所说的过去经历相矛盾，应用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
