INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队设立的、主要为军人服务的医院。", "primary_collocate": null, "pronunciation": "jūn yī yuàn", "ipa": "tɕyn˥ i˥ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "军队在这个城市建了一所军医院。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所军医院主要为军人和家人服务。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军医院有时也让普通人来看病。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队在山里设立了一所军医院。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那所军医院是军队办的。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军医院里的医生大多是军人。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷在军医院工作了三十年。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所军医院有很多新机器。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军医院每个月给战士检查身体。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这所军医院又多了一栋新楼。", "target_word": "军医院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "军队设立、主要为军人服务的医院", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书架", "is_correct": false, "explanation": "语义：“书架”是家具，不是军队可以建设的医疗机构。"}, {"text": "军医院", "is_correct": true, "explanation": "“军医院”是军队设立的医院，符合“军队在这个城市建了一所……”的语境。"}, {"text": "草坪", "is_correct": false, "explanation": "量词：“所”用于机构、房屋，“草坪”不能用“所”，应说“一片”或“一块”。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”是器物，不能由军队建设。"}], "explanations": {"书架": "语义：“书架”是家具，不是军队可以建设的医疗机构。", "军医院": "“军医院”是军队设立的医院，符合“军队在这个城市建了一所……”的语境。", "草坪": "量词：“所”用于机构、房屋，“草坪”不能用“所”，应说“一片”或“一块”。", "花瓶": "语义：“花瓶”是器物，不能由军队建设。"}, "sentence_index": 0, "correct_answer": "军医院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们在军医院里生产炮弹。", "explanation": "这里应该用〈兵工厂〉。军医院是为军人服务的医疗机构，生产炮弹的地方应说〈兵工厂〉。"}, {"text": "战士们每天在军医院里训练。", "explanation": "这里应该用〈军营〉。军医院是看病的地方，战士每天训练应在〈军营〉。"}, {"text": "部队在山里设立了一所军医院，专门教孩子们画画。", "explanation": "这里应该用〈美术学校〉。军医院是看病的地方，教孩子们画画应去〈美术学校〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书本", "is_correct": false, "explanation": "语义：“书本”不是工作的地方，不能说“在书本工作”。"}, {"text": "军医院", "is_correct": true, "explanation": "“军医院”是医疗机构，可以作为“在……工作了三十年”的工作单位。"}, {"text": "拖把", "is_correct": false, "explanation": "语义：“拖把”是清洁用具，不是可以工作的地方，不能说“在拖把工作了三十年”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”是天体，不能作为工作的地方。"}], "explanations": {"书本": "语义：“书本”不是工作的地方，不能说“在书本工作”。", "军医院": "“军医院”是医疗机构，可以作为“在……工作了三十年”的工作单位。", "拖把": "语义：“拖把”是清洁用具，不是可以工作的地方，不能说“在拖把工作了三十年”。", "月亮": "语义：“月亮”是天体，不能作为工作的地方。"}, "sentence_index": 6, "correct_answer": "军医院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所军医院教三年级学生唱歌。", "explanation": "这里应该用〈学校〉。军医院是看病的地方，教学生唱歌的应说〈学校〉。"}, {"text": "战士们在军医院练习射击。", "explanation": "这里应该用〈靶场〉。军医院不是练习射击的地方，练习射击应去〈靶场〉。"}, {"text": "这所军医院的老虎每天都要表演。", "explanation": "这里应该用〈马戏团〉。军医院是看病的地方，老虎表演的应是〈马戏团〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条军医院的设备是部队出钱买的。", "corrected_sentence": "这所军医院的设备是部队出钱买的。", "error_description": "错误：“这条军医院”；正确：“这所军医院”。“条”用于细长的东西，医院应用“所”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那颗军医院的医生今年换了一批。", "corrected_sentence": "那所军医院的医生今年换了一批。", "error_description": "错误：“那颗军医院”；正确：“那所军医院”。“颗”用于小而圆的东西，医院应用“所”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
