INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89209, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大部分是这样，只有一点点不一样。", "primary_collocate": null, "pronunciation": "jī běn shàng", "ipa": "tɕi˥ pən˨˩ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这些菜基本上都是我做的。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里的同学基本上都来了。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话基本上是对的。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业基本上写完了，还差一道题。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间基本上收拾好了。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我基本上看完了。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子基本上一样高。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的想法基本上一样。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的东西基本上都很新鲜。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事基本上办好了。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "大部分如此，仅有少许例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本上", "is_correct": true, "explanation": "正确：“基本上”表示大部分如此，与“都是我做的”搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时、不常，与“都”所表示的全部相抵触。"}, {"text": "稍微", "is_correct": false, "explanation": "搭配：“稍微”表示程度轻微，不能修饰“都是我做的”这种全称判断。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示义务或需要，不能用来陈述已经发生的事实。"}], "explanations": {"基本上": "正确：“基本上”表示大部分如此，与“都是我做的”搭配。", "偶尔": "语义：“偶尔”表示有时、不常，与“都”所表示的全部相抵触。", "稍微": "搭配：“稍微”表示程度轻微，不能修饰“都是我做的”这种全称判断。", "必须": "语义：“必须”表示义务或需要，不能用来陈述已经发生的事实。"}, "sentence_index": 0, "correct_answer": "基本上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他基本上结婚了。", "explanation": "这里应该用〈已经〉。“基本上”表示大部分如此，适用于可以分程度的情况；结婚是非此即彼的事实，已经发生要用“已经”。"}, {"text": "我基本上今年二十岁。", "explanation": "这里应该去掉“基本上”。“基本上”表示大部分如此，年龄是一个确定的数字，不能分程度。"}, {"text": "他基本上是我的哥哥。", "explanation": "这里应该去掉“基本上”。“基本上”表示大部分如此，亲属关系是非此即彼的事实，不能说“大部分是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本上", "is_correct": true, "explanation": "正确：“基本上”表示大部分如此，与“两个孩子一样高”的近似关系相符。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”表示持续变化，与“一样高”这种稳定的状态相抵触。"}, {"text": "分别", "is_correct": false, "explanation": "语义：“分别”表示各自、逐一，“两个孩子分别一样高”无法成立。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或程度结构，不能修饰“一样”。"}], "explanations": {"基本上": "正确：“基本上”表示大部分如此，与“两个孩子一样高”的近似关系相符。", "不断": "语义：“不断”表示持续变化，与“一样高”这种稳定的状态相抵触。", "分别": "语义：“分别”表示各自、逐一，“两个孩子分别一样高”无法成立。", "十分": "搭配：“十分”修饰形容词或程度结构，不能修饰“一样”。"}, "sentence_index": 6, "correct_answer": "基本上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他基本上出生在北京。", "explanation": "这里应该用〈确实〉。“基本上”表示大部分如此，而出生地是确定的事实，应表示确定的意思。"}, {"text": "今天基本上是星期三。", "explanation": "这里应该去掉“基本上”。“基本上”表示大部分如此，今天是星期几是确定的事实，不能分程度。"}, {"text": "这件事基本上绝对是真的。", "explanation": "“基本上”表示大部分如此，与表示毫无例外的意思相抵触，这里应去掉“基本上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划很基本上都能按时完成。", "corrected_sentence": "这个计划基本上都能按时完成。", "error_description": "词语位置错误：“基本上”是副词，前面不能再加程度副词“很”，应说“这个计划基本上都能按时完成”，不能说“很基本上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事基本上的办完了。", "corrected_sentence": "这件事基本上办完了。", "error_description": "助词误加：“基本上”是副词，后面不能加“的”，应说“这件事基本上办完了”，不能说“基本上的办完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
