INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89210, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就主要方面或大体情况而言。", "primary_collocate": null, "pronunciation": "jī běn shàng", "ipa": "tɕi˥ pən˨˩ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "基本上，我同意你的看法。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划基本上没有问题。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的安排基本上合理。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基本上，这是一个很简单的问题。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的情况基本上稳定了。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行基本上让我满意。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法基本上是可行的。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章基本上写得不错。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作基本上做得很好。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的条件基本上能满足我们。", "target_word": "基本上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "就主要方面或大体情况来说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本上", "is_correct": true, "explanation": "正确：句首的“基本上”表示就主要方面而言，引出对看法的总体态度。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，同意对方的看法并不值得惊讶。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，不能说“根本，我同意”。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，与表达同意看法的语境不符。"}], "explanations": {"基本上": "正确：句首的“基本上”表示就主要方面而言，引出对看法的总体态度。", "竟然": "语义：“竟然”表示出乎意料，同意对方的看法并不值得惊讶。", "根本": "搭配：“根本”多与否定词连用，不能说“根本，我同意”。", "故意": "语义：“故意”表示有意为之，与表达同意看法的语境不符。"}, "sentence_index": 0, "correct_answer": "基本上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "基本上，他的第三个字写错了。", "explanation": "这里应该去掉“基本上”。“基本上”用于概括大体情况，不能用来指出某一个具体细节的错误。"}, {"text": "这个数字基本上是三，不是五。", "explanation": "这里应该用〈确切地〉。“基本上”表示大体情况，不能用来确定具体数字的对错；给出具体数字要用“确切地”。"}, {"text": "基本上，我的生日是三月五日。", "explanation": "这里应该去掉“基本上”。“基本上”用于概括大体情况，生日这类确定的事实不能用它来概括。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本上", "is_correct": true, "explanation": "正确：“基本上”表示就主要方面而言，对办法作总体评价。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词，不能放在“是……的”结构前，“十分是可行的”不成立。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”是连词，连接并列成分，不能在此作状语。"}, {"text": "由于", "is_correct": false, "explanation": "搭配：“由于”须引出原因分句，“这个办法由于是可行的”不成句。"}], "explanations": {"基本上": "正确：“基本上”表示就主要方面而言，对办法作总体评价。", "十分": "搭配：“十分”修饰形容词，不能放在“是……的”结构前，“十分是可行的”不成立。", "并且": "搭配：“并且”是连词，连接并列成分，不能在此作状语。", "由于": "搭配：“由于”须引出原因分句，“这个办法由于是可行的”不成句。"}, "sentence_index": 6, "correct_answer": "基本上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "基本上，火车八点整出发。", "explanation": "这里应该用〈正好〉。“基本上”用于概括大体情况，描述确切的时刻要用“正好”。"}, {"text": "基本上，我的名字叫李明。", "explanation": "这里应该用〈确实〉。“基本上”用于概括大体情况，说明姓名这类确定的事实要用“确实”。"}, {"text": "基本上，三加五等于八。", "explanation": "这里应该去掉“基本上”。“基本上”用于概括大体情况，算式结果是确定的，不需要概括。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案基本上地没有漏洞。", "corrected_sentence": "这个方案基本上没有漏洞。", "error_description": "助词误加：“基本上”本身就是副词，作状语时后面不加“地”，应说“基本上没有漏洞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的说法很基本上可信。", "corrected_sentence": "他的说法基本上可信。", "error_description": "程度副词错误：“基本上”是副词，前面不能加程度副词“很”，应说“他的说法基本上可信”，不能说“很基本上可信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
