INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89212, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89212, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词,表示如果不是上文所说的情况,就会出现另一种结果。", "primary_collocate": null, "pronunciation": "fǒu zé", "ipa": "foʊ̯˨˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "快走吧，否则我们要迟到了。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要多喝水，否则会生病。", "target_word": "否则", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请安静，否则别人睡不着。", "target_word": "否则", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你得带伞，否则衣服会湿。", "target_word": "否则", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出门前关好门，否则小偷会进来。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一定很忙，否则早就来了。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你把药吃了，否则病不会好。", "target_word": "否则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要认真听课，否则考试考不好。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带着地图出门了，否则一定会迷路。", "target_word": "否则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机要放好，否则很容易丢。", "target_word": "否则", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "否則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "如果不是上文所说的情况就会出现另一种结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db53ca1e-ed36-4d8f-b5e7-254742013a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，与“快走吧”的催促及后果不相符。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示顺承的因果，“快走吧”不能导致“迟到”。"}, {"text": "否则", "is_correct": true, "explanation": "“否则”引出“不这样就会”的后果，与“快走吧”和“迟到”的关系相符。"}, {"text": "只好", "is_correct": false, "explanation": "语法：“只好”是副词，后面需接动词，不能直接接“我们要迟到了”。"}], "explanations": {"然而": "语义：“然而”表示转折，与“快走吧”的催促及后果不相符。", "因此": "语义：“因此”表示顺承的因果，“快走吧”不能导致“迟到”。", "否则": "“否则”引出“不这样就会”的后果，与“快走吧”和“迟到”的关系相符。", "只好": "语法：“只好”是副词，后面需接动词，不能直接接“我们要迟到了”。"}, "sentence_index": 0, "correct_answer": "否则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很聪明，否则很努力。", "explanation": "这里应该用〈而且〉。否则表示“不这样就会”的后果，用于假设，不能表示并列。"}, {"text": "他很用功，否则考了高分。", "explanation": "这里应该用〈结果〉。否则只引出与前文相反的假设后果，不能引出实际发生的好结果。"}, {"text": "他迟到了，否则堵车。", "explanation": "这里应该用〈因为〉。否则只引出假设性的后果，不能引出原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "搭配：“因为”要引出原因，后句“病不会好”是结果，不能用“因为”连接。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“吃药”与“病不会好”之间不构成这种因果关系。"}, {"text": "否则", "is_correct": true, "explanation": "“否则”引出“不这样就会”的后果，与“吃药”和“病不会好”的假设关系相符。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示顺承的动作结果，不能表示“吃药导致病不好”。"}], "explanations": {"因为": "搭配：“因为”要引出原因，后句“病不会好”是结果，不能用“因为”连接。", "所以": "语义：“所以”表示因果，“吃药”与“病不会好”之间不构成这种因果关系。", "否则": "“否则”引出“不这样就会”的后果，与“吃药”和“病不会好”的假设关系相符。", "于是": "语义：“于是”表示顺承的动作结果，不能表示“吃药导致病不好”。"}, "sentence_index": 6, "correct_answer": "否则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他洗完澡，否则睡觉了。", "explanation": "这里应该用〈然后〉。否则表示“不这样就会”，不能表示动作的先后顺序。"}, {"text": "我们去了北京，否则也去了上海。", "explanation": "这里应该用〈另外〉。否则不能表示在已有行动之外再增加一件事。"}, {"text": "我在做饭，否则在打电话。", "explanation": "这里应该用〈同时〉。否则只引出假设性的另一种结果，不能表示两件事同时进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你早点睡，否则了明天没有精神。", "corrected_sentence": "你早点睡，否则明天没有精神。", "error_description": "错误：“否则”后面加了“了”。正确：“否则”是连词，后面不带“了”，应为“否则明天没有精神”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你要注意安全，你否则会受伤。", "corrected_sentence": "你要注意安全，否则会受伤。", "error_description": "错误：“你否则会受伤”。正确：“否则”是连词，应放在后一分句句首，不能放在主语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
