INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89213, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "服用是把药吃进肚子里。", "primary_collocate": null, "pronunciation": "fú yòng", "ipa": "fu˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种药要饭后服用。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上服用一片药。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧了，医生让他服用退烧药。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服用这种药以后，我有点想睡觉。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药不能和酒一起服用。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天服用三次药。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经服用了两天感冒药。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你服用过这种药吗？", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服用药物前，请先看说明书。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人按时服用了医生开的药。", "target_word": "服用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服用了", "label": "体标"}, {"form": "服用过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "把药吃下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '790811c9-6e97-424f-b6aa-eb7a3bd287ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "涂", "is_correct": false, "explanation": "语义：“涂”是外用，药不能饭后涂。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是用水去掉脏东西，药不能“饭后洗”，句子读不通。"}, {"text": "服用", "is_correct": true, "explanation": "正确。“服用”指把药吃下去，符合“要饭后”的用药语境。"}, {"text": "浸泡", "is_correct": false, "explanation": "搭配：“浸泡”的对象一般是泡在液体里的物体，不能说“饭后浸泡这种药”。"}], "explanations": {"涂": "语义：“涂”是外用，药不能饭后涂。", "洗": "语义：“洗”是用水去掉脏东西，药不能“饭后洗”，句子读不通。", "服用": "正确。“服用”指把药吃下去，符合“要饭后”的用药语境。", "浸泡": "搭配：“浸泡”的对象一般是泡在液体里的物体，不能说“饭后浸泡这种药”。"}, "sentence_index": 0, "correct_answer": "服用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天服用了很多饺子。", "explanation": "这里应该用〈吃〉。服用只用于药物或保健品，饺子要用〈吃〉。"}, {"text": "他每天早上服用一杯牛奶。", "explanation": "这里应该用〈喝〉。服用只用于药物或保健品，牛奶要用〈喝〉。"}, {"text": "护士给他服用了一针。", "explanation": "这里应该用〈注射〉。服用指口服，给人打针要用〈注射〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闻", "is_correct": false, "explanation": "语义：“闻”是用鼻子感知气味，不表示把药吃下去。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”是用手轻击，不表示把药吃下去，句子读不通。"}, {"text": "服用", "is_correct": true, "explanation": "正确。“服用”表示把药吃下去，符合“两天感冒药”的语境。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”是用手碰，不表示把药吃进去。"}], "explanations": {"闻": "语义：“闻”是用鼻子感知气味，不表示把药吃下去。", "拍": "语义：“拍”是用手轻击，不表示把药吃下去，句子读不通。", "服用": "正确。“服用”表示把药吃下去，符合“两天感冒药”的语境。", "摸": "语义：“摸”是用手碰，不表示把药吃进去。"}, "sentence_index": 6, "correct_answer": "服用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我服用了药膏。", "explanation": "这里应该用〈涂〉。药膏是外用的，要用〈涂〉；服用只用于口服的药物。"}, {"text": "他把鱼刺服用了下去。", "explanation": "这里应该用〈吞〉。服用指口服药物或保健品，鱼刺不能服用，应该用〈吞〉。"}, {"text": "我早饭服用了一碗面。", "explanation": "这里应该用〈吃〉。服用只用于药物或保健品，面条要用〈吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天服用过一次药。", "corrected_sentence": "他每天服用一次药。", "error_description": "“过”用错了：“每天”表示习惯性的重复动作，不用“过”，应写作“他每天服用一次药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病人正在服用过医生开的药。", "corrected_sentence": "病人正在服用医生开的药。", "error_description": "“过”用错了：“正在”表示动作正在进行，不能和表示经历的“过”一起用，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
