INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89215, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "迄今是从那时候一直到现在。", "primary_collocate": null, "pronunciation": "qì jīn", "ipa": "tɕʰi˥˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "他十年前搬到北京，迄今还住在那里。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迄今为止，这家店已经开了二十年。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写于一九九〇年，迄今仍有人读。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们认识十年了，迄今没有吵过架。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十岁学画画，迄今没有放弃。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件事发生在去年，他迄今不愿提起。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥建于一百年前，迄今还很结实。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李二十岁来到这个城市，迄今没回过老家。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱踢球，迄今还每天练习。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那首歌是二十年前的，迄今我还记得。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "迄今：从过去某时一直持续到现在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迄今", "is_correct": true, "explanation": "正确。「迄今」表示从过去一直到现在，符合句子的意思。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示立刻，与「十年前搬到北京」矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」指不久前，与「十年前」的时间说法矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：「从来」多用于否定句，与「还住在那里」不搭配。"}], "explanations": {"迄今": "正确。「迄今」表示从过去一直到现在，符合句子的意思。", "马上": "语义：「马上」表示立刻，与「十年前搬到北京」矛盾。", "刚刚": "语义：「刚刚」指不久前，与「十年前」的时间说法矛盾。", "从来": "搭配：「从来」多用于否定句，与「还住在那里」不搭配。"}, "sentence_index": 0, "correct_answer": "迄今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天迄今去了学校。", "explanation": "迄今表示从过去一直延续到现在，不能与「昨天」这样的具体过去时间点搭配来说一次已经结束的动作。应去掉「迄今」，说「他昨天去了学校」。"}, {"text": "他迄今将要出国留学。", "explanation": "这里应该用〈以后〉。迄今只指到现在为止，不能与「将要」这样的将来时搭配。"}, {"text": "我接到电话，迄今立刻就出门了。", "explanation": "这里应该用〈当即〉。迄今表示从过去一直延续到现在，不能用来说接到电话后马上完成的一次动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迄今", "is_correct": true, "explanation": "正确。「迄今」表示截至现在仍然如此，符合句子的意思。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然，与「还很结实」这种持续状态不相符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：「曾经」指过去有过，与「还很结实」表示现在仍然如此相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：「偶尔」表示不经常，不能修饰「很结实」这种持续的状态。"}], "explanations": {"迄今": "正确。「迄今」表示截至现在仍然如此，符合句子的意思。", "忽然": "语义：「忽然」表示突然，与「还很结实」这种持续状态不相符。", "曾经": "语义：「曾经」指过去有过，与「还很结实」表示现在仍然如此相矛盾。", "偶尔": "搭配：「偶尔」表示不经常，不能修饰「很结实」这种持续的状态。"}, "sentence_index": 6, "correct_answer": "迄今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那首歌是二十年前的，迄今我将会忘记。", "explanation": "这里应该用〈以后〉。迄今只指到现在为止，不能与「将会」这样的将来时搭配。"}, {"text": "那首歌是二十年前的，我昨天迄今还记得。", "explanation": "迄今表示一直延续到现在，不能与「昨天」这样的具体过去时间点搭配。应去掉「昨天」，说「迄今我还记得」。"}, {"text": "那首歌是二十年前的，我一听见，迄今就马上跟着唱了。", "explanation": "这里应该用〈即刻〉。迄今表示从过去一直延续到现在，不能用来说听到歌后马上完成的一次动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个传统迄今了还被保留着。", "corrected_sentence": "这个传统迄今还被保留着。", "error_description": "错误形式：「迄今了还」。正确形式：「迄今还」。「迄今」是副词，后面不能加「了」，直接接「还」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他迄今了一直没有去那座城市。", "corrected_sentence": "他迄今一直没有去那座城市。", "error_description": "错误形式：「迄今了」。正确形式：「迄今」。「迄今」是副词，后面不能加「了」，直接修饰后面的「一直没有去那座城市」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
