INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89216, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "到现在为止。", "primary_collocate": null, "pronunciation": "qì jīn", "ipa": "tɕʰi˥˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "迄今为止，我去过五个国家。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迄今，这个问题还没有答案。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迄今为止，他是我见过最努力的学生。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是迄今最大的一场雪。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迄今我们已经卖出了一千本书。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迄今为止，公司一共有两百名员工。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，迄今还没有发现新的病例。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迄今最好的成绩是他去年跑出来的。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迄今为止，这是我吃过最辣的菜。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迄今，他一次也没有迟到过。", "target_word": "迄今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "迄今：到现在为止的范围或总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迄今", "is_correct": true, "explanation": "正确。「迄今为止」表示截至现在，符合句子的意思。"}, {"text": "一共", "is_correct": false, "explanation": "搭配：「一共」表示总计，不能放在「为止」之前组成表示截至时间的固定说法。"}, {"text": "已经", "is_correct": false, "explanation": "语义：「已经」表示事情已经完成，不表示截至现在的范围，与「为止」不搭。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：「曾经」指过去有过，不表示一直到现在的范围。"}], "explanations": {"迄今": "正确。「迄今为止」表示截至现在，符合句子的意思。", "一共": "搭配：「一共」表示总计，不能放在「为止」之前组成表示截至时间的固定说法。", "已经": "语义：「已经」表示事情已经完成，不表示截至现在的范围，与「为止」不搭。", "曾经": "语义：「曾经」指过去有过，不表示一直到现在的范围。"}, "sentence_index": 0, "correct_answer": "迄今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明年迄今会下一场最大的雪。", "explanation": "这里应该用〈到明年〉这类将来的说法。迄今只指到现在为止，不能与「明年会」这样的将来时搭配。"}, {"text": "我昨天迄今看到了这场雪。", "explanation": "迄今表示一直延续到现在，不能与「昨天」这样的具体过去时间点搭配来说一次动作。应去掉「迄今」，说「我昨天看到了这场雪」。"}, {"text": "这场雪很大，请你迄今把它扫干净。", "explanation": "这里应该用〈从现在起〉。迄今只指从过去到现在为止，不能用来对将来提出要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迄今", "is_correct": true, "explanation": "正确。「迄今」表示截至现在仍未发生，符合句子的意思。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示立刻，与「还没有发现」的持续状态不相符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然，与「还没有发现新的病例」的说法不搭。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：「偶尔」表示不经常，不能修饰「还没有发现」这种持续否定的状态。"}], "explanations": {"迄今": "正确。「迄今」表示截至现在仍未发生，符合句子的意思。", "马上": "语义：「马上」表示立刻，与「还没有发现」的持续状态不相符。", "忽然": "语义：「忽然」表示突然，与「还没有发现新的病例」的说法不搭。", "偶尔": "搭配：「偶尔」表示不经常，不能修饰「还没有发现」这种持续否定的状态。"}, "sentence_index": 6, "correct_answer": "迄今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天迄今一次也没有迟到过。", "explanation": "迄今表示到现在为止的整段时间，不能与「昨天」这样的某一天搭配。应去掉「昨天」，说「他迄今一次也没有迟到过」。"}, {"text": "迄今，他明天一次也没有迟到过。", "explanation": "这里应该用〈以后〉。迄今只指到现在为止，不能与「明天」这样的将来时搭配。"}, {"text": "迄今，他答应下周一次也不迟到。", "explanation": "这里应该用〈从今以后〉。迄今只指到现在为止，不能用来表示对将来的承诺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "迄今了为止，我们班一共有十个人报名。", "corrected_sentence": "迄今为止，我们班一共有十个人报名。", "error_description": "错误形式：「迄今了为止」。正确形式：「迄今为止」。「迄今为止」是固定说法，「了」不能插在「迄今」和「为止」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他迄今了一次也没有迟到过。", "corrected_sentence": "他迄今一次也没有迟到过。", "error_description": "错误形式：「迄今了」。正确形式：「迄今」。「迄今」是副词，后面不能加「了」，直接修饰后面的「一次也没有迟到过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
