INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89217, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有很多个国家在一起的。", "primary_collocate": null, "pronunciation": "duō guó", "ipa": "tuo˥ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "这个多国代表团今天到达了北京。", "target_word": "多国", "complexity_tier": "T3", "furigana": "duō guó", "sentence_source": "generated"}, {"text": "这是一支多国队伍，队员来自十个国家。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有一个多国学生班。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多国团队里有中国人，也有法国人。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多国游客坐着同一辆车去看长城。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多国合唱团今晚在公园里唱歌。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多国救援队连夜赶到了地震现场。", "target_word": "多国", "complexity_tier": "T3", "furigana": "duō guó", "sentence_source": "generated"}, {"text": "多国志愿者一起住在这个小楼里。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多国小朋友在一起玩，说着不同的话。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想参加那个多国夏令营，认识各国朋友。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多國", "label": "繁体"}, {"form": "多国部队", "label": "复合"}, {"form": "多国联军", "label": "复合"}], "register": "书面语", "sense_fingerprint": "多个国家的人或队伍聚在一起的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6df07d-0870-46ca-9127-847b9f9f2ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89217, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多国", "is_correct": true, "explanation": "多国（duō guó）指由多个国家的人或团体组成，是本题的正确答案。"}, {"text": "躲过", "is_correct": false, "explanation": "躲过（duǒ guò）与多国（duō guó）两个音节的声调都不同，意思是避开。"}, {"text": "夺过", "is_correct": false, "explanation": "夺过（duó guò）与多国（duō guó）两个音节的声调都不同，意思是抢过来。"}, {"text": "剁过", "is_correct": false, "explanation": "剁过（duò guò）与多国（duō guó）两个音节的声调都不同，意思是用刀切过。"}], "explanations": {"多国": "多国（duō guó）指由多个国家的人或团体组成，是本题的正确答案。", "躲过": "躲过（duǒ guò）与多国（duō guó）两个音节的声调都不同，意思是避开。", "夺过": "夺过（duó guò）与多国（duō guó）两个音节的声调都不同，意思是抢过来。", "剁过": "剁过（duò guò）与多国（duō guó）两个音节的声调都不同，意思是用刀切过。"}, "sentence_index": null, "correct_answer": "多国"}, "level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "“这个多国代表团”指由多个国家的人组成的代表团，符合语境。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容身高，不能修饰代表团，句子不通。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”形容速度，修饰代表团与“今天到达北京”的语义不合。"}, {"text": "红", "is_correct": false, "explanation": "体貌：“红”形容颜色，不能修饰代表团。"}], "explanations": {"多国": "“这个多国代表团”指由多个国家的人组成的代表团，符合语境。", "高": "体貌：“高”形容身高，不能修饰代表团，句子不通。", "慢": "语义：“慢”形容速度，修饰代表团与“今天到达北京”的语义不合。", "红": "体貌：“红”形容颜色，不能修饰代表团。"}, "sentence_index": 0, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支多国队伍的队员都来自法国。", "explanation": "这里应该用〈外国〉。队员都来自一个国家时要说外国，多国指由多个国家的人组成。"}, {"text": "这个多国代表团全是北京人。", "explanation": "这里应该用〈国内〉。成员全来自北京的团队属于国内，多国只用于多个国家组成的团体。"}, {"text": "这里的多国天气很好。", "explanation": "这里是把“多国”误当成“多样”的意思。“多国”只指由多个国家组成的人或团体，不能修饰天气这类自然现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "“多国救援队连夜赶到了地震现场”中的“多国”指多个国家组成，符合语境。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容体型，不能修饰救援队。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”与“连夜赶到”的积极行动相矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能修饰救援队。"}], "explanations": {"多国": "“多国救援队连夜赶到了地震现场”中的“多国”指多个国家组成，符合语境。", "胖": "体貌：“胖”形容体型，不能修饰救援队。", "懒": "语义：“懒”与“连夜赶到”的积极行动相矛盾。", "甜": "语义：“甜”形容味道，不能修饰救援队。"}, "sentence_index": 6, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次多国夏令营只有中国学生参加。", "explanation": "这里应该用〈本国〉。只有一个国家的学生参加的夏令营要说本国，多国指多个国家共同组成。"}, {"text": "这个多国学生班的学生全是中国人。", "explanation": "这里应该用〈本国〉。学生全都是中国人，属于本国，多国指由多个国家的人组成的群体。"}, {"text": "这个多国学生只来自北京。", "explanation": "这里应该用〈本地〉。只来自北京的学生属于本地，多国指由多个国家的人组成的群体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很多国代表团。", "corrected_sentence": "这是一个多国代表团。", "error_description": "错误：“很多国代表团”。正确：“多国代表团”。“多国”是非等级形容词，不能被副词“很”修饰，应删去“很”，直接作定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支很多国救援队连夜赶到了现场。", "corrected_sentence": "这支多国救援队连夜赶到了现场。", "error_description": "错误：“很多国救援队”。正确：“多国救援队”。“多国”是非等级形容词，不能被副词“很”修饰，应直接作定语，删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
