INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "涉及或由多个国家组成的。", "primary_collocate": null, "pronunciation": "duō guó", "ipa": "tuo˥ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "这家多国合资企业在十个国家都有工厂。", "target_word": "多国", "complexity_tier": "T3", "furigana": "duō guó", "sentence_source": "generated"}, {"text": "多国会议下个星期在北京开。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个国家签了一份多国协议。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一部多国合拍的电影。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多国合作让这个研究很快做完了。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察和多国调查组一起查这件事。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多国项目需要很多钱和时间。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条多国铁路把五个国家连在了一起。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们参加了一次多国考察，去了三个国家。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多国基金由六个国家一起出钱。", "target_word": "多国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多國", "label": "繁体"}, {"form": "多国公司", "label": "复合"}, {"form": "多国会议", "label": "复合"}], "register": "书面语", "sense_fingerprint": "涉及多个国家或由多国组成的机构、事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6df07d-0870-46ca-9127-847b9f9f2ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多国", "is_correct": true, "explanation": "多国（duō guó）指涉及或由多个国家组成，是本题的正确答案。"}, {"text": "躲过", "is_correct": false, "explanation": "躲过（duǒ guò）与多国（duō guó）两个音节的声调都不同，意思是避开。"}, {"text": "夺过", "is_correct": false, "explanation": "夺过（duó guò）与多国（duō guó）两个音节的声调都不同，意思是抢过来。"}, {"text": "剁过", "is_correct": false, "explanation": "剁过（duò guò）与多国（duō guó）两个音节的声调都不同，意思是用刀切过。"}], "explanations": {"多国": "多国（duō guó）指涉及或由多个国家组成，是本题的正确答案。", "躲过": "躲过（duǒ guò）与多国（duō guó）两个音节的声调都不同，意思是避开。", "夺过": "夺过（duó guò）与多国（duō guó）两个音节的声调都不同，意思是抢过来。", "剁过": "剁过（duò guò）与多国（duō guó）两个音节的声调都不同，意思是用刀切过。"}, "sentence_index": null, "correct_answer": "多国"}, "level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "“这家多国合资企业”指由多个国家共同投资的企业，与“十个国家都有工厂”相符。"}, {"text": "本地", "is_correct": false, "explanation": "语义：“本地”指一个地方，与“在十个国家都有工厂”相矛盾。"}, {"text": "手工", "is_correct": false, "explanation": "搭配：“手工”修饰企业不合搭配，“手工”多用于手工业或手工制品。"}, {"text": "红色", "is_correct": false, "explanation": "体貌：“红色”描述颜色，不能修饰企业的性质。"}], "explanations": {"多国": "“这家多国合资企业”指由多个国家共同投资的企业，与“十个国家都有工厂”相符。", "本地": "语义：“本地”指一个地方，与“在十个国家都有工厂”相矛盾。", "手工": "搭配：“手工”修饰企业不合搭配，“手工”多用于手工业或手工制品。", "红色": "体貌：“红色”描述颜色，不能修饰企业的性质。"}, "sentence_index": 0, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一家多国工厂，由北京市政府单独投资。", "explanation": "这里应该用〈市属〉。由一个城市政府单独投资的企业要说市属，多国指多个国家共同参与的机构。"}, {"text": "这是我多国的事情，与别人无关。", "explanation": "这里应该用〈个人〉。只涉及一个人的事情要说个人，多国用于涉及多个国家的事务。"}, {"text": "这是一项多国政策，只在本省有效。", "explanation": "这里应该用〈地方〉。只在本省有效的政策属于地方政策，多国政策涉及多个国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多国", "is_correct": true, "explanation": "“这个多国项目”指涉及多个国家的项目，符合语境。"}, {"text": "免费", "is_correct": false, "explanation": "语义：“免费”与“需要很多钱”相矛盾。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能修饰项目。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”指没有内容，与“需要很多钱和时间”不符。"}], "explanations": {"多国": "“这个多国项目”指涉及多个国家的项目，符合语境。", "免费": "语义：“免费”与“需要很多钱”相矛盾。", "瘦": "体貌：“瘦”形容人或动物的身材，不能修饰项目。", "空": "语义：“空”指没有内容，与“需要很多钱和时间”不符。"}, "sentence_index": 6, "correct_answer": "多国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个多国项目，只由中国一个国家出资。", "explanation": "这里应该用〈国内〉。只由一个国家出资的项目属于国内，多国项目需要多个国家共同参与。"}, {"text": "这是一场多国比赛，只有中国的队伍参加。", "explanation": "这里应该用〈全国〉。只有中国队伍参加的比赛属于全国性比赛，多国比赛需要多个国家的队伍参加。"}, {"text": "这是一个多国协会，会员全都是中国人。", "explanation": "这里应该用〈本国〉。会员全都是中国人的协会属于本国，多国协会由多个国家的人组成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一次很多国合作。", "corrected_sentence": "这是一次多国合作。", "error_description": "错误：“很多国合作”。正确：“多国合作”。“多国”是非等级形容词，不能被副词“很”修饰，应删去“很”，直接作定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项很多国合作由三个国家一起完成。", "corrected_sentence": "这项多国合作由三个国家一起完成。", "error_description": "错误：“很多国合作”。正确：“多国合作”。“多国”是非等级形容词，不能被副词“很”修饰，应删去“很”，直接作定语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
