INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "概况是对一件事大概情况的简单说明。", "primary_collocate": null, "pronunciation": "gài kuàng", "ipa": "kai˥˩ kʰuaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师先给我们介绍了学校的概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在会上简单说了公司的概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的第一页是城市的概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这个项目的概况写在纸上。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游向游客介绍了这座山的概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会以前，大家先看了一下活动概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上有这家医院的概况和地址。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用五分钟讲完了国家的历史概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先了解一下这个城市的概况，再决定去不去。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告只写了工作概况，没有写细节。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "对事情大概情况的简单说明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89219, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概况", "is_correct": true, "explanation": "正确：“概况”指学校的大体情况，可以向别人介绍。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“介绍”说的是情况或信息，“钥匙”是物品，前后不搭。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“介绍”一般接情况、信息，不说“介绍学校的心情”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，学校没有脾气，句意不通。"}], "explanations": {"概况": "正确：“概况”指学校的大体情况，可以向别人介绍。", "钥匙": "语义：“介绍”说的是情况或信息，“钥匙”是物品，前后不搭。", "心情": "搭配：“介绍”一般接情况、信息，不说“介绍学校的心情”。", "脾气": "语义：“脾气”指人的性情，学校没有脾气，句意不通。"}, "sentence_index": 0, "correct_answer": "概况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天吃了一碗概况，很好吃。", "explanation": "这里应该用〈面条〉。概况是对情况的简单说明，不能吃，吃的东西要用面条等食物。"}, {"text": "他的概况很高，有一米九。", "explanation": "这里应该用〈个子〉。概况是对事情大概情况的说明，人的高矮要用个子。"}, {"text": "下雨了，我忘了带概况。", "explanation": "这里应该用〈雨伞〉。概况是书面或口头的说明，不是可以带着挡雨的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体貌", "is_correct": false, "explanation": "体貌：“体貌”只用来说人的外形，不能说医院的体貌。"}, {"text": "概况", "is_correct": true, "explanation": "正确：“概况”指医院的基本情况，和“地址”并列放在网站上很合适。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是病人个人的诊疗记录，不会在网站上公开列出。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏用的物品，与医院的基本信息无关。"}], "explanations": {"体貌": "体貌：“体貌”只用来说人的外形，不能说医院的体貌。", "概况": "正确：“概况”指医院的基本情况，和“地址”并列放在网站上很合适。", "病历": "语义：病历是病人个人的诊疗记录，不会在网站上公开列出。", "乐器": "语义：乐器是演奏用的物品，与医院的基本信息无关。"}, "sentence_index": 6, "correct_answer": "概况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士给病人量了一下概况。", "explanation": "这里应该用〈体温〉。概况是对情况的概括，不能用“量”来测，量的是体温。"}, {"text": "他的概况很开朗，大家都喜欢他。", "explanation": "这里应该用〈性格〉。概况指事物的大致情况，描述人的性格要用“性格”，不能说“概况很开朗”。"}, {"text": "他打了一个概况给妈妈，说了很久。", "explanation": "这里应该用〈电话〉。概况是书面的大致说明，不能说“打概况”，与人通话要说“打电话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请先看一只概况。", "corrected_sentence": "请先看一份概况。", "error_description": "错误：“看一只概况”，量词用错。正确：“看一份概况”。“只”多用于动物或成对的物品，“概况”是书面材料，要用“份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们给我们看了一只市场概况。", "corrected_sentence": "他们给我们看了一份市场概况。", "error_description": "错误：“一只市场概况”，量词用错。正确：“一份市场概况”。“只”多用于动物或成对的物品，“概况”是书面材料，要用“份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
