INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89220, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大体的情况，基本的状况。", "primary_collocate": null, "pronunciation": "gài kuàng", "ipa": "kai˥˩ kʰuaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "听了朋友的话，我知道了那里的概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病历上记录了病人的基本概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者报道了这次比赛的概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的生活概况和过去不一样了。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份表格显示了公司的收入概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对市场概况很清楚，所以生意做得好。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一个月调查，我们了解了学生的学习概况。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说了灾区的概况，没说具体数字。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只知道这件事的概况，不知道原因。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年这个地区的生产概况比去年好。", "target_word": "概况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物大体、基本的状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概况", "is_correct": true, "explanation": "正确：“概况”指那里的基本状况，听朋友说后了解到的正是这类情况。"}, {"text": "体貌", "is_correct": false, "explanation": "体貌：“体貌”只指人或动物的外形，不用来说一个地方。"}, {"text": "酒量", "is_correct": false, "explanation": "语义：“酒量”指一个人能喝多少酒，地方没有酒量，句意不通。"}, {"text": "心愿", "is_correct": false, "explanation": "语义：“心愿”是人的愿望，地方没有心愿，前后不呼应。"}], "explanations": {"概况": "正确：“概况”指那里的基本状况，听朋友说后了解到的正是这类情况。", "体貌": "体貌：“体貌”只指人或动物的外形，不用来说一个地方。", "酒量": "语义：“酒量”指一个人能喝多少酒，地方没有酒量，句意不通。", "心愿": "语义：“心愿”是人的愿望，地方没有心愿，前后不呼应。"}, "sentence_index": 0, "correct_answer": "概况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴了，想喝一杯概况。", "explanation": "这里应该用〈水〉。概况指大体的情况，不能喝，喝的东西要用水等饮料。"}, {"text": "他的概况很曲折，我们都很同情他。", "explanation": "这里应该用〈经历〉。概况是基本情况的概括，人生中的遭遇和起伏要用经历。"}, {"text": "这次比赛他取得了很大的概况，大家都很惊讶。", "explanation": "这里应该用〈成就〉。概况指基本的状况，不能说“取得很大的概况”，取得的成绩要用“成就”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人的身体温度，“学习体温”的说法不成立，句意不通。"}, {"text": "概况", "is_correct": true, "explanation": "正确：“概况”指学生学习的基本情况，经过调查后了解的正是这类情况。"}, {"text": "相貌", "is_correct": false, "explanation": "语义：“相貌”指人的外形，与学习情况无关，不能说“学习相貌”。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：“嗓音”指声音的质地，学习不能有嗓音，前后不呼应。"}], "explanations": {"体温": "语义：“体温”指人的身体温度，“学习体温”的说法不成立，句意不通。", "概况": "正确：“概况”指学生学习的基本情况，经过调查后了解的正是这类情况。", "相貌": "语义：“相貌”指人的外形，与学习情况无关，不能说“学习相貌”。", "嗓音": "语义：“嗓音”指声音的质地，学习不能有嗓音，前后不呼应。"}, "sentence_index": 6, "correct_answer": "概况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年这个地区的概况比去年增加了两万吨。", "explanation": "这里应该用〈产量〉。概况是情况的概括，不能用“增加两万吨”这样的数量来说明。"}, {"text": "这款电脑的概况上个月卖了三千台。", "explanation": "这里应该用〈销量〉。概况是对情况的概括，不能说“卖了三千台”，卖出的数量要用销量。"}, {"text": "他的概况比去年长高了五厘米。", "explanation": "这里应该用〈身高〉。概况指大体的情况，不能说“长高了五厘米”，身高的变化要用身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对市场概况们很清楚。", "corrected_sentence": "他对市场概况很清楚。", "error_description": "错误：“概况们”。“概况”是抽象名词，不能加“们”。正确：“对市场概况很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经过一个月调查，我们了解了学生的学习很概况。", "corrected_sentence": "经过一个月调查，我们了解了学生的学习概况。", "error_description": "错误：“很概况”。“概况”是名词，不能受“很”修饰。正确：“学生的学习概况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
