INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89221, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "周是七天,从星期一到星期日。", "primary_collocate": null, "pronunciation": "zhōu", "ipa": "ʈʂoʊ˥", "syllable_count": 1, "sentences": [{"text": "这周我很忙,没有时间去玩。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下周我们要考试。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周我去了北京。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一周有七天,你知道吗?", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每周去公园跑步。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这周的天气很好。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说,这周要看完那本书。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上周的作业你做完了吗?", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈这周都在家里。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每周给奶奶打一个电话。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "週", "label": "繁体"}, {"form": "周末", "label": "复合"}], "register": "中性", "sense_fingerprint": "日历上的一周,从星期一到星期日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db53ca1e-ed36-4d8f-b5e7-254742013a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89221, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "周", "is_correct": true, "explanation": "周 zhōu（第一声）是本词，指星期，即七天。"}, {"text": "昼", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，昼是白天的意思。"}, {"text": "皱", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，皱是皱纹的意思。"}, {"text": "轴", "is_correct": false, "explanation": "zhóu（第二声）与 zhōu（第一声）声调不同，轴是车轴的意思。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 zhōu（第一声）声调不同，肘是手肘的意思。"}], "explanations": {"周": "周 zhōu（第一声）是本词，指星期，即七天。", "昼": "zhòu（第四声）与 zhōu（第一声）声调不同，昼是白天的意思。", "皱": "zhòu（第四声）与 zhōu（第一声）声调不同，皱是皱纹的意思。", "轴": "zhóu（第二声）与 zhōu（第一声）声调不同，轴是车轴的意思。", "肘": "zhǒu（第三声）与 zhōu（第一声）声调不同，肘是手肘的意思。"}, "sentence_index": null, "correct_answer": "周"}, "level_3": {"options": [{"text": "周", "is_correct": true, "explanation": "正确：「这周」指本星期，与句意“很忙、没有时间去玩”相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：「很忙」和「去玩」的主语只能是人，「这书我很忙」不成立。"}, {"text": "猫", "is_correct": false, "explanation": "语义：「这猫」不能作「我很忙、没有时间去玩」的叙述对象。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：「这房间」后不能接「我很忙、没有时间」这类时间叙述，「这」后应接时间词。"}], "explanations": {"周": "正确：「这周」指本星期，与句意“很忙、没有时间去玩”相符。", "书": "语义：「很忙」和「去玩」的主语只能是人，「这书我很忙」不成立。", "猫": "语义：「这猫」不能作「我很忙、没有时间去玩」的叙述对象。", "房间": "搭配：「这房间」后不能接「我很忙、没有时间」这类时间叙述，「这」后应接时间词。"}, "sentence_index": 0, "correct_answer": "周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了三周苹果。", "explanation": "这里应该用〈斤〉。「周」是七天的时间单位，不能作苹果的量词，称苹果要用〈斤〉。"}, {"text": "我每周早上七点起床，今天是这个周的星期几？", "explanation": "这里应该用〈星期〉。问今天是哪一天要说「今天星期几」，不说「这个周的星期几」。"}, {"text": "我们班有三十周学生。", "explanation": "这里应该用〈个〉。「周」是时间单位，不能作学生的量词，数人要用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89221, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "周", "is_correct": true, "explanation": "周 zhōu（第一声）是本词，指星期，即七天。"}, {"text": "抽", "is_correct": false, "explanation": "chōu 与 zhōu 只有声母不同（zh/ch），chōu 是抽烟、抽时间的意思。"}, {"text": "收", "is_correct": false, "explanation": "shōu 与 zhōu 只有声母不同（zh/sh），shōu 是收起、收获的意思。"}, {"text": "咒", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，咒是咒语、诅咒的意思。"}], "explanations": {"周": "周 zhōu（第一声）是本词，指星期，即七天。", "抽": "chōu 与 zhōu 只有声母不同（zh/ch），chōu 是抽烟、抽时间的意思。", "收": "shōu 与 zhōu 只有声母不同（zh/sh），shōu 是收起、收获的意思。", "咒": "zhòu（第四声）与 zhōu（第一声）声调不同，咒是咒语、诅咒的意思。"}, "sentence_index": null, "correct_answer": "周"}, "level_3": {"options": [{"text": "周", "is_correct": true, "explanation": "正确：「这周」指本星期，「这周要看完那本书」与句意相符。"}, {"text": "本子", "is_correct": false, "explanation": "语义：「看完那本书」要求读者作主语，「本子」不能读书，不能作主语。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：「看完那本书」的对象是书，「这饭」与「看完」不搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」不能作「要看完那本书」的主语，句意说的是人读书。"}], "explanations": {"周": "正确：「这周」指本星期，「这周要看完那本书」与句意相符。", "本子": "语义：「看完那本书」要求读者作主语，「本子」不能读书，不能作主语。", "饭": "搭配：「看完那本书」的对象是书，「这饭」与「看完」不搭配。", "桌子": "语义：「桌子」不能作「要看完那本书」的主语，句意说的是人读书。"}, "sentence_index": 6, "correct_answer": "周"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天是十月三十一周。", "explanation": "这里应该用〈号〉。「周」指一个星期，说日期要用「号」，「十月三十一周」不成立。"}, {"text": "他买了一周笔记本。", "explanation": "这里应该用〈本〉。「周」是时间单位，不能作笔记本的量词，买笔记本应说〈本〉。"}, {"text": "他做事很周。", "explanation": "这里应该用〈周到〉。「周」不能单独作形容词，形容做事细致应说「周到」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周这我们要去爬山。", "corrected_sentence": "这周我们要去爬山。", "error_description": "语序错误：指示词「这」要放在「周」前面，应说「这周」，不说「周这」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每周的去两次图书馆。", "corrected_sentence": "他们每周去两次图书馆。", "error_description": "多余的「的」：「每周」作状语修饰动词，中间不能加「的」，应说「每周去两次图书馆」，不说「每周的去两次图书馆」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
