INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "星期,七天的时间。", "primary_collocate": null, "pronunciation": "zhōu", "ipa": "ʈʂoʊ˥", "syllable_count": 1, "sentences": [{"text": "我在这家公司工作了三周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了两周,现在好了。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我看了一周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步,已经跑了三周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你等我一周,好吗?", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去海边玩了一周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药要吃两周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一周,他才回来。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学做饭学了四周。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行只有一周的时间。", "target_word": "周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "週", "label": "繁体"}, {"form": "一周", "label": "复合"}], "register": "中性", "sense_fingerprint": "连续七天的一段时间,用来计算时长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db53ca1e-ed36-4d8f-b5e7-254742013a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "周", "is_correct": true, "explanation": "周 zhōu（第一声）是本词，指星期，即连续七天的时间。"}, {"text": "抽", "is_correct": false, "explanation": "chōu 与 zhōu 只有声母不同（zh/ch），chōu 是抽烟、抽时间的意思。"}, {"text": "收", "is_correct": false, "explanation": "shōu 与 zhōu 只有声母不同（zh/sh），shōu 是收起、收获的意思。"}, {"text": "咒", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，咒是咒语、诅咒的意思。"}], "explanations": {"周": "周 zhōu（第一声）是本词，指星期，即连续七天的时间。", "抽": "chōu 与 zhōu 只有声母不同（zh/ch），chōu 是抽烟、抽时间的意思。", "收": "shōu 与 zhōu 只有声母不同（zh/sh），shōu 是收起、收获的意思。", "咒": "zhòu（第四声）与 zhōu（第一声）声调不同，咒是咒语、诅咒的意思。"}, "sentence_index": null, "correct_answer": "周"}, "level_3": {"options": [{"text": "周", "is_correct": true, "explanation": "正确：「三周」表示三个星期的时段，与「工作了」的时长相符。"}, {"text": "顿", "is_correct": false, "explanation": "语义：「顿」用于饭食或训斥，「工作了三顿」不能表示时长。"}, {"text": "节", "is_correct": false, "explanation": "搭配：「节」多与「课」等搭配，「工作了三节」不能表示时长。"}, {"text": "人", "is_correct": false, "explanation": "搭配：「工作了三人」说的是人数，不是时长，与「工作了」不搭配。"}], "explanations": {"周": "正确：「三周」表示三个星期的时段，与「工作了」的时长相符。", "顿": "语义：「顿」用于饭食或训斥，「工作了三顿」不能表示时长。", "节": "搭配：「节」多与「课」等搭配，「工作了三节」不能表示时长。", "人": "搭配：「工作了三人」说的是人数，不是时长，与「工作了」不搭配。"}, "sentence_index": 0, "correct_answer": "周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天是三周。", "explanation": "这里应该用〈星期三〉。「三周」指三个星期的时长，说今天是哪一天要用「星期三」。"}, {"text": "我们班买了三周粉笔。", "explanation": "这里应该用〈盒〉。「周」是时间单位，不能作粉笔的量词，称粉笔应说〈盒〉。"}, {"text": "他的安排很周。", "explanation": "这里应该用〈周到〉。「周」不能单独作形容词，形容安排细致应说「周到」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "周", "is_correct": true, "explanation": "周 zhōu（第一声）是本词，指星期，即连续七天的时间。"}, {"text": "昼", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，昼是白天的意思。"}, {"text": "皱", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，皱是皱纹的意思。"}, {"text": "轴", "is_correct": false, "explanation": "zhóu（第二声）与 zhōu（第一声）声调不同，轴是车轴的意思。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 zhōu（第一声）声调不同，肘是手肘的意思。"}], "explanations": {"周": "周 zhōu（第一声）是本词，指星期，即连续七天的时间。", "昼": "zhòu（第四声）与 zhōu（第一声）声调不同，昼是白天的意思。", "皱": "zhòu（第四声）与 zhōu（第一声）声调不同，皱是皱纹的意思。", "轴": "zhóu（第二声）与 zhōu（第一声）声调不同，轴是车轴的意思。", "肘": "zhǒu（第三声）与 zhōu（第一声）声调不同，肘是手肘的意思。"}, "sentence_index": null, "correct_answer": "周"}, "level_3": {"options": [{"text": "周", "is_correct": true, "explanation": "正确：「两周」表示两个星期的时段，与「吃药」的时长相符。"}, {"text": "张", "is_correct": false, "explanation": "语义：「张」用于纸、床等扁平物，不能作「吃」的计量，「这个药要吃两张」不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」不能被「吃」，「这个药要吃两桌子」不成立。"}, {"text": "杯", "is_correct": false, "explanation": "搭配：「吃」不与「杯」搭配，「两杯」多用于饮品，与「这个药」不合。"}], "explanations": {"周": "正确：「两周」表示两个星期的时段，与「吃药」的时长相符。", "张": "语义：「张」用于纸、床等扁平物，不能作「吃」的计量，「这个药要吃两张」不成立。", "桌子": "语义：「桌子」不能被「吃」，「这个药要吃两桌子」不成立。", "杯": "搭配：「吃」不与「杯」搭配，「两杯」多用于饮品，与「这个药」不合。"}, "sentence_index": 6, "correct_answer": "周"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去过三周这个城市。", "explanation": "这里应该用〈次〉。「周」表示七天的时长，计算去过几次要用〈次〉，不能用「周」。"}, {"text": "这次旅行只有一周小时的时间。", "explanation": "这里应该用〈一个小时〉。「周」表示七天，不能与「小时」这样的小单位搭配。"}, {"text": "他每天睡一周觉。", "explanation": "这里应该用〈八个小时〉之类的时长。「一周」是七天，不可能在一天里睡一周。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹学了三个周钢琴。", "corrected_sentence": "妹妹学了三周钢琴。", "error_description": "量词错误：表示时段的「周」前不加量词「个」，应说「学了三周钢琴」，不说「学了三个周钢琴」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在北京住了的两周。", "corrected_sentence": "我在北京住了两周。", "error_description": "多余的「的」：「住了两周」是动词加时段补语，中间不能插入「的」，应说「住了两周」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89223, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远因", "is_correct": true, "explanation": "远因：与近因相对，指离结果较远、较早发生的原因。"}, {"text": "河流", "is_correct": false, "explanation": "河流：与近因没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子：与近因没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园：与近因没有反义关系。"}], "correct_answer": "远因", "explanations": {"远因": "远因：与近因相对，指离结果较远、较早发生的原因。", "河流": "河流：与近因没有反义关系。", "桌子": "桌子：与近因没有反义关系。", "花园": "花园：与近因没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89223, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远因", "is_correct": true, "explanation": "远因：与近因相对，指离结果较远、较早发生的原因。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户：与近因没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "书包：与近因没有反义关系。"}, {"text": "草地", "is_correct": false, "explanation": "草地：与近因没有反义关系。"}], "correct_answer": "远因", "explanations": {"远因": "远因：与近因相对，指离结果较远、较早发生的原因。", "窗户": "窗户：与近因没有反义关系。", "书包": "书包：与近因没有反义关系。", "草地": "草地：与近因没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89223, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "近因是离这件事最近的那个原因。", "primary_collocate": null, "pronunciation": "jìn yīn", "ipa": "tɕin˥˩ in˥", "syllable_count": 2, "sentences": [{"text": "这次事故的近因是司机太累了。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争的远因很复杂，近因却很简单。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，火灾的近因是电线坏了。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司关门的近因是没有钱了。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的近因，你得先弄清楚。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病的近因是昨天淋了雨。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，近因是球员受伤了。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生找到了这次发烧的近因。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭的近因是玩具坏了。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查人员认为，这起车祸的近因是路面结冰。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远因", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "离结果最近的原因，与远因相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近因", "is_correct": true, "explanation": "正确：近因指直接引起结果的原因，与后文「司机太累了」相符。"}, {"text": "地点", "is_correct": false, "explanation": "语义：「地点」是位置，不能作为事故的原因，「司机太累了」也说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」是钱数，不能作为事故的原因，「这次事故的价格是司机太累了」句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不能直接说成事故的原因，与「司机太累了」的因果关系对不上。"}], "explanations": {"近因": "正确：近因指直接引起结果的原因，与后文「司机太累了」相符。", "地点": "语义：「地点」是位置，不能作为事故的原因，「司机太累了」也说不通。", "价格": "语义：「价格」是钱数，不能作为事故的原因，「这次事故的价格是司机太累了」句意不通。", "天气": "语义：「天气」不能直接说成事故的原因，与「司机太累了」的因果关系对不上。"}, "sentence_index": 0, "correct_answer": "近因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故的近因是三十年前签下的一份合同。", "explanation": "此处应该用〈远因〉。远因指较早发生、离结果较远的原因；三十年前的合同与事故相隔太久，不能用近因。"}, {"text": "这次事故的近因是三人受伤。", "explanation": "此处应该用〈结果〉。近因指引起事故的原因，三人受伤是事故造成的后果，不能用近因来指。"}, {"text": "他发烧的近因是咳嗽和流鼻涕。", "explanation": "此处应该用〈症状〉。症状指疾病表现出来的状况；咳嗽和流鼻涕是发烧时的表现，不是引起发烧的原因，近因不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近因", "is_correct": true, "explanation": "正确：近因指直接引起结果的原因，与「球员受伤了」形成前因后果。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是事物的色彩，不能导致比赛输掉，句中的因果说不通。"}, {"text": "猫腻", "is_correct": false, "explanation": "语域：「猫腻」是口语俚语，指暗中的花招，与书面语的「近因」语域不符，句意也不合。"}, {"text": "名字", "is_correct": false, "explanation": "语义：「名字」不会造成球员受伤，句中的原因关系说不通。"}], "explanations": {"近因": "正确：近因指直接引起结果的原因，与「球员受伤了」形成前因后果。", "颜色": "语义：「颜色」是事物的色彩，不能导致比赛输掉，句中的因果说不通。", "猫腻": "语域：「猫腻」是口语俚语，指暗中的花招，与书面语的「近因」语域不符，句意也不合。", "名字": "语义：「名字」不会造成球员受伤，句中的原因关系说不通。"}, "sentence_index": 6, "correct_answer": "近因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场灾难的近因是多年前埋下的腐败。", "explanation": "此处应该用〈祸根〉。祸根指长期埋下的根源；近因指离结果最近的原因，多年前的腐败离灾难很远。"}, {"text": "他的老毛病的近因是二十年前的一次摔伤。", "explanation": "此处应该用〈病根〉。病根指长期存在的根本原因；二十年前的摔伤离现在的老毛病很远，近因指离结果最近的原因，不能用于此。"}, {"text": "这场矛盾的近因是十年前积累的怨气。", "explanation": "此处应该用〈根源〉。根源指事物的根本来源；「十年前积累」说明它离矛盾爆发很远，近因指离结果最近的原因，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "专家找到了这次事故的一张近因：司机太累了。", "corrected_sentence": "专家找到了这次事故的一个近因：司机太累了。", "error_description": "量词错误：近因是抽象名词，应用量词「个」。「张」用于纸、桌子等平面的东西，错误形式是「一张近因」，正确形式是「一个近因」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生认为，这次感冒的一张近因是没有穿外套。", "corrected_sentence": "医生认为，这次感冒的一个近因是没有穿外套。", "error_description": "量词错误：近因应用量词「个」。「张」用于纸、桌子等平面的东西，错误形式是「一张近因」，正确形式是「一个近因」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89224, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远因", "is_correct": true, "explanation": "远因：与近因相对，指离结果较远、较早发生的原因。"}, {"text": "湖泊", "is_correct": false, "explanation": "湖泊：与近因没有反义关系。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子：与近因没有反义关系。"}, {"text": "果园", "is_correct": false, "explanation": "果园：与近因没有反义关系。"}], "correct_answer": "远因", "explanations": {"远因": "远因：与近因相对，指离结果较远、较早发生的原因。", "湖泊": "湖泊：与近因没有反义关系。", "椅子": "椅子：与近因没有反义关系。", "果园": "果园：与近因没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89224, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远因", "is_correct": true, "explanation": "远因：与近因相对，指离结果较远、较早发生的原因。"}, {"text": "窗帘", "is_correct": false, "explanation": "窗帘：与近因没有反义关系。"}, {"text": "钢笔", "is_correct": false, "explanation": "钢笔：与近因没有反义关系。"}, {"text": "操场", "is_correct": false, "explanation": "操场：与近因没有反义关系。"}], "correct_answer": "远因", "explanations": {"远因": "远因：与近因相对，指离结果较远、较早发生的原因。", "窗帘": "窗帘：与近因没有反义关系。", "钢笔": "钢笔：与近因没有反义关系。", "操场": "操场：与近因没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "直接引起某一结果的、时间上最接近的原因。", "primary_collocate": null, "pronunciation": "jìn yīn", "ipa": "tɕin˥˩ in˥", "syllable_count": 2, "sentences": [{"text": "这场病的近因是长时间没有休息。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书说，这场战争的近因是一次冲突。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水的远因是下雨多，近因是大坝坏了。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他辞职的近因是和经理吵了一架。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在找这次停电的近因。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的远因和近因都要写在作文里。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格上涨的近因是天气不好。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试不及格的近因是他没有复习。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车晚点的近因是下大雪了。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次车祸的近因比较容易查清。", "target_word": "近因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远因", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "直接引起结果、时间上最接近的原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近因", "is_correct": true, "explanation": "正确：近因指直接引起结果、时间上最接近的原因，与「长时间没有休息」相符。"}, {"text": "地点", "is_correct": false, "explanation": "语义：「地点」是位置，不能作为生病的原因，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」是钱数，不能作为生病的原因，「这场病的价格是长时间没有休息」句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不能引起生病，句中的因果关系说不通。"}], "explanations": {"近因": "正确：近因指直接引起结果、时间上最接近的原因，与「长时间没有休息」相符。", "地点": "语义：「地点」是位置，不能作为生病的原因，句意不通。", "价格": "语义：「价格」是钱数，不能作为生病的原因，「这场病的价格是长时间没有休息」句意不通。", "颜色": "语义：「颜色」不能引起生病，句中的因果关系说不通。"}, "sentence_index": 0, "correct_answer": "近因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他辞职的近因是三年前的一次培训。", "explanation": "此处应该用〈远因〉。远因指较早的原因；三年前的培训与辞职相隔很久，不能用近因。"}, {"text": "他辞职之后，生活陷入了困境，这正是他辞职的近因。", "explanation": "此处应该用〈后果〉。后果指事情发生之后产生的影响；生活陷入困境发生在辞职之后，是辞职的结果，不能用近因指辞职的原因。"}, {"text": "他最近总是咳嗽，这是肺炎的近因。", "explanation": "此处应该用〈症状〉。症状指疾病表现出来的状况；咳嗽是肺炎的表现，不是引起肺炎的原因，近因不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近因", "is_correct": true, "explanation": "正确：近因指直接引起结果的原因，与「天气不好」形成因果关系。"}, {"text": "时刻", "is_correct": false, "explanation": "语义：「时刻」是时间点，不能作为价格上涨的原因，句意不通。"}, {"text": "猫腻", "is_correct": false, "explanation": "语域：「猫腻」是口语俚语，指暗中的花招，与书面语的「近因」语域不符，句意也不合。"}, {"text": "名字", "is_correct": false, "explanation": "语义：「名字」不能导致价格上涨，句中的因果关系说不通。"}], "explanations": {"近因": "正确：近因指直接引起结果的原因，与「天气不好」形成因果关系。", "时刻": "语义：「时刻」是时间点，不能作为价格上涨的原因，句意不通。", "猫腻": "语域：「猫腻」是口语俚语，指暗中的花招，与书面语的「近因」语域不符，句意也不合。", "名字": "语义：「名字」不能导致价格上涨，句中的因果关系说不通。"}, "sentence_index": 6, "correct_answer": "近因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次洪灾的近因是多年前埋下的隐患。", "explanation": "此处应该用〈祸根〉。祸根指长期埋下的根源；近因指离结果最近的原因，多年前的隐患离洪灾很远。"}, {"text": "这种慢性病的近因是童年时的一场大病。", "explanation": "此处应该用〈病根〉。病根指长期存在的根本原因；童年时的大病离现在很远，近因指离结果最近的原因，不能用于此。"}, {"text": "这场矛盾的近因是两家公司多年前结下的旧怨。", "explanation": "此处应该用〈本源〉。本源指事物最初的来源；「多年前结下」说明它离矛盾爆发很远，近因指离结果最近的原因，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说这场病的一张近因是受凉。", "corrected_sentence": "医生说这场病的一个近因是受凉。", "error_description": "量词错误：近因是抽象名词，应用量词「个」。「张」用于纸、桌子等平面的东西，错误形式是「一张近因」，正确形式是「一个近因」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员正在查这次停电的一只近因。", "corrected_sentence": "工作人员正在查这次停电的一个近因。", "error_description": "量词错误：近因应用量词「个」。「只」多用于动物或成对物品中的一个，错误形式是「一只近因」，正确形式是「一个近因」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
