INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "太阳下山后，天黑了的那段时间。", "primary_collocate": null, "pronunciation": "yè", "ipa": "je˥˩", "syllable_count": 1, "sentences": [{"text": "太阳下山了，夜来了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，夜带来了凉风。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜深了，大家都回家了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳一下山，夜就慢慢黑下来了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜越来越深，路上的车也少了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜来了，小城里的灯一盏盏亮了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳落山后，夜的颜色越来越黑。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜到了，鸟都飞回树上睡觉了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜黑得看不见路，我打开了手电筒。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山后，夜静得只能听到风声。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夜晚", "label": "复合"}, {"form": "夜里", "label": "复合"}, {"form": "夜色", "label": "复合"}], "register": "中性", "sense_fingerprint": "夜|太阳下山后天黑的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89225, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夜", "is_correct": true, "explanation": "正确：夜 yè（第四声），指太阳下山后天黑的那段时间。"}, {"text": "野", "is_correct": false, "explanation": "野 yě（第三声）与 yè（第四声）声调不同，意思是“野外”。"}, {"text": "噎", "is_correct": false, "explanation": "噎 yē（第一声）与 yè（第四声）声调不同，意思是“食物堵住喉咙”。"}, {"text": "月", "is_correct": false, "explanation": "月 yuè 与 yè 的介音不同（ü 与 i），声调相同，意思是“月亮”。"}], "explanations": {"夜": "正确：夜 yè（第四声），指太阳下山后天黑的那段时间。", "野": "野 yě（第三声）与 yè（第四声）声调不同，意思是“野外”。", "噎": "噎 yē（第一声）与 yè（第四声）声调不同，意思是“食物堵住喉咙”。", "月": "月 yuè 与 yè 的介音不同（ü 与 i），声调相同，意思是“月亮”。"}, "sentence_index": null, "correct_answer": "夜"}, "level_3": {"options": [{"text": "夜", "is_correct": true, "explanation": "正确：夜，指太阳下山后天黑的时候，与“太阳下山了”相符。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”与“太阳下山”的时间语境冲突，日落时不会是春天来了。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”指中午的饭，与“太阳下山”的时间矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，与“太阳下山了”的时间语境无关，句子不通。"}], "explanations": {"夜": "正确：夜，指太阳下山后天黑的时候，与“太阳下山了”相符。", "春天": "语义：“春天”与“太阳下山”的时间语境冲突，日落时不会是春天来了。", "午饭": "语义：“午饭”指中午的饭，与“太阳下山”的时间矛盾。", "桌子": "语义：“桌子”是家具，与“太阳下山了”的时间语境无关，句子不通。"}, "sentence_index": 0, "correct_answer": "夜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天色已经很夜了，我们回家吧。", "explanation": "这里应该用〈晚〉。夜指一段时间，不能用来形容时间已经很迟，说“很晚了”才对。"}, {"text": "我们在夜出发去爬山。", "explanation": "这里应该用〈夜里〉。“在夜”不成立，表示时间要说“夜里”或“晚上”。"}, {"text": "我们夜七点就吃完了饭。", "explanation": "这里应该用〈晚上〉。说具体钟点要用“晚上七点”，“夜七点”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89225, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "夜", "is_correct": true, "explanation": "正确：夜 yè（第四声），指太阳下山后天黑的那段时间。"}, {"text": "也", "is_correct": false, "explanation": "也 yě（第三声）与 yè（第四声）声调不同，意思是“也”。"}, {"text": "椰", "is_correct": false, "explanation": "椰 yē（第一声）与 yè（第四声）声调不同，意思是“椰子”。"}, {"text": "爷", "is_correct": false, "explanation": "爷 yé（第二声）与 yè（第四声）声调不同，意思是“爷爷”。"}], "explanations": {"夜": "正确：夜 yè（第四声），指太阳下山后天黑的那段时间。", "也": "也 yě（第三声）与 yè（第四声）声调不同，意思是“也”。", "椰": "椰 yē（第一声）与 yè（第四声）声调不同，意思是“椰子”。", "爷": "爷 yé（第二声）与 yè（第四声）声调不同，意思是“爷爷”。"}, "sentence_index": null, "correct_answer": "夜"}, "level_3": {"options": [{"text": "夜", "is_correct": true, "explanation": "正确：夜，指太阳落山后天黑的时候，与“颜色越来越黑”相符。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：“早晨”指天亮之后，与“太阳落山后”的时间矛盾。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪是白色的，颜色不会越来越黑，与语境相反。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“颜色”多用于可见的事物，不说声音的颜色。"}], "explanations": {"夜": "正确：夜，指太阳落山后天黑的时候，与“颜色越来越黑”相符。", "早晨": "语义：“早晨”指天亮之后，与“太阳落山后”的时间矛盾。", "雪": "语义：雪是白色的，颜色不会越来越黑，与语境相反。", "声音": "搭配：“颜色”多用于可见的事物，不说声音的颜色。"}, "sentence_index": 6, "correct_answer": "夜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳下山后，这一个夜我都没睡好。", "explanation": "这里应该用〈这一夜〉。“夜”前面不用量词“个”，直接说“一夜”“这一夜”。"}, {"text": "太阳下山后，夜新闻开始播出。", "explanation": "这里应该用〈晚间〉。“晚间新闻”是固定说法，“夜”不能修饰“新闻”。"}, {"text": "太阳下山后，他夜才回到家。", "explanation": "这里应该用〈深夜〉。“夜”不能单独作时间副词修饰“才回到家”，要说“深夜才回到家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, vali