INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从天黑到天亮的一段时间。", "primary_collocate": null, "pronunciation": "yè", "ipa": "je˥˩", "syllable_count": 1, "sentences": [{"text": "夏天的夜很短，天亮得很早。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的夜很长，我常常睡到天亮。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜很长，他一个人在医院等了很久。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜过去了，天慢慢亮了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的夜特别安静，我一觉睡到天亮。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜很冷，他把被子盖好才睡。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜还没过完，天边已经有一点白了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了一场雨，夜变得更凉了。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜太长了，我怎么也睡不着。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈守着生病的孩子，夜过得很慢。", "target_word": "夜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夜晚", "label": "复合"}, {"form": "夜里", "label": "复合"}, {"form": "夜班", "label": "复合"}], "register": "中性", "sense_fingerprint": "夜|从天黑到天亮的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89226, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夜", "is_correct": true, "explanation": "正确：夜 yè（第四声），指从天黑到天亮的一段时间。"}, {"text": "也", "is_correct": false, "explanation": "也 yě（第三声）与 yè（第四声）声调不同，意思是“也”。"}, {"text": "噎", "is_correct": false, "explanation": "噎 yē（第一声）与 yè（第四声）声调不同，意思是“食物堵住喉咙”。"}, {"text": "椰", "is_correct": false, "explanation": "椰 yē（第一声）与 yè（第四声）声调不同，意思是“椰子”。"}], "explanations": {"夜": "正确：夜 yè（第四声），指从天黑到天亮的一段时间。", "也": "也 yě（第三声）与 yè（第四声）声调不同，意思是“也”。", "噎": "噎 yē（第一声）与 yè（第四声）声调不同，意思是“食物堵住喉咙”。", "椰": "椰 yē（第一声）与 yè（第四声）声调不同，意思是“椰子”。"}, "sentence_index": null, "correct_answer": "夜"}, "level_3": {"options": [{"text": "夜", "is_correct": true, "explanation": "正确：夜，指从天黑到天亮的一段时间，与“夏天的……很短”相符。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与“夏天”的语境冲突，夏天的冬天说不通。"}, {"text": "雪", "is_correct": false, "explanation": "语义：“雪”与“夏天”的季节语境冲突，夏天不说雪很短。"}, {"text": "晚风", "is_correct": false, "explanation": "搭配：“短”多修饰时间、长度，不说“晚风很短”。"}], "explanations": {"夜": "正确：夜，指从天黑到天亮的一段时间，与“夏天的……很短”相符。", "冬天": "语义：“冬天”与“夏天”的语境冲突，夏天的冬天说不通。", "雪": "语义：“雪”与“夏天”的季节语境冲突，夏天不说雪很短。", "晚风": "搭配：“短”多修饰时间、长度，不说“晚风很短”。"}, "sentence_index": 0, "correct_answer": "夜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨晚没有睡觉，一只夜都在看书。", "explanation": "这里应该用〈一夜〉。夜不能用量词“只”，说“一夜”或“整夜”。"}, {"text": "我习惯在夜写日记。", "explanation": "这里应该用〈晚上〉。“夜”单独作时间状语不自然，一般说“夜里”“夜间”，写日记的时间要说“晚上”。"}, {"text": "他在这里住了一把夜。", "explanation": "这里应该用〈一夜〉。计算一段夜晚要说“一夜”，量词“把”不用于计算“夜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89226, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "夜", "is_correct": true, "explanation": "正确：夜 yè（第四声），指从天黑到天亮的一段时间。"}, {"text": "野", "is_correct": false, "explanation": "野 yě（第三声）与 yè（第四声）声调不同，意思是“野外”。"}, {"text": "爷", "is_correct": false, "explanation": "爷 yé（第二声）与 yè（第四声）声调不同，意思是“爷爷”。"}, {"text": "月", "is_correct": false, "explanation": "月 yuè 与 yè 的介音不同（ü 与 i），声调相同，意思是“月亮”。"}], "explanations": {"夜": "正确：夜 yè（第四声），指从天黑到天亮的一段时间。", "野": "野 yě（第三声）与 yè（第四声）声调不同，意思是“野外”。", "爷": "爷 yé（第二声）与 yè（第四声）声调不同，意思是“爷爷”。", "月": "月 yuè 与 yè 的介音不同（ü 与 i），声调相同，意思是“月亮”。"}, "sentence_index": null, "correct_answer": "夜"}, "level_3": {"options": [{"text": "夜", "is_correct": true, "explanation": "正确：夜，指从天黑到天亮的一段时间，与“天边已经有一点白了”的语境相符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“过完”多用于时间、节日，不说“作业过完”。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“过完”用于时间，不说“午饭过完”。"}, {"text": "演出", "is_correct": false, "explanation": "语义：“演出”是活动，与“天边已经有一点白了”的时间语境不合。"}], "explanations": {"夜": "正确：夜，指从天黑到天亮的一段时间，与“天边已经有一点白了”的语境相符。", "作业": "搭配：“过完”多用于时间、节日，不说“作业过完”。", "午饭": "搭配：“过完”用于时间，不说“午饭过完”。", "演出": "语义：“演出”是活动，与“天边已经有一点白了”的时间语境不合。"}, "sentence_index": 6, "correct_answer": "夜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他夜回到家，屋子里的灯都熄了。", "explanation": "这里应该用〈深夜〉。“夜”不能单独作时间副词修饰“回到家”，要说“深夜”或“夜里”。"}, {"text": "我每晚都看夜新闻。", "explanation": "这里应该用〈晚间〉。“晚间新闻”是固定说法，“夜”不能单独修饰“新闻”。"}, {"text": "这家店只在夜营业。", "explanation": "这里应该用〈夜间〉。“夜”单独作时间状语不自然，一般说“夜间”或“夜里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬天的夜长很，我坐在窗边等天亮。", "corrected_sentence": "冬天的夜很长，我坐在窗边等天亮。", "error_description": "错误：形容词谓语的语序颠倒，“很长”不能说成“长很”，应说“夜很长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜过着好久，他才睡着。", "corrected_sentence": "夜过了好久，他才睡着。", "error_description": "错误：“过”后接了“着”，“过着”表示度日、生活，不表示时间流逝。应说“夜过了好久”，用“了”表示时间已经过去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
