INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "死水是不流动的水，常常很脏。", "primary_collocate": null, "pronunciation": "sǐ shuǐ", "ipa": "sz̩˨˩˦ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "池塘里是一潭死水，很脏。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死水里有很多小虫子。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别喝死水，会生病的。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河不流了，变成了死水。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死水发出难闻的味道。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子角落有一洼死水。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，死水里容易生蚊子。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不要在死水边玩。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那盆死水倒掉了。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，路边留下了一些死水。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一潭死水", "label": "量词"}], "register": "中性", "sense_fingerprint": "不流动而且很脏的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89227, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "死水", "is_correct": true, "explanation": "正确。死水指不流动而且很脏的水。"}, {"text": "死鼠", "is_correct": false, "explanation": "shǔ 与 shuǐ 声母、声调相同（均为第三声），只是韵母不同（u 与 uei）；死鼠的意思是死去的老鼠。"}, {"text": "死守", "is_correct": false, "explanation": "shǒu 与 shuǐ 只差韵母（ou 与 uei），声调相同，死守的意思是坚决守住。"}, {"text": "似水", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）只有声调不同；似水的意思是像水一样。"}], "explanations": {"死水": "正确。死水指不流动而且很脏的水。", "死鼠": "shǔ 与 shuǐ 声母、声调相同（均为第三声），只是韵母不同（u 与 uei）；死鼠的意思是死去的老鼠。", "死守": "shǒu 与 shuǐ 只差韵母（ou 与 uei），声调相同，死守的意思是坚决守住。", "似水": "sì（第四声）与 sǐ（第三声）只有声调不同；似水的意思是像水一样。"}, "sentence_index": null, "correct_answer": "死水"}, "level_3": {"options": [{"text": "死水", "is_correct": true, "explanation": "正确。“一潭死水，很脏”描述不流动的脏水，用“死水”最合适。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水是香的，与“很脏”矛盾，且不说“一潭香水”。"}, {"text": "清水", "is_correct": false, "explanation": "语义：清水干净，与“很脏”矛盾。"}, {"text": "甜水", "is_correct": false, "explanation": "语义：甜水干净可口，与“很脏”矛盾。"}], "explanations": {"死水": "正确。“一潭死水，很脏”描述不流动的脏水，用“死水”最合适。", "香水": "语义：香水是香的，与“很脏”矛盾，且不说“一潭香水”。", "清水": "语义：清水干净，与“很脏”矛盾。", "甜水": "语义：甜水干净可口，与“很脏”矛盾。"}, "sentence_index": 0, "correct_answer": "死水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂排出的死水直接流进了河里。", "explanation": "这里应该用〈污水〉。死水指不流动的积水，工厂排出的脏水要说污水。"}, {"text": "这场大雨过后，死水直冲下游。", "explanation": "这里应该用〈洪水〉。死水不流动，不会直冲下游，冲下游的大水要说洪水。"}, {"text": "这条河水流很急，是一潭死水。", "explanation": "这里应该用〈活水〉。河水在奔流，不能说成不流动的死水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死水", "is_correct": true, "explanation": "正确。“夏天，死水里容易生蚊子”指不流动的积水，用“死水”最合适。"}, {"text": "海水", "is_correct": false, "explanation": "语义：海水咸，不是蚊子繁殖的地方。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不是蚊子能在其中繁殖的积水。"}, {"text": "矿泉水", "is_correct": false, "explanation": "搭配：矿泉水多为瓶装饮用水，不说“矿泉水里容易生蚊子”。"}], "explanations": {"死水": "正确。“夏天，死水里容易生蚊子”指不流动的积水，用“死水”最合适。", "海水": "语义：海水咸，不是蚊子繁殖的地方。", "汽油": "语义：汽油不是蚊子能在其中繁殖的积水。", "矿泉水": "搭配：矿泉水多为瓶装饮用水，不说“矿泉水里容易生蚊子”。"}, "sentence_index": 6, "correct_answer": "死水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水库放闸后，水哗哗地涌出来，是一潭死水。", "explanation": "这里应该用〈活水〉。水在哗哗地流，不是不流动的死水。"}, {"text": "这口井的水源源不断地往外涌，是一汪死水。", "explanation": "这里应该用〈泉水〉。水源源不断地涌出，是流动的水，不是死水。"}, {"text": "这条小溪哗哗地流着，是一汪死水。", "explanation": "这里应该用〈溪水〉。溪水一直在流动，不是不流动的死水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙角的破缸里积了一条死水。", "corrected_sentence": "墙角的破缸里积了一缸死水。", "error_description": "“死水”的量词应用“缸”（一缸死水），用“条”是量词错误，“条”用于细长的东西，不能用于破缸里的积水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想把那条死水倒掉。", "corrected_sentence": "我想把那盆死水倒掉。", "error_description": "“死水”的量词应用“盆”（那盆死水），用“条”是量词错误，“条”用于细长的东西，不能用于水。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
