INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不流动的水，如池塘、水坑中的积水。", "primary_collocate": null, "pronunciation": "sǐ shuǐ", "ipa": "sz̩˨˩˦ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "水坑里的死水很浑。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池塘没有出口，水成了死水。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死水不流动，容易发臭。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，地上有一滩死水。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼在死水里活不长。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个池塘的死水该换了。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把死水抽走了。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的死水里长满了草。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河堵住后，就成了死水。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着一池死水，想起了小时候。", "target_word": "死水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一潭死水", "label": "量词"}], "register": "中性", "sense_fingerprint": "池塘水坑里不流动的积水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89228, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "死水", "is_correct": true, "explanation": "正确。死水指不流动的积水，如池塘、水坑中的积水。"}, {"text": "死鼠", "is_correct": false, "explanation": "shǔ 与 shuǐ 只差韵母 ei，声调相同（均为第三声）；死鼠的意思是死去的老鼠。"}, {"text": "死守", "is_correct": false, "explanation": "shǒu 与 shuǐ 只差韵母（ou 与 uei），声调相同，死守的意思是坚决守住。"}, {"text": "似水", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）只有声调不同；似水的意思是像水一样。"}], "explanations": {"死水": "正确。死水指不流动的积水，如池塘、水坑中的积水。", "死鼠": "shǔ 与 shuǐ 只差韵母 ei，声调相同（均为第三声）；死鼠的意思是死去的老鼠。", "死守": "shǒu 与 shuǐ 只差韵母（ou 与 uei），声调相同，死守的意思是坚决守住。", "似水": "sì（第四声）与 sǐ（第三声）只有声调不同；似水的意思是像水一样。"}, "sentence_index": null, "correct_answer": "死水"}, "level_3": {"options": [{"text": "死水", "is_correct": true, "explanation": "正确。“水坑里的……很浑”指水坑中不流动的积水，用“死水”最合适。"}, {"text": "清水", "is_correct": false, "explanation": "语义：清水清澈，与“很浑”矛盾。"}, {"text": "矿泉水", "is_correct": false, "explanation": "语义：矿泉水清澈干净，与“很浑”矛盾。"}, {"text": "饮用水", "is_correct": false, "explanation": "搭配：“饮用水”指供人喝的水，不说“水坑里的饮用水”。"}], "explanations": {"死水": "正确。“水坑里的……很浑”指水坑中不流动的积水，用“死水”最合适。", "清水": "语义：清水清澈，与“很浑”矛盾。", "矿泉水": "语义：矿泉水清澈干净，与“很浑”矛盾。", "饮用水": "搭配：“饮用水”指供人喝的水，不说“水坑里的饮用水”。"}, "sentence_index": 0, "correct_answer": "死水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂排出的死水流进了河里。", "explanation": "这里应该用〈污水〉。死水指不流动的积水，工厂排出的脏水要说污水。"}, {"text": "山洪暴发，死水冲垮了大桥。", "explanation": "这里应该用〈洪水〉。死水不流动，不会冲垮大桥，冲垮东西的大水要说洪水。"}, {"text": "这条小河奔流不息，是一滩死水。", "explanation": "这里应该用〈活水〉。小河在奔流，不能说成不流动的死水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死水", "is_correct": true, "explanation": "正确。“工人把……抽走了”指抽走积水，用“死水”最合适。"}, {"text": "头发", "is_correct": false, "explanation": "语义：“抽走”不能用于头发，与抽水的场景不符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是水，不能像抽水一样被抽走。"}, {"text": "胡子", "is_correct": false, "explanation": "语义：胡子不能被“抽走”，与工人抽水的场景不符。"}], "explanations": {"死水": "正确。“工人把……抽走了”指抽走积水，用“死水”最合适。", "头发": "语义：“抽走”不能用于头发，与抽水的场景不符。", "月亮": "语义：月亮不是水，不能像抽水一样被抽走。", "胡子": "语义：胡子不能被“抽走”，与工人抽水的场景不符。"}, "sentence_index": 6, "correct_answer": "死水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "自来水厂把水处理后，水就变成了死水。", "explanation": "这里应该用〈自来水〉。死水指不流动的脏积水，处理后的自来水不叫死水。"}, {"text": "屋顶上哗哗流下来的死水很干净。", "explanation": "这里应该用〈雨水〉。死水指不流动的水，屋顶上哗哗流下来的是雨水，不能说成死水。"}, {"text": "瀑布从山上冲下来，是一汪死水。", "explanation": "这里应该用〈活水〉。瀑布的水一直在流动，不是不流动的死水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路边的洼地里积了一条死水。", "corrected_sentence": "路边的洼地里积了一滩死水。", "error_description": "“死水”应用量词“滩”（一滩死水），用“条”是量词错误，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们用水泵把哗哗流动的死水抽干了。", "corrected_sentence": "工人们用水泵把池塘里的死水抽干了。", "error_description": "“死水”指不流动的水，不能用“哗哗流动的”来修饰，语义矛盾；应改为“池塘里的死水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
