INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89231, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进出是走进去，又走出来。", "primary_collocate": null, "pronunciation": "jìn chū", "ipa": "tɕin˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他一天进出图书馆好几次。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在门口进出，一会儿也不停。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见他进出那家商店三次。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们进出教室，吵个不停。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸今天进出厨房好几次。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫从小门进出很方便。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来回进出办公室，好像在找东西。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天进出超市两次，都忘了买水。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不停地进出房间，门响个不停。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天早上进出家门，都会和邻居打招呼。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进出了", "label": "体标"}, {"form": "进出口", "label": "复合"}], "register": "中性", "sense_fingerprint": "同一个人走进去又走出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进出", "is_correct": true, "explanation": "正确：「进出」指走进去又走出来，「一天进出图书馆好几次」符合句意。"}, {"text": "修", "is_correct": false, "explanation": "语义：「修」指修理，一天修图书馆好几次不符合常理，句意说不通。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：「锻炼」不能直接带「图书馆」作宾语，搭配不当。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出歌声，不能用来指去图书馆，句意不通。"}], "explanations": {"进出": "正确：「进出」指走进去又走出来，「一天进出图书馆好几次」符合句意。", "修": "语义：「修」指修理，一天修图书馆好几次不符合常理，句意说不通。", "锻炼": "搭配：「锻炼」不能直接带「图书馆」作宾语，搭配不当。", "唱": "语义：「唱」指发出歌声，不能用来指去图书馆，句意不通。"}, "sentence_index": 0, "correct_answer": "进出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两份报告的数字有进出，需要重新核对。", "explanation": "此处应该用〈出入〉，指两者不一致。进出表示走进去又走出来，不能用来说数字有差别。"}, {"text": "他终于进出了大学。", "explanation": "此处应该用〈进入〉。进入只指走进去，考上大学不需要再出来；进出强调既进又出，不能用于此。"}, {"text": "这件事让他进出了深深的悲伤。", "explanation": "此处应该用〈陷入〉。陷入指落入某种不好的境地或状态；进出指人或车辆往来于某处，不能用来说情绪或心境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进出", "is_correct": true, "explanation": "正确：「进出」指来回走进走出，「来回进出办公室」符合句中的动作。"}, {"text": "说", "is_correct": false, "explanation": "搭配：「说」要带话语或语言作宾语，不能带「办公室」，搭配不当。"}, {"text": "踢", "is_correct": false, "explanation": "语义：「踢」是用脚撞击的动作，「来回踢办公室」不合常理，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」不能用于办公室，「来回咬办公室」句意不通。"}], "explanations": {"进出": "正确：「进出」指来回走进走出，「来回进出办公室」符合句中的动作。", "说": "搭配：「说」要带话语或语言作宾语，不能带「办公室」，搭配不当。", "踢": "语义：「踢」是用脚撞击的动作，「来回踢办公室」不合常理，句意不通。", "咬": "语义：「咬」不能用于办公室，「来回咬办公室」句意不通。"}, "sentence_index": 6, "correct_answer": "进出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项工作的进出很快，大家都很高兴。", "explanation": "此处应该用〈进展〉。进展指事情向前推进的速度；进出指人或车辆的往来，也指钱款的收支，这里说的是工作，不能用进出。"}, {"text": "他进出了前三名。", "explanation": "此处应该用〈进入〉。进入指进到某个范围或行列之中；进出强调既进又出，不能用来说进到名次里。"}, {"text": "他进出了那道难题。", "explanation": "此处应该用〈攻克〉。攻克指战胜困难、解决难题；进出指人或车辆往来于某处，只能用于处所，「那道难题」不是可以进出的地方，不能用进出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天进出那家超市三个。", "corrected_sentence": "我昨天进出那家超市三次。", "error_description": "量词错误：表示动作的次数要用量词「次」，不能用「个」。「进出那家超市三个」应改为「进出那家超市三次」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天进出着医院，很辛苦。", "corrected_sentence": "她每天进出医院，很辛苦。", "error_description": "体标错误：「进出」表示反复进出的动作，后面不用「着」，错误形式是「进出着医院」，正确形式是「进出医院」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
