INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89232, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进来和出去。", "primary_collocate": null, "pronunciation": "jìn chū", "ipa": "tɕin˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "进出大楼的人都要登记。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口有人看着，外人不能随便进出。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门是进出的路，不要放东西。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站里进出的人很多。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请小心，进出电梯不要挤。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口进出的车太多了。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十点以后，学生不能进出宿舍。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进出小区要给保安看卡。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很小，客人进出都不方便。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条路太窄，大车进出很难。", "target_word": "进出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进出了", "label": "体标"}, {"form": "进出口", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或车辆通行，进来和出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进出", "is_correct": true, "explanation": "正确：「进出」指人或车辆通行，进来和出去，「进出大楼的人」符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱大楼」说不通，「唱」不能指向建筑，句意不通。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：「锻炼」不能带「大楼」作宾语，搭配不当。"}, {"text": "踢", "is_correct": false, "explanation": "语义：「踢大楼」是不合常理的动作，句子不通。"}], "explanations": {"进出": "正确：「进出」指人或车辆通行，进来和出去，「进出大楼的人」符合句意。", "唱": "语义：「唱大楼」说不通，「唱」不能指向建筑，句意不通。", "锻炼": "搭配：「锻炼」不能带「大楼」作宾语，搭配不当。", "踢": "语义：「踢大楼」是不合常理的动作，句子不通。"}, "sentence_index": 0, "correct_answer": "进出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的研究进出了问题的核心。", "explanation": "此处应该用〈深入〉。深入指进到事物的深处；进出指人或车辆往来于某处，不能用来说研究触及的深度。"}, {"text": "这个项目正在进出，已经快做完了。", "explanation": "此处应该用〈进行〉。进行指事情正在开展；进出指人或车辆往来于某处，不能用来说项目正在开展。"}, {"text": "这个人进出了那件事。", "explanation": "此处应该用〈卷入〉。卷入指牵涉到某件事情之中；进出指人或车辆往来于某处，只能用于处所，「那件事」不是可以进出的地方，不能用进出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进出", "is_correct": true, "explanation": "正确：「进出」指人或车辆通行，进来和出去，「晚上十点以后不能进出宿舍」符合句意。"}, {"text": "说", "is_correct": false, "explanation": "搭配：「说」要带话语作宾语，不能带「宿舍」，搭配不当。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」不能用于宿舍，「不能咬宿舍」句意不通。"}, {"text": "晒", "is_correct": false, "explanation": "语义：「晒」指把东西放在阳光下，「不能晒宿舍」句意不通。"}], "explanations": {"进出": "正确：「进出」指人或车辆通行，进来和出去，「晚上十点以后不能进出宿舍」符合句意。", "说": "搭配：「说」要带话语作宾语，不能带「宿舍」，搭配不当。", "咬": "语义：「咬」不能用于宿舍，「不能咬宿舍」句意不通。", "晒": "语义：「晒」指把东西放在阳光下，「不能晒宿舍」句意不通。"}, "sentence_index": 6, "correct_answer": "进出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她终于进出了那所学校。", "explanation": "此处应该用〈进入〉。进入只指走进去，考上学校不需要再出来；进出强调既进又出，不能用于此。"}, {"text": "他的思绪进出了很久，终于停了下来。", "explanation": "此处应该用〈飘〉。飘指思绪不定地游走；进出指人或车辆往来于某处，不能用来形容思绪。"}, {"text": "这个问题在上线后进出了。", "explanation": "此处应该用〈出现〉。出现指事物显露或产生；进出指人或车辆往来于某处，不能用来说问题产生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区的车辆进出了都要登记。", "corrected_sentence": "这个小区的车辆进出都要登记。", "error_description": "体标错误：此句说的是一般规定，「进出」后不能加「了」，错误形式是「进出了都要登记」，正确形式是「进出都要登记」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "进出着仓库的人都要戴帽子。", "corrected_sentence": "进出仓库的人都要戴帽子。", "error_description": "体标错误：「进出」不带「着」，「着」表示持续的状态，这里是一般说法，应去掉「着」，正确形式是「进出仓库的人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
