INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吃得又多又快。", "primary_collocate": null, "pronunciation": "dà chī", "ipa": "ta˥˩ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他饿坏了，坐下就大吃起来。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，他在饭桌上大吃了一顿。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天过节，我们可以大吃一顿了。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他饿了一天，晚上大吃了两碗面。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家店的烤肉很好，我们想去大吃一顿。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，大家围着桌子大吃起来。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟看见红烧肉，立刻大吃起来。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥结束了，她高兴地大吃了一顿。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边大吃海鲜。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别大吃了，小心肚子疼。", "target_word": "大吃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大吃了", "label": "完成体"}, {"form": "大吃起来", "label": "复合"}, {"form": "大吃一顿", "label": "固定搭配"}], "register": "口语", "sense_fingerprint": "饿了或高兴时吃得又多又快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1db7579-ff47-4f4b-8f4b-d3cbfdbf4ed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大吃", "is_correct": true, "explanation": "正确：“大吃起来”指开始大口吃，与“饿坏了”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：坐下之后不能游泳，与句子的吃饭情境不符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”要求参观的对象作宾语，不能用来描述吃饭的动作。"}, {"text": "绝食", "is_correct": false, "explanation": "语义：“绝食”指不吃饭，与“饿坏了”后马上吃的情况矛盾。"}], "explanations": {"大吃": "正确：“大吃起来”指开始大口吃，与“饿坏了”相符。", "游泳": "语义：坐下之后不能游泳，与句子的吃饭情境不符。", "参观": "搭配：“参观”要求参观的对象作宾语，不能用来描述吃饭的动作。", "绝食": "语义：“绝食”指不吃饭，与“饿坏了”后马上吃的情况矛盾。"}, "sentence_index": 0, "correct_answer": "大吃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他渴坏了，一口气大吃了两杯水。", "explanation": "这里应该用〈大喝〉。“吃”用于固体食物，水要用“喝”。"}, {"text": "他在公园里大吃了一个小时步。", "explanation": "这里应该用〈散〉。“大吃”的对象是食物，散步不能说“大吃”，应说“散了一个小时步”。"}, {"text": "感冒后，他每天大吃三次药。", "explanation": "这里应该用〈服〉。“大吃”指大量吃食物，吃药要用“服”，不能说“大吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大吃", "is_correct": true, "explanation": "正确：“大吃起来”指开始大口吃，与“看见红烧肉”的反应相符。"}, {"text": "逛", "is_correct": false, "explanation": "语义：“逛”指随意走看，与看见红烧肉就吃的情境不符。"}, {"text": "跳伞", "is_correct": false, "explanation": "语义：“跳伞”需要飞机和高空，与看见红烧肉的情境完全不符。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指睡觉，看见红烧肉后立刻睡觉，与“立刻大吃”的情境完全不符。"}], "explanations": {"大吃": "正确：“大吃起来”指开始大口吃，与“看见红烧肉”的反应相符。", "逛": "语义：“逛”指随意走看，与看见红烧肉就吃的情境不符。", "跳伞": "语义：“跳伞”需要飞机和高空，与看见红烧肉的情境完全不符。", "睡": "语义：“睡”指睡觉，看见红烧肉后立刻睡觉，与“立刻大吃”的情境完全不符。"}, "sentence_index": 6, "correct_answer": "大吃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工地上大吃了一顿砖头，累得直不起腰。", "explanation": "这里应该用〈搬〉。“大吃”的对象必须是食物，“砖头”不能吃，应说“搬砖头”。"}, {"text": "他把一支笔大吃了下去。", "explanation": "这里应该用〈吞〉。笔不是食物，“大吃”只用于食物；“吞”可用于非食物的物体。"}, {"text": "他渴了，大吃了一大杯牛奶。", "explanation": "这里应该用〈喝〉。“大吃”用于固体食物，牛奶是液体，应说“喝了一大杯牛奶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚饭后，弟弟又大吃了一个饭。", "corrected_sentence": "晚饭后，弟弟又大吃了一碗饭。", "error_description": "量词错误：“饭”的量词应用“碗”，不能用“个”。应说“又大吃了一碗饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在饭店大吃一个。", "corrected_sentence": "我们在饭店大吃一顿。", "error_description": "量词错误：吃饭的次数要用“顿”，不能用“个”。应说“我们在饭店大吃一顿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89235, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89235, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89235, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "死生是说活着和死去这两件事。", "primary_collocate": null, "pronunciation": "sǐ shēng", "ipa": "sɹ̩˨˩˦ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "古人常常思考死生的问题。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死生有命，富贵在天。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把死生看得很淡。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死生是每个人都要面对的事。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对死生已经看开了。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是死生的道理。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对死生，他一点也不害怕。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每天都要面对病人的死生。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战场上，士兵早已把死生置之度外。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一起经历过死生。", "target_word": "死生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "活着和死去这两件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '790811c9-6e97-424f-b6aa-eb7a3bd287ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89235, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "死生", "is_correct": true, "explanation": "正确答案。死生指活着和死去这两件事，读音为 sǐ shēng。"}, {"text": "四声", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）声调不同，四声指四种声调，与“死生”不同。"}, {"text": "此生", "is_correct": false, "explanation": "cǐ 与 sǐ 声母不同（c 与 s），此生指今生、这一辈子，与“死生”不同。"}, {"text": "死伤", "is_correct": false, "explanation": "shāng 与 shēng 韵母不同（ang 与 eng），死伤指死亡和受伤，与“死生”不同。"}], "explanations": {"死生": "正确答案。死生指活着和死去这两件事，读音为 sǐ shēng。", "四声": "sì（第四声）与 sǐ（第三声）声调不同，四声指四种声调，与“死生”不同。", "此生": "cǐ 与 sǐ 声母不同（c 与 s），此生指今生、这一辈子，与“死生”不同。", "死伤": "shāng 与 shēng 韵母不同（ang 与 eng），死伤指死亡和受伤，与“死生”不同。"}, "sentence_index": null, "correct_answer": "死生"}, "level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：古人不可能思考电脑，时代不符，句子读不通。"}, {"text": "死生", "is_correct": true, "explanation": "正确答案。死生指活着和死去，正是“古人常常思考……的问题”的思考对象。"}, {"text": "高铁", "is_correct": false, "explanation": "语义：高铁是现代交通工具，古人不可能思考，时代不符，句子读不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“思考”接抽象的道理或问题，不接“石头”这类具体物。"}], "explanations": {"电脑": "语义：古人不可能思考电脑，时代不符，句子读不通。", "死生": "正确答案。死生指活着和死去，正是“古人常常思考……的问题”的思考对象。", "高铁": "语义：高铁是现代交通工具，古人不可能思考，时代不符，句子读不通。", "石头": "搭配：“思考”接抽象的道理或问题，不接“石头”这类具体物。"}, "sentence_index": 0, "correct_answer": "死生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种动物的死生条件很差。", "explanation": "这里应该用〈生存〉。“生存条件”指生物能否活下去的环境，死生指生与死这件事本身，不能用来描述环境。"}, {"text": "这种电池的死生比较长。", "explanation": "这里应该用〈寿命〉。死生不用于器物，电池的使用期限要说寿命。"}, {"text": "我们要珍惜自己的死生。", "explanation": "这里应该用〈生命〉。被珍惜的是生命本身，死生是生与死这件事，不能被珍惜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋不是需要“面对”的事，“面对拖鞋”句子读不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，不是需要“面对”的事，句子读不通。"}, {"text": "死生", "is_correct": true, "explanation": "正确答案。死生指生与死，是“面对……”的合适对象，与“他一点也不害怕”相呼应。"}, {"text": "零食", "is_correct": false, "explanation": "语义：零食是日常小吃，不是需要“面对”的事，句子读不通。"}], "explanations": {"拖鞋": "语义：拖鞋不是需要“面对”的事，“面对拖鞋”句子读不通。", "钢笔": "语义：钢笔是书写工具，不是需要“面对”的事，句子读不通。", "死生": "正确答案。死生指生与死，是“面对……”的合适对象，与“他一点也不害怕”相呼应。", "零食": "语义：零食是日常小吃，不是需要“面对”的事，句子读不通。"}, "sentence_index": 6, "correct_answer": "死生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在火灾中丢了死生。", "explanation": "这里应该用〈性命〉。“丢了性命”指失去生命，死生指生与死这件事，不是可以丢失的东西。"}, {"text": "他过着平静的死生。", "explanation": "这里应该用〈生活〉。死生指生与死这件事，描述日常状态要说“生活”。"}, {"text": "这片森林充满了死生。", "explanation": "这里应该用〈生机〉。充满的是生机，死生指生与死，不能说“充满死生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事关系到他的一个死生，大家都很紧张。", "corrected_sentence": "这件事关系到他的死生，大家都很紧张。", "error_description": "错误形式是“一个死生”，正确形式是“死生”。“死生”是抽象名词，不能在前面加“一个”计数，应直接说“关系到他的死生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书中有很多关于死生讨论。", "corrected_sentence": "书中有很多关于死生的讨论。", "error_description": "漏了“的”。“关于死生”修饰名词“讨论”时要在中间加“的”，应说“关于死生的讨论”，不能说“关于死生讨论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
