INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89239, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "运营商是让手机能打电话、能上网的公司。", "primary_collocate": null, "pronunciation": "yùn yíng shāng", "ipa": "yn⁵¹ iŋ³⁵ ʂɑŋ⁵⁵", "syllable_count": 3, "sentences": [{"text": "我的手机没有信号，我要打电话给运营商。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家运营商的网速很快，价格也不贵。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一个运营商，因为现在的信号太差了。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机卡是运营商给我的，上面有一个号码。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月我都给运营商交一次话费。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运营商说，今天晚上会停一会儿网。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去国外以前，我想问问运营商手机还能不能用。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手机用的是哪家运营商？", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月运营商送了我很多流量。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机不能上网时，可以问问运营商。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "通信运营商", "label": "复合"}, {"form": "运营商们", "label": "复数"}, {"form": "運營商", "label": "繁体"}], "register": "中性", "sense_fingerprint": "提供手机通话和上网服务的公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89239, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运营商", "is_correct": true, "explanation": "正确：手机没有信号，要打电话找能提供通信服务的公司。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能接电话，「打电话给」的对象须是能接听的人或机构。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是材料，无法接听电话，与「打电话给」不符。"}, {"text": "空气", "is_correct": false, "explanation": "配价：「打电话给」的接受者须能接听，「空气」不能作接受者。"}], "explanations": {"运营商": "正确：手机没有信号，要打电话找能提供通信服务的公司。", "花园": "语义：花园不能接电话，「打电话给」的对象须是能接听的人或机构。", "玻璃": "语义：玻璃是材料，无法接听电话，与「打电话给」不符。", "空气": "配价：「打电话给」的接受者须能接听，「空气」不能作接受者。"}, "sentence_index": 0, "correct_answer": "运营商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家运营商专门制造汽车。", "explanation": "这里应该用〈车企〉。运营商只提供通信或网络服务，不制造汽车；制造汽车的企业要说「车企」。"}, {"text": "他在运营商取了钱，又存了一笔钱。", "explanation": "这里应该用〈银行〉。取钱、存钱是银行的业务，运营商只提供通信或网络服务，不办理存取款。"}, {"text": "这家运营商负责修建大楼，工期很短。", "explanation": "这里应该用〈承包商〉。运营商只提供通信或网络服务，不负责修建大楼；承接建筑工程的公司要说「承包商」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89239, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运营商", "is_correct": true, "explanation": "正确：手机在国外能不能用，要问提供通信服务的公司。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不能被「问问」，无法回答手机能不能用。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会回答问题，「问问桌子」不成立。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：米饭不能被询问，与句意不符。"}], "explanations": {"运营商": "正确：手机在国外能不能用，要问提供通信服务的公司。", "故事": "语义：故事不能被「问问」，无法回答手机能不能用。", "桌子": "语义：桌子不会回答问题，「问问桌子」不成立。", "米饭": "语义：米饭不能被询问，与句意不符。"}, "sentence_index": 6, "correct_answer": "运营商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家运营商每年生产几百万台手机。", "explanation": "这里应该用〈厂商〉。运营商只提供通信或网络服务，不生产手机等实物；生产手机的要用「厂商」。"}, {"text": "这家运营商每个月给工厂供应大量零件。", "explanation": "这里应该用〈供应商〉。运营商提供的是通信或网络服务，不向工厂供应零件，供货要说「供应商」。"}, {"text": "我们公司请了一家运营商来打扫卫生。", "explanation": "这里应该用〈保洁公司〉。运营商只提供通信或网络服务，不负责打扫卫生；做清洁的公司要说「保洁公司」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想换一运营商，因为家里信号太差。", "corrected_sentence": "我想换一家运营商，因为家里信号太差。", "error_description": "错误：「一运营商」。「一」与「运营商」之间缺少量词，正确为「一家运营商」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
